    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item cannot fit anywhere after this placement pattern.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: when mean residual is low, conserve tight bins;
    // when mean residual is high, prefer filling bins aggressively.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive late in the stream or when
    // open bins are all poor fits (large mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 20.0 * progress - 30.0 * poor_fits;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum item size) are nearly worthless -> heavy penalty.
    let min_item = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_item && post_residual > 0 {
        score += 60.0 + (min_item - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    } else {
        // Usable gap: reward proportionally to how well the next item fits it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Reward tight fits generally (small waste relative to item size).
    score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spawning new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate (empty bin) should only win when existing residuals
    // are large/awkward: penalize the fresh bin by mean residual slack.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual;
    } else {
        // Prefer bins with below-average residual (closer to full).
        score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild lookahead coupling: if the next item exactly matches the gap,
    // extra reward for preserving that chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small unusable dead space (unless it matches next item)
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 20.0;
    }

    // Reward bins tighter than the mean residual (better fits)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fitting_bins_count as f64;
        // Prefer new bin when many bins fit (good spread) or item is large
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * item_frac - 10.0 * pressure * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    // Mild tie-breaking toward tighter existing bins
    score += (bin_capacity as f64 - residual_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 250.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward closeness.
            score -= 150.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize wasting this bin's future.
            score += 60.0 + 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already below average fill
    // (i.e. keep tight bins tight, avoid fragmenting well-filled bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 1.5 * (mean_residual - res);
    } else {
        score += 1.0 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fitting_bins_count <= 1 && post_residual > 20;
        if poor_fit || progress < 0.15 {
            score -= 90.0;
        } else {
            score += 150.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild preference for fewer open bins (consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

