    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item -> big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Reward small post-residuals that still fit the next item.
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: penalize tight fits that strand space.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize very large leftover space only when it can't be chained;
    // large usable space is good, small dead space is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly in existing bins (large item, tight mean residual).
