        score -= 5.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0; // reserve fresh bin for a big pair
        }
    }

    // Mild phase adaptation: early stream, be picky about wasted space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits: reward low post_residual relative to mean residual.
    score -= 0.35 * (mean_residual - post_residual as f64).max(0.0);

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item, scaled by closeness of fit.
            let gap = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Dead space: next item cannot fit in the leftover; penalize proportionally.
            let waste = next_item_size - post_residual;
            score += 0.9 * waste as f64;
        }
    }

    // Penalize creating tiny unusable residuals (dead space below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins by default.
        score += 8.0;
        // But if next item is large and current bins are fragmented, new bin is fine.
        if next_item_size as f64 > mean_residual {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty when many bins are already open (encourage packing density).
    score += 0.15 * open_bins_count as f64;

    // Early stream: be slightly more willing to keep bins tight for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling with next item: if the leftover can host the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + post_residual as f64 - next_item_size as f64;
    } else if next_item_size > 0 {
        // leftover too small for lookahead: mild penalty scaled by waste
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual context: penalize placing into bins already below mean residual
    // (keeps large-capacity bins available for big items).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current fit is bad
    // (large dead space) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // base new-bin score: slightly worse than a decent existing fit
        score = 20.0 + 15.0 * bad_fit + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin fits lookahead well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest item are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Non-linear penalty on mid-range residuals that are hard to fill later
    // (residuals that can't hold typical items 10..80 are risky).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 40 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: penalize.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is well below mean, it's a tight fit;
    // reward placing into tight bins (keeps loose bins available for future items).
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.5 * tightness.min(50.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no good existing fit exists; otherwise slightly discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 10.0; // large item: fresh bin is fine
        } else {
            score += 20.0; // small item: prefer existing bins
        }
    }

    // Mild time progression: early in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus when next item exactly fills the post residual (perfect 2-chain).
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if diff < 10.0 {
            score -= 20.0 * (1.0 - diff / 10.0);
        }
        // Penalize leaving a residual that is awkwardly close but not matching
        // (dead space trap: slightly larger than next item but unusable).
        if post_residual > next_item_size && post_residual - next_item_size < 5 {
            score += 8.0;
