    // relax when this bin is the only fitting candidate (last chance).
    let pressure = (open_bins_count as f64).ln().max(0.5) * 6.0;
    if fitting_bins_count == 1 {
        score -= 30.0; // strongly prefer using the last chance bin
    } else {
        score += pressure;
    }

    // Prefer bins below mean residual (denser bins) to consolidate fill.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.25 * mean_gap;

    // New-bin candidate logic: an empty bin is attractive only when the
    // item is large relative to capacity or existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Slight default penalty so open bins win on good fits.
        score += 10.0;
        // Large items open fresh bins to avoid fragmenting partial bins.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // If mean residual is small, opening a bin is wasteful.
        if mean_residual < item_size as f64 * 1.5 {
            score += 20.0;
        }
