        score += dead * (1.0 + 0.05 * next.min(80.0) / 10.0);
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from mean residual. Bins with residual below mean are "tight" -> good to fill.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / mean_residual;
        // tight bins (below mean) get reward; loose bins get penalty
        score -= dev * 30.0;
    }

    // Last-chance bin: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // unusable dead space. Empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // base penalty for opening new bin
        score += 400.0;
