        // opening may be reasonable: reduce penalty for large items
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 250.0;
        // if next item could pair with leftover in new bin, soften further
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Stream progression: late in stream, waste matters less; reward tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    // Small reward for many open bins being consolidated (prefer filling existing bins
    // when open_bins_count is high)
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
