    let cls = pr % 10;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if pr < 10 {
        // Dead space: unusable for items >= 1... but items can be as small as 1,
        // so weight by how small the class minimum is.
        score += (10 - pr) as f64 * 2.0;
    } else if cls == 0 {
        // Harmonic class: residual divisible by 10 aligns with common item sizes.
        score -= 8.0;
    } else if cls <= 3 {
        score += cls as f64 * 1.5; // slightly awkward class
    }

    // Integer-division threshold: can next item fit into post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward keeping this bin usable.
            score -= 12.0;
            // Extra reward if next item also lands in a harmonic class (divisible by 10).
            if next_item_size % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here: this placement likely seals the bin.
            // Penalize unless the leftover is tiny (already near-perfect fit).
            score += 6.0;
            if pr >= 10 {
                score += (pr as f64) * 0.05;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits poorly everywhere
        // else (many fitting bins => keep using existing bins).
        score = 100.0
            + (fitting_bins_count as f64) * 30.0
            + (open_bins_count as f64) * 2.0;
        // Late in the stream, discourage new bins more (consolidation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If next item is large, a fresh bin may be valuable for it later.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += ((post_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last chance: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 30.0; // but don't create dead space just because it's last chance
        }
    }

    // Pressure against proliferating open bins: with many open bins,
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (3.0 + 5.0 * progress);

    // Lookahead: if the next item fits into the post residual, reward it;
    // if the next item would leave this residual wasted, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate: attractive early or when existing bins are tight,
    // but discouraged when open bins are plentiful with usable residual.
    if bin_residual == bin_capacity {
        let mean_usable = mean_residual;
        let tight = mean_usable < item_size as f64 * 1.2;
        if tight {
            score -= 20.0;
        } else {
            score += 10.0 + 4.0 * open_bins_count as f64;
        }
        if progress > 0.8 {
            score += 8.0; // late stream: avoid spawning bins with tiny leftovers
        }
    }

    // Mild preference for bins whose residual is close to item size
    // (best-fit coupling) beyond the raw post_residual term.
    score += 0.15 * ((bin_residual - item_size) as f64).abs().min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as f64 - mean_residual) < item_size as f64 * 0.5;
        if tight_fit_exists {
            score += 25.0; // discourage opening a new bin when decent fits exist
        } else {
            score -= 10.0; // encourage fresh bin when open bins are fragmented
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let gap = pr - nx;
            // smaller gap after next placement is better
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap <= 10 {
                score -= 15.0; // near-perfect second-step fit
            }
        } else {
            // next item cannot fit here; penalize by the shortfall
            let shortfall = nx - pr;
            score += 0.8 * shortfall;
            if post_residual < 10 {
                score -= 5.0; // tiny dead space is acceptable (bin effectively closed)
            }
        }
    }

    // Compare post_residual relative to mean residual: prefer leaving residuals
    // close to the fleet average to keep future options balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize large wasted residual after placement (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-zero residual = efficient packing
    } else if post_residual >= 40 {
        score += 0.25 * (post_residual as f64 - 40.0); // big leftover is wasteful
    }

    // Early in stream: keep bins flexible; late: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Penalize dead space: post residuals that are too small for typical future items
    // (items >= 10) are wasted. Perfect fill (post_residual == 0) is best.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (chaining),
    // penalize if post_residual is nonzero but cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: prefer zero post_residual extremely strongly.
        score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream horizon.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 - 25.0 * progress;

        // Opening a new bin is more attractive when many bins are open with small,
        // fragmented residuals (mean residual low relative to capacity).
        let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        new_bin_score -= 20.0 * frag;

        // If the item would leave a dead-space residual in any open bin, new bin helps.
        if post_residual == bin_capacity - item_size && item_size < 100 {
            new_bin_score -= 5.0;
        }

        // If next item is large and this empty bin could host both, slight boost.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 6.0;
        }

        // Fewer open bins -> cheaper to open a new one (exploration).
        new_bin_score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

        score = new_bin_score;
    } else {
        // Existing bins: mild preference for bins with residual close to item size
        // (best-fit signal already in post_residual), plus tie-break toward bins
        // whose residual deviates from the mean (consolidate outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;

        // Slight penalty for using a bin when many bins can fit (keep flexibility),
        // but only when post_residual is not near zero.
        if fitting_bins_count > 3 && post_residual > 15 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual (capacity fractions) ---
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // fraction of capacity remaining

    // Dead-space penalty: residuals below the minimum item size are pure waste.
    if post_residual < 1 {
        score += 10.0 * c;
    } else if post_residual <= 5 {
        score += 60.0;
    } else if post_residual < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: classify post_residual into harmonic bands.
    // Band 0: (0, C/4), Band 1: [C/4, C/2), Band 2: [C/2, 3C/4), Band 3: [3C/4, C]
    let band = post_residual / (bin_capacity / 4).max(1);
    score -= band as f64 * 8.0; // prefer bins with larger leftover class

    // Exact fit reward (item fills bin perfectly).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25) are more likely to be usable later -> reward them.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is highly desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves more waste -> mild penalty proportional to waste
        score += (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's leftover: dead space likely
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good harmonic class exists
    // among open bins (i.e., mean residual is small / fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / c) * (open_bins_count as f64);
        // opening a new bin is penalized normally, but reduced when open bins are fragmented
        score += 30.0 - fragmentation.min(25.0);
    }

    // Stream progression: early on, keep bins tight; late, allow more slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * band as f64;

    // Prefer bins with residuals close to the mean (balance load mildly).
    score += ((pr - mean_residual) / c).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps smaller than the minimum item size (1..100
    // stream, but conservative threshold ~10) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }
    // Gaps that cannot fit the lookahead item are semi-dead if next item is close in size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual as f64 <= 0.1 * bin_capacity as f64 {
        score -= 10.0;
    }

    // Last-chance bin: only fitting bin -> strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin should be penalized, more so when many bins
    // are already open and when other bins fit the item.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * fit_pressure + 5.0 * progress;
        // But if the item is huge relative to residual-capable bins, allow opening:
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If next item is large, hoarding residual now is bad -> opening is less bad.
        if next_item_size > 50 && bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure toward bins with below-mean residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item -> big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Reward small post-residuals that still fit the next item.
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: penalize tight fits that strand space.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize very large leftover space only when it can't be chained;
    // large usable space is good, small dead space is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly in existing bins (large item, tight mean residual).
    if bin_residual == bin_capacity {
        score -= 5.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0; // reserve fresh bin for a big pair
        }
    }

    // Mild phase adaptation: early stream, be picky about wasted space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on post residual (dead space).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize using a bin whose residual is far larger than needed (wasteful fit).
    let slack = bin_residual as f64 - item_size as f64;
    if slack > 0.0 {
        score += 0.25 * slack;
    }

    // Last-chance bin: strongly reward using the only bin that can fit,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward leaving room for the next item proportionally to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - fill_after / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for leaving awkward gap
            score += 0.10 * (post_residual as f64);
        }
    }

    // Global state coupling: when many bins are open, discourage fragmenting;
    // prefer filling bins with high residual relative to the mean.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res_f - mean_residual) / mean_residual;
        score += 6.0 * dev; // prefer below-average residual bins (tighter bins)
    }

    // When few bins are open, mildly prefer spreading into fresh capacity.
    if open_bins_count <= 2 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // (large post residual would result) or stream is early.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // early in the stream: opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // using an existing bin saves a bin: reward
        score -= 8.0;
    }

    // Time horizon: late in stream, be extra greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small jitter-free tie-break on residual for determinism.
    score += 0.001 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let mut score = post + 18.0 * (post / cap).powi(3);

    // Smooth stream-progress coupling: tighten packing as stream advances.
    score -= 14.0 * progress * (1.0 - post / cap).powi(2);
    score += 6.0 * progress * (post / cap).powi(2);

    // Dead-space penalty: residual that no future item likely fits.
    let dead = (post / cap).powi(4);
    score += 22.0 * dead;

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - (gap / cap).powi(2));
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 {
        score -= 9.0;
    }

    // Mild penalty for spreading across many bins vs mean residual.
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (bin_residual as f64 / cap));
    score -= 0.6 * (bin_residual as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with a harmonic decay so tiny
    // residuals are disproportionately attractive.
    score += 40.0 / (1.0 + post_residual as f64);

    // Harmonic class of post_residual via integer division thresholds.
    // Residual classes: 0 (perfect), 1..=5 (nearly perfect), 6..=20 (usable),
    // 21..=50 (awkward), >50 (half-empty).
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 5 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };
    score += class as f64 * 12.0;

    // Modulo-arithmetic coupling: residuals that are multiples of common
    // item-size divisors are more likely to be filled later.
    if post_residual > 0 {
        let pr = post_residual;
        let divisible_bonus = |d: u32| if pr % d == 0 { 1.0 } else { 0.0 };
        let harmonicity = divisible_bonus(10) + divisible_bonus(20) + divisible_bonus(25)
            + divisible_bonus(50) + divisible_bonus(5);
        score -= harmonicity * 6.0; // reward "clean" residual slots
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits with slack; scale by how cleanly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual <= 10 { score -= 10.0; }
    } else if fitting_bins_count > 1 {
        // competition: mildly prefer tighter fits among many candidates
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Penalize it so open bins with decent fits win, but if all open
    // bins would leave huge dead space, allow the new bin.
    if bin_residual == bin_capacity {
        // progress-aware: late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0 + 25.0 * progress;
        // if the item is large relative to capacity, a fresh bin is natural
        if item_size >= bin_capacity / 2 { new_bin_penalty -= 15.0; }
        // if many open bins exist with high mean residual, discourage sprawl
        if mean_residual > 40.0 { new_bin_penalty += 10.0; }
        score += new_bin_penalty;
    } else {
        // mild preference for using bins whose residual deviates from mean
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Penalize creating residuals that no plausible item (>=1, <=100)
    // can exploit awkwardly: residual just above a "gap" zone.
    if post_residual > 80 && post_residual < 90 {
        score += 6.0; // hard-to-fill zone for typical items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // since items are >= 1..100 but small gaps rarely get filled; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placing into bins whose residual tightly matches the item
    // (small waste relative to bin size).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, but allow new-bin escape when all fits are poor.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += pressure * tightness * 10.0;

    // New-bin candidate handling: neutral-to-slightly-penalized baseline so it
    // is chosen only when every open bin scores badly (poor fit / dead space).
    if bin_residual == bin_capacity {
        let mut nb = 55.0;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        nb -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If next item is large too, opening fresh now may waste the new bin.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            nb += 5.0;
        }
        // Few open bins and early stream: opening is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb -= (1.0 - progress) * 8.0;
        return nb;
    }

    // Lookahead coupling: if post_residual can still hold the next item,
    // reward keeping that option alive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual cannot host next item: mild dead-space penalty scaled
        // by how close it is to being useful.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer filling bins with residual near the mean to keep balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item can still fit here afterwards; reward proportional to tightness.
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize unusable leftover.
            let dead = next_item_size - post_residual;
            score += 0.6 * dead as f64;
            // Small post-residuals are generally good (tight fit now).
            score -= 0.3 * post_residual as f64;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 10.0;
    }

    // Relative to mean residual: bins below mean residual are tighter, favor them.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        // But if it leaves a big unmatchable hole, soften the reward.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // New empty bin candidate: penalize so it's only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening bins is costlier relative to remaining items.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open, slightly discourage adding more.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for filling larger items into tighter bins overall.
    score += 0.1 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (below min item size 1..small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item cannot fit here: mild penalty scaled by how badly it misses.
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing
    // residuals are large (poor fits everywhere) or the item is huge relative to
    // typical residual space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If mean residual across open bins is large, a fresh bin is more attractive.
        score -= 0.15 * mean_residual;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Huge items pair well with an empty bin late in the stream.
        if item_size >= 70 {
            score -= 6.0;
        }
    }

    // Mild global pressure: when many bins are open, favor filling existing ones.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins whose residual is close to the item (best-fit flavor).
    score += 0.02 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tightness: reward near-full packing (small post_residual) with a smooth non-linear term.
    let tight = 1.0 - (pr / cap);
    score -= 18.0 * tight * tight * tight;

    // Dead-space penalty for awkward residuals that few future items can use.
    if post_residual > 0 {
        let awkward = (pr / cap).powf(2.3) * (1.0 - (pr / cap));
        score += 26.0 * awkward;
    }

    // Lookahead coupling: if the next item could exactly consume this post_residual,
    // strongly reward; if next item is larger than post_residual, mildly penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 14.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * (1.0 - pr / nxt);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Stream progress coupling: later in the stream, favor consolidating into
    // existing bins (penalize new-bin tendency) via smooth interaction with tightness.
    let prog_term = progress * progress * (3.0 - 2.0 * progress);
    score -= 10.0 * prog_term * (1.0 - pr / cap);

    // Penalize spreading across many open bins when mean residual is already low.
    if open_bins_count > 1 {
        let spread = (mean_residual / cap - pr / cap).abs();
        score += 4.0 * spread;
    }

    // New-bin candidate handling: make an empty bin attractive only when item is
    // large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 30.0 * (1.0 - size_ratio) * (1.0 - size_ratio);
        if fitting_bins_count > 0 {
            score += 12.0 / (fitting_bins_count as f64);
        }
        // Late-stream new bins are costly.
        score += 15.0 * prog_term;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod capacity fractions.
    // Residuals that are "dead" (too small to host typical items) get penalized.
    let dead_threshold = cap_f * 0.1; // residual <= 10 is nearly unusable
    if (post_residual as f64) <= dead_threshold && post_residual > 0 {
        score += 12.0; // creating dead space is bad
    }

    // Perfect fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic bucket: classify post_residual by integer division of capacity/4.
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter.max(1);
    score += bucket as f64 * 3.0; // prefer smaller residual buckets

    // Modulo arithmetic on residual classes: residuals matching common item
    // size classes (multiples of 10) are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // penalize slack left for the next item
        } else {
            // next item cannot fit here: this residual is a dead end for lookahead
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to capacity or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 45.0;
        // large items justify a fresh bin
        score -= (item_size as f64 / cap_f) * 40.0;
        // late in the stream, avoid opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // many open bins: discourage more
        score += open_bins_count as f64 * 1.5;
    } else {
        // Reward using already-open bins, more so when many are open.
        score -= open_bins_count as f64 * 0.8;
        // Prefer bins tighter than the mean residual (good packing).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Progression: as stream advances, favor tighter fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item (or the
    // minimum item size) are nearly worthless -> heavy penalty.
    let min_item = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_item && post_residual > 0 {
        score += 60.0 + (min_item - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 40.0;
    } else {
        // Usable gap: reward proportionally to how well the next item fits it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Reward tight fits generally (small waste relative to item size).
    score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spawning new ones.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate (empty bin) should only win when existing residuals
    // are large/awkward: penalize the fresh bin by mean residual slack.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual;
    } else {
        // Prefer bins with below-average residual (closer to full).
        score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild lookahead coupling: if the next item exactly matches the gap,
    // extra reward for preserving that chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

