        score -= 12.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // If post_residual can't fit next item, penalize dead space relative to next item.
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
