    }

    // Penalize opening a new bin when open bins exist that fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residuals near mean (balanced packing).
    score += 0.4 * ((post_residual as f64 - mean_residual).abs());

    // Tight fits (small post_residual) are generally good.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize placements that strand space just above the next item's size.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is penalized by default,
    // but attractive when the item leaves a large residual that other bins can't match
    // or when current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 45.0;
        // If no open bin fits, opening is necessary-ish; soften penalty.
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // Late in the stream, prefer squeezing into existing bins.
        new_bin_score += 20.0 * progress;
        // If mean residual across open bins is small, opening a bin is reasonable.
        new_bin_score -= (mean_residual / 10.0).min(20.0);
        // Large item relative to capacity: new bin fine.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        score += new_bin_score;
    }

    // Mild preference for bins that are already partially filled (compactness),
    // scaled by how many alternatives exist.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio / (fitting_bins_count.max(1) as f64).sqrt();

    // Tie-break with global state: when many bins are open, favor consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with smooth polynomial shaping
    let mut score = pr;

    // Non-linear coupling: tight fits are increasingly valuable as the stream progresses
    let tightness = 1.0 - norm_pr; // 1.0 = perfect fit
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space quadratically (small residuals that waste capacity)
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Lookahead coupling: reward residuals that can still hold the next item,
    // smoothly weighted by how much of the residual the next item would consume
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fill = nxt / pr.max(1.0);
            score -= 18.0 * fill * (1.0 - fill) * (0.4 + 0.6 * progress);
        } else {
            // post-residual too small for lookahead item: penalize proportionally
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild regularization toward mean residual state: avoid extreme outliers
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate (bin_residual == bin_capacity => post_residual large):
    // its large pr naturally raises the score; add a slight smooth penalty that
    // fades late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ---- New-bin candidate (empty bin) ----
    if bin_residual == bin_capacity {
        let mut s = post_residual as f64;
        // Opening a bin when others fit is expensive.
        if fitting_bins_count > 0 {
            s += 80.0;
        }
        // Harmonic class of the new bin's post residual: leaving a large
        // "class-0" gap (0..10) in a fresh bin is wasteful.
        if post_residual > 0 && post_residual < 10 {
            s += 25.0;
        }
        // Large items justify opening a new bin more than small ones.
        s -= (item_size as f64 / 20.0);
        // Lookahead: fresh bin that also fits the next item is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            s -= 12.0;
        }
        return s;
    }

    // ---- Existing open bins ----
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Unusable dead space below the minimum item size: heavy penalty.
        score += 45.0;
    }

    // Harmonic class logic: bucket post_residual by integer division.
    // Residuals in the "next item fits" class are valuable; others mildly penalized.
    let class = post_residual / 10;
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += class as f64 * 0.8;
        }
    }

    // Modulo-based refinement: residuals near multiples of 25 are
    // structurally reusable (quarter-capacity harmony).
    let m = post_residual % 25;
    if m == 0 && post_residual > 0 {
        score -= 6.0;
    } else if m < 10 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling bins that are already far below the mean residual
    // (reduces dispersion of open capacities).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    }

    // Late in the stream, favor closing bins out (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are already covered by post_residual, but tiny "almost dead" gaps
    // (1..=9) are the worst kind — they trap capacity without utility.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight-but-usable fit reward: prefer bins where the item fills most of
    // the residual, leaving a gap that is still "fillable" by typical items.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 && post_residual >= 10 {
        score -= 25.0 * (fill_ratio - 0.85);
    }

    // Dead-space coupling with lookahead: if the next item could have used
    // the post_residual but we leave a small awkward gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing bins,
    // avoid spreading; few open bins -> new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // New-bin candidate (empty bin): only attractive when existing residuals
    // are large and fragmented, or when nothing fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        // If mean post-placement residual across open bins would be poor,
        // opening fresh is fine; otherwise penalize the new bin.
        if mean_gap < 15.0 {
            score -= 10.0 + mean_gap.max(-30.0).abs() * 0.2;
        } else {
            score += 35.0 + mean_gap * 0.5;
        }
        // Late in the stream, opening new bins wastes capacity — penalize more.
        score += 20.0 * progress;
    }

    // Mild preference toward bins whose residual is closest to the item
    // (best-fit flavor) beyond the raw post_residual baseline.
    score -= 0.05 * (bin_residual as f64 - item_size as f64).abs().max(1.0).recip() * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, slightly conservative.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when alternatives are bad; baseline
        // score sits at a moderately high value so existing bins with good
        // 2-step matches beat it.
        let mut new_bin_score = 75.0;
        // If the next item is large and this fresh bin would hold it well,
        // opening now is fine.
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.5 {
            new_bin_score -= 10.0;
        }
        // Late in the stream, avoid spawning bins that will likely stay empty.
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.9 {
            new_bin_score += 25.0;
        }
        return new_bin_score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect match: post_residual exactly equals next item size.
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        }
        // Near-perfect match: next item fits with small slack.
        else if next_item_size <= post_residual {
            let slack = pr - nxt;
            // Exponentially reward small slack after the next placement.
            score -= 45.0 * (-slack / 12.0).exp();
        }
        // Next item does NOT fit in the residual: penalize proportionally
        // to how much dead space is stranded relative to the next item.
        else {
            let dead = nxt - pr;
            score += 0.8 * dead;
        }

        // Coupling with mean residual: bins whose post_residual deviates
        // strongly below the mean are "tight" — penalize gently to keep
        // flexibility across the bin pool.
        let dev = mean_residual - pr;
        if dev > 0.0 {
            score += 0.15 * dev;
        } else {
            score += 0.05 * dev.abs();
        }
    } else {
        // Last item: just minimize leftover directly (score already = post_residual).
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for extremely tight placements that leave tiny unusable
    // slivers (< 10) when the next item can't use them.
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 8.0;
    }

    // Slight preference for using fuller bins early in the stream
    // (best-fit flavor scaled by stream position).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= 40.0 * (1.0 - post / cap).powi(3);

    // Penalize dead space that is too small for typical items (unusable gap).
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be pickier (leave room); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post / cap);

    // Global state coupling: many open bins with high mean residual -> favor reusing bins.
    if open_bins_count > 2 && mean_residual > item {
        score -= 6.0 * (mean_residual / cap);
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * (item / cap);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Stream-progress coupling: early on, keep bins flexible (penalize low post_residual
    // less), late in the stream, drive toward filling bins tightly.
    let progress_gain = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= progress_gain;

    // Non-linear reward for leaving residual close to a plausibly fillable size,
    // coupled with the next item's size (lookahead fit reward).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-gap / 15.0).powi(2).exp();
    }

    // Penalize dead space that nothing can use: post_residual below typical minimum item size.
    if pr < 1.0 {
        score -= 20.0; // perfect fill bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Slight preference for bins already below mean residual (balancing load),
    // with smooth quadratic interaction.
    let mean_gap = pr - mean_residual;
    score += 0.15 * mean_gap * mean_gap / cap;

    // New-bin candidate: make it mildly unattractive unless post_residual is full
    // capacity (it is) — add a penalty that decays with stream progress so late
    // in the stream we prefer opening fresh bins over bad fits.
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * progress;
    }

    // Mild penalty for proliferation of open bins early on.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo-10 classes behave differently.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals like 1..9 are nearly unusable (items >= 10... but sizes 1..100 possible).
    if pr > 0 && pr < 10 {
        score += 40.0; // worst dead space
    } else if class == 0 && pr > 0 {
        score -= 12.0; // perfectly aligned residual, easy to fill
    } else if class >= 1 && class <= 3 {
        score += 15.0; // awkward sliver
    } else if class >= 8 {
        score += 5.0;
    }

    // Integer-division thresholds: quarter/half/full harmonic levels of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr == quarter || pr == half || pr == quarter * 3 {
        score -= 18.0; // canonical reusable residual levels
    }
    if pr > half && pr < bin_capacity {
        score += 8.0; // large residual means loose packing; slight penalty vs tight fits
    }

    // Tight fit reward: post_residual small but usable.
    if pr > 0 && pr <= 15 && pr >= 1 {
        score -= 10.0;
    }

    // Perfect fit: zero waste.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does this bin's post-residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match: residual class divisible by next item's class
            if pr % next_item_size.max(1) == 0 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize more if residual is small (bin becomes dead)
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: only fitting bin -> strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish score, opened only when fits are poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its residual is full capacity, but that is "good" space.
        score = cap * 0.55 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps sequence of large items
        }
        // late in stream, prefer closing out open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        return score;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's already ragged; prefer it less.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Many open bins: encourage filling existing ones harder.
    score -= (open_bins_count as f64).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 12.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 5 {
            score -= 10.0; // gap is tailored for the next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 30.0 + 2.5 * open_bins_count as f64;
        // But if mean residual is small and fragmented, a fresh bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // Early stream: building fresh bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            score -= 15.0;
        }
    }

    // Prefer filling bins with larger residuals when few bins are open.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (item fills bin completely).
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 300.0; // perfect chain placement
        } else {
            score += gap * 1.5; // penalize mismatch with next item's demand
        }
        // Penalize leaving dead space that the next item cannot use at all.
        if post_residual > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Penalize creating very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in
    // the stream or when few bins are open; relax slightly when many bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 + 100.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // If next item could pair with a big residual, opening new bin is less bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual; penalize leaving large awkward gaps.
            score += 0.03 * (post_residual as f64);
        }
    }

    // New-bin candidate handling: opening a bin should be discouraged unless
    // the current bin fits poorly or there are no alternatives.
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, scaled by how many bins already fit the item.
        let alt_penalty = if fitting_bins_count == 0 { -20.0 } else {
            15.0 + 4.0 * fitting_bins_count as f64
        };
        score += alt_penalty;
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: prefer filling bins above the mean residual
    // (i.e., bins with less room than average) to consolidate fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    // Mild reward for using bins when many are open (reduce bin count pressure).
    score -= 0.15 * open_bins_count as f64 * tightness;

    // Prefer placing larger items into emptier bins early on.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fill_ratio * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer minimal post-residual, with a non-linear polynomial shaping.
    let mut score = pr - 0.6 * (pr / cap).powi(2) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tight fits mildly); later, reward tight fits.
    let flex = (pr / cap).powi(2);
    let tightness_bias = (0.5 - progress) * 2.0; // >0 early, <0 late
    score += tightness_bias * 12.0 * flex;

    // Interaction: post_residual * progress polynomial — reward tight fits more as stream advances.
    score -= 8.0 * progress * (1.0 - flex);

    // Last-chance bin: strong smooth reward, scaled by how well the item fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - (pr / cap).powf(1.5));
    }

    // Lookahead: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += 0.15 * waste * (1.0 + progress);
    }

    // Mean-residual coupling: penalize bins deviating from mean residual (non-linear).
    let dev = (mean_residual - bin_residual as f64).abs();
    score += 0.05 * dev * dev / cap;

    // Mild new-bin preference when many bins are open late in the stream.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into buckets
    // via integer division. Small post_residual classes are "tight" fits.
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => score -= 30.0,               // near-perfect fit (dead space < 10)
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score -= 0.0,
        5 => score += 3.0,                // half-empty bins are awkward
        6 => score += 5.0,
        7 => score += 6.0,
        8 => score += 5.0,
        _ => {}                            // 90..100 residual: nearly empty bin
    }

    // Modulo-20 resonance: leftover space that is an exact multiple of 20
    // is likely reusable by future items (sizes often cluster mod 20).
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 6.0;
    }
    // Odd tiny remainders (< 5) are dead space; penalize.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item exactly fits the post_residual,
    // this is a chain fit — reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }
    // If next item cannot use the leftover and leftover is small, mildly favor.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely
    // better (no fitting bins, or current fits are terrible). Penalize new bin.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if nothing fits anywhere, new bin must be attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream with many open bins, prefer reusing existing space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with below-mean residual (denser bins) for balance.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.15;
    } else {
        score += (residual_f - mean_residual) * 0.05;
    }

    // Big items should go into big-residual bins to preserve small slots.
    if item_size > 50 {
        score -= (residual_f - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10.0 - post) * 6.0;
    }

    // Residuals that cannot fit the lookahead item but could fit a small
    // item are moderately wasteful when next_item_size is known.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward tight fits: fill ratio of the consumed space.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins over opening new ones.
    let pressure = (open_bins_count as f64).ln1p() * 4.0;
    score += pressure;

    // New-bin candidate: neutral residual (post == cap), but should only
    // win when existing bins have bad fits. Make empty-bin score depend on
    // how bad the mean residual situation is.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when open bins are
        // fragmented (high mean residual spread / many bins).
        score += 55.0 - pressure * 1.5;
        if mean_residual < 25.0 {
            score -= 10.0; // open bins nearly full anyway
        }
    }

    // Late in stream, avoid leaving tiny gaps even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: tighter fit is better (post_residual already does this).

    // --- 2-step lookahead core ---
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            // Reward chains: this bin can also host the next item.
            // Reward grows when the chain is tight (little slack after both).
            let chain_slack = post_residual as f64 - next_item_size as f64;
            score -= 8.0 + 0.35 * chain_slack;
            // Perfect two-item packing bonus.
            if chain_slack == 0.0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here; penalize more if the leftover is
            // small dead space that no other item can use.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 4.0 * (10.0 - dead);
            } else {
                score += 2.0;
            }
            // If next item is large relative to capacity, opening a fresh bin
            // that can host both may be wiser.
            let next_big = (next_item_size as f64) > 0.5 * bin_capacity as f64;
            if next_big && bin_residual == bin_capacity {
                score -= 10.0;
            }
        }
    } else {
        // Last item: just minimize residual (already done).
        score -= 2.0;
    }

    // --- Mean residual coupling ---
    // Prefer bins whose residual is below the mean (i.e., tighter bins),
    // keeping loose bins available for larger future items.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.15 * (residual_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - residual_f);
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin.
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; make it unattractive unless the
        // lookahead strongly favors it (handled above via next_big bonus).
        score += 20.0;
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Slight preference for consolidating when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 12.0;

    // Penalize leaving awkward dead space (small but unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // Next item won't fit here: penalize slightly more if it creates dead space.
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default neutral-competitive; discourage unless open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 - pressure * 10.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (balance load, keep big gaps alive).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // Slight bonus for using bins that are already fairly full (compaction).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = post / capacity;

    // Base: prefer small post-residual, with non-linear tightening over stream progress
    let mut score = post * (1.0 + 1.5 * progress * fit_ratio);

    // Penalize dead space quadratically as stream advances
    score += 8.0 * progress * fit_ratio * fit_ratio * capacity;

    // Reward tight fits via smooth coupling of item size and residual
    let fill = item_size as f64 / capacity;
    score -= 10.0 * fill * fill * (1.0 - fit_ratio);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(3.0);
        score += 12.0 + 6.0 * progress - 2.0 * crowd;
    }

    // Lookahead: bonus if post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - progress) + 3.0 * (next_item_size as f64 / capacity);
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    // Residuals that are near-useless (tiny slivers) are heavily penalized.
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows quadratically as residual shrinks below 20
        if pr < 20 {
            score += ((20 - pr) as f64) * ((20 - pr) as f64) * 0.15;
        }
        // modulo classes: residuals divisible by 10 pair well with the size grid
        let m = pr % 10;
        if m != 0 {
            score += m as f64 * 0.4; // off-grid residual is harder to fill
        }
        // quarter-capacity harmonic classes: 0,25,50,75 residuals are "clean"
        let q = pr % 25;
        if q == 0 {
            score -= 3.0;
        } else if q >= 20 {
            score += 2.5; // just above a quarter boundary: awkward
        }
    } else {
        score -= 12.0; // perfect fill: best possible outcome
    }

    // Tight-fit reward: item consumes most of the bin
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.75 {
        score -= 6.0 * fill_ratio;
    }

    // Last-chance bonus: only one open bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual we abandon.
    if bin_residual == bin_capacity {
        // Opening fresh is good only if existing residuals are all too small
        // relative to the item and mean residual is fragmented.
        let waste = mean_residual - item_size as f64;
        if waste > 0.0 && fitting_bins_count > 0 {
            // some bin fits but poorly: new bin costs a lost mean_residual
            score += waste * 0.5 + 5.0;
        } else {
            score += 15.0; // default: prefer reusing open bins
        }
        // late in the stream, avoid spawning many half-empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
        if open_bins_count == 0 {
            score -= 30.0; // must open the first bin
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here: residual may become dead space
        score += 0.03 * post_residual as f64;
    }

    // Prefer filling bins with larger residuals when many bins are open (balance)
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no item (min size 1..100, but
    // practically small) can use are pure waste. Penalize tiny gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Gaps that can still hold the lookahead item are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild dead-space penalty scaled by gap.
        score += (post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Tight fit reward: item filling most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * fill * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin opening) unless this is the only fitting bin.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base cost plus pressure from open bins.
        score += 10.0 + open_bins_count as f64 * 4.0;
        // But if existing bins would leave a tiny unusable gap, new bin is attractive;
        // new bin has huge residual, so its raw score is already high — offset a bit
        // when the stream is early and bins are few.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 25.0;
    }

    // Mild preference for bins below mean residual (keeps residual spread tight).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect 2-step match is a huge reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // bin becomes exactly full after next item
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0; // near-perfect match
        } else if post_residual < next_item_size {
            // Dead space: next item cannot use this residual
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        } else {
            // Next item fits, but leaves further residual: mild reward scaled by closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack / 10.0);
        }
    } else {
        // Last item: prefer tightest fit only
        score += 0.0;
    }

    // Compare residual against mean residual across open bins.
    // A bin with residual well below mean is "tight" — using it consolidates space.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent,
    // but allow it when the current bin's post-fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // New bin is attractive only if item is large relative to capacity
            // and post residual would be small (efficient fresh packing).
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score -= 15.0 * tightness;
            score += 5.0; // base reluctance to fragment across bins
        } else {
            score -= 100.0; // must open first bin
        }
    }

    // Slight progression bonus: late in stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: the fuller the bin becomes, the lower the score.
    score -= 8.0 * (1.0 - post_residual as f64 / cap);

    // Penalize creating dead space: if the lookahead item cannot use the leftover,
    // this residual is likely wasted forever.
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 0.6 * post_residual as f64;
    } else if next_item_size > 0 {
        // Lookahead synergy: next item can still land here.
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins with slack: mild pressure to consolidate into existing bins.
    score += 0.05 * open_bins_count as f64;

    // Coupling with global state: penalize bins whose post-residual deviates
    // strongly from the mean residual (encourages homogeneous, reusable slack).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: default is expensive; only attractive when the item
    // is large and would leave almost nothing usable anywhere else.
    if bin_residual == bin_capacity {
        let mut new_score = cap * 1.25 + 0.5 * open_bins_count as f64;
        if item_size >= 60 {
            new_score -= 20.0; // big items open fresh bins more readily
        }
        if fitting_bins_count > 0 && (bin_residual - item_size) >= 30 {
            new_score += 15.0; // existing bins would still keep usable slack
        }
        score = new_score;
    }

    // Dynamic time horizon: late in the stream, slightly tighten preferences
    // (less tolerance for slack, since fewer items remain to fill it).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling between post_residual and stream progress.
    let x = pr / cap; // normalized post-residual in [0,1]
    let t = progress;
    // Quadratic dead-space penalty grows with progress: tight fits matter more late.
    score += 12.0 * (1.0 - x) * (1.0 - x) * (0.5 + t);
    // Cubic coupling: reward small post-residuals increasingly as stream advances.
    score -= 20.0 * (1.0 - x) * x * x * (0.3 + 0.7 * t);
    // Quartic term: strongly discourage leaving mid-range awkward residuals.
    score += 8.0 * 16.0 * x * x * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item can use the post-residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64) / pr.max(1.0);
        score -= 10.0 * fit_quality * (1.0 - fit_quality) * 4.0 * (0.5 + t);
    } else if next_item_size > 0 {
        // Next item cannot fit in the residual: penalize proportional to wasted opportunity.
        score += 6.0 * (1.0 - x) * (0.5 + t);
    }

    // Mild penalty for opening a new bin when many bins are open (encourage consolidation).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins below mean residual (balance load smoothly).
        score += 0.05 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Class the leftover space by which "harmonic slots" (capacity fractions) it can host.
    // C=100 nominal, but bin_capacity given for generality.
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Fractional fill of the bin after placement: near 1.0 is a tight, good fit.
    let fill = 1.0 - post / c; // in (0,1]

    // Reward high fill with a harmonic (quadratic) bonus.
    score -= 60.0 * fill * fill;

    // --- Integer-division thresholds on post_residual ---
    // Residual classes: dead zones where few item sizes (1..=100) can still fit.
    // If post_residual < 25, only small items fit -> strong dead-space penalty.
    let dead = (post_residual < 25) as i32 as f64;
    score += 18.0 * dead * (1.0 - fill); // only penalize if fill wasn't already near-perfect

    // Mid residual band 25..=49: exactly one "half-class" slot; mild penalty.
    if post_residual >= 25 && post_residual < 50 {
        score += 6.0;
    }
    // Sweet spot 50..=74: can host half-capacity items; small reward.
    if post_residual >= 50 && post_residual < 75 {
        score -= 5.0;
    }

    // --- Lookahead: can the next item land in the leftover? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic continuation: next item exactly fills a slot class.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / c);
            // Exact match (next item consumes the residual entirely) -> jackpot.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional to waste potential.
            score += 0.15 * (next_item_size as f64 - post);
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is huge (fits > half)
        // and would leave a very awkward residual in existing bins.
        let big_item = item > 0.5 * c;
        if big_item {
            score -= 10.0; // fresh bin for a big item is reasonable
        } else {
            score += 40.0; // discourage opening new bins for small/medium items
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress) * (big_item as i32 as f64);
    }

    // --- Mean residual coupling: when open bins are generally full, keep them tight ---
    let mean_gap = (mean_residual - post).abs();
    score += 0.05 * mean_gap;

    // --- Modulo arithmetic on post_residual: residuals divisible by common item
    //     granularities (10s) are more reusable ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Lookahead: if next item fits the post residual exactly, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        // Dead space unusable by next item: extra penalty.
        score += 10.0;
    }

    // New-bin candidate: only attractive when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; scale with stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + 10.0 * progress;
        // If this bin is the only fitting option, opening is acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // High open-bin pressure makes new bins less attractive.
        score += 3.0 * open_bins_count as f64;
    }

    // Slight nudge toward bins below mean residual (more filled bins).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin normally.
        score += 60.0;
        // But if this is the only fitting bin, opening fresh is often better.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // If the item leaves a tiny dead space in any existing bin, prefer new bin.
        if post_residual < 10 {
            score -= 30.0;
        }
        // Late in stream, avoid opening bins.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * progress;
        return score;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            // Reward tight chains; penalize loose ones.
            score -= 60.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
            // Bonus if the chain leaves an exact fit afterward too.
            if post_residual - next_item_size >= 10 || post_residual - next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use the post residual: dead space risk.
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable residuals relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.4 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
        // Extra reward if the fit is tight.
        if post_residual <= 15 {
            score -= 30.0;
        }
    }

    // Prefer filling bins that are already below mean residual (consolidating).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 60 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio over the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract proportionally for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        // Reward chaining, stronger late in the stream when bin economy matters.
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving dead space the next item cannot use.
        let dead = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
        score += 0.05 * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates from the mean (avoid fragmentation outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: bin_residual == bin_capacity means an empty bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 20.0 + 3.0 * open_bins_count as f64;

        // If few bins can fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 18.0;
        }

        // Early in the stream, opening bins is cheaper; late, consolidate.
        new_bin_penalty *= 1.0 - 0.4 * progress;

        // If the next item would fit nicely in the fresh residual, soften the penalty.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            new_bin_penalty -= 4.0;
        }

        score += new_bin_penalty;
    } else {
        // Slight preference for reusing already-open bins, scaled by open count pressure.
        score -= 1.0 + 0.2 * open_bins_count as f64;
    }

    // Waste-avoidance: penalize residuals too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convexity
    // so that very small residuals are rewarded super-linearly.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Stream-progress coupling: as the stream advances, dead space becomes
    // more costly (fewer future chances to fill it), so scale the base
    // penalty smoothly with progress.
    score += (0.4 + 1.2 * progress) * (pr * pr) / cap;

    // Interaction with mean residual: placing into a bin whose residual is
    // far from the mean residual is penalized quadratically (keeps the bin
    // pool homogeneous, improving future packing), scaled by progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (0.5 + 1.0 * progress) * dev * dev * cap * 0.25;

    // Lookahead coupling: reward leaving a residual that can still host the
    // next item (smooth kernel over the gap between post_residual and next).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (-gap * gap / (2.0 * 9.0 * 9.0)).exp();
        score -= 3.0 * fit_kernel * (1.0 + progress);
        // Penalize post_residual that is small but just below next item size
        // (unusable dead space for the lookahead).
        if pr < next_item_size as f64 {
            score += 0.6 * (next_item_size as f64 - pr) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (smoothly decaying with more fitting bins).
    if fitting_bins_count >= 1 {
        score -= 2.5 / (fitting_bins_count as f64).powf(1.3);
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity, hence
    // a large post_residual already; add an extra opening cost that shrinks
    // with progress (late in the stream, reusing bins is cheaper) and grows
    // with the number of open bins.
    let is_new = (bin_residual as u64) == (bin_capacity as u64);
    if is_new {
        score += 4.0 + 0.15 * (open_bins_count as f64) * (1.0 - progress) + 2.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more strongly when many are open.
        score -= 0.05 * (open_bins_count as f64).min(20.0);
    }

    // Mild overall preference for bins with larger residuals (big holes first),
    // smoothly interpolated with progress.
    score -= (0.3 + 0.4 * progress) * (bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead space classification ---
    // Class boundaries at capacity fractions 1/4, 1/2, 3/4
    let q1 = bin_capacity / 4;      // 25
    let q2 = bin_capacity / 2;      // 50
    let q3 = 3 * bin_capacity / 4;  // 75

    // Dead space: post_residual too small to ever fit another item (min size 1,
    // but tiny residuals are nearly unusable) -> heavy penalty, worse the smaller.
    if post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual < 20 {
        // "awkward" class: fits only very small items
        score += 25.0;
    } else {
        // Harmonic reward: residual that is an exact divisor-class match
        // for common item sizes is more reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 12.0; // aligns with decadal item sizes
        } else if r % 5 == 0 {
            score -= 5.0;
        }
        // Quarter-class alignment bonus
        if r == q1 || r == q2 || r == q3 {
            score -= 8.0;
        }
    }

    // Perfect fit
    if post_residual == 0 {
        score -= 200.0;
    }

    // --- Lookahead coupling: does next_item_size fit in post_residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus, stronger the tighter the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
            // Harmonic chain: next item exactly consumes the rest
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by waste class
            score += 10.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing open bins are
        // heavily fragmented (high mean residual relative to capacity) or
        // the current item is large and would leave good residual structure.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 70.0; // base cost of opening a new bin
        if fragmentation > 0.5 {
            score -= 40.0 * (fragmentation - 0.5);
        }
        if item_size >= 70 {
            score -= 20.0; // large items start fresh bins cleanly
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 10.0;
        }
    } else {
        // Slight preference for fuller bins (best-fit flavor beyond raw post_residual)
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 15.0 * fill;
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (min item size is 1, but tiny gaps below the typical item mass are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating unusable slivers
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Penalize leaving a gap that exactly (or nearly) matches the next item only mildly;
    // reward reserving space when the next item fits snugly into the post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; // this bin remains useful for the lookahead item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate, whose residual == capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + 12.0 * open_bins_count as f64;
    } else {
        // Slight bonus for using an existing bin, scaled by open bin count.
        score -= 4.0 + 0.8 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins fill first),
    // keeping larger residual bins available for larger future items.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();

        // Perfect 2-step match: big bonus
        if diff < 0.5 {
            score -= 40.0;
        } else if pr >= nr {
            // Item fits next too: bonus scaled by tightness of match
            score -= 15.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // Dead space: post_residual too small for next item -> penalize
            // Especially bad if dead space is large (unusable gap)
            let dead = nr - pr;
            score += dead * 0.6;
        }
    }

    // Penalize post_residual that is small but nonzero (hard-to-fill slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin before opening a new bin: favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins score badly.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.5;
        // If lookahead has no match anywhere, new bin is fine; if next item huge, discourage
        if next_item_size as f64 > bin_capacity as f64 * 0.8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to item size is good.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness;

    // Penalize creating dead space: post_residual too small for any future item (1..=100).
    if post_residual < 1 {
        score -= 25.0; // perfect fill, excellent
    } else if post_residual < 10 {
        score += 30.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0;
        // Extra reward if next item nearly fills the remainder too.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item would have fit if we didn't place here; slight penalty.
        score += 6.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when current bin fit is poor (large post_residual)
        // or when this is the last-chance bin is irrelevant (new bin always "fits").
        let waste = post_residual as f64; // = bin_capacity - item_size for new bin
        // Penalize new bins generally; allow opening when item is huge (small waste).
        score += 22.0 + 0.35 * waste;
        // Early in stream, opening extra bins is cheap (more options later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage proliferation.
        score += 0.8 * open_bins_count as f64;
    } else {
        // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins with residuals below the mean (consolidate emptier space elsewhere).
        score += 0.25 * (mean_residual - bin_residual as f64);
        // Slight preference for using fuller bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space becomes exponentially worse as it grows
    let waste_norm = post / cap;
    score += 40.0 * waste_norm * waste_norm * (1.0 + 2.0 * progress);

    // Reward tight fits: smooth polynomial bonus peaking at post_residual near 0
    let tightness = 1.0 - waste_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // Mild penalty when many bins compete, to prefer better packing elsewhere
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post_residual - next_item_size;
        let gap_norm = gap as f64 / cap;
        score -= 15.0 * (1.0 - gap_norm) * (1.0 - gap_norm);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to leftover waste
        score += 8.0 * waste_norm;
    }

    // Stream-progress coupling: late in stream, consolidate into fewer bins
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    score += 5.0 * consolidation * (0.3 + progress);

    // Deviation from mean residual: prefer bins whose residual matches the mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current fits are very poor
    if bin_residual == bin_capacity {
        score += 45.0 - 10.0 * progress + 3.0 * (open_bins_count as f64);
        if fitting_bins_count <= 1 && item_size > 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual ---
    // Classify leftover space into residue classes modulo 10 (harmonic granularity).
    let r_mod = post_residual % 10;
    // Residuals that are "dead" (too small for the smallest plausible item) are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 80.0; // perfect closure
    } else {
        // Prefer residuals that are themselves plausible item sizes (harmonic alignment).
        if post_residual >= 10 && post_residual <= 80 {
            score -= 25.0;
        }
        // Penalize awkward remainders: mod classes 1..4 are hard to fill.
        match r_mod {
            0 => score -= 12.0,
            1 | 2 | 3 | 4 => score += 18.0,
            5 | 6 => score += 6.0,
            _ => {}
        }
    }

    // --- Fit tightness: reward filling a large fraction of the bin ---
    let fill_ratio = item_size as f64 / cap;
    score -= 40.0 * fill_ratio;

    // --- Lookahead coupling (k=2): can next item also land here? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Pairing possible: reward if combined fill is near-harmonic (sum mod 10 == 0)
            let sum = item_size + next_item_size;
            if sum % 10 == 0 {
                score -= 30.0;
            }
            // Reward proportionally to how well next item nests
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize more if this bin's residual is stranded
            score += 8.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large post_residual waste) or when many bins are already open and fragmented.
        score += 55.0;
        if post_residual >= 90 {
            // item nearly fills a fresh bin entirely -> good
            score -= 60.0;
        }
        // Late in the stream, discourage proliferation of barely-used bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If current bin would leave a tiny dead space, opening fresh is competitive
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    }

    // --- Fragmentation pressure: many open bins with high mean residual ---
    score += 0.15 * open_bins_count as f64;
    score += 0.10 * (mean_residual - (post_residual as f64)).max(0.0);

    // --- Integer-division threshold: quantize residual into fifths of capacity ---
    let fifth = bin_capacity / 5; // 20
    if post_residual >= fifth && post_residual < 2 * fifth {
        score -= 10.0; // residual in [20,40) is a sweet spot for mid-size items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Medium-small gaps are mildly penalized (hard to fill later).
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 10.0 * pressure;

    // If this bin can also host the next item well, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mean-residual coupling: penalize bins far below mean residual (fragmenting).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: base cost of opening a bin, discounted early and when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();

        // Perfect 2-step match: strongly reward (subtract).
        if diff == 0.0 {
            score -= 60.0;
        } else if post >= next {
            // Next item fits after this placement: mild reward proportional to tightness.
            let tight = 1.0 - (post - next) / bin_capacity as f64;
            score -= 20.0 * tight;
        } else {
            // Next item will NOT fit in this bin afterwards: penalize wasted lookahead.
            score += 10.0 * (next - post) / 100.0;
        }

        // Penalize leaving dead space that neither next item nor typical items can use.
        if post < next && post > 0 {
            score += 0.5 * post;
        }
    }

    // Compare post_residual against mean residual across open bins.
    let cap = bin_capacity as f64;
    let mean_gap = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * mean_gap;

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Favor bins that become nearly full (small usable residual left).
    let post = post_residual as f64;
    if post <= 10.0 {
        score -= 30.0; // tiny residual => effectively closed bin, great outcome
    } else if post <= 20.0 {
        score -= 12.0;
    }

    // Early in the stream: slight preference for packing into existing bins
    // to keep bin count low; late in stream, trust the lookahead more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when item truly fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral residual, penalized so it's chosen only
        // when lookahead/dead-space penalties make open bins worse.
        score = 0.5 * bin_capacity as f64 + 0.4 * (item_size as f64);
        if next_item_size > 0 {
            // If next item could combine with current item in the new bin, reward.
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
        if fitting_bins_count == 1 {
            score += 20.0; // discourage abandoning the last fitting open bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1..=10) is nearly unusable.
    let dead = post_residual.min(10) as f64;
    score -= 2.5 * (post_residual as f64).sqrt();
    score += 6.0 * dead;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
            // Penalize leaving residual just barely too small for next item.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 10.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    // (fragmentation control): favor bins below mean residual (tighter bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate handling: opening a bin is fine early or when
    // nothing fits well; penalize it otherwise.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        } else {
            // Base cost of a new bin, softened late in the stream.
            score += 45.0 - 25.0 * progress;
            // If the best existing fit would be terrible (huge post residual),
            // opening fresh is more acceptable.
            if post_residual > 55 {
                score -= 20.0;
            }
        }
    }

    // Mild preference for consolidating into fewer bins overall.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Slight time-decay urgency: as stream ends, waste matters more.
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr * pr * (1.0 + progress) + pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post residual), scaled by how crowded bins are.
    let tight = (1.0 - pr).powi(3);
    score -= 10.0 * tight;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 == pr * cap {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here anyway; dead space is less costly, mild penalty if huge.
        score += 4.0 * pr;
    }

    // New-bin candidate: prefer it only when item fits poorly in existing bins.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs() / cap;
        score += 20.0 - 15.0 * spread - 5.0 * progress;
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    // Penalize bins far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes by capacity fraction.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class boundaries: dead space is residual that cannot fit typical items.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable dead space (min item is 10 in classic setting, but sizes 1..100 here).
        score += 15.0 * (1.0 - post_f / 10.0);
    } else if post_residual <= 25 {
        // Small leftover: only useful for tiny items; mild penalty.
        score += 4.0;
    } else if post_residual <= 50 {
        // Mid class: decent leftover.
        score -= 3.0;
    } else {
        // Large leftover: very desirable.
        score -= 8.0;
    }

    // Integer-division harmonic class: post_residual / 10 bucket.
    let post_class = post_residual / 10;
    score -= match post_class {
        0 => 2.0,
        1 => 0.0,
        2 => 1.0,
        3 => 2.5,
        4 => 3.5,
        _ => 5.0,
    };

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: reward, scaled by how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 4.0 * (1.0 - slack / cap_f);
        } else {
            // Next item won't fit here: penalize wasting this bin's future.
            let gap = (next_item_size - post_residual) as f64;
            score += 2.0 * (gap / cap_f).min(1.0);
            // If next item is small relative to capacity, leaving large residual is fine anyway.
            if post_residual > 60 {
                score -= 2.0;
            }
        }
    } else {
        // Last item: prefer zero residual.
        score += post_f * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Open a new bin when the item fits poorly in existing bins (large post residual elsewhere
        // would be wasted anyway) or when many bins are open and mean residual is fragmented.
        let fragmentation = if open_bins_count > 0 { mean_residual / cap_f } else { 0.0 };
        // If item is large, filling a fresh bin is efficient.
        if item_size as f64 / cap_f > 0.6 {
            score -= 20.0;
        }
        // If existing bins are highly fragmented (high mean residual), a new bin is less costly.
        if fragmentation > 0.5 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 15.0 * progress;
        }
        // If next item is large and this item is small, better to keep current bins for it.
        if next_item_size > 50 && item_size < 30 {
            score -= 8.0;
        }
    } else {
        // Reward using existing bins: prefer fullest bins (tightest fit).
        let fill = 1.0 - (bin_residual as f64) / cap_f;
        score -= 5.0 * fill;
        // Prefer bins whose residual is "harmonically compatible" with item size:
        // residual mod item small means item divides residual nicely.
        if item_size > 0 {
            let m = bin_residual % item_size;
            score -= 3.0 * (1.0 - m as f64 / item_size as f64);
        }
        // Slight penalty for spreading across many open bins when residuals are similar.
        if (bin_residual as f64 - mean_residual).abs() < 5.0 {
            score += 1.5;
        }
    }

    // Global tie-breaker: keep total residual variance low (prefer bin closest to mean).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_zone = 12.0;
    if (post_residual as f64) < dead_zone {
        score += 60.0 * (dead_zone - post_residual as f64);
    } else {
        // Reward tight fits (small but usable residual) super-linearly.
        score -= 45.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(8);
    }

    // Perfect or near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / (bin_capacity as f64)).powi(3);
        } else {
            // Next item won't fit here; penalize leaving medium gaps that trap it.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 30.0 {
                score += 25.0 * (1.0 - gap / 30.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage proliferation of bins, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 6.0 * progress);

    // Prefer bins tighter than the mean residual (consolidate fullness).
    score += ((mean_residual - bin_residual as f64) * 0.35).max(-30.0).min(30.0);

    // New-bin candidate: baseline attractiveness so it is chosen only when
    // open bins offer genuinely poor fits (their scores must beat this).
    if bin_residual == bin_capacity {
        score = 90.0 + (open_bins_count as f64) * 0.5 - 10.0 * progress;
        if post_residual == bin_capacity {
            // Item is huge relative to capacity; new bin is natural.
            if item_size as f64 > 0.6 * bin_capacity as f64 {
                score -= 40.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 20.0;

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits here: mild reward proportional to how well it fills remainder
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fill;
    } else if next_item_size > 0 {
        // next item won't fit in the leftover: penalize wasted capacity
        score += 0.2 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Relative to mean residual: prefer bins whose post_residual is near/below mean
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize creating tiny dead space (<10) that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: baseline so it's chosen only when open bins look bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Exact-ish follow-up fit is very valuable.
            let gap = (post - nxt).abs();
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            let waste = post / cap;
            score += 6.0 * waste * waste;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to encourage diversity of residual sizes.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state coupling: if mean residual is high, bins are generally loose;
    // prefer consolidating into bins below the mean (avoid fragmentation).
    let diff = mean_residual - post;
    score += 0.05 * diff;

    // Time horizon: early in the stream, be conservative (prefer tight fits,
    // penalize loose placements more); late in stream, prioritize just fitting.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let early = (1.0 - t).clamp(0.0, 1.0);
    score += 8.0 * early * (post / cap);

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else. Empty bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Opening is more attractive if this bin's post residual would be tiny
        // (near-perfect new-bin fit) or if there are no alternatives.
        if post_residual <= 5 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, opening new bins is cheaper than wasting space.
        score -= 10.0 * t;
        // If many open bins with large mean residual, avoid adding another.
        if mean_residual > item && open_bins_count > 2 {
            score += 8.0;
        }
    }

    // Small nudge toward bins with residual close to item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item).abs();
    score += 0.02 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress * 2.0) - norm_pr * progress;

    // Reward tight fits, scaled by stream position
    let tight_fit = (1.0 - norm_pr) * (1.0 - progress);

    // Penalize dead space that next item could not use
    let dead = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        gap * gap * (0.5 + progress)
    } else {
        pr / cap * 0.25
    };

    // Last-chance bonus when few fitting bins
    let last_chance = if fitting_bins_count <= 1 { -3.0 } else { 0.0 };

    // Mild penalty for spreading across many open bins
    let spread = open_bins_count as f64 * 0.01 * norm_pr;

    let mut score = pr + poly * cap * 0.5 - tight_fit * cap * 0.3 + dead * cap - last_chance + spread;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarters of capacity
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    let class_center = (class * quarter + quarter / 2) as f64;

    // Reward residuals close to class centers (harmonic buckets)
    let deviation = ((post_residual as f64) - class_center).abs();
    score += deviation * 0.3;

    // Reward leaving a residual that exactly fits the next item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score -= 25.0;
    }

    // Penalize dead space that can never fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Tight fit reward: small post_residual is good, especially tiny remainders
    if post_residual <= 10 {
        score -= 35.0;
    }

    // Modulo-based harmony: residuals that are multiples of common item sizes are reusable
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else {
        score += mod10 as f64 * 0.4;
    }

    // Penalize opening a new bin when plenty of open bins exist with room
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // But opening a fresh bin is good early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Slight pull toward bins below mean residual (balance load)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver, essentially unusable
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Gap can't fit the lookahead item: dead space penalty scaled by gap smallness.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (i.e., penalize the empty new-bin candidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: opening a new bin should only win when the item leaves a
    // clean, usable residual (e.g., exact fill or large residual) and current bins
    // are already tight. Penalize new bins otherwise.
    if bin_residual == bin_capacity {
        // Base penalty comparable to a mediocre existing fit.
        score += 20.0 + 0.3 * open_bins_count as f64;
        // Exact/near-exact fills from a fresh bin are excellent: reward.
        if item_size >= bin_capacity - 10 {
            score -= 90.0;
        }
        // If no open bin can fit and mean residual is small, new bin is justified.
        if fitting_bins_count == 0 || mean_residual < (item_size as f64) * 0.3 {
            score -= 45.0;
        }
    }

    // Mild preference for bins whose residual deviates below the mean (tighter bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight global bias toward minimizing post residual over the stream.
    score += 0.05 * post_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(4);

        // Perfect chain: item fits now, next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 100.0;
        }
        // Next item can't fit in the leftover: penalize dead space creation.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: tightest fit wins.
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin for one item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else is viable.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Slight early-stream conservatism: keep flexibility when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty for post-residual waste.
    score += 0.6 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (creates a chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use leftover space: penalize large dead space more.
            score += 0.3 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates above the mean (they are "loose").
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Early in the stream, encourage opening fresh bins for large items
    // (keeps flexibility); late in the stream, pack tightly into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (30.0 - 40.0 * progress);

    // Prefer filling bins that are already mostly full (small residual).
    score += 0.15 * (bin_residual as f64);

    // With many open bins, mildly discourage spreading; consolidate.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, weighted more as the stream progresses
    // (late in the stream, residual space is less likely to be filled).
    let mut score = post * (0.8 + 0.6 * progress);

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill = (cap - post) / cap;
    score -= 30.0 * fill * fill;

    // Smooth non-linear coupling: quadratic penalty on post_residual relative
    // to capacity, growing with progress (dead space hurts more late).
    let dead_frac = post / cap;
    score += 40.0 * dead_frac * dead_frac * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward placements whose post-residual can still host the
    // next item (smooth interaction with progress).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_margin = (post - nxt) / cap;
            score -= 12.0 * (1.0 - fit_margin) * (0.6 + 0.4 * progress);
        } else {
            // Smooth penalty for residual that cannot host the next item,
            // scaled by how much it misses.
            let miss = (nxt - post) / cap;
            score += 15.0 * miss * (0.5 + progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual differs from the mean
    // in a way that consolidates space (smooth quadratic term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the fit is very poor (handled by dead-space terms above).
    if bin_residual == bin_capacity {
        score += 20.0 * (0.7 + 0.3 * progress);
    }

    // Open-bin count pressure: many open bins -> favor consolidation.
    score += (open_bins_count as f64).sqrt() * 0.5 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (<10, or below half the smallest plausible item) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus per-open-bin pressure.
        score += 40.0 + 3.0 * open_bins_count as f64;
        // But if the next item would fit nicely in a fresh bin while current residuals
        // are fragmented, opening can be attractive: slight discount.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is close to the item (efficient packing).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * tightness;
        // If next item fits exactly in post_residual, bonus for preserving that opportunity.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving a gap the next item cannot use.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Mild stream-position term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item still fits in the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }
    // Dead space: leftover smaller than the smallest plausible item (1..100 unknown, use small floor)
    if post_residual < 10 {
        score -= 20.0; // small leftover is fine, it's nearly a perfect fill
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover can't host the next item: penalize proportional to wasted space
        score += 0.8 * (post_residual as f64).powf(1.3);
    }

    // Compare against mean residual: filling a bin far below mean residual is good (reduces spread).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual is huge, so add a fixed opening cost
        // unless current bin residuals are too fragmented to help.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits elsewhere: new bin is mandatory
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If mean residual comfortably fits the item, opening new bins is wasteful.
        if mean_residual >= item_size as f64 {
            score += 80.0;
        }
    }

    // Mild bonus for tighter fits overall (relative waste).
    score += 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Penalize dead space: residuals too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item exactly/nearly fills the resulting residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap <= 10 {
            score -= 10.0;
        }
    }
    // Lookahead: if next item cannot fit the post residual, slight penalty (bin becomes dead)
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when existing bins can fit the item
        score += 5.0 + 3.0 * fitting_bins_count as f64;
        // But if this item is large (would leave little waste anyway), new bins are cheap
        if item_size >= 60 {
            score -= 8.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If current open bins are heavily fragmented (high mean residual), a fresh bin is fine
        if mean_residual > 50.0 {
            score -= 6.0;
        }
    }

    // Mild preference for bins whose residual deviates favorably from the mean
    score -= 0.03 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_it = it / cap;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 30.0 * norm_it * (norm_it - norm_pr) * (0.5 + progress);

    // Reward near-perfect fits smoothly (dead-space avoidance)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize opening a new bin, more so as the stream progresses
    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score += 55.0 + 45.0 * progress + 8.0 * open_pressure;
        // But soften penalty if item is large relative to mean residual (poor fit elsewhere)
        let poor_fit = ((mean_residual - it) / cap).max(0.0);
        score -= 70.0 * poor_fit * (0.5 + progress);
    }

    // Lookahead coupling: favor bins whose post-residual can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 20.0 * gap * gap;
        }
    }

    // Mild preference for bins deviating from mean residual (consolidation)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space below 20 is nearly unusable
    // for typical items (10..80 interface: min item 1, but bulk of mass >= 10).
    let pr = post_residual as f64;

    // Penalize small unusable leftovers strongly (harmonic classes).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // dead space class [1..9]
    } else if post_residual < 20 {
        score += 12.0; // class [10..19]: only fits tiny items
    } else if post_residual < 30 {
        score += 5.0;  // class [20..29]
    } else if post_residual < 50 {
        score -= 4.0;  // mid class: still quite reusable
    } else {
        score -= 8.0;  // large residual: very reusable
    }

    // Modulo-10 harmonic coupling: residuals that are multiples of 10 align with
    // the classical item grid, making them more valuable.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            score += 4.0 * (next_item_size as f64 - pr).min(30.0) / 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over
    // opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // mediocre default so it only wins when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + mean_residual * 0.2;
        // late in the stream, slightly discourage opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 8.0; // some bin fits: new bin should lose
        }
        return score;
    }

    // Prefer filling tighter (fuller) bins among fitting ones: reward low residual
    // before placement relative to mean.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference to keep number of open bins small.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can no longer fit a
    // "typical" small item (say < 20) are near-useless -> heavy penalty.
    let dead = post_residual < 20;
    if dead {
        // Penalty grows the smaller the gap is relative to capacity.
        score += 40.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: post_residual close to zero is great,
    // but only if it is not a tiny unusable sliver.
    if post_residual == 0 {
        score -= 30.0; // perfect fit
    } else if post_residual <= 10 && !dead {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin should be penalized
    // mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item exactly fills a fresh bin, opening is fine.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // Lookahead: if next item could combine with this one's leftover,
        // opening a fresh bin is less attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than adding more.
    score += 0.3 * open_bins_count as f64;

    // Lookahead synergy: if placing here leaves room exactly for the
    // next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong preference for exact/near-exact fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            if diff < 1.0 {
                score -= 500.0;
            } else if diff <= 10.0 {
                score -= 200.0 - 10.0 * diff;
            } else {
                score += 0.5 * diff;
            }
        } else {
            // next item cannot fit here; penalize proportional to wasted potential
            score += 0.3 * nxt;
        }
    }

    // Penalize small unusable residuals relative to mean residual
    let mean_r = mean_residual.max(0.0);
    if post < 10.0 && post > 0.0 {
        score += 150.0;
    }
    score += 0.4 * (post - mean_r).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let good_fit = post <= 10.0 || (next_item_size > 0 && post_residual == next_item_size);
        score += if good_fit { 50.0 } else { 400.0 };
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for tighter bins early in stream
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= 20.0 * tightness;

    // Slight preference for more-filled bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post-residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine (unusable anyway)
    } else if post_residual >= 10 && post_residual <= 40 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 30.0);
    }

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // the item fits poorly everywhere else or many bins are already tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight_world = (mean_residual / bin_capacity as f64).min(1.0);
        // Base cost of opening a new bin, discounted by scarcity and progress.
        score += 55.0 - 45.0 * scarcity - 20.0 * tight_world - 10.0 * progress;
    }

    // Lookahead: if the next item would fit exactly into this bin's post-residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty if gap is tiny
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 5.0;
            }
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - fit_ratio.min(1.0));

    // Prefer filling bins with larger residuals when many bins are open
    // (reduces bin count pressure).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty for very large post residual relative to capacity.
    score += 0.05 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item / cap;

    // Base: tight fill reward (low post_residual preferred, non-linearly)
    let mut score = (post / cap).powi(2) * 60.0 + post * 0.35;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, squeeze harder into existing bins.
    let progress_coupling = (post / cap) * (1.0 - progress).powi(2) * 25.0;
    score -= progress_coupling;

    // Cubic interaction: penalize mid-range post_residual dead space more as stream progresses
    let dead = (post / cap) * (1.0 - post / cap);
    score += dead.powf(1.5) * (30.0 + 40.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item could use this post_residual, reward leaving that exact room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= (1.0 - gap * 4.0).max(0.0) * 12.0;
        } else {
            score += (nxt - post) / cap * 15.0;
        }
    }

    // Divergence from mean residual: prefer bins below mean (more filled)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 8.0 + dev.abs() * dev * 5.0;

    // Bin-count pressure: with many open bins, discourage fragmentation
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap) * 6.0;

    // New-bin candidate: penalize unless it is genuinely better than squeezing
    if bin_residual == bin_capacity {
        let squeeze_pain = (fit_ratio * fit_ratio * 70.0) + (post / cap) * 20.0;
        score = cap * 0.5 + squeeze_pain - (progress * 5.0);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "useful" sizes
    // (multiples of 10 and small leftovers that pair with common items)
    // are more valuable than awkward dead space.
    let r = post_residual;
    if r > 0 {
        let mod10 = (r % 10) as f64;
        // Penalize awkward residues (dead space that few items can use).
        score += mod10 * 0.6;
        // Harmonic classes: residual divisible by 10 is highly reusable.
        if r % 10 == 0 {
            score -= 6.0;
        } else if r % 10 == 5 {
            score -= 3.0;
        }
        // Integer-division thresholds on post_residual:
        // very small residuals (<10) are near-wasted space.
        if r < 10 {
            score += 12.0;
        } else if r < 20 {
            score += 5.0;
        }
        // Perfect-fit bonus: residual exactly matched by next item.
        if next_item_size > 0 && next_item_size == r {
            score -= 25.0;
        }
        // Next item fits the post-residual: strong reward (chaining).
        if next_item_size > 0 && next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        }
        // Next item slightly too large: mild penalty (blocked chain).
        if next_item_size > r && next_item_size - r <= 10 {
            score += 4.0;
        }
    } else {
        // Perfectly closed bin: best outcome.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Crowding: with many open bins, prefer tight packing of existing bins.
    if open_bins_count > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Progress-scaled preference: later in the stream, waste hurts more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * progress * 8.0;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth filling; if far above, it holds reusable space.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current placement would leave a bad class.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Open a new bin if the item fits terribly elsewhere (large post
        // residual in awkward harmonic class) or it's the very first item.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
        if step_index == 0 {
            score -= 100.0;
        }
        // With lookahead: opening fresh for a known-good chain.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are worthless.
    // Treat post_residual < 10 as "dead" and penalize heavily (strict archetype).
    if post_residual < 10 {
        // Perfect fill is great, otherwise dead space is heavily punished.
        score = if post_residual == 0 { -500.0 } else { 1000.0 + (10 - post_residual) as f64 * 50.0 };
    } else {
        // Prefer small but usable residuals: nonlinear coupling on usable gap.
        let gap = post_residual as f64;
        score += 0.8 * (gap / 10.0).powi(2);

        // Reward bins whose residual is "tuned" to common item sizes (10..80):
        // a residual exactly consumable by next item is excellent.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // next item cannot go here after placement; mild penalty proportional to waste
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }

        // Lookahead synergy: if the bin's CURRENT residual almost exactly fits next item
        // but current item barely fits, that's a fragile fit — slight penalty.
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 25.0; // leaves room for the lookahead item too
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // But if the current item is large relative to mean residual, new bin may be wise:
        if (item_size as f64) > mean_residual * 0.9 {
            score -= 90.0;
        }
        // Late in the stream, avoid proliferating bins for tiny leftovers.
        if step_index as f64 / total_items.max(1) as f64 > 0.8 && item_size <= 20 {
            score += 60.0;
        }
    } else {
        // Mild bonus for reusing bins that are already fairly empty of usable space.
        score -= 5.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Global residual balance: prefer placing into bins below mean residual
    // (consolidate waste into few bins rather than spreading it).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin closes exactly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item almost fills remaining space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    }
    // Next item cannot fit here: penalize tiny dead space (wasted capacity).
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 400.0 * (10.0 - dead);
        } else {
            score += 50.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer bins tighter than the mean residual (good fits among open bins).
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Penalize leaving very small unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (10 - post_residual) as f64;
    }

    // New-bin candidate: only attractive when current item is large and
    // no open bin offers a good fit; discourage otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.5 * bin_capacity as f64;
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if big_item && poor_fit {
            score -= 150.0 + 100.0 * progress;
        } else {
            score += 500.0;
        }
    }

    // Mild pressure to fill bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize dead space relative to the smallest plausible item (1..100 interface).
        // Small residuals that cannot hold a future item are waste; scale by fraction of capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste_frac * waste_frac;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Mild reward proportional to how well next item uses leftover space.
            let nxt_use = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nxt_use;
        } else {
            // Leftover cannot host next item: mild penalty, worse for tiny leftovers.
            let frac = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * (1.0 - frac);
        }
    } else {
        // Last item in stream: strongly prefer zero-waste bins.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins; encourage using fuller bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by existing slack in the system.
        let mut nb = 15.0;
        nb += 0.5 * mean_residual;
        nb += 2.0 * open_bins_count as f64;
        // If no open bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            nb -= 100.0;
        }
        score = score.max(nb);
    } else {
        // Prefer bins with residual below mean (fuller bins) to consolidate waste.
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (low post_residual); later,
    // slightly tolerate loose fits to keep options open.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * progress * 0.5;
    score += 30.0 * poly;

    // Reward very tight fits (small dead space), stronger late in stream.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 20.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // Next item won't fit here: penalize bins that strand the lookahead.
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: bins far below mean residual are
    // already tight; prefer spreading load smoothly.
    let dev = (mean_residual - post) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it moderately attractive early, less so late,
    // and unattractive when a last-chance open bin exists.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.35 * progress);
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits.
    score = post_residual as f64 * 1.0;

    // Harmonic class of the leftover: multiples of 10 (or small remainders)
    // are reusable by typical item sizes; odd residues create dead space.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0; // perfectly aligned leftover, highly reusable
    } else if residue_class <= 3 {
        score += 2.0 + 1.5 * residue_class as f64; // sliver -> dead space risk
    } else {
        score += 1.0;
    }

    // Big harmonic bonus: leftover exactly matches the next item size
    // or a harmonic fraction of capacity.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 8.0;
        } else if post_residual < next_item_size {
            score += 5.0; // leftover can't host the lookahead item
        }
        // Modulo harmony: leftover divisible by next item size
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 4.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer the emptiest bin? No —
        // minimize leftover waste by tightest fit overall.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: discourage spreading; prefer bins already partially filled
    // when mean residual is high (bins are fragmented).
    if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when it
    // beats poor fits. Score it relative to mean residual and stream position.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.55 - 15.0 * progress;
        // Avoid opening new bins when a good fit already exists elsewhere.
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= 60 {
            score += 10.0; // big item coming; keep fresh bin? mild penalty
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing fits: must open new bin
        }
    }

    // Integer-division thresholds: bins whose residual is in "useful" bands.
    let band = bin_residual / 25; // 0..4 harmonic band
    score -= band as f64 * 1.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item are wasted capacity.
    if post_residual > 0 {
        // Dead zone: gap that no item can realistically use.
        let dead_threshold = 12u32;
        if post_residual <= dead_threshold {
            score += 60.0 + (dead_threshold - post_residual + 1) as f64 * 4.0;
        } else if post_residual < 25 {
            // Semi-dead zone: only very small items fit; mild penalty.
            score += (25 - post_residual) as f64 * 1.5;
        }
    }

    // Reward tight fits: post_residual near zero is excellent (perfect fill).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next known item fits exactly-ish in the
    // resulting gap, this bin becomes more attractive.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0 - slack as f64;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin; strongly prefer it over a marginal fit elsewhere.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // encouraging consolidation into existing bins vs. opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Phase coupling: early in the stream, keep bins flexible (avoid leaving
    // awkward mid-sized gaps); late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 40 {
        score += (1.0 - progress) * 6.0;
    }
    if post_residual == 0 {
        score += progress * 10.0; // late-game perfect closures extra-valuable
    }

    // New-bin candidate tuning: an empty bin has post_residual = capacity-item,
    // which is large; add a mild fixed bias so it only wins when open-bin fits
    // are truly poor (large dead-space penalties above dominate).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Mean-residual coupling: when open bins are already slack-heavy,
    // slightly prefer tightening the emptiest-feeling placement.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * diff;                    // penalize mismatch
        if post_residual == next_item_size {
            score -= 30.0;                      // perfect 2-step match bonus
        } else if post_residual < next_item_size {
            // next item can't follow in this bin: dead space unless post_residual tiny
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: any placement is fine, prefer tightest fill
        score -= 10.0;
    }

    // Prefer bins already tighter than the mean (consolidate waste)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 20.0;
        // allow new bin if item leaves a big awkward gap in existing bins
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0;
        }
    }

    // Small absolute post-residual is always good
    score -= 0.2 * (bin_capacity - post_residual) as f64 * 0.0; // keep base as post_residual
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item also fits in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the known next item: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used sparingly
        score += 45.0;
        // More open bins => more reluctance to open another
        score += open_bins_count as f64 * 3.0;
        // Late in the stream, avoid opening new bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If mean residual across open bins is large, opening a new bin is more wasteful
        score += mean_residual * 0.3;
        // But if item is large and no bin likely fits well, allow new bin
        if item_size as f64 > mean_residual + 10.0 {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins, especially early when bins are few
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Global residual balance: prefer bins whose residual deviates from the mean
    // (consolidate waste into few bins rather than spreading it)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Small penalty scaled by item size to prefer placing large items in tight bins
    score += (item_size as f64 / bin_capacity as f64) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear penalty for large dead space
    let mut score = pr * (1.0 + 0.35 * progress) + 60.0 * norm_pr * norm_pr;

    // Smooth interaction: post_residual coupled with progress polynomially
    let prog_poly = 2.0 * progress - progress * progress;
    score += 25.0 * norm_pr * prog_poly * (pr / 100.0);

    // Reward tight fits (post_residual near zero) more strongly as stream progresses
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when plenty of bins can fit the item
    if bin_residual == bin_capacity {
        let fit_pressure = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 10.0 * fit_pressure + 15.0 * (1.0 - progress);
        // Allow new bin if current item leaves little room and next item would fit the fresh residual
        if next_item_size > 0 && post_residual < next_item_size && (bin_residual as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balance), smooth coupling
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: small bonus if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > post_residual {
        score += 5.0 * (next_item_size as f64 - pr) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals in the same
    // "modulo band" as common item sizes are more reusable.
    let pr = post_residual;
    // Class 0: residual <= 10 (dead space) -> heavy penalty
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Class 1: residual exactly in {10,20,..} multiples of 10 -> reward
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Class 2: residual fits next item exactly -> big reward
    if next_item_size > 0 && pr == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && pr >= next_item_size {
        // residual can hold next item at all
        score -= 6.0;
        // harmonic match: pr and next_item in same decade band
        if pr / 10 == next_item_size / 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit in residual: penalty scaled by waste
        score += 8.0;
    }

    // Integer-division thresholds on post_residual
    let q = pr / 25; // quarter classes
    match q {
        0 => score += 5.0,          // very tight leftover
        1 => score -= 3.0,          // 25..49: good small pocket
        2 => score -= 6.0,          // 50..74: half-ish bin left
        _ => score -= 9.0,          // >=75: nearly empty bin, keep flexible
    }

    // Fraction-of-capacity coupling
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 {
        score -= 15.0; // reward placing big items (first-fit-decreasing spirit)
    } else if fill_frac < 0.25 {
        score += 6.0; // discourage dumping tiny items into good bins
    }

    // Last-chance bonus: only this bin fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // less costly early in the stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // if lookahead item is large and current item small, new bin pairs well
        if next_item_size >= 60 && item_size <= 40 {
            score -= 20.0;
        }
        // if current item is large and would leave tiny residual anywhere, new bin ok
        if item_size >= 70 {
            score -= 12.0;
        }
    }

    // Mild tie-break toward bins below mean residual (consolidation)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins that are nearly filled.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: post_residual too small to ever host a future item
    // (below the smallest plausible item size ~10) is wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead dead space: if the next item cannot fit into the post residual,
    // this bin likely becomes dead unless the gap is genuinely small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize proportionally to how "stranded" the gap is.
        score += 6.0 + 0.15 * post_residual as f64;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Open-bin pressure: mild preference to consolidate into existing bins
    // rather than proliferating bins.
    score += 0.05 * open_bins_count as f64;

    // Mean-residual coupling: if open bins are on average quite full
    // (low mean residual), opening a new bin is more acceptable; if mean
    // residual is high, we should prefer using existing capacity.
    score += 0.10 * mean_residual;

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // already scores poorly; add an explicit opening tax so a new bin wins
    // only when every existing fit leaves a large stranded gap.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large, filling a fresh bin is fine.
        if item_size >= 50 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial lookahead reward: next item fits in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64 / 4.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted lookahead space.
        score += (next_item_size as f64 - post_residual as f64) * 2.0;
    }

    // Penalize leaving very small unusable dead space (but exact match already rewarded).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer bins whose residual is below mean (tighter bins get used first),
    // keeping looser bins flexible for future larger items.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(40.0) * 1.5;
    } else {
        score += (res - mean_residual).min(40.0) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity if decent fits exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 250.0;
        // If other bins fit the item, discourage the new bin more.
        if fitting_bins_count > 0 {
            score += 150.0;
        }
        // Early in the stream, opening bins is cheaper (more items remain to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 120.0;
        // A new bin is attractive if the item fits nowhere else tightly... but lookahead:
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Mild penalty scaled by item size relative to capacity: big items prefer tight fits.
    score += (item_size as f64 / bin_capacity as f64) * (bin_residual - item_size) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Core tightness reward: strongly reward high fill ratios.
    score -= 40.0 * fill * fill;

    // Dead-space penalty: residuals that are hard to reuse (small leftovers)
    // are penalized super-linearly, since tiny slivers rarely fit future items.
    if post_residual > 0 {
        let sliver = post_frac.min(0.25);
        score += 25.0 * sliver * sliver;
    }

    // Perfect or near-perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item cannot fit into the post-residual,
    // this bin's leftover space is likely dead anyway -> reward using it now.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score -= 18.0;
        } else {
            // Next item could still use the leftover; penalize burning it.
            let waste_risk = 1.0 - (post_residual as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
            score += 8.0 * waste_risk;
        }
        // If next item exactly matches post-residual, huge synergy.
        if next_item_size as u32 == post_residual {
            score -= 25.0;
        }
    }

    // New-bin candidate logic: penalize opening a new bin, more so when
    // decent alternatives exist or the item is small (wasting fresh capacity).
    if bin_residual == bin_capacity {
        let alt_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let mut new_bin_penalty = 30.0 + 12.0 * alt_pressure;
        // Small items in a fresh bin waste the most capacity.
        new_bin_penalty += 0.6 * (bin_capacity - item_size) as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= (1.0 + progress);
        // If the item is huge, a fresh bin is nearly forced anyway.
        if fill > 0.8 {
            new_bin_penalty *= 0.3;
        }
        score += new_bin_penalty;
    }

    // Global state coupling: when open bins are already slack (high mean residual),
    // prefer packing into existing space rather than fragmenting further.
    if bin_residual < bin_capacity {
        let slack_gap = mean_residual - post_residual as f64;
        if slack_gap > 0.0 {
            score -= 6.0 * (slack_gap / bin_capacity as f64).min(1.0);
        }
        // Too many open bins: encourage consolidation.
        score += 0.4 * open_bins_count as f64;
    }

    // Time-horizon modulation: late in the stream, tight fits matter more
    // (less opportunity to recover wasted space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (small post_residual) via smooth convex penalty.
    let mut score = x * x * cap;

    // Dead-space penalty: residuals too small to be useful later (smooth ramp).
    let useless = ((18.0 - pr) / 18.0).max(0.0);
    score += 30.0 * useless * useless;

    // Stream-progress coupling: later in the stream, tighter packing matters more,
    // so amplify the tight-fit reward and the dead-space penalty.
    score -= 12.0 * progress * x * (1.0 - x) * 4.0; // smooth interaction bump
    score += 15.0 * progress * useless;

    // Lookahead: if next item fits the resulting residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).max(0.0);
        score -= 8.0 * (1.0 - fits_next / (1.0 - x + 1e-9)) * (x - nx / cap).max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: smooth penalty proportional to how much space would sit idle.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * x * (1.0 - x) * 4.0;
    }

    // Mild dispersion pressure: prefer bins whose residual is below the mean
    // (consolidating space) with a smooth quadratic term.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small" class (<= 10) are nearly perfect; reward them heavily.
    let small_class = post_residual <= 10;
    let mid_class = post_residual > 10 && post_residual <= 20;
    if small_class {
        score -= 60.0;
    } else if mid_class {
        score -= 20.0;
    }

    // Modular harmonic structure: leftover divisible into common item-size
    // buckets (10, 20, 25, 50) is reusable dead space, penalize mildly.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 5.0;
    } else if pr > 0 && pr < 10 {
        score += 10.0; // awkward sliver
    }

    // Lookahead: strongly reward if the next item fits the post_residual,
    // scaled by how "harmonically aligned" next_item_size is with it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / post_residual as f64;
        score -= 30.0 * (1.0 - (fit_frac - 0.5).abs());
        if post_residual % next_item_size.max(1) == 0 {
            score -= 15.0; // exact harmonic division: perfect future fill
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover is likely dead space.
        score += 8.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the waste would be egregious.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // open bins are already tight on average.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / cap;
        let penalty = 45.0 - 40.0 * tightness - 30.0 * large_item * (0.5 + 0.5 * progress);
        score += penalty.max(-20.0);
        // A fresh bin with a large item keeps a big usable residual.
        score += 0.5 * post_residual as f64;
    }

    // Prefer filling bins that are already well-used (low residual).
    score += 0.15 * (bin_residual as f64 - post_residual as f64).signum() * (cap - bin_residual as f64) * 0.05;

    // Mild pressure toward consolidating many open bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to the residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item would leave another dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nr = post_residual - next_item_size;
        if nr > 0 && nr < 10 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a very tight future fit.
        score += 20.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 {
            let nr = bin_capacity - next_item_size;
            if nr < 10 { score -= 35.0; }
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-perfect lookahead matches (small slack for next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }
    // Penalize post_residual that is too small for next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Penalize tiny unusable residuals (dead space), scaled by item size.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Prefer tight fits: closeness of item to bin_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor relative to mean residual.
    if bin_residual == bin_capacity {
        // Default moderate penalty so open bins with decent fits win.
        score += 20.0;
        // But if the item leaves large post_residual relative to mean residual, opening
        // a fresh bin becomes competitive.
        if (post_residual as f64) > mean_residual + 20.0 {
            score -= (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    // Mild preference for filling emptier bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - bin_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored, amplify it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * post_residual as f64;
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // Bonus if the next item fits exactly-ish in the leftover space.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus a term growing with open bins.
        score += 15.0 + 2.5 * open_bins_count as f64;
        // But if mean residual is very low (open bins nearly full), new bin is fine.
        score -= 0.25 * mean_residual;
        // Late in the stream, opening a bin is less costly (less time to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin is useful.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild penalty for leaving residuals that are small but nonzero (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Favor bins whose residual is far below mean (already tight) slightly less
    // when the item still fits well — encourages balanced packing.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog_poly = 0.6 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = pr * prog_poly;

    // Smooth non-linear penalty on very small residuals (dead space), growing quadratically
    score += (norm_pr * norm_pr) * 60.0 * (1.0 - progress);

    // Reward tight fits: small post_residual gets a subtractive bonus, scaled by progress
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 30.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        // next item cannot fit here; mildly penalize leaving a tempting-but-unusable gap
        score += 10.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) smoothly
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen only when
    // all open bins look bad; small progress-dependent drift
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post_residual relative to capacity)
    score -= 40.0 * (1.0 - post / cap).powi(3);

    // Harmonic class logic on post_residual (capacity fractions / divisibility)
    if post_residual < 10 {
        // Unusable dead space: strong penalty
        score -= 25.0;
    } else {
        if post_residual % 10 == 0 {
            // Residual lands on a "harmonic" decile class: reusable by common item sizes
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        } else {
            // Odd classes are harder to fill later
            score += 3.0;
        }
        // Integer-division threshold: residuals >= 50 are half-bin or better
        if post_residual / 10 >= 5 {
            score -= 4.0;
        } else if post_residual / 10 <= 1 {
            score += 5.0; // nearly dead space
        }
    }

    // Lookahead coupling with next item (k=2)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic chain: next item leaves another decile-class residual
            let chain_post = post_residual - next_item_size;
            if chain_post % 10 == 0 { score -= 5.0; }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling
    if is_new_bin {
        // Baseline reluctance grows with number of open bins
        score += 12.0 * open_bins_count as f64;
        // No open bin fits: new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is bigger, a fresh bin is a good host for the current one
        if next_item_size > item_size {
            score -= 10.0;
        }
        // Discourage opening a bin that immediately becomes a bad harmonic class
        if post_residual % 10 != 0 && post_residual < 40 {
            score += 8.0;
        }
    }

    // Stream phase: later in the stream, consolidation matters more
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * phase * (post / cap);

    // Mild pull toward bins whose residual is near the mean (balanced packing)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define a "useful gap" threshold relative
    // to the smallest plausible item (1..100 stream => treat gaps < 10 as dead).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Dead space: gap unusable for any future item -> big penalty.
        score += (dead_threshold - pr) * 8.0;
    }

    // Reward very tight fits (near-perfect packing) with a strong bonus.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * 20.0;

    // Exact fit gets a massive bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With several candidates, mildly prefer bins that leave gaps
        // matching the lookahead item (k=2 lookahead synergy).
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 6.0; // gap too small for lookahead: penalize
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // bins with large residuals; prefer consolidating into tighter bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * pr * 0.05;

    // New-bin candidate: only attractive when current item cannot fit well
    // anywhere (large dead space risk) or few bins fit. Penalize opening a
    // new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 25.0;
        // If it's the last chance to avoid a new bin elsewhere, make new bin costly.
        let last_chance_bonus = if fitting_bins_count == 1 { 30.0 } else { 0.0 };
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base + last_chance_bonus + progress * 10.0;
        // But if this item would leave a large dead gap in any existing bin,
        // opening a fresh bin becomes relatively better (score already low
        // for existing bins with dead-space penalties).
        if item_size >= 60 && open_bins_count > 0 {
            score -= 8.0;
        }
    }

    // Mild preference for bins below mean residual (keeps residuals balanced).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item (perfect chain fit)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying for near matches
        let match_reward = 40.0 / (1.0 + diff * 0.5);
        score -= match_reward;

        // If next item fits in post_residual, mild bonus; if not, penalize stranded residual
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // post_residual becomes dead space unless small
            if post_residual < 10 {
                score += 15.0; // tiny dead space is acceptable
            } else {
                score += (post_residual as f64 - 10.0) * 0.3;
            }
        }
    } else {
        // Last item: just minimize leftover
        score += 10.0;
    }

    // Compare against mean residual: bins tighter than average get preference
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the only fitting bin, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins that are already quite full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on post-residual dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // If next item cannot fit in post-residual but would fit elsewhere, mildly penalize
    // leaving a large unusable gap relative to the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        // Base cost of opening a bin, modulated by global residual pressure.
        let pressure = mean_residual / bin_capacity as f64;
        score += 55.0 + pressure * 30.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // Few open bins -> opening is cheaper.
        score -= (open_bins_count.min(20) as f64) * 1.5;
        // If the item perfectly consumes a fresh bin, opening is great.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 70.0;
        }
    }

    // Prefer filling bins that are already mostly full (keep small-residual bins busy).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Mild penalty for spreading across many bins when mean residual is high.
    if mean_residual > bin_capacity as f64 * 0.5 && !is_new_bin {
        score += 3.0;
    }

    // Early stream: slight preference for opening bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer minimal post residual, with non-linear (quadratic) coupling
    // that grows as the stream progresses (tighter packing later in the stream).
    let mut score = post * (1.0 + 0.5 * progress) + 0.35 * post * post / cap;

    // Reward tight fits: small post_residual relative to item size.
    score -= 12.0 * fit_frac * (1.0 - post / cap);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            // Dead space for the next item: penalize smoothly.
            score += 6.0 * (next - post) / cap * (1.0 + progress);
        } else {
            // Bonus: bin remains usable for the next item.
            score -= 4.0 * (1.0 - (post - next) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth decay as more bins fit).
    let denom = fitting_bins_count.max(1) as f64;
    score -= 18.0 / denom * (1.0 - post / cap);

    // New-bin candidate: bin_residual == bin_capacity means an empty bin.
    // Penalize opening a new bin, more so early in the stream and when
    // open bins exist that could absorb the item.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 25.0 + 30.0 * open_pressure * (1.0 - progress);
        // Slightly relax penalty late in stream when mean residual is large (fragmentation).
        score -= 10.0 * (mean_residual / cap) * progress;
    } else {
        // Mild reward for reducing mean residual spread (consolidation).
        score -= 2.0 * (1.0 - (post - mean_residual).abs() / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches 0
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Harmonic class of the gap: dead space is what next item must consume.
    // Classify gap by integer-division thresholds relative to typical item sizes.
    let gap = post_residual;
    // Gaps that next_item_size exactly fills are gold
    if next_item_size > 0 && next_item_size <= gap {
        let leftover = gap - next_item_size;
        if leftover == 0 {
            score -= 45.0; // chain: next item closes this bin completely
        } else if leftover <= 5 {
            score -= 25.0;
        } else if leftover <= 10 {
            score -= 12.0;
        }
        // modulo harmonic: leftover divisible into small chunks is usable
        if leftover > 0 && leftover % 10 == 0 {
            score -= 6.0; // gap aligns with decimal class boundaries
        }
    } else if next_item_size > 0 && next_item_size > gap {
        // next item cannot use this bin's gap at all -> dead space penalty
        score += (gap as f64) * 0.35;
    }

    // Penalize large residual gaps (unusable dead space), superlinear
    if gap > 50 {
        score += (gap as f64 - 50.0) * 0.6;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only good when the item
    // is large relative to capacity or current bins are crowded with big residuals.
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 25.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // large items fit best in empty bins
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        }
        // if mean residual is low (bins nearly full), new bin is attractive
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // late in stream, prefer consolidating
        score += progress * 10.0;
        // many open bins: discourage opening more
        score += open_bins_count as f64 * 1.5;
    }

    // Mild preference for fuller bins generally
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Modulo harmonic on item_size class: items in the 30-40 class pair well
    // with residual 60-70; reward matching complementary classes
    if item_size % 10 == 0 && gap % 10 == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates dead space the next item cannot use.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Penalize bins that deviate from the mean residual (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive when existing fits are poor/absent.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: open new bin
        } else {
            // Deter opening a new bin when alternatives exist; stronger if a tight fit exists.
            score += 25.0 + 10.0 * fitting_bins_count as f64;
            if post_residual >= 50 {
                score += 20.0; // wasting a fresh bin on a small item
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is excellent: item + next item perfectly fill the bin
        if diff == 0.0 {
            score -= 45.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        } else if diff <= 15.0 {
            score -= 8.0 - diff * 0.3;
        } else {
            // Post residual leaves awkward dead space for the next item
            score += diff * 0.15;
        }
        // If next item cannot fit at all, dead space is more costly
        if post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: prefer minimal waste directly
        score += 0.0;
    }

    // Relative to mean residual: bins with more residual than average are
    // attractive targets (keep tight bins tight for future large items)
    score -= (bin_residual as f64 - mean_residual) * 0.25;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Progress-aware slight tightening: early on, keep flexibility (penalize
    // very small residuals); late in stream, prioritize filling tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 && post_residual > 0 {
        score += (1.0 - progress) * 8.0; // tiny dead space hurts early
    }

    // New empty bin candidate: only preferable when item is large and would
    // wreck an existing bin's usability, or no good fit exists.
    if bin_residual == bin_capacity {
        if item_size > 60 {
            score -= 10.0; // large items start fresh bins willingly
        } else {
            score += 20.0; // small items should go into open bins
        }
        // If many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items (sizes 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual >= 10 {
        // Reward residual that can fit the lookahead item exactly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else if next_item_size > 0 {
            score += 4.0; // lookahead item won't fit here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless the
    // current bin's fit is very poor or the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 20.0;
        // More willing to open new bins early in the stream (long horizon left).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Discourage new bins when many bins are already open and mean residual
        // is large (plenty of slack available overall).
        score += 0.15 * open_bins_count as f64;
        score += 0.3 * (mean_residual - post_residual as f64).max(0.0);
        // If the current item is large, a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
    }

    // Mild penalty for leaving residuals in the awkward 40-60 band (hard to fill
    // with typical item sizes), mild reward for residuals >= 70.
    let pr = post_residual as f64;
    if pr > 40.0 && pr < 60.0 {
        score += 3.0;
    } else if pr >= 70.0 {
        score -= 2.0;
    }

    // Late-stream consolidation: as the stream ends, prefer packing into
    // existing bins to avoid leftover near-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    // Core: prefer small post-residual, with smooth polynomial amplification
    // as the stream progresses (tighter packing later in the stream).
    let norm_post = post / cap; // in [0,1]
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    let mut score = post * (1.0 + 0.8 * progress) + 40.0 * norm_post * norm_post * progress_coupling;

    // Reward filling a bin almost exactly (post_residual near zero),
    // smoothly weighted by how rare fitting bins are.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin, scaled by stream progress.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer best-fit among them anyway.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement;
    // smooth interaction term between next item size and post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here; penalize leaving a moderately large dead zone
            // that neither helps now nor later.
            score += 8.0 * norm_post * (1.0 - progress);
        }
    }

    // Mean-residual context: penalize placing into bins whose residual is far below
    // the mean (fragmenting small holes), reward consolidating space near the mean.
    let dev = (resid - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: an empty bin has high residual; make it mildly
    // unattractive so existing bins are preferred, but attractive when the item
    // barely fits anywhere or residual would be very small anyway.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // A new bin wastes capacity for small items; penalize proportionally.
        score += 0.3 * (cap - item);
    }

    // Small penalty for very large post-residual late in stream (dead space).
    score += 5.0 * norm_post * norm_post * norm_post * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // --- Harmonic class logic on post_residual ---
    // Residuals that are exact multiples of 10 are "harmonic" with the smallest
    // item class and are easy to close out later: reward them.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Non-harmonic tiny residues (1..9) are near-dead space: penalize,
    // unless the lookahead item can still use them.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Integer-division threshold: a residual that can hold at least half of
    // the next item is still "usable" — soften the raw residual term.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).min(post_residual as f64) * 0.5;
        // Perfect lookahead fit: strong harmonic closure reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Perfect closure of the bin.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Last-chance bin pressure ---
    // If this is the only bin that fits, strongly prefer using it over
    // opening a new bin (new-bin candidate will score lower otherwise).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a fresh bin is only attractive for large items where an
        // almost-full packing is likely anyway.
        let size_bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        score += 18.0 - size_bonus + t * 5.0;
        // Never open a new bin when an existing bin is the last chance.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
        // Perfect fit in a fresh bin (item is a multiple of 10 filling it exactly).
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Mild pressure to consolidate when many bins are open relative to mean fill.
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that the lookahead item
    // cannot use is wasted capacity. Penalize proportionally to the waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // Perfect or near-perfect fills are highly desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only open bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins
    // exist, with pressure growing with the number of already open bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0 + open_bins_count as f64 * 6.0;
            // But if no open bin can fit the item at all, opening is fine.
            if fitting_bins_count == 0 {
                score -= 80.0;
            }
            // Late in the stream, avoid proliferating bins even more.
            if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
                score += 10.0;
            }
        }
    }

    // Mild preference for bins that are already relatively full
    // (keeps residual mass concentrated in fewer bins).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && bin_residual >= 100;

    if is_new_bin {
        // Prefer opening a new bin only when no existing bin fits well.
        // Base cost of a fresh bin: high, but reduced late in the stream
        // and when many bins are already open (consolidation pressure).
        score = bin_capacity as f64 * 1.5 - 30.0 * progress;
        // If this is the last chance to fit anywhere, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // If the next item is large, a fresh bin leaves room for it.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (next_item_size as f64) * 0.3;
        }
        return score;
    }

    // Exact fit reward: post_residual matches next item perfectly.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Reward leaving residuals near the mean (balanced packing),
    // penalize residuals far above the mean (wasteful).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Tight fit reward: small post_residual is good (already base term),
    // extra reward for very tight fits.
    if post_residual <= 10 {
        score -= 25.0;
    }

    // Late in the stream, consolidate: penalize spreading across many bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Lookahead reward: leaving room for the next item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + next_item_size as f64 * 0.05;
    }

    // Penalize tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 4.0;
    }

    // Last chance bin before opening a new one
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    if is_new_bin {
        // Opening a new bin: penalize early, less late in the stream
        score += 8.0 - 4.0 * t;
        // Extra penalty if many bins already open (fragmentation control)
        score += open_bins_count as f64 * 0.05;
        // If next item fits comfortably in the fresh bin, soften the penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    } else {
        // Prefer using fuller existing bins
        score -= (bin_capacity - bin_residual) as f64 * 0.02;
        // Slight reward for bins tighter than the current average residual
        score -= (mean_residual - bin_residual as f64).max(0.0) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space (quadratic in normalized post residual).
    let post_norm = post / cap;
    let mut score = post + 40.0 * post_norm * post_norm;

    // Reward tight fits: small post_residual relative to item size.
    score -= 25.0 * (1.0 - post_norm) * (item / cap);

    // Smooth non-linear coupling with stream progress: early on, keep bins
    // flexible (favor larger post_residual slightly); late, pack tightly.
    let flex = (progress * std::f64::consts::PI).sin();
    score += 15.0 * flex * post_norm;
    score -= 20.0 * progress * (1.0 - post_norm) * (1.0 - post_norm);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless it enables a great future fit.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 25.0 * (1.0 - progress);
        // If the next item fits perfectly in the residual left by this item,
        // opening a new bin is attractive (sequential pairing).
        let pair_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            20.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap)
        } else {
            0.0
        };
        score += base_penalty - pair_bonus;
    } else if next_item_size > 0 {
        // Lookahead: reward bins whose post residual accommodates the next item.
        if post_residual >= next_item_size {
            let slack = ((post_residual - next_item_size) as f64) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = ((next_item_size - post_residual) as f64) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Mild penalty for scattering across many open bins when mean residual is high.
    score += 2.0 * open_bins_count as f64 * (mean_residual / cap) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Items sized 1..100; classify post_residual into harmonic bins that
    // future items can plausibly fill. Small "dead" residues are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic classes of 100/2, /3, /4)
    let h2 = post_residual / (bin_capacity / 2);   // 0 if post < 50
    let h3 = post_residual / (bin_capacity / 3);   // 0 if post < 33
    let h4 = post_residual / (bin_capacity / 4);   // 0 if post < 25

    // Dead-space penalty: residues that most items (>=10) cannot use
    if post_residual < 10 {
        score += 25.0;
    }
    // Modulo arithmetic: residues that are "awkward" (not divisible into
    // common item-size classes) get penalized slightly.
    let awkward = (post_residual % 10 != 0) as f64 * 2.0
        + (post_residual % 25 == 1 || post_residual % 25 == 24) as f64 * 3.0;
    score += awkward;

    // Reward residues in usable harmonic classes
    if h4 >= 1 { score -= 4.0; }         // post >= 25: very reusable
    if h3 >= 1 { score -= 2.0; }         // post >= 33
    if h2 >= 1 { score -= 1.0; }         // post >= 50: half-empty bin
    // Exact harmonic sweet spots
    if post_residual == bin_capacity / 2 { score -= 5.0; }
    if post_residual == bin_capacity / 3 { score -= 3.0; }
    if post_residual == bin_capacity / 4 { score -= 2.0; }

    // --- Tight fit reward ---
    let tightness = 1.0 - post / cap;
    score -= tightness * 8.0;

    // --- Last-chance bin: strongly favor using it to avoid a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only sensible when no good alternative exists:
        // penalize it unless this item fits nowhere else, or the fit elsewhere
        // would be terrible (large post_residual in every fitting bin).
        let pressure = (fitting_bins_count == 0) as f64;
        let poor_fit_everywhere = (fitting_bins_count > 0 && mean_residual < item_size as f64 + 5.0) as f64;
        score = cap + 30.0
            - pressure * 60.0
            - poor_fit_everywhere * 20.0
            // late in the stream, waste matters less than compactness
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // --- Lookahead (k=2): if next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
            // harmonic coupling: next item leaves another usable residue
            let next_post = post_residual - next_item_size;
            if next_post >= 10 { score -= 2.0; }
        } else {
            // next item cannot use this residue; slightly penalize large residue
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.05;
        }
    }

    // Mild normalization toward mean residual: prefer bins already committed
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // since they can rarely host future items (min size ~10).
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as f64) * 25.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual that exactly fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Post-residual that cannot fit the lookahead item while being large-ish:
    // mild penalty scaled by how much it wastes relative to lookahead needs.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // tolerate imperfect fits.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * post_residual as f64 * 0.15;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if no open bin can fit, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Mild preference for bins with residuals near the mean (keeps bin states uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post - next;
        score -= 30.0 * (1.0 - slack / cap);
        if slack == 0.0 {
            score -= 40.0; // chain-perfect fit
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to wasted lookahead
        score += 10.0 + 0.5 * (next - post);
    }

    // Compare post_residual relative to mean residual: avoid leaving far-above-average waste
    score += 0.3 * (post - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage unless current residuals are tight and item is large
    if bin_residual == bin_capacity {
        let avg_fill = cap - mean_residual;
        let pressure = (open_bins_count as f64).max(1.0);
        let tight = mean_residual / cap < 0.35;
        let big_item = (item_size as f64) > 0.6 * cap;
        if tight && big_item {
            score -= 5.0;
        } else {
            score += 20.0 + 2.0 * pressure.sqrt();
        }
        // Large items start fresh bins more willingly
        score -= 0.1 * item_size as f64;
    }

    // Mild early-stream exploration: open bins more freely at the start
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large leftover dead space nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1.0) as f64);
        } else {
            // next item won't fit here; penalize small awkward residuals
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (smaller post residual already does this),
        // but slightly penalize bins that are already very full to keep flexibility.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score += 10.0 * fill * fill;
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    let reuse_benefit = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * (mean_residual / bin_capacity as f64);
    score -= 12.0 * reuse_benefit;

    // Time horizon: early in the stream, keep bins flexible; late, pack tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += t * 3.0 * (pr / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * item_frac;
        score += 55.0 * (1.0 - item_frac);
        if fitting_bins_count == 1 {
            score += 30.0; // discourage opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, with smooth polynomial coupling to progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty: small residuals are fine, mid-range residuals are worst.
    let norm_post = post / cap;
    score += 18.0 * norm_post * (1.0 - norm_post) * (1.0 - progress);

    // Reward tight fits (post residual near zero) more strongly early in the stream.
    score -= 10.0 * (1.0 - norm_post).powi(3) * (1.0 - progress);

    // Lookahead: if next item fits exactly in post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt).abs();
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64 + 1.0) };
        score += 12.0 * fit_pressure * (1.0 - progress) + 4.0;
    } else {
        // Favor bins whose residual deviates from mean (consolidate space).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score -= 2.0 * dev;
    }

    // Slight preference for bins with larger residual when item is large.
    score -= 0.02 * bin_residual as f64 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small residues are dead space
    let r10 = post_residual % 10;
    score += (10 - r10) as f64 * 0.8;

    // Penalize tiny post_residual that is still nonzero (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward post_residual that could fit next item exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= gap as f64 * 0.6;
            if gap == 0 {
                score -= 150.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer division thresholds on post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score += 10.0;
    } else if post_residual < half {
        score -= 5.0;
    } else {
        score -= 12.0;
    }

    // Last-chance bin bonus: only one bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when it seems genuinely better
    if bin_residual == bin_capacity {
        // Fresh bin has full flexibility; score relative to mean residual of open bins
        score += mean_residual * 0.15;
        // Prefer keeping existing bins busy when many are open
        score += open_bins_count as f64 * 2.0;
        // Slight preference for new bin late in stream when item is large
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    } else {
        // Favor bins whose residual is closest to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score -= (bin_capacity as f64 - tightness) * 0.05;
    }

    // Mean residual coupling: encourage using bins with above-average residual
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size) are the worst outcome -> heavy penalty.
    let min_item = 1.0f64.min(cap); // items >= 1 by interface
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize "awkward" small gaps that most items (10..80 originally, 1..100 now)
    // cannot fill well: gaps in [1, 15) are hard to reuse.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post) * 3.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 40.0 * (1.0 - post / cap).powi(6);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward proportional to how well next item uses the gap
        score -= 10.0 * (next_item_size as f64 / post).min(1.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // gap too small for next item: penalize proportionally to wasted gap
        score += 8.0 * (post / cap);
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but under pressure (few fitting bins) strongly favor using this bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's residual would be wasted (large dead space) or the fit is bad.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: slightly worse than a good fit,
        // better than a wasteful fit.
        score = 45.0 + 0.3 * (item_size as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0; // next item needs a full bin anyway
        }
    }

    // Mean-residual coupling: if mean residual is high, prefer bins that
    // reduce dispersion (i.e., small post_residual relative to mean).
    score += 0.15 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 - slack.min(50.0)) * 2.0;
        } else {
            // next item cannot fit here; dead-space penalty grows with tightness
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score += 50.0 - fit_ratio * 40.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 200.0; // large item leaves unusable sliver, but fresh bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Prefer filling older/more crowded bins lightly
    score += open_bins_count as f64 * 0.05;

    // Slight preference to place larger items earlier in the stream
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base preference: tighter packing (smaller post_residual) is already favored
    // by using post_residual as the base. Now add couplings.

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit_ratio = item_size as f64 / bin_residual as f64; // how well item fills this bin

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits into post_residual, this bin is doubly valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap); // tighter chain fits rewarded more
        } else {
            // Next item will NOT fit here: leaving large dead space is costlier.
            let waste = post_residual as f64;
            if waste > 30.0 {
                score += 0.25 * (waste - 30.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing bins rather than spreading out.
    if open_bins_count > 2 {
        score -= 0.8 * (open_bins_count as f64).ln();
    }

    // Global residual context: if mean residual is high, prefer bins below mean
    // (consolidate small residuals into big ones).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.15 * (mean_residual - res_f);
    } else {
        score += 0.10 * (res_f - mean_residual);
    }

    // New-bin candidate handling: an empty bin should only win when the item fits
    // poorly everywhere else. Penalize empty-bin candidate proportionally to
    // progress and existing bin count, but relax it if item is large relative to
    // residual (poor fit) so we don't destroy big residual bins with bad fits.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fit_ratio < 0.55 && fitting_bins_count <= 2;
        let early = progress < 0.25;
        if poor_fit_elsewhere && !early {
            score -= 12.0; // allow opening a new bin for a bad fit on a large-residual bin
        } else {
            score += 35.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        }
    }

    // Mild time-horizon modulation: early in the stream, be more conservative
    // (prefer tight fits since many items remain); late, allow more slack use.
    score -= 5.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Smooth non-linear coupling: tight fits are rewarded quadratically,
    // scaled by stream progress (tightness matters more as stream advances).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful relative to the
    // minimum plausible item size, with a smooth saturating term.
    let dead = (post / cap).powi(3);
    score += 8.0 * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward bins whose post residual still accommodates
    // the next item (chaining), penalize those that leave awkward leftovers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 5.0 * miss * miss;
        }
    }

    // New-bin candidate: empty bin should only win when open bins are crowded
    // or the fit is poor. Penalize opening a new bin smoothly by residual
    // abundance and mean residual of open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress + 0.05 * mean_residual;
        if fitting_bins_count > 1 {
            score += 6.0;
        }
        // If the item is large, a fresh bin is more attractive.
        score -= 0.08 * item;
    }

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += 0.02 * open_bins_count as f64 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/6 granularity) and reward "harmonic"
    // leftovers that future items (10..80 range) can plausibly reuse.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post * 6.0 / cap).floor(); // 0..6 harmonic index
    match class as u32 {
        0 => score -= 12.0,          // near-perfect fit, tiny dead space
        1 => score -= 6.0,           // very good fit
        2 => score -= 2.0,           // decent fit
        3 => score += 0.0,           // neutral half-full leftover
        4 => score += 3.0,           // awkward large leftover
        5 => score += 6.0,           // mostly-empty bin: wasteful placement
        _ => score += 8.0,           // untouched bin used for a small item
    }

    // Reward closing in on fullness: small post residual is king.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is a harmonic chain — strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize leaving a residual that
            // is just barely too small (classic dead-space trap).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 5.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are
    // congested (mean residual is low) or the current fit is bad.
    if bin_residual == bin_capacity {
        let congestion = 1.0 - (mean_residual / cap).min(1.0);
        let bad_fit = (item_size as f64 / cap) > 0.6;
        // Base penalty so we normally prefer existing bins.
        score += 10.0;
        if congestion > 0.6 || bad_fit {
            score -= 14.0 * congestion.max(if bad_fit { 0.7 } else { 0.0 });
        }
        // Early in the stream, seeding bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Modulo-flavored nudge: residuals that are multiples of common small
    // item sizes (10, 20, 25) are more reusable — small bonus.
    if post_residual % 10 == 0 {
        score -= 2.0;
    } else if post_residual % 25 == 0 {
        score -= 1.5;
    }

    // Tie-break with mean residual: prefer filling bins below the mean
    // (draining the emptiest-ish bins first keeps the bin set tight).
    if (post as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< smallest plausible item) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly larger but still awkward gaps get a graded penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space that still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, filling tighter is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += pressure.min(30.0) * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bins fit poorly
    // (large item, tight residuals elsewhere).
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let residual_pressure = (mean_residual / bin_capacity as f64).min(1.0);
        score = bin_capacity as f64 - 25.0 * poor_fit * (1.0 - residual_pressure) - 20.0 * (item_size as f64 / 100.0);
        if fitting_bins_count == 1 {
            score += 80.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward closeness of a 2-step fit, decaying with gap size.
            score -= (40.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
            // Penalize leaving a residual too small for the next item (dead space).
            if post_residual < next_item_size {
                score += 25.0;
            }
        } else {
            // post_residual < next_item_size: unusable dead space for lookahead.
            score += 25.0;
        }
    }

    // Tight fit reward: small post_residual is good, but avoid tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins with residual below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when current bin would leave
    // large dead space or many bins are open.
    if bin_residual == bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        if dead > 40.0 && open_bins_count < 4 {
            score -= 80.0;
        } else {
            score += 120.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Mild preference for filling older/tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space < item size
    // range minimum (1) is worthless. Penalize unusable slivers.
    if post_residual > 0 {
        // fraction of capacity wasted
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * waste_frac * waste_frac;
        // if post_residual cannot fit even the smallest plausible item, penalize hard
        if post_residual < 10 {
            score += 15.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 20.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward;
    // if next item would be blocked by this placement, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement blocks the next item from using this bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. An empty bin has post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 18.0;
        // as stream progresses, discourage proliferation of open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if many bins are open, discourage new ones further
        score += (open_bins_count as f64).min(20.0) * 0.6;
        // if this bin is the last chance among open bins, opening new is less bad
        if fitting_bins_count == 1 {
            score -= 22.0;
        } else if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // if mean residual across open bins is high, opening new bin is wasteful
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 8.0;
    } else {
        // Reward using existing bins, especially ones with residual close to item
        let fit_tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 10.0 * fit_tightness;
        // early stream: be more liberal with bins; later: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress;
    }

    // Mild preference for bins with residual above the mean (keep flexible bins free,
    // fill rigid ones): lower score for bins with small residual.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: raw wasted space, mildly compressed for large residuals
    let mut score = post + 0.5 * (post * post) / cap;

    // Quadratic dead-space penalty: small residuals are fine (tight fit), large ones waste
    let tightness = post / cap;
    score += 40.0 * tightness * tightness * (1.0 - tightness);

    // Stream-progress coupling: later in the stream, tolerate less slack
    score += 25.0 * tightness * progress;

    // Lookahead synergy: reward residuals that still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 18.0 * (1.0 - slack_fit * 2.0).max(0.0);
        } else {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: bin_residual == bin_capacity. Penalize opening a new bin,
    // unless the item is large relative to capacity (poor fit anywhere else anyway).
    if bin_residual == bin_capacity {
        let big_item = item / cap;
        score += 55.0 - 35.0 * big_item * big_item;
        // Early stream: opening bins is cheaper; late stream: consolidate
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (balance load)
    score += 3.0 * (bin_residual as f64 - mean_residual) / cap;

    // Mild scaling with number of open bins: prefer reusing when many bins open
    score += 1.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer filling a bin almost exactly (small post_residual is good).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Harmonic class of the dead space: residuals divisible by small numbers
    // are more reusable by future items (modular "harmony").
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 8.0; }
        if pr % 5 == 0 { harmony += 4.0; }
        if pr % 2 == 0 { harmony += 2.0; }
        if pr % 20 == 0 { harmony += 6.0; }
        if pr % 25 == 0 { harmony += 5.0; }
        // dead space in 1..=9 is nearly unusable (items >= 10 typically)
        if pr < 10 { harmony -= 25.0; }
        score -= harmony;

        // Integer-division thresholds: classify residual into usable bands.
        let band = pr / 10; // which decade of dead space
        score += band as f64 * 6.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 300.0;
        } else if gap < 10 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot follow in this bin: penalize mildly unless residual is dead
        score += 20.0;
        if pr < 10 { score += 10.0; } // dead space anyway, less harm
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: it's the pristine bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 120.0;
        // Prefer a new bin when the current item is large and no tight fits exist.
        if item_size > 50 { score -= 30.0; }
        // If many bins are open with slack, discourage new bins.
        score += open_bins_count as f64 * 4.0;
        score += (mean_residual - 40.0).max(0.0);
        // If next item is huge, opening fresh bin may be wise.
        if next_item_size >= 70 { score -= 25.0; }
        // Near end of stream, avoid opening new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 150.0;
        }
    }

    // Global context: when many bins are open, tighten packing (prefer best fits).
    score += open_bins_count as f64 * 0.5;
    score -= (mean_residual - (post_residual as f64)) * 0.1;

    // Slight preference for bins with lower residual relative to item (tighter fit).
    score += (bin_residual as f64 - item_size as f64 - post_residual as f64).abs() * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline for the brand-new empty bin candidate: mildly attractive,
    // but only wins when existing bins leave bad dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 42.0 + 18.0 * progress + 1.5 * open_bins_count as f64;
        // If next item could combine with current item in a fresh bin, slight bonus.
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            nb -= 6.0;
        }
        // If this is the only fitting option, opening a bin is natural.
        if fitting_bins_count <= 1 {
            nb -= 20.0;
        }
        return nb;
    }

    // Strict dead-space avoidance: post_residual gaps below the minimum item
    // size (1) are pure waste; but gaps too small for typical items (<=10)
    // are the real dead space under the original regime — penalize heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits (post_residual very small relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // If the leftover exactly accommodates the lookahead item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize leftovers that can neither fit the next item nor be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., filling fuller bins first keeps large residuals for big items).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still hold the next item comfortably: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize unusable gap.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.8 * dead;
    }

    // Penalize tiny unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    // Zero residual is perfect packing: big reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if the item fits very poorly in tight context
    // (i.e., item large, residuals small). Otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        score -= 5.0; // base slight preference to keep flexibility
        if item_size >= 60 || (next_item_size > 0 && item_size + next_item_size as u32 > bin_capacity) {
            score -= 20.0;
        } else {
            score += 30.0;
        }
        // More open bins with small residuals -> opening a new bin is fine.
        if mean_residual < item_size as f64 && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Prefer tighter bins (small residual relative to mean) generally.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but exact 0 is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0; // tiny slivers are nearly unusable anyway
    } else {
        // Usable leftover: mild penalty scaled by how much of capacity is wasted.
        score += 0.05 * (post_residual as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 2.0; // next item can still go here; keep pairing
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 6.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 4.0 * (fitting_bins_count as f64).min(6.0);
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // consume large residuals (consolidation effect).
    let dev = (mean_residual - bin_residual as f64).abs();
    score += 0.02 * dev;

    // Slight preference for bins with larger residuals when many bins are open
    // (reduce bin count pressure by emptying big-residual bins).
    score -= 0.03 * bin_residual as f64 * (open_bins_count as f64 / 20.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    score -= (1.0 - post / cap) * (1.0 - post / cap) * 18.0;

    // Penalize leaving dead space that nothing can use later
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Many fitting bins -> less urgency to use this one; slight spread
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 1.5;
    }

    // Lookahead: if next item would fit in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size as f64 > post {
        score += (next_item_size as f64 - post).min(20.0) * 0.4;
    }

    // New-bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score += 30.0 - 35.0 * size_ratio * size_ratio;
        if item_size > 50 {
            score -= 10.0;
        }
    }

    // Stream-progress coupling: later in stream, prefer packing into existing bins
    score += progress * (bin_residual as f64 - post) * 0.15;

    // Prefer bins with residual above mean (balance across bins)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.1;

    // Non-linear interaction: tightness x progress
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 6.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well post_residual decomposes
    // into capacity fractions. Residuals in "small" classes are dead space.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Integer-division thresholds on post_residual: classify dead space.
    let k = post_residual / 10; // decade class
    score += match k {
        0 => -20.0,                    // near-perfect fit
        1 => -8.0,
        2 => 0.0,
        3 => 4.0,
        4 => 8.0,
        _ => 12.0,                     // large residual: wasteful
    };

    // Modulo coupling: post_residual divisible by small sizes (10, 20, 25, 50)
    // is more likely reusable by future items -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
        // Odd, prime-ish residuals are awkward
        if post_residual % 10 != 0 && post_residual % 5 != 0 { score += 3.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here anyway; slightly penalize leaving
            // residual in awkward harmonic class vs next item's class
            let nm = next_item_size % 10;
            let pm = post_residual % 10;
            if nm != 0 && pm != 0 && nm == pm { score += 2.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current residual is
    // hopeless dead space (very small and unusable by next item).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0;
        // Allow new bin if this bin's residual would be tiny dead space
        // and next item can't use it.
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            score -= 45.0;
        }
        // Early in stream, opening bins is cheaper (more items to come)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure toward filling bins tightly relative to mean residual.
    score -= 0.05 * (mean_residual - frac * 100.0);

    // Slight preference to keep number of open bins in check late in stream.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any post_residual that is too small to ever
    // hold a future item (min item size = 1, but tiny gaps < 10 are near-useless)
    // is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: waste ratio of the placement.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, and make new bins less attractive.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive if current item is large
        // relative to typical residuals or next item pairs well.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If the next item could combine with the residual left here, new bin
        // is more attractive (pairing lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Large items fragment bins; prefer a fresh bin for very large items.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Placing into an existing bin: slight reward scaled by congestion.
        score -= open_bins_count as f64 * 0.5;
        // If next item fits exactly in the post residual, big bonus (chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 6.0;
        }
        // Penalize leaving a gap slightly larger than the next item (near-miss dead space).
        if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 5 {
            score += 5.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a
    // "leftover" bin; using it consolidates waste.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, be more conservative: tighten penalty on residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste_ratio * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: exact match bonus ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin after this placement.
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            // Next item still fits: mild bonus proportional to tightness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize, since we strand the residual.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // --- Tight fit reward: small post_residual is good dead-space control ---
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // --- Compare against mean residual: prefer bins tighter than average ---
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 6.0 * (rel - 1.0).min(2.0);
        }
    }

    // --- Last-chance bonus: if this is the only fitting bin, use it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: acceptable early or when many bins are open,
        // penalize otherwise so we prefer existing bins with decent fits.
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 15.0 + 40.0 * (1.0 - open_pressure) - 20.0 * progress;
        // If next item is small, a fresh bin wastes capacity potential.
        if next_item_size > 0 && next_item_size < 30 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity wasted by this placement
    let waste = post_residual as f64 / bin_capacity as f64;

    // Base: prefer tight fits, penalize large residuals quadratically
    score += 0.35 * waste * waste * bin_capacity as f64;

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward leaving usable space, scaled by how much would remain after next item
            let post2 = post_residual - next_item_size;
            score -= 12.0 * (1.0 - (post2 as f64 / bin_capacity as f64));
        } else {
            // Post-residual unusable by next item: penalize dead space
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, keep discrimination via residual (already in score)
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes the residual of all existing bins contextually.
        // Penalize new bins more when many open bins exist and mean residual is large.
        score += 14.0 + 0.6 * open_bins_count as f64 + 0.25 * mean_residual;
        // But if no other bin fits (fitting_bins_count counts open bins; for the
        // new-bin call it is effectively zero alternatives), the penalty above is
        // offset: open bins that fit would have lower base scores anyway.
        // Early in the stream, be more willing to open bins for diversity.
        if t < 0.2 {
            score -= 10.0;
        }
        // If mean residual across open bins is small, opening a fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Reward filling existing bins, especially when they are nearly full.
        let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill_frac;
        // Penalize placing into bins whose residual deviates a lot from mean
        // (keeps a balanced spread of residual classes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-horizon coupling: late in the stream, prioritize closing bins tightly.
    score -= 4.0 * t * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth polynomial interaction: penalize large residuals more as stream progresses
    let coupling = x * x * (0.5 + p) + x * x * x * (1.0 - p) * 2.0 + x * p * 4.0;
    score += coupling * cap * 0.5;

    // Reward tight fits (small post residual) more strongly later in the stream
    let tightness = 1.0 - x;
    score -= tightness * tightness * (10.0 + 30.0 * p);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 15.0 + 2.0 * openness * (0.5 + 0.5 * p);
        // If next item could use the fresh bin better, soften the penalty
        if next_item_size > 0 && (next_item_size as f64) >= (item_size as f64) + pr {
            score -= 12.0;
        }
    }

    // Mean-residual awareness: bins deviating from mean residual are less attractive
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 + p);

    // Lookahead: favor bins whose post residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residues divisible by 10 are more reusable
    // by the typical item-size granularity; reward them, penalize awkward residues.
    let pr = post_residual as i64;
    let residue_class = (pr % 10) as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if residue_class == 0.0 {
        score -= 12.0; // "harmonic" residual, likely reusable
    } else if residue_class <= 3.0 {
        score += 4.0;  // small dead sliver, hard to use
    } else {
        score += residue_class * 0.5; // larger awkward residue
    }

    // Lookahead: reward if next item fits exactly into post_residual (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + chain_slack * 0.2);
        } else {
            // next item cannot use this residual at all: mild penalty scaled by waste
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, push toward tightest fit (already via post_residual).
        score += fitting_bins_count as f64 * 0.3;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or mean residual is too small for typical items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Penalize opening a new bin; relax as stream progresses or bins are crowded.
        score += 30.0 - 15.0 * progress - crowding.min(20.0);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // fallback: nothing fits anywhere sensibly
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0; // existing bins are nearly full anyway
        }
    }

    // Slight preference to fill already-open bins when many are open (bin count control).
    score += open_bins_count as f64 * 0.15;

    // Mild encouragement to place large items into bins with proportionally matching residual
    // (integer-division harmonic pairing).
    if bin_residual > 0 {
        let ratio = (item_size * 100 / bin_residual) as f64 / 100.0;
        if (ratio - 1.0).abs() < 0.05 {
            score -= 20.0; // near-exact harmonic match of item to residual
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap thresholds relative to smallest plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // likely dead space
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // next item can't use the leftover
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packs).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and the current fit would be poor.
        let poor_fit = if post_residual < 20 { 1.0 } else { 0.0 };
        score += 45.0 - 20.0 * poor_fit + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize leaving a gap that next item cannot use at all
        if next_item_size > post_residual {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fill
        score += (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Relative-to-mean residual coupling: avoid creating outliers of dead space
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tight-fit bonus for current item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // New-bin candidate: only attractive when open bins are heavily fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = 70.0 + 40.0 * (1.0 - progress) + 8.0 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 55.0; // no real alternative: opening is fine
        }
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.5 {
            score -= 10.0; // fresh bin can serve lookahead well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 0.15 * (post_residual as f64).min(next_item_size as f64);
    }

    // New-bin candidate handling: only attractive when alternatives are scarce
    // or the item fits poorly elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.5;
        if scarcity > 0.0 || (poor_fit && post_residual > 0) {
            score -= 25.0 * scarcity + 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        } else {
            score += 45.0; // discourage opening bins when good fits exist
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating
    // into bins with above-average residual (balance closing bins out).
    if open_bins_count > 1 {
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, keep residual space flexible;
    // late in the stream, aggressively close bins (favor small post_residual more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear waste penalty: dead space becomes quadratically worse as it shrinks
    score += 40.0 * norm_post * norm_post * (1.0 - norm_post);

    // Stream-progress coupling: later in the stream, prefer tighter fills (lower post residual)
    score *= 1.0 + 0.6 * progress * (1.0 - norm_post);

    // Reward using bins whose residual aligns with the item (good fit, smooth kernel)
    let fit_quality = (item_size as f64 / cap - 0.5).abs();
    score -= 15.0 * (1.0 - 2.0 * fit_quality) * (1.0 - norm_post);

    // Last-chance bin: strongly reward filling it to avoid waste
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_post);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 30.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Penalize bins far from mean residual (imbalance), smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight penalty on many open bins to discourage excessive fragmentation
    score += 0.15 * open_bins_count as f64 * norm_post;

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 35.0 * (1.0 - norm_post);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual lies in "dead zones"
    // (too small to fit any plausible future item) are punished less than bins whose
    // residual is a "good" reusable class.
    let dead_zone = bin_capacity / 3; // residual < ~33 is nearly unusable
    if post_residual < dead_zone {
        // small leftover: acceptable, mild bonus scaled by how dead it is
        score -= (dead_zone - post_residual) as f64 * 0.35;
    } else {
        // large leftover: penalize proportionally, but modulate by harmonic class
        let class = post_residual % (bin_capacity / 4).max(1);
        let class_penalty = if class == 0 {
            0.0 // clean multiple: easy to fill with standard items
        } else if class < bin_capacity / 8 {
            2.0 // awkward small offset
        } else {
            4.0 // highly fragmented class
        };
        score += class_penalty;
    }

    // Integer-division threshold: reward placements that keep residual in a
    // "fillable by medium items" band [bin_capacity/4, bin_capacity/2].
    let lo = bin_capacity / 4;
    let hi = bin_capacity / 2;
    if post_residual >= lo && post_residual <= hi {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly prefer this bin (perfect harmonic match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0; // exact fit for the next item
        } else if gap < bin_capacity / 5 {
            score -= 8.0; // near-exact fit
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: mild penalty proportional to overflow
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing an existing bin unless the new-bin option is genuinely better
    // (i.e., current bin would leave a large, awkward residual).
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin; add a fixed opening cost so it only wins
        // when open bins would waste a lot of space.
        score += 10.0;
        // If the stream is early, opening bins is cheap; later, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Mean-residual coupling: when open bins are generally quite full (low mean
    // residual), reusing bins is even more valuable.
    score -= (mean_residual / bin_capacity as f64) * 5.0;

    // Fraction-of-capacity packing: reward tight fits (small post_residual relative
    // to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    if tightness < 0.25 {
        score -= 10.0 * (0.25 - tightness);
    }

    // Tie-break: prefer bins with lower index-like state via open_bins_count pressure —
    // with many open bins, consolidation is valuable.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (<= 1 unit
    // of headroom under the observed minimum) are pure waste; push hard against them.
    if post_residual < 10 {
        score += 45.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // Medium-small gaps are risky dead space too.
        score += 12.0 + (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        // Perfect fill is the best possible outcome.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin's leftover will be unusable for the next item: mild penalty.
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins; new-bin candidate
    // (bin_residual == bin_capacity) gets penalized so it only wins on poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 15.0 * progress;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Alignment with mean residual: bins far below the mean residual are already
    // fragmented; deprioritize them slightly.
    score += (mean_residual - bin_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating awkward dead space that few items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is wasted
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // still usable zone
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare against the mean residual: prefer bins with below-average residual
    // (consolidating into fuller bins keeps many partially-filled bins flexible).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: late in the stream, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // New-bin candidate handling: empty bin baseline. Prefer opening a new bin
    // only when the item fits poorly everywhere else (large post_residual among
    // open bins) or when open bins are crowded.
    if bin_residual == bin_capacity {
        let base = 45.0
            + 0.3 * open_bins_count as f64
            + 0.2 * item_size as f64
            + 10.0 * (1.0 - progress);
        // If next item would combine with current item into a fresh bin perfectly, encourage it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score = base - 15.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr;

    // Polynomial coupling: post_residual^2 scaled by capacity, modulated by progress.
    // Late in the stream, dead space becomes more costly.
    let quad = (norm_pr * norm_pr) * cap;
    score += quad * (0.15 + 0.85 * progress);

    // Cubic smooth term: heavily penalize large residuals late in the stream.
    let cube = norm_pr * norm_pr * norm_pr * cap;
    score += cube * (0.05 + 0.45 * progress * progress);

    // Lookahead: if the next item fits the post-residual exactly or well, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let fit_quality = 1.0 - (gap / cap);
        score -= fit_quality * (next_item_size as f64) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted space.
        score += norm_pr * cap * 0.3 * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Compare against mean residual: bins below mean residual are more "committed"; prefer them.
    let mean_gap = mean_residual - pr;
    score -= mean_gap * 0.2;

    // Early stream: mild preference for keeping bins balanced (spread items across bins).
    let balance_bonus = (pr - mean_residual) * 0.1 * (1.0 - progress);
    score += balance_bonus;

    // Slight penalty for opening new bins when many are open and fitting bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers that match common item sizes
    // (or their complements) are "harmonious" and should be rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty grows super-linearly for small, hard-to-fill residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward residuals that are multiples of small harmonic units (10, 20, 25, 50).
    let harmonics: [u32; 5] = [10, 20, 25, 50, 100];
    let mut harmonic_bonus = 0.0;
    for h in harmonics.iter() {
        if post_residual % h == 0 {
            harmonic_bonus += 6.0 * (post / cap);
        }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this bin is a perfect harmonic partner — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of the pair.
            let tightness = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.3 * tightness;
        } else {
            // Next item cannot use this bin's leftover: penalize leftover size.
            score += 0.15 * (next_item_size as f64 - post);
        }
    }

    // Integer-division threshold on bin_residual: bins whose residual falls
    // in a "last-chance" band (residual < 2 * typical item) should be used now.
    if bin_residual / 2 < item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Last-chance bin: only one open bin can fit the item — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // here is poor (large post_residual relative to capacity) or the item is huge.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Large items justify fresh bins (they leave useful large residuals).
        if item_size >= bin_capacity / 2 {
            score -= 45.0;
        }
        // If many bins are open and mean residual is low, opening fresh is cheaper.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 20.0;
        }
        // Early in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    } else {
        // Reward using bins that are already well-filled (small residual).
        score -= 0.1 * (cap - bin_residual as f64);
    }

    // Mild preference for tight fits overall.
    score -= 0.5 * (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: post_residual that is too small to be useful later
    // is worse than a large gap. Items >= 1..=100, so treat gaps below ~20
    // as increasingly toxic dead space.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 20 {
            // small gap: penalize quadratically (dead space)
            score += (21.0 - pr) * (21.0 - pr) * 0.8;
        } else {
            // usable gap: mild reward for keeping flexible space
            score -= (pr - 20.0).min(40.0) * 0.15;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * (fill_ratio - 0.8);
    }

    // Last chance: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream
        score += 30.0 + 2.5 * open_bins_count as f64 + 40.0 * progress;
        // But if no open bin has a decent residual, opening is fine:
        if mean_residual < item_size as f64 {
            score -= 55.0;
        }
        // Lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight preference to keep mean residual balanced
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
        // Lookahead synergy: if next item fits the post_residual, reward
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // next item won't fit here; slight penalty for stranding space
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits in the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.8 * slack;
    }
    // Next item cannot use the leftover: penalize proportionally to wasted potential.
    else if next_item_size > 0 {
        let waste = next_item_size.min(post_residual) as f64;
        score += 0.5 * (next_item_size as f64 - waste);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (1..=5 units).
    if post_residual > 0 && post_residual <= 5 {
        score += 30.0;
    }

    // Compare against mean residual: bins with residual near mean are neutral,
    // much-larger-than-mean residuals are less attractive (save big bins for big items).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: only attractive early in the stream or when
    // the current bin would leave an awkward fit for the next item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        score += 10.0 + 40.0 * progress + if awkward { 35.0 } else { 0.0 };
    }

    // Late in the stream, prefer tightening fills to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: reward tight fits nonlinearly.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += residual_frac * residual_frac * 30.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward;
    // if this bin's post residual would be dead space relative to next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space unless future items are tiny; scale by how dead
            score += (post_residual as f64) * 0.35;
        }
        // Perfect pairing: item + next item exactly fills bin
        if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
            score -= 25.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: opening a new bin wastes the residual of all
    // open bins; penalize proportionally to open bins and mean residual,
    // unless current bin fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.25;
        // Early in stream, slightly prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 15.0;
    }

    // Prefer filling bins with larger residuals less when mean residual is low
    // (bins are nearly full anyway; keep tightness pressure).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Mild preference for bins whose residual is close to item size.
    let slack = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += slack * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress.clamp(0.0, 1.0);
    let poly = 1.0 + 0.8 * t - 0.9 * t * t + 0.6 * t * t * t;
    score *= poly;

    // Penalize dead space relative to capacity, amplified over time
    let dead_frac = pr / cap;
    score += 20.0 * dead_frac * dead_frac * (0.5 + t);

    // Reward tight fits (small post_residual) with mild non-linear bonus
    score -= 10.0 * (1.0 - dead_frac) * (1.0 - dead_frac);

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * 0.5);
    }

    // Prefer bins below mean residual (consolidating space)
    score += 0.3 * (pr - mean_residual);

    // Lookahead: penalize leaving residual too small for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: penalize mildly so only opened when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class analysis: classify post_residual into residue classes
    // modulo common small-item sizes (5, 10, 20). Dead space that cannot
    // host a future small item is penalized; usable space is rewarded.

    // Tightness: exact fill is best.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space that cannot hold even the smallest plausible item.
        let smallest = 5u32;
        if post_residual < smallest {
            score += 40.0; // nearly-useless sliver
        } else {
            // Modulo-class harmony: residual divisible by 5 or 10 is more
            // likely to be exactly consumed by future items.
            if post_residual % 5 == 0 {
                score -= 12.0;
            }
            if post_residual % 10 == 0 {
                score -= 12.0;
            }
            if post_residual % 20 == 0 {
                score -= 8.0;
            }
        }
    }

    // Integer-division thresholds: bucket post_residual into decile classes.
    // Mid-range leftovers (30..70) are the most reusable; extremes less so.
    let decile = post_residual / 10;
    match decile {
        0 => score += 6.0,           // 0-9: mostly dead space
        1 => score += 0.0,           // 10-19
        2 | 3 => score -= 6.0,       // 20-39: sweet spot for small items
        4 | 5 => score -= 2.0,       // 40-59
        6 => score += 4.0,           // 60-69
        7 => score += 8.0,           // 70-79
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how well next item harmonizes.
            let gap = post_residual - next_item_size;
            if gap % 5 == 0 {
                score -= 8.0;
            }
            if gap <= 10 {
                score -= 10.0;
            }
        } else {
            // Next item cannot go here; mild penalty scaled by overflow class.
            let overflow = next_item_size - post_residual;
            if overflow <= 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the fit would be poor (large dead space left behind).
        let poor_fit = (post_residual as f64) > 0.5 * (bin_capacity as f64);
        let crowded = mean_residual < 20.0 && open_bins_count > 0;
        if poor_fit && !crowded {
            score -= 15.0;
        } else {
            score += 55.0; // default: prefer filling existing bins
        }
        // Late in the stream, opening fresh bins is less valuable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild pressure to consolidate: prefer bins below mean residual when
    // many bins are open (keeps the mean low, closes bins faster).
    if open_bins_count > 3 {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..=20) are mildly penalized; they can still fit small items.
    else if post_residual > 0 && post_residual <= 20 {
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score += 2.0; // slight penalty: leaves a coupled placement less controlled
    }

    // New-bin candidate handling: opening a bin is penalized unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Open bins pressure: when many bins are open, prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual deviates from the mean (consolidate waste).
    score -= 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect match: huge reward.
        if diff == 0.0 {
            score -= 40.0 + 0.5 * nxt;
        } else if pr > nxt {
            // Next item fits exactly into leftover: partial reward scaled by closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space, worse when close to next size.
            score += 8.0 * (1.0 - diff / nxt.max(1.0) / 2.0).max(0.0);
        }
        // If next item is large and this bin's post_residual can't hold it, mild penalty
        // unless post_residual is tiny (nearly full bin is fine).
        if pr < nxt && pr > 0 && pr < 10.0 {
            score -= 3.0; // small residual is good dead space
        }
    }

    // Compare against mean residual: bins with residual far below mean are "tight" bins;
    // filling them fully is good (removes fragmentation).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(20.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(30.0) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discourage opening a new bin when good existing fits exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline score = full capacity; only wins if existing bins score worse.
        score = bin_capacity as f64 * 0.9;
        // Open a new bin early in stream or when open bins are crowded / poor fits.
        if next_item_size > 0 && (next_item_size as f64) > pr + 0.0 {
            score -= 5.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Mid-stream, prefer compacting into open bins unless this is a large item.
        score += progress * 5.0;
        if item_size >= 60 {
            score -= 8.0; // large items pair well in fresh bins
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 6.0; // existing bins are fragmented; fresh bin helps
        }
    }

    // Slight penalty for wasting a large-capacity bin on a tiny item.
    if (item_size as f64) < 0.25 * bin_residual as f64 && bin_residual != bin_capacity {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty for leftover space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: leftover smaller than the smallest plausible item (<=10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chained fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // leftover too small for next item: mild penalty scaled by how close it is
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate logic: an empty bin is attractive when current bins fit poorly
    // or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin: moderate default so it only wins when needed.
        score = 0.5 * bin_capacity as f64 + 10.0;
        // Prefer new bin when item is large and would leave tight fits elsewhere.
        score -= 0.2 * item_size as f64;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Many open bins with slack: discourage new bin.
        score += 0.5 * open_bins_count as f64;
        // If mean residual comfortably exceeds item, prefer existing bins.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // If no open bin fits (fitting_bins_count == 1 refers to the new bin itself), allow opening.
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Prefer filling bins that deviate below the mean residual (consolidate slack).
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
        // Early stream: slightly favor spreading to build flexible partial bins? No—
        // favor consolidation to keep future freedom: mild penalty for many open bins.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual (tight fits), scaled non-linearly.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth non-linear coupling with stream progress:
    // early on, tight fits matter more; later, keep flexibility.
    let tightness_bias = (1.0 - progress) * (norm_pr * norm_pr) * 6.0;
    let flexibility_bonus = progress * (1.0 - norm_pr) * 1.5;
    score += tightness_bias - flexibility_bonus;

    // Reward using bins with larger residuals when item is big (avoid wasting big items on small holes).
    let hole_item_coupling = (norm_pr - norm_item) * (0.5 + progress);
    score += hole_item_coupling * 0.4;

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.5 + 2.0 * progress;
    }

    // Lookahead: if the next item fits in post-residual, reward this placement.
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let smooth = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= next_fits * (1.2 + 0.8 * smooth);
    }

    // Mean residual context: prefer bins deviating above mean (consolidate large holes).
    let mean_norm = mean_residual / cap;
    score += 0.6 * (norm_pr - mean_norm) * (1.0 - progress);

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 1.0 + 3.0 * (1.0 - progress) + 0.02 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: integer-division thresholds (capacity / 10 buckets)
    let cls = post_residual / 10;
    score += match cls {
        0 => -30.0,           // near-perfect fill (0-9 dead space)
        1 => -15.0,           // good fit
        2 => -5.0,            // acceptable
        3 => 8.0,             // mediocre
        4 => 15.0,            // poor
        5 => 20.0,            // half-bin waste
        _ => 22.0,            // large dead space
    };

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic alignment: item sizes on capacity-fraction grid pack better
    if item_size % 10 == 0 {
        score -= 5.0;
    }
    if item_size % 25 == 0 {
        score -= 3.0;
    }

    // New-bin candidate: penalize strongly so open bins are preferred unless fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in stream, opening bins is cheaper; late, hoard capacity
        score -= 15.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly reward using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): reward if next item also fits in the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic bonus: next item lands on a class boundary of post_residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Coupling with mean residual across open bins: prefer bins below mean (tighter)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    // Slight time scaling to stabilize late-stream choices
    score * (1.0 + 0.1 * progress)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (1..=10) are essentially unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        // Marginal zone: usable only by very small items; moderate penalty.
        score += 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 6.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 120.0;
    } else {
        // Large comfortable residual: mild reward scaled by size.
        score -= (post_residual as f64 - 35.0).min(30.0) * 0.4;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading further,
    // favor consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if mean residual is high, prefer bins that
    // reduce dispersion (place into bins with residual below the mean).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward;
    // otherwise penalize leaving a gap that blocks the known next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(25.0) * 1.5;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Base cost of opening a new bin, softened late in the stream or when
    // the current item is large (large items fill a fresh bin efficiently).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 35.0;
        // Large items justify a fresh bin more readily.
        if item_size >= 60 {
            new_bin_cost -= 20.0;
        } else if item_size <= 25 {
            new_bin_cost += 15.0;
        }
        // Late in the stream, leftover bins are less costly to open.
        new_bin_cost -= progress * 10.0;
        // If many bins are already open, avoid adding more.
        new_bin_cost += open_bins_count as f64 * 0.5;
        score += new_bin_cost.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (2-step lookahead perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item still fits in the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (post_residual as f64 - next_item_size as f64);
    }
    // Penalty: next item cannot fit in this bin's leftover (dead space until later).
    else if next_item_size > 0 {
        score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight packing relative to mean residual of open bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Penalize very small unusable leftovers relative to the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when few bins fit the item
    // or the stream is just starting.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 0.0 } else { (fitting_bins_count as f64) * 18.0 };
        let early = if total_items > 0 && step_index < 2 { -20.0 } else { 0.0 };
        score = cap * 0.55 + scarcity + early;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 20.0; // perfect lookahead fit — excellent
        } else {
            score -= 4.0; // next item can still fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // If many bins fit, prefer the one with least waste.
        score += 0.5 * fitting_bins_count as f64;
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * pressure;
        // Late in the stream, opening new bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If mean residual is small (bins nearly full), new bin is reasonable.
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    }

    // Prefer filling bins that are already partially committed (low residual relative to mean).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Early in stream: keep bins open and flexible; penalize creating tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress); // small dead space costly early
        score -= 5.0 * progress;          // acceptable late
    }

    // Mild penalty for proliferating open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = 60.0 * norm_pr.powf(1.8);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, slack is acceptable.
    let coupling = 1.0 + 1.6 * progress * (1.0 - 0.5 * progress);
    score *= coupling;

    // Interaction: post_residual^2 relative to mean residual across open bins.
    let mean_r = mean_residual.max(0.0);
    score += 0.35 * (pr * pr) / (cap * cap) * (1.0 + mean_r / cap);

    // Penalty if post_residual is a dead zone: too small for typical future items,
    // but not zero. Smooth bump around small-but-nonzero residuals.
    let dead = (norm_pr * (norm_pr - 0.15)).abs();
    score += 8.0 * dead;

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - pr / cap) * (nx / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: mildly penalize opening new bins unless residuals are tight.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 10.0 + 2.0 * openness.powf(0.7) * (1.0 - progress);
        // Opening a new bin is attractive if current item leaves a huge post_residual
        // in any existing bin (poor fit everywhere).
        score += 0.2 * item_size as f64;
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_residual as f64 / cap).ln().max(-3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic class of the leftover space: how the post residual
    // partitions the capacity. Class 0 = perfect fit (residual 0),
    // class 1 = tiny dead space, larger classes = increasingly reusable.
    let mut score = post_residual as f64;

    // ---- Perfect fit: strongest reward ----
    if post_residual == 0 {
        score -= 60.0;
    }

    // ---- Dead-space penalty: leftover that the NEXT item cannot use ----
    // Harmonic bucketing of post_residual via integer division thresholds.
    let pr = post_residual;
    if next_item_size > 0 {
        if pr > 0 && pr < next_item_size {
            // leftover is unusable by the lookahead item -> dead space
            // bucket it: tiny leftovers (1..=9) are worst, then 10..=24, etc.
            let bucket = if pr <= 9 { 3.0 } else if pr <= 24 { 2.0 } else if pr <= 49 { 1.2 } else { 0.6 };
            score += bucket * (next_item_size as f64 - pr as f64) * 0.35;
        } else if next_item_size > 0 && pr >= next_item_size {
            // leftover can host the next item: reward proportional to snugness
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - snug / bin_capacity as f64).max(0.0);
        }
    } else {
        // last item of the stream: only perfect closure matters
        if pr > 0 {
            score += pr as f64 * 0.2;
        }
    }

    // ---- Modulo-class coupling between item and residual ----
    // Items whose size divides the capacity cleanly leave harmonious gaps.
    let fits_nicely = (bin_capacity % item_size.max(1)) == 0;
    if fits_nicely && pr < item_size {
        score -= 4.0;
    }

    // ---- Last-chance bin: if this is the ONLY bin that fits, use it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // extra push when the fit is tight
        if pr <= 10 {
            score -= 10.0;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high, so we only open when
        // existing bins offer poor fits.
        score = bin_capacity as f64 * 1.1;
        if fitting_bins_count == 0 {
            // no open bin can take the item: opening is mandatory
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            // an existing last-chance bin exists; only open new if that
            // bin would leave a really awkward gap
            if pr >= 0 && item_size * 2 <= bin_capacity {
                score -= 15.0; // big item, fresh bin may be fine
            }
        } else if open_bins_count > 6 {
            // many open bins with slack: discourage fragmentation
            score += 10.0;
        }
        // if next item is huge and current item is small, keep bins tight
        if next_item_size > 60 && item_size < 30 {
            score += 20.0;
        }
    }

    // ---- Mild global pressure: fewer open bins is better ----
    score += open_bins_count as f64 * 0.15;

    // ---- Mean-residual coupling: prefer bins below mean residual
    // (i.e., tighter than average) to consolidate fullness ----
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size (1..100 interface => treat < 10 as near-dead) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
        if post_residual == 0 {
            score -= 25.0; // perfect fit is excellent despite the rule
        }
    } else {
        // Prefer small-but-usable residuals, with a soft quadratic pull.
        score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Reward tight fits generally.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if the next item would not fit, penalize creating that residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 0.8 * (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // prefer the single existing fitting bin
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64; // keep using open bins
        }
    }

    // Mild stream-progression coupling: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 50.0; // exact 2-step fill: strongly favored
        } else {
            score += diff * 0.5; // penalize mismatch magnitude
        }
        // penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a large residual bin on a small item
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Prefer bins tighter than the mean residual
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty
    score += (post_residual as f64 / cap).powi(2) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post-residual that still fits the lookahead item is excellent
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            score -= 15.0 + 25.0 * (ni / cap);
        } else {
            // dead space that can't hold the next item
            score += 10.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        let mut penalty = 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            penalty += 30.0;
        }
        if next_item_size > 0 && (bin_residual as f64 >= item_size as f64 + next_item_size as f64) {
            penalty -= 20.0; // new bin can host current + next item
        }
        score += penalty;
    }

    // Time horizon: early on, be frugal with bins; late, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Prefer bins whose residual deviates favorably from the mean residual
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0 * (mean_residual - res) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer low post_residual (tight packing).
    let mut score = pr;

    // Normalized fit quality: fraction of the bin consumed by this placement.
    let fill = item / cap;                       // in (0,1]
    let tightness = 1.0 - pr / cap;              // 1 = perfectly full bin

    // Smooth non-linear reward for tight fits, growing with stream progress.
    let tight_reward = (tightness * tightness) * (1.0 + progress) * 12.0;
    score -= tight_reward;

    // Penalize leaving dead space that is too small for typical items:
    // smooth polynomial bump centered at small-but-nonzero residuals.
    let dead = pr / cap;
    let dead_penalty = 20.0 * dead * (1.0 - dead) * (1.0 - dead);
    score += dead_penalty;

    // Lookahead coupling: if next item fits the post-residual, reward this placement;
    // otherwise penalize mildly, scaled by how much it fails.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let compat = 1.0 - (pr - nxt) / cap;
            score -= 8.0 * compat * compat * (1.0 + progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 6.0 * progress;
    }

    // Slight preference for bins already below mean residual (balance avoidance of
    // fragmenting many bins): penalize bins with residual far above the mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for proliferation of open bins early in the stream.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 0.5;

    // New-bin candidate guard: an empty bin has pr == cap - item, which is large,
    // so it naturally scores worse than a good fit; add a small constant edge
    // only when the fit into an existing bin is very poor (high post_residual).
    if bin_residual == bin_capacity {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins with residual in "dead" classes
    // (small, hard-to-fill gaps) should be penalized; snug fits rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Snug fit reward: post_residual small relative to item size.
    let snug = (item - post) / item; // in [0,1), higher = tighter fit
    score -= 12.0 * snug;

    // Dead-space class penalty via modulo arithmetic on post_residual.
    // Residuals that are small but nonzero (1..=9) are nearly useless.
    let class = post_residual % 25;
    if post_residual > 0 && class <= 9 {
        score += 8.0 + (9.0 - class as f64);
    }

    // Perfect fill: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly-ish,
    // reward; if next item cannot ever fit post residual, mild penalty only
    // when post residual is in a dead class.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let waste = post - nx;
            score -= 6.0 * (1.0 - waste / cap);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the
    // item is large or all existing residuals are poor. Penalize default
    // new-bin score so it loses unless fits are bad.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.35 * (mean_residual - post);
        // If item fills a fresh bin well, make new bin more attractive.
        if item >= 0.6 * cap {
            score -= 20.0;
        }
        // Early in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if fitting_bins_count <= 1 && next_item_size > 0 && (next_item_size as f64) > post {
            score -= 10.0;
        }
    }

    // Mild pressure against many open bins with high mean residual.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is a last resort: make it expensive.
        score = bin_capacity as f64 * 1.5;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If no existing bin fits, we must open one regardless.
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 2.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        return score;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // marginal gap
    } else if post_residual == 0 {
        score -= 20.0; // perfect fit: strongly reward closing the bin
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Tight-fit reward: residual close to item size means good packing.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Lookahead: if next item exactly fits the resulting post_residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits into the resulting gap: reward proportionally to tightness.
        let tight = 1.0 - ((post - nxt) / cap);
        score -= 25.0 * tight;
    } else if next_item_size > 0 {
        // Next item would NOT fit: penalize dead space beyond a small threshold.
        score += 8.0;
    }

    // Reward tight fits relative to current bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize bins that are already much emptier than the mean (poor consolidation),
    // favor bins whose residual is close to the item.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last chance bin: strong incentive to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    // (item large relative to mean residual) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / cap;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 70.0
            - 40.0 * pressure
            - 20.0 * crowding
            - 10.0 * progress;
        // If this is the only fitting bin among open ones, discourage new bin.
        if fitting_bins_count <= 1 {
            score = base + 60.0;
        } else {
            score = base + post;
        }
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 15.0; // new bin can also host the next item
        }
    }

    // Small bonus for leaving post-residual below the smallest plausible item (dead space).
    if post > 0.0 && post < 10.0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize small unusable dead space (post_residual below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // existing fits are poor or the item would leave big dead space elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0 + 0.15 * open_bins_count as f64;
        // If the next item is large and current residual would be tiny, opening
        // a fresh bin for the pair can be better.
        if next_item_size > 0 {
            let combo = item_size + next_item_size;
            if combo > bin_capacity {
                // item + next cannot share; if this bin would waste space, prefer new bin.
                if post_residual < next_item_size.min(30) {
                    score -= 30.0;
                }
            } else if post_residual >= next_item_size {
                // Empty bin can host both items: attractive.
                score -= 20.0;
            }
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        // Lookahead synergy: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 35.0;
            } else if post_residual > next_item_size {
                score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
            } else {
                // next item won't fit here; slight penalty proportional to mismatch.
                score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
            }
        }
        // Prefer bins whose residual deviates from mean in a useful way:
        // filling below-mean-residual bins reduces fragmentation.
        let dev = bin_residual as f64 - mean_residual;
        if dev < 0.0 {
            score -= 0.05 * (-dev);
        } else {
            score += 0.03 * dev;
        }
    }

    // Global pressure: when many bins are open, consolidate; when few, spread.
    if open_bins_count > 8 {
        score += 1.0;
    } else {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, with non-linear (quadratic) waste emphasis.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth coupling of waste penalty with stream progress: later in the stream,
    // dead space becomes more costly.
    score += 1.5 * progress * (post / cap) * (post / cap) * cap * 0.1;

    // Reward tight fits: normalized fill fraction of the bin after placement.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 4.0 * fill * fill;

    // Lookahead: if the next item fits the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 3.0 * (1.0 - nxt / cap);
        } else {
            score += 2.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Slight preference for bins with residuals near the mean (keeps spread balanced),
    // penalizing outliers smoothly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate (empty bin): penalize unless the item fills it well,
    // so we only open new bins when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let waste = cap - item_size as f64;
        let base = 8.0 + 6.0 * (waste / cap) * (waste / cap) + 4.0 * progress;
        score += if waste <= 20.0 { 1.0 } else { base };
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets modulate dead-space penalty.
    let harm = post_residual % 10;
    score += match harm {
        0 => -12.0,          // perfectly harmonic residual, highly reusable
        5 => -6.0,           // half-harmonic
        1 | 9 => 4.0,        // near-full dead space
        2 | 4 | 6 | 8 => 2.0,
        _ => 0.0,
    };

    // Integer division threshold: small post_residual (< 10) is dead space unless item filled bin.
    if post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fits: post_residual small relative to item_size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 10.0 / (1.0 + tightness);

    // Lookahead coupling: prefer bins whose post_residual matches next item's harmonic class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0 / (1.0 + gap as f64);
            }
        } else {
            // Next item cannot fit here; slight penalty for wasting the residual.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.25 && open_bins_count > 2 {
            score -= 5.0 * (0.5 + progress);
        } else {
            score += 6.0;
        }
    }

    // Late-stream consolidation: tighten bin preference as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful
    // for typical items are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 40.0; // tiny unusable sliver
    } else if pr >= 10.0 && pr < 20.0 {
        score += 12.0; // only fits very small items
    } else if pr >= 20.0 && pr < 35.0 {
        score += 4.0;  // marginal gap
    } else if pr == 0.0 {
        score -= 30.0; // perfect fill
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Reward using bins with little residual relative to mean (compact bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 15.0 * dev; // prefer bins tighter than average

    // Pressure on number of open bins: discourage opening new bins
    // when many are already open; encourage consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.9 * progress) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // post-residual cannot host the next item: slight penalty if gap is dead
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Penalize opening a brand-new empty bin unless current bins are truly bad:
    // an empty-bin candidate gets its baseline post_residual = capacity - item,
    // which is already high; add extra inertia so consolidation wins ties.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual is good).
    score *= 1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: excellent — subtract a reward proportional to leftover after next item.
            let chain_left = post_residual - next_item_size;
            score -= 30.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted residual that is neither usable by next item nor tight.
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            if post_residual < next_item_size && post_residual > 0 {
                score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
            }
            let _ = gap;
        }
    }

    // Compare post_residual against mean residual: leaving this bin far below mean
    // creates fragmented dead space; prefer bins whose residual converges to the mean.
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or open bins are very fragmented.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; make it slightly worse than a good fit,
        // but attractive when fits are scarce or item is huge.
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain the next item too
        }
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0; // big item: fresh bin gives clean placement
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear emphasis
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residuals that are too small for the minimum item size are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // exact chain fit is excellent
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin even now; mild bonus for using it
            score -= 4.0;
        } else {
            // next item fits this bin now but would not after placement: penalize
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation into existing bins rather than spreading
    let open_frac = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    score += open_frac * 2.0;

    // Compare against mean residual: prefer bins with below-average residual (fuller bins)
    let dev = mean_residual - (bin_residual as f64);
    score += dev * 0.6;

    // Time horizon: early in the stream, be more willing to open new bins / keep flexibility;
    // late in the stream, pack tightly and avoid leftovers
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 - progress * 5.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when all open bins score poorly (bad fits, last-chance failures)
    if bin_residual == bin_capacity {
        score += 45.0;
        // late in stream, opening a new bin is cheaper than wasting space
        if progress > 0.7 && post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (waste compounds less recoverably).
    let coupling = 1.0 + 1.5 * progress * progress;
    score *= coupling;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > post_residual {
        // Dead space that the next item cannot use; penalize smoothly.
        score += 3.0 * (next_item_size as f64 / cap) * (post / cap);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: make it attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually; relax as stream progresses.
        score = cap * (0.35 + 0.4 * progress);
        // If current bin would leave large dead space, new bin becomes competitive.
        if post_residual > item_size / 2 {
            score -= 4.0;
        }
        // Many open bins with high mean residual: prefer filling existing bins.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into
    // capacity-fraction buckets. Residuals in small buckets (near 0) are
    // excellent (tight fit); large buckets waste capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Quadratic dead-space penalty (harmonic curvature)
    score += 40.0 * frac * frac;

    // Integer-division thresholds on post_residual: reward residuals that
    // still admit common small item classes (1..=20, 21..=40, ...).
    let class = post_residual / 20; // 0..=5
    let class_bonus: [f64; 6] = [30.0, 18.0, 10.0, 4.0, 0.0, -6.0];
    score -= class_bonus[(class as usize).min(5)];

    // Modulo arithmetic on post_residual: residuals divisible by small
    // integers are more likely reusable by future items.
    let res = post_residual;
    if res > 0 {
        if res % 10 == 0 { score -= 6.0; }
        else if res % 5 == 0 { score -= 3.0; }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportionally to how well next item uses leftover.
        score -= 8.0 * (next_item_size as f64 / pr.max(1.0));
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leftover is likely dead space.
        score += 12.0 * frac;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0 + 0.1 * open_bins_count as f64;
        // If no open bin can fit the item, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Large items justify fresh bins; small items should pack tightly.
        score -= 0.3 * item_size as f64;
        // Early in the stream, opening bins builds flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual is high, open bins have room; discourage new bin.
        score += 0.4 * (mean_residual - 20.0).max(0.0);
    }

    // Slight preference for fuller bins overall (best-fit bias).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Medium-small gaps: moderate penalty scaled by how "wasted" the space is.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // Larger usable gaps: mild reward for keeping flexibility.
        score -= 5.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: the smaller post_residual relative to item, the better.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Open-bins pressure: penalize opening new bins when alternatives exist.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for reusing existing bins, stronger when few fitting bins.
        score -= 3.0;
        if fitting_bins_count == 1 {
            score -= 15.0; // last-chance bin: strongly favor using it
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetically placing next item
            score += slack * 0.8;
            if slack < 10.0 {
                score -= 15.0; // near-match still good
            }
        } else {
            // next item won't fit here anyway; leftover dead space penalty
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (good fit),
    // penalize wasting a very full bin on a small item.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists,
    // i.e., when current bin would leave a large awkward residual.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            post_residual as f64
        };
        score = 100.0 + bad_fit * 0.5 - (item_size as f64) * 0.1;
        if fitting_bins_count <= 1 {
            score += 50.0; // never open a new bin if this is the only fitting bin
        }
    }

    // Early stream: be slightly more willing to spread items across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual fraction, the better.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot follow here: slight penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when the item is large and
    // existing residuals are poor fits, or when many bins exist and spreading
    // load is beneficial.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins early or for small items.
        score += 15.0 * (1.0 - fill_frac);
        score += 10.0 * (1.0 - progress);
        // Reward opening a new bin when existing bins are crowded (low mean residual)
        // relative to the item, or when this is a near-perfect single-item fit.
        if fill_frac > 0.85 {
            score -= 10.0;
        }
        if (mean_residual as u32) < item_size && mean_residual > 0.0 {
            score -= 6.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance load),
    // scaled by how many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count.min(20) as f64).sqrt();

    // Late-stream consolidation: favor filling existing bins tightly as the
    // stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate slack; later, punish dead space quadratically.
    let slack_term = pr / cap;
    score += 60.0 * slack_term * slack_term * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly over time.
    let tightness = 1.0 - slack_term;
    score -= 25.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by how much slack others have.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins whose residual is below the mean (consolidating waste).
    score += 8.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Lookahead: if the next item would fit the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Penalize placements that strand space the next item can't use.
            score += 10.0 * (nxt - pr) / cap * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (late in the stream, slack is cheaper to leave behind).
        score = cap * (1.0 - 0.6 * progress);
        // If the item would leave a large unusable gap in this new bin, keep it cheap.
        score -= 15.0 * (1.0 - slack_term);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are exact capacity fractions
    // (C/4=25, C/2=50, 3C/4=75) or multiples of common item sizes are reusable.
    let post = post_residual;
    let harmonic_bonus: f64 = if post == 0 {
        -60.0 // perfect fit, best outcome
    } else if post % 25 == 0 {
        -25.0 // quarter-capacity class residuals are highly reusable
    } else if post % 10 == 0 {
        -12.0 // decade class
    } else if post % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead space penalty: residual too small to fit the minimum item class.
    // Use integer-division thresholds: post < 10 is almost surely dead.
    if post > 0 && post < 10 {
        score += 45.0;
    } else if post > 0 && post < 20 {
        // awkward class: penalize proportionally to how close to dead it is
        score += 20.0 * (1.0 - post as f64 / 20.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post && post % next_item_size == 0 {
            score -= 20.0; // next item divides residual evenly
        } else if next_item_size <= post {
            score -= 8.0;
        } else {
            // next item cannot use this residual: penalize residual we leave behind
            score += (post as f64) * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: brand-new empty bin has post_residual == bin_capacity.
    // It should be chosen only when no open bin gives a decent fit. Give it a mild
    // baseline penalty so tight fits into open bins win, but keep it competitive
    // against bins leaving dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in the stream, opening bins is cheaper; late, consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer filling bins that are already relatively full (low residual relative to mean).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 5.0 * (rel - 1.0).min(2.0);
        }
    }

    // Mild penalty per open bin to encourage consolidation when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Integer-division threshold on item_size: large items (half capacity or more)
    // should go into bins they nearly fill.
    if item_size >= bin_capacity / 2 && post <= 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already favored).

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest item are unusable — penalize them extra.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0; // leaves room for the next item
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we
    // only open a new bin when fits in open bins are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Extra pressure when many bins are already open.
        score += open_bins_count as f64 * 2.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins,
    // but only when this bin would leave a decent residual anyway.
    if post_residual >= 10 {
        score += open_bins_count as f64 * 0.5;
    }

    // Alignment with mean residual: bins whose post_residual is far below
    // the mean are being filled tighter than average — slight reward.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fills (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can be packed here afterwards: strong bonus, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.25 * slack;
        } else {
            // Leftover is dead space for the next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.4 * dead;
        }
    }

    // Relative to mean residual: bins already loose (large residual) are better
    // candidates to consume; tight bins should be preserved.
    if (bin_residual as f64) > mean_residual {
        score -= 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening new bins when several bins already fit the item mildly,
    // and when the stream still has many items left.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base penalty so we only open when fits are bad.
        score += 55.0;
        // As the stream progresses, opening new bins becomes less harmful.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 20.0 * progress;
        }
    } else if fitting_bins_count > 2 {
        score += 5.0; // plenty of options; prefer tightest fit via post_residual ordering
    }

    // Discourage creating residuals that no plausible item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are wasteful unless it was a near-perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
