pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits, with a non-linear (quadratic) penalty on leftover space.
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth coupling: late in the stream, dead space matters more (fewer chances to fill it).
    let late = progress * progress;
    score += 60.0 * late * post_norm * (1.0 - post_norm);

    // Reward using a bin whose post-residual matches the next item (chained fit), smoothly.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let chain = 1.0 - (post - nxt).abs() / cap;
        score -= 25.0 * chain.max(0.0) * (1.0 - late);
    }

    // Penalize bins with residual far above the mean (hoarding space), smoothed by progress.
    score += 0.5 * (bin_residual as f64 - mean_residual).abs() * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - post_norm);
    }

    // Mild preference against opening new bins when many are open; eased late in stream.
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress) * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += post_residual as f64 * 0.5;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" class (large enough for typical next items) get a bonus.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr / 10; // integer division class 0..=9
        match cls {
            0 => score -= 20.0,           // nearly perfect fit
            1 => score -= 8.0,            // small but usable
            2 => score -= 4.0,
            3 => score += 2.0,
            4 => score += 5.0,            // awkward mid leftover
            5 => score += 3.0,
            6 => score += 0.0,
            7 => score -= 3.0,            // large leftover still reusable
            8 => score -= 5.0,
            _ => score -= 6.0,            // nearly empty bin, very flexible
        }
    } else {
        score -= 25.0; // perfect closure: bin exactly filled
    }

    // Lookahead coupling: reward leftovers that can host the next item,
    // penalize leftovers that cannot.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= (next_item_size as f64) * 0.4;
        } else {
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless few bins fit
    // the item or current bins are very full (large mean fill).
    if bin_residual == bin_capacity {
        score = 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else {
            let fill = 1.0 - mean_residual / bin_capacity as f64;
            if fitting_bins_count == 1 {
                score -= 40.0; // only one fitting bin: allow new bin sometimes
            }
            if fill > 0.75 {
                score -= 30.0; // existing bins nearly full
            }
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= progress * 5.0;
        }
    }

    // Slight preference for bins already below mean residual (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.0 + progress);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (avoid outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // New-bin candidate: only attractive when it creates roomy residual relative to next item.
    if bin_residual == bin_capacity {
        let new_bin_bonus = if next_item_size > 0 && post_residual >= next_item_size { 4.0 } else { 12.0 };
        score += new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus when next item exactly fills the post residual (perfect 2-chain).
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 40.0;
        } else if diff < 10.0 {
            score -= 20.0 * (1.0 - diff / 10.0);
        }
        // Penalize leaving a residual that is awkwardly close but not matching
        // (dead space trap: slightly larger than next item but unusable).
        if post_residual > next_item_size && post_residual - next_item_size < 5 {
            score += 8.0;
        }
        // If post residual can't hold next item, mild penalty scaled by dead space.
        if post_residual < next_item_size {
            score += 3.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 5.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    // far below the mean (fragmented bin) unless the fit was tight.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.25;
    } else {
        score += mean_gap * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: small post residual is good (already in base score),
    // but give extra shaping for very tight fits.
    if post_residual <= 5 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, but allow it
    // when existing bins would leave large dead space or when bins are few.
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) as f64;
        let pressure = open_bins_count as f64;
        // Prefer new bin when it would preserve a flexible large residual
        // relative to typical open-bin residuals.
        score = dead * 0.5 + 20.0 - pressure * 0.5;
        if next_item_size > 0 && dead >= next_item_size as f64 {
            score -= 10.0; // fresh bin can also host next item
        }
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared normalized fill ratio discount.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill * fill;

    // Penalize small dead space that nothing can use later (dead-space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits badly everywhere else. Base penalty that shrinks with stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 40.0 - 15.0 * progress;
        // If many bins are open and mean residual is high, prefer reusing them.
        new_bin_penalty += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.15;
        // If item is large relative to capacity, new bin is less bad.
        new_bin_penalty -= (item_size as f64 / cap) * 10.0;
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference to fill bins with residual close to mean (balance exploitation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - pr / cap;
    score -= 12.0 * tight * tight;

    // Penalize dead space that no future item (>=10) can plausibly use,
    // weighted by stream progress: dead space hurts more later.
    let waste = (pr - 0.0).max(0.0);
    score += 0.35 * (waste / cap).powi(2) * (1.0 + progress);

    // Lookahead coupling: reward if the next item fits in the post residual,
    // penalize if next item is large relative to remaining space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = 1.0 - (pr - nxt) / cap;
            score -= 6.0 * fit_ratio * fit_ratio;
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (item_size as f64 / cap);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Prefer open bins unless they leave very large unusable residuals.
        // Penalize new bin mildly, more as progress grows (packing density matters late).
        score += 4.0 + 10.0 * progress;
        // If mean residual across open bins is already large, opening a new bin
        // is less attractive (spread items across existing space).
        score += 0.05 * mean_residual.max(0.0);
    } else {
        // Slight preference for filling bins with above-mean residual usage.
        let res = bin_residual as f64;
        let dens = (cap - res) / cap;
        score -= 2.0 * dens * dens;
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.15 * (open_bins_count as f64) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are good (tight packing), large residues waste space.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward very tight fits strongly.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr <= 10 {
        score -= 10.0;
    }

    // Harmonic (modular) classes on post_residual: residues divisible by
    // common item granularities are more reusable.
    let residue_class_bonus = match pr % 10 {
        0 => 8.0,
        1 | 2 | 3 | 4 => 4.0,
        5 => 6.0,
        _ => 0.0,
    };
    score -= residue_class_bonus;

    // Penalize large dead space unless the next item can use it.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward leaving exactly enough room.
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 - (slack / cap) * 4.0;
        } else {
            // Lookahead cannot use the residual: penalize proportionally.
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing residuals are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If open bins are fragmented (high mean residual but item still doesn't fit
        // many bins), opening fresh can be right — reduce penalty.
        if open_bins_count > 0 {
            let fragmentation = mean_residual / cap;
            score -= fragmentation * 20.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Mild preference to fill already-open bins as their count grows.
    score -= (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items are heavily penalized. Treat residual < 10 (or < next item) as waste.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is slightly larger than next item (near-miss waste).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 8.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening more.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins with residual close to the item (minimizes post_residual variance).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Mean-residual coupling: if mean residual is high, filling a large-residual
    // bin is more valuable.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the fit
    // is large relative to capacity or no good existing option exists.
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin is costly.
        score += 45.0;
        // But if the item is huge and would leave a usable gap elsewhere, ease it.
        if fill_ratio > 0.7 {
            score -= 30.0;
        }
        // If open bins are mostly full (low mean residual), new bin is fine.
        if mean_residual < 25.0 {
            score -= 15.0;
        }
        // Lookahead: if next item is huge and current bin can't hold both anyway,
        // a fresh bin preserves flexibility.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity && next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Mild stream-progression term: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual).
    let residual_f = bin_residual as f64;
    let cap = bin_capacity as f64;
    let item_f = item_size as f64;

    // Reward near-perfect packing: small post_residual relative to capacity.
    score -= 2.5 * (1.0 - (post_residual as f64) / cap);

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item size, enabling a chain placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = ((post_residual as f64) - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits after this placement: strong reward for exact match.
            score -= 18.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 25.0; // perfect two-item chain
            }
        } else {
            // Post-residual is dead space for the next item: penalize.
            score += 6.0 + diff * 0.08;
        }
    }

    // Coupling with mean residual: avoid bins whose placement leaves them
    // far below the fleet's mean residual (wasted large gaps).
    let gap = (post_residual as f64) - mean_residual;
    score += 0.15 * gap.max(0.0) - 0.05 * (-gap).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - (post_residual as f64) / cap);
    }

    // New-bin candidate handling: penalize opening a new bin for small items,
    // but allow it when the item is large and would leave a usable remainder.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_f <= 0.5 * cap {
            score += 30.0; // discourage new bin for small items
        } else {
            score += 8.0 - 10.0 * (item_f / cap) - 3.0 * progress;
        }
        // If other fitting bins exist, new bin should rarely win.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Mild preference for filling fuller bins first (best-fit flavor).
    score += 0.1 * (residual_f / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 22.0 * tight * tight;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leaving gaps that no plausible item (>=1) fills well.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // tiny slivers are hard to reuse
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; mildly penalize leaving medium gaps
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize dumping into bins with large residuals when many bins are open (fragmentation risk).
    let frag = (bin_residual as f64 - mean_residual).abs();
    score += 0.35 * frag * (open_bins_count as f64).sqrt();

    // Prefer using fuller bins (low residual) to keep high-residual bins flexible.
    score += 0.10 * bin_residual as f64;

    // New-bin candidate handling: an empty bin is a fallback.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // More attractive late in the stream or when current bins are badly fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0; // nothing usable anyway
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference to keep number of open bins in check early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, with a convex (quadratic) coupling so
    // large dead space is punished disproportionately.
    let mut score = pr * (1.0 + 0.9 * pr_norm);

    // Smooth stream-progress coupling: late in the stream, tighten the
    // tolerance for wasted residual (multiplicative amplification).
    let late = progress * progress;
    score *= 1.0 + 0.6 * late;

    // Reward bins whose residual is nearly consumed (smooth saturating term).
    let fill = 1.0 - pr_norm;
    score -= 12.0 * fill * fill * (1.0 + 0.5 * late);

    // Interaction with mean residual: prefer bins below the mean residual
    // (i.e., tighter bins), smoothly scaled.
    score += 0.25 * (mean_residual - pr);

    // Last-chance bonus: if this is the only fitting bin, strongly encourage
    // using it rather than opening a new bin (smooth ramp).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * late;
    } else if fitting_bins_count > 1 {
        // Slight preference spread among multiple candidates: tighter fits win
        // via base term already; add mild penalty scaled by crowding.
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (smooth compatibility term).
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 20.0);
    }

    // New-bin candidate: it has pr = cap - item_size, which is naturally
    // large; add an explicit smooth penalty so a new bin is only chosen when
    // all open bins would leave comparable waste.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + late) - 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits strongly (post_residual dominates).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // since min item size ~10; penalize small nonzero residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 are
    // "usable slots" — reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Integer-division tier of post_residual (classes of 10).
    let tier = post_residual / 10;
    score -= tier as f64 * 1.5;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            let gap_waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.1 * gap_waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - frac);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or open bins are crowded (few fitting bins).
    if bin_residual == bin_capacity {
        let crowded = fitting_bins_count == 0;
        let bad_fit = item_size > bin_capacity / 2;
        if crowded || (bad_fit && fitting_bins_count <= 1) {
            score -= 12.0; // allow opening when necessary
        } else {
            score += 20.0 + mean_residual * 0.15; // prefer reusing open bins
        }
    }

    // Late-stream tightening: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Mild penalty when this bin's residual is far from mean residual
    // (prefer balanced bin usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let nxt = next_item_size as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward for completely filling a bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small NONZERO residuals are likely stranded
    // forever; penalize them proportionally to how close to zero they are.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 2.0;
    }

    // Tight-fill reward: fraction of the bin's current space consumed now.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling (k=2): strongly reward a residual that can host the
    // next item (chaining); otherwise a leftover residual risks becoming dead
    // space relative to the immediate future.
    if nxt > 0.0 {
        if nxt <= post {
            score -= 30.0 + 0.5 * nxt;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Outlier residual guard: don't create a much-looser bin than the current
    // fleet average unless it pays off elsewhere.
    if post > mean_residual + 25.0 {
        score += 3.0;
    }

    if is_new_bin {
        // Open-bins pressure: opening a new bin is penalized more when many
        // bins are already open (fragmentation cost).
        score += open_bins_count as f64 * 5.0 + 10.0;
        // If no open bin can fit the item, the new bin is the only option:
        // cancel the pressure entirely.
        if fitting_bins_count == 0 {
            score -= 10.0 + open_bins_count as f64 * 5.0;
        }
    } else {
        // Prefer placing into an existing bin over opening a new one.
        score -= 10.0;
        // Last-chance bin: this is the only open bin that fits the item;
        // using it avoids stranding capacity in a freshly opened bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (low post_residual) are good.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect follow-up fit: strongly reward small gap.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra reward if next item fits almost exactly.
            if gap <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Next item would not fit here; slight penalty proportional to overshoot.
            score += 0.15 * (nxt - post);
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter" than average;
    // placing into them is efficient, but avoid leaving tiny unusable fragments.
    let res = bin_residual as f64;
    let dev = res - mean_residual;
    if dev < 0.0 {
        // Below-mean residual: reward proportionally (aggressive packing into tight bins).
        score -= 0.25 * (-dev);
        // Penalize creating very small dead space (<10) that nothing can use.
        if post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Above-mean residual: mild penalty to prefer tighter bins.
        score += 0.10 * dev;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be
    // badly fragmented or no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If lookahead shows the next item pairs with the current item in a fresh bin,
        // soften the penalty a bit.
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= bin_capacity as f64 * 0.9 {
            score -= 20.0;
        }
    }

    // Stream progression: early on, allow slightly more liberal bin opening to build
    // diverse residual profiles; late in the stream, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    // Many open bins: discourage spreading items; prefer consolidating.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (low post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio; // squadratic dead-space penalty

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        let lookahead_quality = 1.0 - (slack_after_next as f64 / bin_capacity as f64);
        score -= 6.0 * lookahead_quality * (0.5 + 0.5 * t);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for lookahead item: potential dead space, penalize
        // proportionally to how unusable it is, more so late in the stream.
        let dead = post_residual as f64 / (next_item_size as f64).max(1.0);
        score += 4.0 * (1.0 - dead.min(1.0)) * (0.4 + 0.6 * t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Global congestion: many open bins with large mean residual -> encourage
    // consolidating into existing bins (penalize new-bin tendency).
    let congestion = (open_bins_count as f64).ln().max(0.0) * (mean_residual / bin_capacity as f64);
    score += 2.5 * congestion * fit_ratio;

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 14.0;
        // If the item is large relative to capacity, filling a fresh bin is attractive.
        let size_frac = item_size as f64 / bin_capacity as f64;
        new_bin_penalty -= 10.0 * size_frac * size_frac;
        // Early stream: opening bins is cheaper; late stream: consolidation matters.
        new_bin_penalty += 6.0 * t;
        // If this is the only fitting option (no alternatives), relax the penalty.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 12.0;
        }
        score += new_bin_penalty.max(-2.0);
    }

    // Waste-avoidance coupling: penalize leaving residuals below the smallest
    // plausible item size (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Mild preference for bins already partially filled (fragmentation control).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 2.0 * fill * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post_residual (tight fit), scaled by capacity.
    let mut score = post / cap;

    // Non-linear polynomial coupling: post_residual^2 interacts with stream progress.
    // Early in the stream, keep bins flexible (penalize very small post_residual more);
    // later, tight fits are rewarded more aggressively.
    let post_norm = post / cap;
    let poly = post_norm * post_norm * (0.5 + 1.5 * progress) - post_norm * (1.0 - progress);
    score += 0.8 * poly;

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 stream).
    let dead = (post - (next_item_size as f64)).max(0.0);
    let dead_frac = dead / cap;
    score += 0.35 * dead_frac * dead_frac * (1.0 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 0.4 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening new bins implicitly
    // by rewarding this bin, more so late in the stream.
    if fitting_bins_count == 1 {
        score -= 0.5 + 0.5 * progress;
    }

    // Mean-residual coupling: placing into a bin below mean residual leaves larger bins
    // for future items; smooth polynomial preference.
    let mean_dev = (mean_residual - post) / cap;
    score += 0.25 * mean_dev * mean_dev - 0.15 * mean_dev;

    // New-bin candidate: empty bin gets a mild penalty that shrinks as stream progresses,
    // so we consolidate into open bins early and allow new bins when needed late.
    if bin_residual == bin_capacity {
        score += 0.6 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness reward: reward small post_residual more than linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * 40.0;               // tighter fit -> lower score
    score += frac * frac * 60.0;                // superlinear penalty on wasted space

    // Harmonic class of post_residual: dead-space classes (small residuals that
    // few items can use) are penalized via modulo arithmetic on C=100.
    let pr = post_residual as i64;
    let class_pen: f64 = if pr == 0 {
        -80.0 // perfect fit
    } else if pr <= 10 {
        55.0 // nearly unusable sliver
    } else if pr <= 20 {
        25.0
    } else if pr <= 35 {
        8.0
    } else {
        -10.0
    };
    score += class_pen;

    // Modulo coupling: residuals congruent to small usable sizes (item min sizes)
    let m = pr % 100;
    if m == 0 && pr > 0 {
        score -= 30.0; // exact multiple of capacity => effectively full usable
    }
    if m >= 1 && m <= 5 {
        score += 20.0; // awkward remainder
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover
            let nf = next_item_size as f64 / post_residual as f64;
            score -= nf * 35.0;
            // harmonic class of (post_residual - next_item_size)
            let pr2 = post_residual as i64 - next_item_size as i64;
            if pr2 <= 10 && pr2 >= 0 {
                score += 18.0;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we prefer
    // reusing open bins with decent fits, but keep it competitive when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // late in the stream, opening a new bin is cheap-ish; early, prefer reuse
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        // if many open bins already, spreading load is fine
        score -= (open_bins_count as f64).min(20.0) * 0.8;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, its
    // leftover is atypical; penalize dumping items into unusually empty bins when
    // other bins are tighter (keeps tight bins for tight fits).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (small, hard-to-fill leftovers) are heavily penalized.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // tiny sliver: nearly dead space
        score += 60.0;
    } else if pr >= 10 && pr < 20 {
        score += 25.0;
    } else if pr >= 20 && pr < 35 {
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when current bins have poor fits
    // or would leave bad dead space. Make the fresh bin a decent default
    // (post_residual = capacity - item_size) but discourage when a good
    // fit exists among open bins.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize slightly so tight fits in open
        // bins win, but keep it better than dead-space placements.
        score += 15.0;
        // if open bins are crowded with large residuals, opening fresh is fine
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= pr && pr - next_item_size < 10 {
        score += 10.0; // would create a sliver for the next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step fit: place now, then fill exactly
        } else if ni <= pr {
            // next item fits after placement: reward proportional to tightness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: penalize wasted capacity
            score += 15.0 * (ni - pr) / bin_capacity as f64;
        }
        // bonus if bin also fits next item right now (chained fit)
        if next_item_size <= bin_residual {
            score -= 8.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 5.0;
    }

    // relative to mean residual: prefer bins tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // penalize very small dead space that becomes unusable
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 10.0; // tiny residual is fine (near-perfect fill)
    } else if pr >= 10.0 && pr < 20.0 {
        score += 12.0; // awkward dead zone
    }

    // early stream: be slightly more willing to open bins (long horizon amortizes)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress;

    // new-bin candidate: neutral baseline; only chosen when it beats all open bins
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual is naturally better (base score already does this).
    // Exponentially reward very tight fits to break ties toward near-perfect packing.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves another gap; mild reward scaled by fit quality
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; slight penalty for creating a trap
            score += 3.0;
        }
    }

    // Dead-space penalty: residual that is too small to hold anything useful (items >= 1,
    // but small fragments are wasteful). Penalize tiny unusable residuals.
    if post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this empty bin's
    // potential unless current bins fit poorly. Penalize new bins by default; the penalty
    // shrinks when the item fits badly everywhere (many fitting bins but large mean residual
    // mismatch) or late in the stream when consolidation matters less.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins are penalized more when open bins are fragmented (high mean residual spread)
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_penalty = 30.0
            + 0.5 * open_bins_count as f64
            + fragmentation * 0.3;
        // Late in the stream, opening a bin is less costly (fewer future items to fill it)
        new_bin_penalty *= (1.0 - 0.5 * progress);
        // If the item is huge relative to typical residuals, a fresh bin may be the right call
        if item_size as f64 > mean_residual {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bins: mildly reward bins whose residual is close to mean (keeps balance),
        // and reward using bins when many are open (consolidation pressure).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        score -= 0.3 * open_bins_count as f64;
    }

    // Time-horizon coupling: early in the stream, be greedy for tight fits; late in the
    // stream, avoid leaving tiny residuals that can never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 20 {
        score += 10.0 * progress * (20 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) shaping
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr);

    // Smooth progress coupling: later in stream -> penalize residual more strongly
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 6.0 * tightness;

    // Penalize residuals too small for the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 4.0 * gap * gap * (1.0 + progress);
        // Bonus if post_residual still fits the next item well
        let fits_next = (pr / nxt).min(1.0);
        score -= 2.0 * fits_next * fits_next;
    }

    // Last-chance bin: strongly favor using it (avoid opening new bins)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // Crowding: many open bins -> favor consolidating into existing bins
    let crowd = (open_bins_count as f64).ln1p();
    score -= 0.6 * crowd * (1.0 - norm_pr);

    // Mean-residual coupling: if this bin is below mean residual, it's "loose" -> slightly favor
    let dev = (mean_residual - pr) / cap;
    score += 0.5 * dev;

    // New-bin candidate: penalize opening a new bin, unless existing fit would be terrible
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
        // Allow new bin if item is huge relative to what existing bins leave
        score -= 12.0 * fit_frac * fit_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Penalize post-residuals that fall into "dead" harmonic classes:
    // residuals in (0, 10) are nearly unusable for any item (min size 1, but
    // small classes waste space); residuals in low quarters are poor.
    if post_residual == 0 {
        score -= 40.0; // perfect closure is ideal
    } else if post_residual < 10 {
        score += 12.0; // tiny dead space
    } else if post_residual <= quarter {
        score += 5.0; // quarter-class: hard to fill
    } else if post_residual <= 2 * quarter {
        score += 0.0; // half-class: neutral
    } else {
        score -= 3.0; // large residual: roomy, fine
    }

    // Harmonic match: does next_item_size divide the post residual nicely?
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size;
        if n <= post_residual {
            if post_residual % n == 0 {
                score -= 10.0; // exact harmonic subdivision
            } else {
                let r2 = post_residual % n;
                if r2 < 10 {
                    score += 4.0; // leaves near-dead residue
                } else if r2 <= eighth {
                    score += 1.0;
                } else {
                    score -= 2.0; // leaves a usable class
                }
            }
        } else {
            // next item cannot use this bin's residual anyway
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when current bin would
    // leave a bad harmonic class and mean residual is already low-utility.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline, slightly penalized so we only open
        // new bins when open bins score badly.
        score = cap * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin can host the next big item too
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open
        }
        if post_residual <= quarter && fitting_bins_count >= 1 {
            score -= 6.0; // open bins would leave dead space anyway
        }
    }

    // Mild tightness pressure: prefer filling bins with small residuals
    // relative to the fleet mean.
    score += (mean_residual - pr) * 0.15;

    // Progress coupling: late in the stream, be greedier about closing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0 * (post_residual == 0) as i32 as f64;
    score += progress * 1.0 * (post_residual < 10 && post_residual > 0) as i32 as f64;

    // Item-size harmonic class: big items prefer big residuals.
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.6 {
        score += (pr - (cap - item_size as f64)) * 0.0; // already exact
        score -= 2.0 * (bin_residual as f64 / cap - item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest item are pure waste.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Non-linear penalty on mid-range residuals that are hard to fill later
    // (residuals that can't hold typical items 10..80 are risky).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 40 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: penalize.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is well below mean, it's a tight fit;
    // reward placing into tight bins (keeps loose bins available for future items).
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.5 * tightness.min(50.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no good existing fit exists; otherwise slightly discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 10.0; // large item: fresh bin is fine
        } else {
            score += 20.0; // small item: prefer existing bins
        }
    }

    // Mild time progression: early in stream, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = 60.0 * (-gap / 30.0).exp();
        score -= match_bonus;
        // Perfect chain: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving dead space that neither fits next item nor is useful.
        if post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 20.0 * (1.0 - fit_ratio);
    }

    // Relative-to-mean residual coupling: prefer bins deviating below mean residual
    // (filling fuller bins first keeps many partial bins flexible).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5 && post_residual as f64 > mean_residual;
        if poor_fit {
            score -= 25.0; // allow opening when fit is really bad
        } else {
            score += 80.0; // prefer existing bins otherwise
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // Many open bins: encourage closing them out (fill high-residual bins less,
    // favor near-full ones).
    if open_bins_count > 4 {
        score += 0.1 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be conservative; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill ratio of this bin before placement.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits: post_residual near zero gets strong bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for typical future items
    // (dead zone: post_residual in (0, 10) is nearly useless).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot use the leftover: leftover is more likely dead space
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * fill;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage
    // unless the current bin fit is bad or stream is early with few bins.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 30.0;
        // Early in the stream with few bins, opening is cheaper.
        score -= 25.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
        // If many bins are open and mean residual is high, prefer reusing them.
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Prefer filling bins that are already mostly full (reduce bin spread).
    score -= 8.0 * fill * fill;

    // Slight preference for bins whose residual is close to item size (perfect-ish fit).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * (1.0 - fit_gap).max(0.0) * fit_gap.max(0.0);

    // Mild time-horizon shaping: as the stream nears its end, tighten packing.
    score -= 5.0 * progress * tight;

    // Penalize spreading across too many open bins when mean residual is low.
    if open_bins_count > 4 && mean_residual < 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;

    // Smooth base: reward tight fits (low post_residual)
    let mut score = post;

    // Non-linear penalty for mid-range dead space (quartic bowl centered near small residuals)
    let x = post / cap;
    score += 12.0 * x * x * (1.0 - x) * (1.0 - x) * cap;

    // Reward near-exact fills more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 20.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize wasting a large fraction of the bin, especially early (keep capacity flexible later)
    score += 8.0 * x * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Encourage consolidation when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - x);

    // Lookahead coupling: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size as f64 <= post {
        score -= 8.0 * (next_item_size as f64 / post.max(1.0));
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to leftover
        score += 4.0 * x;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are all bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is leftover space?
    // Class residual into capacity-fraction bands via integer division.
    let pr = post_residual;
    let quarter = bin_capacity / 4;   // 25
    let tenth = bin_capacity / 10;    // 10
    let half = bin_capacity / 2;      // 50

    // Dead-space penalty: residual below the smallest item size (1..=10 band)
    if pr < tenth {
        score += (tenth - pr) as f64 * 6.0;
    }
    // Awkward mid-band residuals (just above a small-item size) are semi-dead
    if pr >= tenth && pr < 2 * tenth {
        score += 4.0;
    }

    // Reward tight fits (post_residual near zero) strongly
    if pr == 0 {
        score -= 30.0;
    } else if pr <= quarter {
        score -= (quarter - pr) as f64 * 0.8;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10
    // pair perfectly with common item sizes; reward them.
    if pr % tenth == 0 && pr > 0 {
        score -= 5.0;
    }
    // Odd-class residuals (coprime-ish leftovers) are harder to fill
    if pr % 3 == 1 && pr > 4 {
        score += 2.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect or near-perfect follow-up fit is very desirable
            if pr == next_item_size {
                score -= 20.0;
            } else {
                let next_post = pr - next_item_size;
                if next_post < tenth {
                    score -= 12.0; // chain of tight fits
                } else {
                    score -= 4.0;
                }
            }
        } else {
            // Next item won't fit here: penalize less if residual is small anyway
            let waste = (next_item_size - pr) as f64;
            score += waste * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are all badly fragmented. Give the fresh bin a moderate baseline.
    if bin_residual == bin_capacity {
        // Baseline: fresh bin has full capacity; score by remaining stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.35 * cap + 0.25 * cap * progress;
        // If the current item alone leaves a harmonic residual, fresh bin looks good
        let ipr = bin_capacity - item_size;
        if ipr % tenth == 0 {
            score -= 8.0;
        }
        // Few open bins and large mean residual -> prefer existing bins
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Next item large: opening fresh bin with big item may waste space
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 6.0;
        }
    }

    // Mild global pressure: many open bins -> discourage hoarding space
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if item_size as f64 / bin_residual as f64 > 0.9 {
        score -= 40.0;
    } else if item_size as f64 / bin_residual as f64 > 0.75 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin is a bad host
    // or would leave dead space. Base new-bin score sits above good fits.
    if bin_residual == bin_capacity {
        // Neutral starting point; penalize opening new bins when many are open.
        score = 45.0 + 2.0 * open_bins_count as f64;
        // If next item can pair with this item in a fresh bin, mildly favor it.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 * progress;
        // If this bin is the only fitting option elsewhere, discourage new bin.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        return score;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Pressure from number of open bins: prefer denser bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is far from mean residual (consolidate extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.1 * dev;

    // Lookahead: if post_residual can still host the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is just below next item size, it's likely dead space later.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but scaled so a new empty
    // bin (post_residual = 100 - item) is rarely preferred unless fits are bad.
    score *= 1.0 + 0.01 * (bin_residual as f64 / bin_capacity as f64);

    // Lookahead: strongly reward when the leftover exactly hosts the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits here: reward proportional to tightness of that fit.
            score -= 45.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize unusable gap.
            score += 0.35 * diff;
        }
        // Exact match jackpot.
        if post_residual as u32 == next_item_size {
            score -= 60.0;
        }
    }

    // Coupling with mean residual: prefer bins that deviate favorably
    // (smaller residual than average = tighter packing so far).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive so we reuse bins,
    // but keep it competitive when the fit would leave large dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, opening bins is cheaper (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Mild penalty for leaving tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_waste = post_residual - next_item_size;
        score -= 15.0 * (1.0 - lookahead_waste as f64 / post_residual.max(1) as f64);
        if lookahead_waste == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty for leaving stranded space.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize the brand-new empty bin candidate unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // Attractive if current open bins are crowded / few fitting options.
        score -= 10.0 * (fitting_bins_count as f64).recip();
        // If mean residual is small, open bins are tight; new bin less costly.
        score -= 0.15 * mean_residual.max(0.0);
        // Large items prefer fresh bins.
        if item_size > 60 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for fuller bins among many open bins.
    score -= 0.05 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual, smooth polynomial shaping.
    let pr_norm = pr / cap;

    // Late in the stream, waste matters more: weight grows smoothly with progress^2.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Tight-fit reward: smooth bell around small residuals.
    let tightness = 1.0 - (pr_norm - 0.05) * (pr_norm - 0.05) * 40.0;
    score -= 3.0 * tightness.max(0.0);

    // Penalize creating residual just below the smallest plausible next item,
    // smoothly via a smoothstep-like term.
    let dead_zone = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 { gap * gap * cap } else { 0.0 }
    } else { 0.0 };
    score += 2.0 * dead_zone;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (0.5 + 0.5 * progress);
    }

    // Prefer filling bins that are already below-average residual (denser bins),
    // with smooth quadratic coupling.
    let density_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 2.0 * density_gap * density_gap;

    // Mild penalty for opening a new bin when others fit, smoothed by progress.
    if bin_residual == bin_capacity {
        let fits_others = fitting_bins_count > 0;
        if fits_others {
            score += 1.0 + 2.0 * progress;
        } else {
            score -= 0.5;
        }
    }

    // Reward leaving room for the lookahead item (smooth interaction).
    if next_item_size > 0 && post_residual >= next_item_size {
        let room = (post_residual - next_item_size) as f64 / cap;
        score -= 1.5 * room * (1.0 - room);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: residues modulo small moduli.
    let r = post_residual as u32;
    let mod4 = r % 4;
    let mod10 = r % 10;
    let mod20 = r % 20;

    // Reward post-residuals that are "harmonic" (divisible) — these leave
    // clean slots for typical item sizes (multiples of 10, 20).
    if r > 0 {
        if mod10 == 0 {
            score -= 6.0;
        } else if mod20 == 0 {
            score -= 8.0;
        } else if mod4 == 0 {
            score -= 2.0;
        } else {
            score += (mod4 as f64) * 1.5;
        }
    }

    // Penalize dead space below the smallest plausible item (1..100 unknown,
    // but small residues are hard to fill): quadratic dead-space penalty.
    if r > 0 && r < 10 {
        score += (10 - r) as f64 * (10 - r) as f64 * 0.6;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 12.0;
        } else if gap % 10 == 0 {
            score -= 5.0;
        } else {
            score -= 2.0 + gap as f64 * 0.05;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how far off.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the
    // item is large or current bins are badly fragmented.
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Base cost of a fresh bin.
        score += 14.0;
        // If existing bins are very fragmented (high mean residual unusable),
        // opening a fresh bin becomes more attractive.
        if fragmentation > 0.5 {
            score -= (fragmentation - 0.5) * 20.0;
        }
        // Large items relative to capacity favor fresh bins.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= (frac - 0.6) * 15.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += progress * 4.0;
    }

    // Mild preference for tighter bins overall (best-fit flavor) scaled by
    // how full this bin already is.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 3.0;

    // Tie-break noise-free deterministic coupling with open bin count:
    // many open bins -> favor consolidation.
    if open_bins_count > 4 {
        score -= 1.0 + (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can't fit even the smallest
    // plausible item are pure waste. Penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Gaps that only fit tiny items are half-dead space.
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // If the next item would fit exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0; // near-perfect two-item sequence
        } else {
            score -= 5.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: dead space for lookahead.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin if this bin's placement would create bad dead space anyway.
        if post_residual > 0 && post_residual < 10 && bin_residual >= item_size + 10 {
            score -= 55.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Mean residual coupling: if open bins are already slack, prefer the bin
    // closest to being closed out (small residual before placement).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

