            score += 15.0 * (next_item_size - post_residual) as f64 / 50.0;
        }
    } else {
        // last item: strongly prefer filling a bin completely
        score -= 60.0;
    }

    // Relative-to-mean residual coupling
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty grows with number of open bins
        score += 25.0 + 2.0 * open_bins_count as f64;
        // allow new bin late in stream if mean residual is small (fragmented bins)
        if mean_residual < 20.0 {
            score -= 35.0;
        }
        // lookahead-aware new-bin decision
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward dead space that can only fit tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow.
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= 0.4 * pressure.min(10.0);

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a base cost so it's only chosen
    // when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Time horizon: as stream progresses, discourage wasteful large post_residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear waste penalty: dead space squared, normalized by capacity.
    let waste_norm = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_norm * waste_norm * (1.0 - waste_norm);

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    let tightness = 1.0 - waste_norm;
    score -= (2.0 + 6.0 * progress) * tightness * tightness;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening a brand-new bin when other bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0 + 20.0 * progress;
        } else {
            score -= 5.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * fit_frac * (1.0 - fit_frac) + 2.0 * fit_frac;
        } else if post_residual > 0 {
            // Dead space unlikely to be used later: penalize quadratically.
            let gap = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 6.0 * gap * gap;
        }
    }

    // Mild dispersion penalty: prefer bins near the mean residual (smooth).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 1.5 * dev * dev * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonically useful" (multiples of common item classes)
    // are rewarded; awkward small dead-space classes are penalized.
    let cap_frac = (bin_capacity / 4) as f64; // 25 for C=100, but scales generally
    let post = post_residual as f64;

    // Class 0: post_residual % 25 == 0 -> perfectly reusable, strong reward
    let class = post_residual % 25;
    match class {
        0 => { score -= 8.0; }
        10 | 20 => { score -= 3.0; }   // common item-size compatible residuals
        5 | 15 => { score += 1.0; }
        _ => {
            // awkward class: penalize proportionally to how small the dead space is
            if post > 0.0 && post < 10.0 {
                score += (10.0 - post) * 1.5;
            }
        }
    }

    // Integer-division threshold coupling: does the NEXT item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward scaled by how much slack remains after that
            let post2 = post_residual - next_item_size;
            score -= 6.0 + (post2 as f64).sqrt() * 2.0;
        } else {
            // lookahead won't fit this bin: penalize more if post residual is tiny
            if post_residual < next_item_size && post_residual < 15 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewest bins
    if fitting_bins_count > 2 {
        score += 1.5;
    }

    // Best-fit coupling: tight fit (small post_residual) rewarded
    score -= (bin_capacity as f64 / (post + 1.0)).min(12.0) * 0.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when the current fit would be terrible or lookahead needs space.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual < 10 && item_size < bin_capacity;
        let lookahead_needs = next_item_size > 0 && next_item_size > post_residual && next_item_size >= 60;
        if poor_fit || lookahead_needs {
            score -= 14.0; // opening a fresh bin is better than wrecking a bin
        } else {
            score += 20.0; // otherwise reuse open bins
        }
    }

    // Late in the stream: consolidate harder, avoid sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leave zero dead space.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Strict dead-space avoidance: if the leftover gap cannot accommodate the
    // lookahead item, it risks becoming unusable dead space -> penalize.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Small gaps (< 15) are hard to fill in general; dampen the reward for
    // leaving them unless it is a perfect fit (already handled above).
    if post_residual > 0 && post_residual < 15 {
        score += 6.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Reward using already-open bins (penalize the brand-new empty bin
    // candidate slightly, unless other terms dominate).
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins and late in the stream,
    // consolidation is valuable -> penalize spreading across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is below the current mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack after also fitting the next item: how tight is the double fit?
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; penalize dead space relative to next item.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Reward filling bins tighter than the current mean residual.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score -= (mean_post - post_residual as f64) * 0.3;
    }

    // Small unusable dead space penalty (dead space below min item size 1..100).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Slight preference for keeping many bins consolidated when stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared dead-space penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 6.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize stranding just below the next item's size.
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
        // Reward exact pairing: item + next fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when current bin would waste a lot
    // or mean residual across open bins is already low (bins nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_here = (bin_residual - item_size) as f64;
        // Prefer a fresh bin when the item would leave big dead space in an open bin
        // and open bins are collectively tight.
        let tightness = (mean_residual / bin_capacity as f64).max(0.0);
        let attraction = waste_if_here / bin_capacity as f64 * 35.0
            - tightness * 20.0
            + progress * 5.0;
        // Base cost of opening a new bin.
        score += 45.0 - attraction;
        // Never open a new bin when a perfect/tight fit exists elsewhere.
        if post_residual <= 15 && bin_residual < bin_capacity {
            score -= 20.0;
        }
    } else {
        // Mild penalty for using very empty open bins when many are open
        // (keeps a spread of medium residuals available).
        if bin_residual as f64 > mean_residual + 30.0 && open_bins_count > 2 {
            score += 5.0;
        }
        // Reward using bins whose residual is close to the item (good fill ratio).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 10.0;
    }

    // Global balance: discourage leaving mean residual far below item needs.
    if (mean_residual as u32) < item_size && bin_residual >= item_size {
        score -= 4.0;
    }

    // Small time-horizon modulation: early on, be conservative about waste;
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Normalize post residual and item size
    let x = pr / cap;                       // fraction of capacity left after placement
    let s = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Smooth non-linear coupling: polynomial in x with progress-dependent coefficients
    let poly = x * x * (3.0 - 2.0 * progress) + x * (1.0 + progress) * (1.0 - x);
    score += poly * cap * 0.35;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (1.0 + progress) * 12.0;

    // Penalize dead space that can't fit the lookahead item
    if nx > 0.0 && pr < next_item_size as f64 {
        score += (nx - x).max(0.0) * cap * (0.3 + 0.4 * progress);
    }
    // Reward bins that can still host the next item
    if nx > 0.0 && pr >= next_item_size as f64 {
        score -= (x - nx).max(0.0) * cap * 0.2;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins whose post residual matches average fill
    score += (pr as f64 - mean_residual).abs() * (0.05 + 0.1 * progress);

    // New-bin candidate: penalize opening a new bin, more so early and when others fit
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 6.0 + 10.0 * (1.0 - progress) } else { -2.0 };
        score += pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residuals divisible into
    // common item-size classes (small, mid) are more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -50.0 // perfect fill
    } else if pr <= 10 {
        -12.0 // near-perfect, likely dead space is tiny
    } else if pr % 10 == 0 {
        -6.0 // aligns with typical size granules
    } else if pr < 20 {
        3.0 // risky dead space
    } else {
        0.0
    };
    score += class_bonus;

    // Reward tight fits relative to item size (relative waste).
    let waste_ratio = post / (item_size as f64).max(1.0);
    score += 8.0 * waste_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 6.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            // next item won't fit here; slightly penalize leaving large unusable gaps
            score += 2.0 * ((next_item_size as f64 - post) / cap).max(0.0) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-to-slightly-high base so it's chosen only
    // when all open bins fit poorly; its post_residual is large naturally.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
    }

    // Stream progression: early on, prefer consolidating into open bins
    // (keep flexibility); late, accept tight fills more eagerly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post / cap);

    // Mild penalty when this bin's residual is far below the mean
    // (it's already the "fullest" type; prefer spreading otherwise).
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mild penalty proportional to how much space is wasted relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
