    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // penalize leftover mismatch relative to next item
            let diff = (post_residual - next_item_size) as f64;
            score += 0.3 * diff;
            // small bonus if next item still fits comfortably
            score -= 10.0;
        } else {
            // next item cannot reuse this space: penalize dead space more
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize new empty bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early stream: be more conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
