pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward small post-residual, with quadratic sharpening
    let mut score = pr * (1.0 + norm_pr * norm_pr * 2.0);

    // Smooth polynomial coupling with stream progress: tight fits matter more later
    let progress_term = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_term;

    // Dead-space penalty: post-residual too small for typical items becomes waste
    let dead = (25.0 - pr).max(0.0) / 25.0;
    score += dead * dead * 18.0;

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 0.15 * next_item_size as f64;
    }

    // Last-chance fitting: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (compacting)
    score += 0.08 * (pr - mean_residual);

    // Slight openness penalty: prefer fewer open bins overall
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it mildly unattractive unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 14.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 (dead-space granularity).
    let pr = post_residual as i64;
    let dead_penalty = match pr % 10 {
        0 => -6.0, // perfectly clean fill level
        1..=3 => 12.0, // tiny unusable sliver -> bad
        4..=6 => 4.0,
        7..=9 => -2.0, // still usable for small items
        _ => 0.0,
    };
    score += dead_penalty;

    // Exact fill bonus (post_residual == 0 handled by base score already; add extra reward).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item.
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / cap;
        // Open a new bin if existing residuals are tight (poor fit for future) and we're early.
        score += 55.0
            - 40.0 * (1.0 - avg_fill).clamp(0.0, 1.0)
            - 15.0 * (1.0 - progress);
        // Penalize opening new bin for small items.
        score += 0.4 * item_size as f64;
    }

    // Prefer bins with large residual waste absorbed by this item (tight fit relative to residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Mild preference for filling emptier bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space that likely cannot host future items (items >= 10).
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless the fit is very poor in all bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual;
    } else {
        // Reward tight fills relative to mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 30.0;
    }
    // Penalize leaving a gap too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small waste left.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted residual.
    else if next_item_size > 0 {
        score += 0.25 * post_residual as f64;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Reward bins tighter than the mean residual (good fits), penalize looser ones.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize very small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: make it unattractive unless nothing reasonable fits.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.3;
    }

    // Early in the stream, slightly discourage proliferation of bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small unusable residuals (dead space below min item size 1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: penalize this bin slightly if its residual is far above mean
    if fitting_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.10 * dev;
    }

    // Time horizon: early in stream, prefer spreading (favor new bins less); late, consolidate tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: base cost of opening a fresh bin
    if bin_residual == bin_capacity {
        let base = 40.0 + 30.0 * (1.0 - progress);
        // opening a bin is attractive if item is large relative to capacity
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        // if few bins fit the item, new bin is more acceptable
        let scarcity = if fitting_bins_count <= 1 { 25.0 } else { 0.0 };
        score += base - large_item_bonus - scarcity;
    }

    // Mild penalty on very large residual waste overall
    score += 0.05 * post_residual as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Strong reward for tight fits (small post residual), stronger late in stream
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness.powi(3) * (0.5 + progress);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - ((pr - nxt) / cap).powf(2.0));
        } else {
            score += 4.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // New-bin candidate handling: neutral-ish, slightly penalized early, competitive when fits are bad
    if bin_residual == bin_capacity {
        score = pr * (1.0 + progress) + 5.0 * (1.0 - progress);
        if pr_norm < 0.35 {
            score += 25.0; // don't open new bin for a near-perfect fit elsewhere
        }
        if mean_residual > 0.0 && mean_residual / cap > 0.8 {
            score -= 6.0; // open bins are nearly full; new bin attractive
        }
    }

    // Mild penalty for scattering across many open bins
    score += 0.15 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small residues (<10) are dead space
    let class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else {
        score -= (10 - class) as f64 * 0.5;
    }

    // Next-item lookahead: reward bins whose residue can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 6.0;
        }
        // Harmonic pairing: next item exactly fills remainder
        if post_residual == next_item_size {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // fresh bin can host the pair
        }
    }

    // Fraction-of-capacity coupling: prefer filling large fractions
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Mean residual pressure: if mean residual is high, favor consolidation
    score += (mean_residual - post_residual as f64) * 0.2;

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Integer-division threshold: residues in [50,100) still very reusable
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual >= 25 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // even the smallest plausible item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is risky too, softer penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item would leave a bad gap in an existing bin, or
    // when the next item is large and a full bin would serve it better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (bin pressure).
        score += 30.0 + 2.0 * open_bins_count as f64;

        // If the next item is large and this item would nearly fill the
        // chosen bin, opening a fresh bin now is fine.
        if next_item_size > 0 && post_residual < 20 && next_item_size >= 50 {
            score -= 35.0;
        }
        // If the item fits an open bin with a good (small) gap, discourage
        // the new bin.
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Open-bins pressure: mildly prefer bins with residuals below the mean
    // (consolidate waste into fewer bins) as the stream grows.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev * (0.5 + progress);

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover; the gap is likely dead space.
        score += 0.5 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
