    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness of post_residual to next_item_size (perfect 2-step match).
        score -= 18.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));

        // Perfect pairing: this bin will be exactly filled by the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }

        // Dead space: post_residual too small for next item and likely unusable.
        if post_residual < next_item_size {
            // Penalize proportional to wasted space relative to mean residual.
            let dead = post_residual as f64;
            score += 0.6 * dead + 8.0 * (1.0 - dead / bin_capacity as f64);
            // Extra penalty if next item cannot fit anywhere else well either.
            if next_item_size > mean_residual {
                score += 6.0;
            }
        }
    } else {
        // Last item: prefer tightest fill (small post_residual), reward exact zero.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless the item is large relative to capacity
    // or no open bin fits (fitting_bins_count==0 means only the new bin exists).
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - big) + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Mild tie-break: prefer bins whose residual is above mean (keeps small bins for small items).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    // Slight preference for consolidating into fewer bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty, scaled by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item can fit into the post-residual,
    // reward leaving that space; otherwise penalize wasted slack.
    if next_item_size > 0 {
        let next_fits = (post_residual as u32) >= next_item_size;
        if next_fits {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling open bins);
    // late in the stream, allow more aggressive bin spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Global state: many open bins with high mean residual -> penalize adding
    // slack to a bin that keeps the mean high; prefer the emptiest-balance fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;
    if open_bins_count > 8 && bin_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when the item is large relative to a
    // fresh bin and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - desperation * 55.0 - fit_quality * 10.0;
        if post_residual < 15 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer minimal post residual, normalized
    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress:
    // late in the stream, tight fits matter more; dead space is penalized quadratically.
    let tight = 1.0 - (pr / cap);
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Reward near-perfect fits (small post residual) more aggressively via cubic term
    score -= 8.0 * tight.powi(3);

    // Lookahead coupling: if the next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            // reward good chained fit, penalize leaving awkward gap
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item cannot follow here; mild penalty scaled by gap size
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (it / cap);
    }

    // Penalize spreading across too many open bins relative to mean residual
    let mean_diff = (mean_residual - pr) / cap;
    score += 5.0 * mean_diff * mean_diff;

    // Slight penalty for opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New-bin candidate: accept only if it would otherwise create large dead space
        let dead = (cap - it) / cap;
        score += 25.0 * dead * dead * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: tight fits are good (low post_residual wins), but avoid
    // ultra-tiny slivers that can never be reused (dead space class 0).
    if post_residual > 0 {
        // Harmonic class of the leftover space: classify by integer division
        // into deciles of capacity. Small-but-usable classes are rewarded,
        // unusable slivers (class 0) are penalized.
        let class = (post_residual * 10) / bin_capacity; // 0..=9
        match class {
            0 => { score += 18.0; }                    // sliver: nearly dead
            1 => { score -= 2.0; }                     // small but plausibly usable
            2 | 3 => { score -= 5.0; }                 // sweet spot for medium items
            4 | 5 => { score -= 3.0; }                 // decent
            6 | 7 => { score -= 1.0; }                 // half-full-ish
            _ => {}                                    // large leftover: neutral
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Exact-fill potential with the lookahead item: if next item exactly
    // matches post_residual, this is a harmonic pair -> big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits inside the leftover: keep this bin attractive,
        // reward proportional to how snugly it will fit.
        let snug = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportional to waste.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate detection: bin_residual == bin_capacity means empty bin.
    // Opening a new bin should only win when the fit into existing bins is bad
    // (i.e., post_residual here is large = loose fit) or few bins fit.
    if bin_residual == bin_capacity {
        // Penalize the fresh bin mildly so it only wins on genuinely poor fits.
        // Scale penalty down as the stream progresses (end-game consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 8.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    }

    // Coupling with mean residual: if this bin's post-fit residual is far below
    // the mean, we are consolidating space well; reward it.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 4.0 * rel.max(-1.5).min(1.5);
    }

    // Prefer filling bins when many bins are open (reduce bin count pressure).
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - pr / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Medium gaps (10..=20) mildly penalized: usable only by small future items.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base high score, scaled by open bin count.
        score = 60.0 + open_bins_count as f64 * 5.0;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If current item nearly fills a fresh bin, opening is fine.
        if item_size >= bin_capacity - 10 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keeps bin profile balanced),
    // so large residuals get used before they fragment.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if next item fits the post residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Post-residual can still fit the next item but not perfectly: mild reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post-residual too small for next item: penalize dead space, worse when it's tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 20.0 * (1.0 - dead / 50.0).max(0.0);
        // Very small unusable slivers are strongly penalized.
        if dead < 10.0 {
            score += 25.0;
        }
    }
    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // New-bin candidate: neutral-ish baseline, slightly above well-matched open bins.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if the current bin is a bad fit for the next item, opening new is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    }
    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }
    // Early in the stream, allow more bins; later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but zero-ish is best.
    if post_residual == 0 {
        score -= 80.0; // perfect closure
    } else if post_residual < 10 {
        score -= 35.0; // nearly unusable leftover is fine
    } else if post_residual > 50 {
        score += 12.0; // large leftover means poor packing
    }

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let good_fit_exists = fit_ratio > 0.0 && post_residual <= 15 && bin_residual < bin_capacity;
        let _ = good_fit_exists;
        let bad_fit_penalty = if post_residual > 40 { 20.0 } else { 0.0 };
        let _ = bad_fit_penalty;
        // base penalty for new bin; reduced late in stream or when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 - 30.0 * progress;
        // if lookahead item is large, a fresh bin may be valuable
        if next_item_size >= 50 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size <= 10 {
            score += 15.0; // tiny next item wastes a fresh bin
        }
    }

    // Lookahead synergy: prefer leaving a residual that fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // kills the bin for the next item
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 5.0 * (mean_residual - 30.0).min(40.0) / 40.0;
    }

    // Time horizon: early in stream, be slightly conservative about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post residual), non-linearly scaled.
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Penalize post residual relative to mean residual: creating dead space
    // worse than average residual state.
    score += 0.4 * (pr - mean_residual).abs() * (pr / cap);

    // Lookahead: reward bins whose post residual can host the next item
    // exactly; penalize near-miss slivers.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 18.0 * (1.0 - slack / cap).powi(3);
    } else if next_item_size > 0 {
        score += 6.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Last-chance fitting bin: strongly favor using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Stream progress coupling: later in stream, tighten preference for
    // minimal post residual (polynomial in progress).
    score -= 10.0 * progress * (1.0 - pr / cap).powi(2);
    score += 8.0 * progress * (pr / cap);

    // New empty bin candidate: penalize opening unless item is large relative
    // to capacity (poor fit elsewhere) — smooth quadratic gate.
    if bin_residual == bin_capacity {
        let fill = item / cap;
        let gate = (fill - 0.8).powi(2);
        score += 30.0 + 40.0 * gate - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity octaves.
    let oct = post_residual / (bin_capacity / 8).max(1); // 0..=8
    score += match oct {
        0 => -60.0,                       // perfect fit class
        1 => -20.0,                       // small sliver, likely dead space
        2 | 3 => 15.0,                    // mid-low residual, poor future fit
        4 => 0.0,                         // half-full: flexible
        5 | 6 => -10.0,                   // roomy, still useful
        _ => -25.0,                       // near-empty bin used well
    };

    // Dead-space penalty: residuals that few plausible items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot follow here; penalize slightly more for tight leftovers
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is bad if other bins already fit the item,
        // but good if this item would leave a horrible sliver elsewhere.
        let sliver_elsewhere = post_residual < 10 && post_residual > 0;
        if !sliver_elsewhere {
            score += 150.0 + open_bins_count as f64 * 5.0;
        } else {
            score += 30.0;
        }
    }

    // Prefer filling bins that are already relatively full (best-fit flavor),
    // scaled by stream progress: pack tighter as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 40.0 * (0.5 + progress);

    // Slight pressure to consolidate when many bins are open.
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (given items >= 1, but practically < ~15) are heavy penalties.
    if post_residual > 0 {
        let dead_threshold = 15.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= tightness * 8.0;

    // Open-bin pressure: discourage scattering across many bins when few
    // remain, encourage consolidation; but encourage opening a fresh bin
    // when the stream is young and bins are crowded with dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (1.0 - progress);

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item would fit into the post residual, reward.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 18.0;
        } else if next_item_size as f64 > post_residual as f64
            && post_residual > 0
            && (post_residual as f64) < dead_threshold_max()
        {
            score += 10.0;
        }
    }

    // Mean residual coupling: penalize bins far below mean residual
    // (they are the emptiest; placing here wastes the fullest bins' chance).
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate calibration: an empty bin has score = capacity.
    // Only beat it when an open bin offers a genuinely tight fit; add a
    // mild bonus to the new bin late in the stream to limit bin sprawl.
    if bin_residual == bin_capacity {
        score += 12.0 * progress;
    }

    score
}

#[inline(always)]
fn dead_threshold_max() -> f64 { 15.0 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward exact/predictive matches more strongly.
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly equals next item -> huge reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: good, reward proportional to closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space, worse if next item is large.
            let miss = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.3 * miss;
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0;
    }

    // Reward using bins whose residual deviates from the mean (special-shaped bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating very small unusable residuals (<10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with decent fits are preferred.
        score += 20.0 + open_bins_count as f64;
        // But if the current item leaves a perfect slot for the next item in a fresh bin,
        // and no open bin can chain, allow opening.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // Early in stream, opening is cheaper; late, discourage fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Slight preference to fill fuller bins first (best-fit flavor).
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: quadratic penalty on wasted space, amplified for very small leftovers.
    let waste = post_residual as f64;
    score += 0.6 * waste * waste / bin_capacity as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild bonus scaled by tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will not fit here: penalize leaving awkward gaps that
            // neither the next item nor typical future items can use.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 && gap > 0.0 {
                score += 5.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when it
    // enables a two-item perfect chain (item + next item == capacity), or when
    // no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let chain_perfect = next_item_size > 0 && (item_size + next_item_size == bin_capacity);
        if chain_perfect {
            score -= 35.0;
        } else {
            // Penalize opening a new bin; the penalty decays if the global
            // mean residual suggests existing bins are all badly fragmented.
            let fragmentation = (mean_residual - post_residual as f64).abs();
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 + 10.0 * (1.0 - progress) - 5.0 * (fragmentation / bin_capacity as f64);
        }
    } else {
        // Mild preference for bins that are already partially filled (less
        // fragmented overall state), scaled by how close residual is to mean.
        let closeness = 1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
        score -= 4.0 * closeness;
    }

    // Late in the stream, be greedy about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize spreading across too many open bins when many could fit.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer low post-residual, but with smooth non-linear shaping
    let mut score = pr;

    // Polynomial coupling: small residuals are extra good, mid residuals mildly penalized
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly;

    // Tight fit reward amplified by stream progress (endgame: minimize waste)
    let tight = 1.0 - x;
    score -= tight * tight * (20.0 + 60.0 * progress);

    // Penalize creating dead space that likely can't fit the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.15 * gap;
        if pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * x * x;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
    }

    // Divergence from mean residual: prefer bins that are more filled than average
    score += 0.1 * (pr - mean_residual).abs() * (pr - mean_residual).signum() * -1.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(2) as f64);

    // Base: best-fit preference (smaller post-residual wins).
    let mut score = post;

    // Quadratic dead-space penalty: large leftover capacity is wasted capacity.
    score += 0.5 * post * post / cap;

    // Harmonic band logic on post_residual (integer-division thresholds):
    // post in 1..=5  -> bin is effectively closed, reward.
    // post in 10..=39 (bands 1..3) -> awkward dead space, hardest to fill later, penalize.
    if !is_new_bin {
        let band = post_residual / 10;
        if post_residual > 0 && post_residual <= 5 {
            score -= 12.0;
        } else if band >= 1 && band <= 3 {
            score += 15.0;
        }
    }

    // Lookahead coupling (k=2): avoid destroying residual capacity that the
    // next item could have used; reward placements that keep the bin usable.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let blocks_next = !is_new_bin && next > post && next_item_size <= bin_residual;
        if blocks_next {
            // This placement kills a residual the next item needs -> strongly
            // prefer deferring this item elsewhere (possibly a new bin).
            score += 90.0;
        } else if next <= post && post > 0.0 {
            // Bin remains compatible with the lookahead item.
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin -> strong reward (unless fit is catastrophic,
    // which the quadratic penalty above already accounts for).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: baseline reluctance to open a fresh bin when any
    // open bin can host the item; slightly more willing late in the stream.
    if is_new_bin {
        score += 15.0 + 5.0 * progress;
    }

    // Mild tie-break: among equal post-residuals, prefer the fuller bin.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item cannot fit anywhere after this placement pattern.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    score += (open_bins_count as f64) * 0.8;

    // Mean residual coupling: when mean residual is low, conserve tight bins;
    // when mean residual is high, prefer filling bins aggressively.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive late in the stream or when
    // open bins are all poor fits (large mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 20.0 * progress - 30.0 * poor_fits;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that matches next item size.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect lookahead match: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Post residual can host the next item: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space relative to gap.
            score += 0.6 * (look - post_residual as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Tight-fit reward: near-perfect packing of the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 10.0 * tightness;
    }

    // Penalize bins far above mean residual (wasteful choice), reward below-mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor or lookahead fails.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred by default.
        score += 12.0;
        // If item fits poorly anywhere (large post residual everywhere), new bin is attractive:
        // reward a fresh bin when the item is large relative to typical residuals.
        if (post_residual as f64) >= mean_residual {
            score -= 8.0;
        }
        // Lookahead: an empty bin gives full flexibility for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Late in the stream, avoid leaving many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && open_bins_count > 3 {
            score += 10.0 * progress;
        }
    }

    // Small structural bonus for using bins with small residual already (compact packing).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract proportional fill of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Dead-space penalty: if the lookahead item cannot fit in the post-residual,
    // this bin becomes unusable for the next step; penalize more as stream progresses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = next_item_size as f64 - post_residual as f64;
        score += 6.0 + waste * (0.5 + 0.5 * progress);
    }

    // Perfect closure bonus: leaving exactly zero residual fully uses the bin.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Coupling with global state: if mean residual across open bins is high,
    // we have slack globally, so be pickier about loose fits (raise score of loose fits).
    let loose = post_residual as f64 / bin_capacity as f64;
    score += loose * (mean_residual / bin_capacity as f64) * 8.0;

    // Late in the stream, prefer consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: base cost plus scaling with open bins and progress.
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        // But if the current item is large relative to capacity and would leave a big
        // residual in any existing bin, a fresh bin can still win naturally.
        let big = item_size as f64 / bin_capacity as f64;
        score -= 4.0 * big;
    }

    // Small tie-breaker toward bins with the smallest residual above the item.
    score += 0.01 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with a smooth convex emphasis
    let mut score = norm_pr * (1.0 + 0.9 * norm_pr * (1.0 - progress));

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = if it > 0.0 { pr / it } else { 1.0 };
    score -= 0.6 * (-fit_ratio).exp();

    // Penalize leaving residual that cannot fit typical next items
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr >= nx) as i32 as f64;
        score -= 0.35 * usable * (1.0 - progress);
        // penalize waste just above the next item size (dead space band)
        let waste = ((pr - nx) / cap).max(0.0);
        score += 0.25 * waste * (1.0 - usable);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor it
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    } else {
        // mild competition penalty scaled by number of alternatives
        score += 0.02 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Stream-progress coupling: early on, keep bins flexible (favor small fill),
    // later, pack tightly
    score += 0.3 * progress * norm_pr - 0.2 * (1.0 - progress) * norm_pr;

    // Mean-residual coupling: if this bin is below mean residual, it's a good target
    let dev = (r - mean_residual) / cap;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when open bins are truly poor fits
    if bin_residual == bin_capacity {
        score += 0.9 + 0.6 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (>=10) are better than dead-space classes.
    let residue_class = post_residual % 10;
    if residue_class != 0 {
        // penalize awkward leftovers not aligned to the 10-grid
        score += (10 - residue_class) as f64 * 0.7;
    }

    // Exact fit is golden
    if post_residual == 0 {
        score -= 60.0;
    }

    // Perfect harmonic leftover: post_residual can exactly host next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Penalize leftover that is positive but smaller than the smallest
    // possible future item (dead space below harmonic floor).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next item fits in the post residual: strong reward for chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit: penalize proportionally to wasted chaining
        score += (next_item_size as f64) * 0.25;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Integer-division threshold: reward large post_residual buckets
    let bucket = post_residual / 20; // 0..5 harmonic bucket
    score -= bucket as f64 * 4.0;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Stream progression: early on, prefer keeping bins flexible (higher residual);
    // late, prefer consolidation (tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * 8.0;

    // Prefer bins below mean residual (consolidating emptier bins)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // only chosen when all open bins score badly (poor fits).
    if bin_residual == bin_capacity && item_size > 0 {
        score += 55.0;
        // but if the new bin would leave a clean harmonic residual, ease slightly
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
        // if many open bins already exist and this is a big item, opening fresh is fine
        if open_bins_count > 4 && item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild penalty for having many open bins, encouraging reuse
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    // dead space; penalize them heavily, scaled by how close to the minimum.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits (tight packing) strongly.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: only this bin can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; encourage closing bins out.
    score += open_bins_count as f64 * 0.8;

    // Pull toward the mean residual: prefer bins with residual close to mean
    // to keep bin states homogeneous (helps future pairings).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Lookahead coupling: if the next item can use this bin's post-residual,
    // reward; if post-residual is large but next item can't use it, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is justified only for large items or when the current
    // fit would leave a bad gap in a nearly-full bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a new bin.
        score += 55.0;
        // Large items relative to capacity benefit from fresh bins.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // Late in the stream, opening new bins is less costly (fewer future
        // pairings lost).
        score -= progress * 15.0;
        // If the item is small, strongly prefer an existing bin.
        if item_size <= 30 {
            score += 30.0;
        }
    }

    // Slight preference for filling fuller bins (low residual) first.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual can host the next item,
    // extra reward for an exact chain fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // usable for next item; reward proportional to how much slack remains after
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - chain_slack.min(60.0);
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual is good (tight packing), leaving more is wasteful.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin when decent fits exist; make the empty-bin
    // candidate unattractive unless it's the only option or lookahead demands it.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > bin_capacity - item_size {
            // next item can't share this bin anyway; opening fresh is fine
            score -= 300.0;
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Strong reward for near-perfect fill (post_residual <= 5).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward for exact match with lookahead.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }
    // Penalize leaving residual too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // unless this bin's residual was already unusable (handled by it being empty).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin costs one bin; penalize more when few bins open
        // (early stream, consolidation is cheap) and when other bins fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate small leftovers).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    // Prefer placing larger items into tighter bins early (best-fit bias).
    score += 0.1 * (item_size as f64) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling with stream progress: tighten packing more aggressively later
    score += 30.0 * (pr / cap).powi(3) * (0.5 + progress);

    // Interaction: post_residual vs mean residual — penalize bins far from the fleet mean
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if pr >= ns { 1.0 } else { 0.0 };
        score -= 10.0 * fit_next * (1.0 - (pr - ns) / cap);
        // Penalize post-residual just below next item size (dead space)
        if pr < ns && pr > 0.0 {
            score += 8.0 * (1.0 - pr / ns);
        }
    }

    // Mild penalty on many open bins to discourage bin sprawl
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: make empty bin attractive only when fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress) + 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonically compatible" with common item sizes (multiples
    // of 10 within 1..100) are more reusable; penalize awkward classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space class: residuals in (0,10) are nearly unusable -> heavy penalty.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // small but potentially usable by tiny items; mild penalty scaled by stream progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Harmonic bonus: post_residual divisible by common item classes (10, 20, 25, 50).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }
    if post_residual % 50 == 0 {
        score -= 3.0;
    }

    // Integer-division threshold: classify post_residual into deciles of capacity.
    let decile = post_residual / 10;
    let decile_bonus = match decile {
        0 => 30.0,          // 0-9: dead
        1 => 10.0,          // 10-19: awkward
        2 => 4.0,           // 20-29
        3 | 4 => 0.0,       // 30-49: sweet zone
        5 => -2.0,          // 50-59: very reusable
        6 | 7 => -3.0,      // 60-79
        _ => -1.0,          // 80+
    };
    score += decile_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility of next item with leftover
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 15.0 - gap; // near-perfect second fit
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Mean residual context: prefer bins far below mean residual (tighter packing).
    score += (pr - mean_residual) * 0.3;

    // New empty bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists. Penalize opening a new bin for small items.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // opening a fresh bin wastes capacity if item is small
        score += 30.0 * (1.0 - fill_frac);
        if fitting_bins_count > 0 {
            score += 18.0; // some open bin fits; discourage new bin
        }
        // but if item is huge and next item also large, fresh bin is fine
        if item_size >= 70 && next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with larger current residual among equals (balance load)
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but tiny gaps waste capacity). Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover that cannot host the next item: mild penalty scaled by gap size
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and avoid opening new ones unnecessarily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Relative tightness: favor bins whose residual is close to the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., when existing residuals are small relative to the item).
    if bin_residual == bin_capacity {
        let avg_slack = mean_residual / bin_capacity as f64;
        if avg_slack < item_size as f64 / bin_capacity as f64 {
            score -= 15.0; // open a fresh bin rather than cramming
        } else {
            score += 40.0 + 0.3 * open_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: post_residual can still fit next item with small waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Post residual too small for next item: dead space penalty scaled by tightness
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        let next = next_item_size as f64;
        // penalize more if dead space is a large fraction of what next item needs
        score += dead * (1.0 + 0.05 * next.min(80.0) / 10.0);
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from mean residual. Bins with residual below mean are "tight" -> good to fill.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / mean_residual;
        // tight bins (below mean) get reward; loose bins get penalty
        score -= dev * 30.0;
    }

    // Last-chance bin: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // unusable dead space. Empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // base penalty for opening new bin
        score += 400.0;
        // but if item is large relative to capacity and no open bin fits well,
        // opening may be reasonable: reduce penalty for large items
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 250.0;
        // if next item could pair with leftover in new bin, soften further
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Stream progression: late in stream, waste matters less; reward tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    // Small reward for many open bins being consolidated (prefer filling existing bins
    // when open_bins_count is high)
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional waste: penalize relative leftover more when it's unusable-looking.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Leftover too small for the next item: dead-space penalty scaled by near-miss.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + 10.0 * (1.0 - gap / 100.0);
        }
    } else {
        // Last item: maximize filling, prefer smallest post_residual.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // bins with below-average residual (balance toward closing bins out).
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // Time horizon: early in the stream, be pickier about waste (long future);
    // late in the stream, just fill anything.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * t;

    // New-bin candidate: neutral-ish baseline; only attractive when current
    // fits are all poor (large post_residual) or the item is huge.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = item_size as f64 / 100.0;
        score = 55.0
            - 20.0 * tightness
            - 25.0 * poor_fits
            - 10.0 * (1.0 - t)
            + (open_bins_count as f64).min(10.0) * 2.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack mildly; later, tighten preference quadratically.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += 8.0 * prog_poly * (post / cap) * (post / cap) * cap * 0.1;

    // Reward using bins that are nearly full (post_residual small) more aggressively.
    score -= 6.0 * (-post / (0.25 * cap)).exp();

    // Penalize dead space that likely cannot fit future items: compare post_residual
    // with next_item_size lookahead (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // Wasted space: cannot fit the next item.
            score += 4.0 * (nxt - post) / cap * 10.0;
        } else {
            // Bonus for leaving space exactly usable by the next item.
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // fits poorly everywhere. Recognized by bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // Big items justify a new bin; small items should reuse open bins.
        score += 20.0 * (1.0 - tightness) * (1.0 - tightness);
        // Late in the stream, opening new bins is more wasteful.
        score += 10.0 * prog_poly;
        // Many open bins with slack -> discourage another bin.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.5 * ((post - mean_residual) / cap);

    // Slight penalty on very large post_residual (hoarding capacity).
    score += 0.02 * post * post / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap; // fraction of capacity left over

    // Bucket post_residual by integer division thresholds (harmonic classes: 1/8,1/4,1/2,3/4).
    let class = post_residual / (bin_capacity / 8); // 0..=8 coarse class
    match class {
        0 => score -= 12.0,           // near-perfect fit
        1 => score -= 8.0,            // small but usable leftover
        2 => score -= 4.0,            // quarter-ish leftover
        3 => score -= 1.0,
        4 => score += 2.0,            // half-full leftover: mediocre
        5 => score += 4.0,
        6 => score += 6.0,            // mostly empty: poor use
        _ => score += 9.0,            // item barely dented the bin
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common item sizes (10,20,25,50)
    // are more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 2.0; }
        if pr % 20 == 0 { bonus += 1.5; }
        if pr % 25 == 0 { bonus += 1.5; }
        if pr % 50 == 0 { bonus += 1.0; }
        score -= bonus;
    }

    // Dead-space penalty: leftover too small for the minimum item size (1..100 stream => min 1),
    // but penalize tiny unusable slivers strongly.
    if post_frac > 0.0 && post_frac < 0.03 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // harmonic class of the gap after the next item
            let gap = post_residual - next_item_size;
            let gap_frac = gap as f64 / cap;
            score -= 6.0 * (1.0 - gap_frac);
        } else {
            // next item won't fit here: slight penalty if this bin is the only fitting one
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap) < 0.35 && open_bins_count > 0;
        let late = step_index as f64 / total_items.max(1) as f64;
        if pressure {
            score += 4.0; // open bins still roomy => keep using them
        } else {
            score -= 2.0 + 3.0 * late; // bins tight => fresh bin is fine, esp. late in stream
        }
    }

    // Mild preference to balance against mean residual (avoid many half-empty bins).
    score += 0.05 * (post - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 10 {
        score += 50.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual is close to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.8 {
        score -= 20.0 * (fit_ratio - 0.8);
    }

    // Penalize bins that would leave a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: prefer already-open bins when many are open,
    // pushing toward consolidation rather than proliferation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current open bins
    // are nearly full or the fit is terrible.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // New bin is good if existing bins are mostly full (low mean residual).
        score = 0.5 * bin_capacity as f64 - 30.0 * (1.0 - avg_pressure);
        // Discourage opening new bins early in the stream.
        score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // Discourage new bin if a fitting bin exists and fits are decent.
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 25.0;
        }
        // Favor new bin for large items that barely fit anywhere.
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild preference for using emptier bins when residuals are similar.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or tight fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 250.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward closeness.
            score -= 150.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize wasting this bin's future.
            score += 60.0 + 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already below average fill
    // (i.e. keep tight bins tight, avoid fragmenting well-filled bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 1.5 * (mean_residual - res);
    } else {
        score += 1.0 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fitting_bins_count <= 1 && post_residual > 20;
        if poor_fit || progress < 0.15 {
            score -= 90.0;
        } else {
            score += 150.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild preference for fewer open bins (consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize large unusable dead space (post_residual too small for typical future items)
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powf(1.6);
        score += 25.0 * dead;
    } else {
        // perfect fill
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: penalize opening new bins unless it's clearly better
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // base penalty for opening a bin
        score += 30.0;
        // more open bins -> slightly cheaper to open new (parallel packing)
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // early in stream, prefer consolidation; late, opening fresh bins ok
        score += 20.0 * (1.0 - progress);
        // if current item is large relative to mean residual, new bin attractive
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // if next item won't fit in a fresh bin's typical use, slight penalty
        if next_item_size > bin_capacity - item_size.min(bin_capacity) && next_item_size > 0 {
            score += 6.0;
        }
    } else {
        // Favor bins with residual close to item size (best-fit flavor)
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.15 * fit_gap;
        // many fitting bins: mild penalty for spreading too thin
        if fitting_bins_count > 3 {
            score += 2.0;
        }
    }

    // Global state: prefer filling bins when mean residual is high (fragmentation risk)
    if mean_residual > 50.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;

    // Base: prefer minimal post residual, smoothly normalized.
    let mut score = pr / cap;

    // Non-linear quadratic coupling: dead space is increasingly costly as the stream progresses.
    let dead = pr / cap;
    score += 0.9 * dead * dead * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with a smooth saturating term.
    let tightness = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= 0.35 * tightness * tightness;

    // Interaction with mean residual: prefer bins deviating below the mean (consolidating space).
    let dev = (mean_residual - pr as f64) / cap;
    score -= 0.2 * dev / (1.0 + dev.abs());

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.6 + 0.4 * progress;
    }

    // Lookahead coupling: if next item fits the post residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        let miss = (nx - pr).max(0.0) / cap;
        score += 0.25 * fits_next;
        score -= 0.15 * (1.0 - (miss / (miss + 0.25)));
    }

    // New-bin candidate handling: penalize opening a new bin, with penalty decaying
    // smoothly when the item is large relative to capacity or late in the stream.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let size_ratio = it / cap;
        let relief = size_ratio * size_ratio * (0.5 + progress);
        score += 1.2 - 0.8 * relief;
        // If no open bin fits, opening is unavoidable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 0.9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual modulo 10: dead space in (0,10) is nearly unusable
    // since items are >= 1 but typical sizes cluster; penalize small nonzero leftovers.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // dead-space penalty for tiny unusable slivers
    } else if pr >= 10 && pr < 20 {
        score -= 8.0; // moderately reusable class
    } else if pr >= 30 && pr < 60 {
        score -= 5.0; // mid-range residual still useful for medium items
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins give poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 80.0;
        // Early in stream, opening bins is cheap-ish; late in stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If many open bins already, discourage adding more.
        score += 4.0 * open_bins_count as f64;
        // But if mean residual across open bins is small (all nearly full), new bin is fine.
        score -= 30.0 * (1.0 - mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // If item is large relative to capacity, a fresh bin guarantees a clean fit.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Lookahead: if next item also large, fresh bin with room helps.
        if next_item_size > bin_capacity / 2 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Prefer bins with residual close to item (waste minimization) via integer division class.
    let waste_class = post_residual / 10;
    score -= 3.0 * (10 - waste_class.min(10)) as f64;

    // Mild penalty for very loose fits (large leftover) to keep bins compact.
    if post_residual > bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual that can never fit even the smallest item (<=10) is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - post_residual as f64; // tiny gaps are worst
    }

    // Residuals below ~25 are hard to fill: extra penalty scaled by gap smallness.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit reward: subtract to strongly prefer zero post_residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post residual but would fit a fresh bin, penalize slightly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 * 0.6;
    // New-bin candidate gets penalized by pressure so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it's a tighter bin; favor closing it out (tighter packing).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Late in the stream, be more tolerant of small residuals (no future to plan for).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 10 && post_residual > 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leave exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit: this bin is ideal for the next item too
        } else if post_residual >= next_item_size {
            // leftover can still host the next item: mild reward proportional to tightness
            score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // dead space: cannot host next item, penalize proportionally to waste
            score += 0.5 * (next_item_size - post_residual) as f64;
        }

        // Exact fill: bin closed completely
        if post_residual == 0 {
            score -= 25.0;
        }
    } else {
        // No lookahead: just prefer tight fits
        score += 0.3 * (bin_residual - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current fit is terrible or stream is early
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 - next_item_size as f64).abs();
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        score = 45.0 + poor_fit * 0.2 - 20.0 * (1.0 - progress);
        // discourage new bins when many open bins with room remain
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but nonzero.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if bin_residual >= next_item_size && post_residual == 0 {
            score += 5.0;
        }
        // Penalize creating a gap just below the next item size.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Global state: with many open bins, prefer consolidating into existing ones.
    let open_f = open_bins_count as f64;
    score += 0.15 * open_f * (mean_residual / bin_capacity as f64);

    // Time horizon: early in stream, mild preference to open bins (spread items);
    // late in stream, strongly avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score -= 6.0 * (1.0 - progress); // new bins more attractive early
        score += 20.0 * progress;        // new bins discouraged late
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fill preferred, non-linearly scaled by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space: small post_residual that is too small for any plausible item.
    let small_item = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    let waste = (small_item - pr).max(0.0) / cap;
    score += 8.0 * waste * waste * (1.0 - progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 4.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure toward consolidating among many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Prefer bins whose residual deviates from the mean in a useful (smaller) way.
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: discourage opening a fresh bin unless residuals are all bad.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 20.0 * avg_fill * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (1/4, 1/2, 3/4) to reward "clean" leftovers.
    let quarter = bin_capacity as f64 / 4.0;
    let half = bin_capacity as f64 / 2.0;
    let post = post_residual as f64;

    // Reward small, well-formed leftovers (tight fit).
    if post <= quarter {
        score -= 8.0 * (quarter - post) / quarter;
    } else if post <= half {
        // Mid-range leftover: mildly penalize dead space beyond a quarter.
        score += 2.0 * (post - quarter) / half;
    } else {
        // Large leftover: penalize wasteful low-fill placements.
        score += 6.0 * (post - half) / half;
    }

    // Integer-division harmonic classes on post_residual (multiples of 10/25).
    let cls = post_residual / 25; // 0..=4
    score -= match cls {
        0 => 5.0,              // nearly full bin: excellent
        1 => 1.0,              // decent
        2 => 0.0,
        3 => 2.0,
        _ => 4.0,              // mostly empty after placement: bad choice
    };

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // Next item fits; prefer leaving usable residue.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive for large items or when
    // open bins are all nearly full (high mean fill).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Penalize opening new bins when existing bins are well utilized.
        score += 15.0 + 10.0 * mean_fill;
        // Early in the stream, opening a fresh bin is cheaper (more future use).
        score -= 10.0 * (1.0 - progress);
        // Large items are hard to place later; a fresh bin is a safe bet.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference for packing into fuller bins (best-fit flavor).
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    // Tie-break noise-free harmonic jitter based on bin index modulo class.
    score += 0.01 * ((open_bins_count % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // for future items (min item size >= 1, but small gaps < 10 are dead).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating tiny unusable gaps
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Exact match with the lookahead item: this gap is immediately reusable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host the next item: mildly reward
        score -= 8.0;
    }

    // Open-bin pressure: prefer packing into existing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Pull score toward mean residual: avoid fragmenting one bin while
    // leaving others uniformly loose; keeps residual distribution balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.25;

    // New empty bin candidate: it has bin_residual == bin_capacity, so its
    // post_residual is huge; add a fixed opening cost so it only wins when
    // all open placements are truly bad.
    if bin_residual == bin_capacity {
        score += 90.0;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fill: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: exact match with the next item is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward.
            score -= 6.0;
        }
    }

    // Penalize awkward dead space: small nonzero residuals that likely waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer bins that are already tighter than average (better packing density).
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only open bin that fits, use it rather
    // than opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: default penalty so existing bins are preferred,
    // unless no open bin can fit the item at all.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: must open a new bin
        } else {
            score += 18.0; // discourage wasteful opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Last fitting bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Multiple candidates: slight penalty to keep flexibility, mild.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item exactly fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves some slack: moderate reward proportional to fit quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize bins that strand space the next item needs.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item in stream: fill any bin as tightly as possible.
        score -= 15.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 10) are useless.
    if post_residual < 10 {
        score += 8.0;
    }

    // Global state coupling: prefer bins with residuals near the mean (keeps bin pool balanced),
    // penalize outliers, scaled by how many bins are open.
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.15 * (1.0 + open_bins_count as f64 / 20.0).min(2.0);

    // Time horizon: early in the stream, be more conservative about fragmenting bins
    // (long future => keep bins flexible); late in the stream, just pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: opening a fresh bin is wasteful unless existing bins are crowded
    // or this is the only option. Penalize the empty-bin call when decent alternatives exist.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let relief = if fitting_bins_count == 1 {
            30.0 // no real alternative, allow opening
        } else {
            0.0
        };
        // More open bins => slightly more willing to open a new one (avoid overpacking one bin).
        let crowding = (open_bins_count as f64).ln().max(0.0) * 3.0;
        score += base_penalty - relief - crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) * (1.0 + 0.5 * progress);

    // Reward near-perfect fits more aggressively as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to fit a plausible future item
    if pr > 0 && pr < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a large unusable gap
        score += 3.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin should be strongly favored over opening new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress;
    }

    // Mild dispersion penalty: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in
    // "reusable" residue classes are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class A: post_residual divisible by 10 -> leftover matches common item
    // granularity, highly reusable.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> still reusable.
    else if pr % 5 == 0 {
        score -= 3.0;
    }
    // Class C: tiny dead space (1..10) is nearly wasted.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Integer-division thresholds on post_residual: leftover buckets.
    let bucket = pr / 20; // 0..=5
    score -= bucket as f64 * 2.0;

    // Perfect fit is best possible.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward (chained harmonic fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 4.0 + (pr - next_item_size) as f64 / 10.0;
            // Next item lands on a harmonic boundary of the leftover.
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize slightly more
            // when leftover is small (dead space risk).
            if pr < next_item_size && pr < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins with good fits, but reward opening a fresh bin when the
    // current item is large and would leave a badly fragmented residual.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score = cap as f64 - item_size as f64; // post_residual of empty bin = 100 - item
        // Penalize opening new bins when a decent reuse exists.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // But if item is large (> 2/3 capacity), a fresh bin wastes little;
        // slight reward keeps large items from fragmenting partial bins.
        if frac > 0.66 {
            score -= 6.0;
        }
        // Harmonic alignment: item size divisible by 10 pairs well in fresh bins.
        if item_size % 10 == 0 {
            score -= 2.0;
        }
    }

    // Mild pressure toward consolidating open bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (open_bins_count as f64).sqrt() * 0.5;

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // (smaller than mean) so large gaps stay available for large items.
    if prf < mean_residual {
        score -= (mean_residual - prf) * 0.05;
    } else {
        score += (prf - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0; // gap unusable by the lookahead item
    } else {
        // Reward tight fits: post_residual just above the usable threshold.
        score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).min(1.0);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when the fit here is bad and many bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual < 10 { 1.0 } else if next_item_size > 0 && post_residual < next_item_size { 0.6 } else { 0.0 };
        score += 30.0 - bad_fit * 35.0 - (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer closing out existing bins.
        score += progress * 10.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing), slightly.
    score -= ((bin_residual as f64) - mean_residual).abs() * -0.05 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).
    // Strongly reward a perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills the remainder.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 200.0 - fill_after * 1.5;
        } else {
            // Next item does NOT fit here: penalize leaving a gap that might be dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: just minimize post_residual (already base score).
        score += 0.0;
    }

    // Penalize small unusable residues (< 10, minimum item size in classic setting)
    // but items go down to 1, so penalize only truly tiny gaps relative to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (concentrate packing), avoid scattering across many bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; lookahead can override it
        // only if next item pairs perfectly with current item in a fresh bin.
        let mut nb = 120.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            nb -= (bin_capacity as f64 - leftover as f64) * 0.5;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 40.0;
        score += nb;
    }

    // Mild pressure against accumulating many open bins with large residuals.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for any future item (items >= 1,
    // so dead space of 0 is perfect; very small dead space is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving large gaps
            // that will likely never be used efficiently.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are
    // mostly full or the fit is terrible.
    if bin_residual == bin_capacity {
        // Mild penalty so we prefer reusing open bins with decent fits.
        score += 10.0;
        // But if open bins are nearly exhausted on average, new bin is attractive.
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        if avg_fullness > 0.75 {
            score -= 14.0 * (avg_fullness - 0.75) / 0.25;
        }
        // With many open bins, prefer consolidating rather than spreading.
        if open_bins_count > 5 {
            score += 1.5 * (open_bins_count as f64).sqrt();
        }
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps a diverse residual portfolio for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be slightly more willing to keep bins flexible;
    // late in the stream, prioritize filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;
    score += 3.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap;

    // Base: penalize leftover space, with sharpening polynomial in fill
    let mut score = pr * (1.0 + 0.5 * fill * fill);

    // Smooth non-linear coupling of residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let progress_coupling = (pr / cap).powi(2) * (0.5 + 1.5 * progress) * cap * 0.3;
    score += progress_coupling;

    // Cubic interaction: reward near-full placements increasingly with progress
    score -= (fill.powi(3)) * cap * (0.2 + 0.4 * progress);

    // Lookahead: penalize residuals that can't fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0);
        score += (gap / cap) * nxt * 0.4;
        // bonus if post-residual still fits next item (keeps bin useful)
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= fits_next * (pr - nxt).min(20.0) as f64 * 0.15 * (0.5 + progress);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    // New-bin candidate adjustment: empty bin has large post_residual; make it
    // attractive only when the item is large relative to capacity
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score -= item_frac * item_frac * cap * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 8ths
    let cap_frac = (post_residual * 8) / bin_capacity; // 0..=7
    // Dead-space penalty: residuals in awkward small classes are penalized
    let class_penalty = [4.0f64, 1.0, 0.5, 0.0, 0.0, 0.5, 1.5, 3.0][cap_frac as usize];
    score += class_penalty;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly; mild reward scaled by fit quality
            let fit_q = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * fit_q;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 2.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when item is large
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // Large items (>60% capacity) favor a fresh bin; small items penalized
        if load_frac > 0.6 {
            score -= 8.0 * (load_frac - 0.6);
        } else {
            score += 6.0 * (0.6 - load_frac);
        }
        // Late in the stream, avoid opening bins (fewer future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    }

    // Prefer filling bins that are already tight relative to mean residual
    if mean_residual > 0.0 {
        let tightness = 1.0 - (bin_residual as f64 / mean_residual);
        score -= 3.0 * tightness;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // Integer-division threshold on post_residual: residuals < 10 are near-dead
    if post_residual < 10 && post_residual > 0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 {
        if dead <= 10.0 {
            // Gap too small for the minimum item: pure waste.
            score += 60.0 - dead * 2.0;
        } else if dead <= 25.0 {
            score += 18.0 - dead * 0.4;
        } else {
            score -= 4.0; // generous gaps may still host future items
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit reward relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 - 0.4 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if current fit is bad and lookahead won't
    // use the leftover gap. Compare against mean residual as a fit-quality baseline.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        let lookahead_waste = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let bad_fit_here = if post_residual > 0 && post_residual <= 10 { 1.0 } else { 0.0 };
        let open_penalty = (open_bins_count as f64) * (1.0 - progress) * 2.0;
        score = 70.0 + fit_quality * 10.0 + lookahead_waste * 25.0 + bad_fit_here * (-20.0) - open_penalty;
        // If current bins would leave tiny dead space anyway, opening fresh is fine.
        if bad_fit_here > 0.0 && next_item_size >= post_residual as u32 && next_item_size > 0 {
            score -= 15.0;
        }
        // Mean residual context: if open bins are already full-ish, new bin is natural.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: prefer bins whose leftover still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item fits in the post-placement residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        // Tighter leftover after the next item => better.
        let after_next = post_residual - next_item_size;
        score -= 25.0 - 0.5 * after_next as f64;
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space creation.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste.min(60.0);
    }

    // Compare post_residual against mean residual: leaving far less than the
    // average residual is fine (tight packing), leaving more is worse.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild bonus for choosing among many fitting bins the tightest one,
        // already captured by post_residual; add slight penalty to spread load.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are poor
        // fits (large post_residual everywhere) or no real competition.
        let desperation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 - 35.0 * desperation;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If next item is large, a fresh bin is more flexible.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for tight fits overall (small post_residual), non-linear.
    score += 0.1 * (post_residual as f64 * post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Tightness reward: strongly favor small post_residual (best-fit core) ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // ---- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // ---- Lookahead: penalize leaving residue that cannot host the next item ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the next item, scaled by how well it would fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / 100.0).min(1.0);
        }
    } else {
        // last item: purely minimize residue
        score -= 3.0 * tightness;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: heavy, but shrinks as stream matures
        // (later on, consolidation matters more; early on, stocking bins is fine)
        score += 55.0 - 20.0 * progress;

        // If no existing bin fits well (many fitting bins means alternatives exist),
        // opening a fresh bin becomes more attractive when the fit elsewhere is bad.
        if fitting_bins_count == 0 {
            score -= 25.0; // item literally only fits a new bin
        } else if fitting_bins_count == 1 {
            // sole fitting bin: only open new bin if that fit is terrible
            if post_residual > 0 && (bin_residual - item_size) as f64 > 0.5 * bin_capacity as f64 {
                score -= 12.0;
            }
        }

        // Lookahead synergy: a new bin guarantees room for the next item
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 8.0;
        }
    } else {
        // ---- Existing-bin context adjustments ----
        // Prefer bins with residuals below the mean (consolidate small holes),
        // keeping large residuals free for large future items.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }

        // Mild penalty for spreading across too many open bins
        score += 0.15 * open_bins_count as f64 * (1.0 - progress);
    }

    // ---- Nonlinear coupling: penalize mid-range residuals (hard-to-fill holes) ----
    let r = post_residual as f64 / bin_capacity as f64;
    if r > 0.0 && r < 0.25 {
        score += 5.0 * (0.25 - r); // small awkward leftovers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), with mild non-linear shaping.
    let mut score = post + 12.0 * (post / cap) * (post / cap) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, demand tight packing.
    let late_pressure = 1.0 + 2.5 * progress * progress;
    score += late_pressure * (post / cap).powi(3) * 40.0;

    // Reward using an existing bin (penalize opening new bins), stronger late in stream.
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;
    if is_new_bin {
        score += 30.0 + 45.0 * progress;
    } else {
        score -= 8.0 + 10.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving post_residual that barely fails to fit next item,
    // reward leaving room that fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 + 8.0 * (nxt / cap);
        } else if post > 0.0 {
            // dead space relative to next item — smooth penalty near the threshold
            let gap = (nxt - post) / cap;
            score += 10.0 * (1.0 - gap) * (1.0 - gap);
        }
    }

    // Coupling with mean residual: prefer bins whose post residual moves the
    // portfolio toward balance; avoid extreme outliers.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for filling fuller bins as open-bin count grows.
    score -= (1.0 - post / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are divisors of capacity
    // (or near-divisors) are "perfect" dead space classes.
    let harmonic: [u32; 8] = [0, 10, 20, 25, 50, 100, 5, 4];
    let mut harm_bonus = 0.0;
    for &h in harmonic.iter() {
        if post_residual == h {
            harm_bonus = 12.0;
        }
    }
    // Modulo-class smoothness: post_residual % 10 small => tighter packing
    let class = (post_residual % 10) as f64;
    score -= harm_bonus;
    score -= 3.0 * (10.0 - class) / 10.0;

    // Integer-division threshold: item fills bin into a "half / third / quarter" class
    let cap_frac = (post_residual as f64) / (bin_capacity as f64);
    if cap_frac < 0.05 {
        score -= 15.0; // near-perfect fill
    } else if cap_frac < 0.25 {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * slack; // prefer next item to also fit snugly
        } else {
            score += 4.0; // next item won't fit here
        }
        // harmonic classes of next item size
        let nq = next_item_size / 10;
        let pq = post_residual / 10;
        if nq == pq && next_item_size <= post_residual {
            score -= 5.0; // same decade class: excellent chaining
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if item is huge relative to capacity and fit is bad elsewhere
        if (item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 5.0; // next item is big too; fresh bin helps
        }
    }

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below mean (fuller bins)
    score += 0.15 * (mean_residual - post_residual as f64).abs().signum()
        * (mean_residual - post_residual as f64).abs().min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates a gap the next item cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: many open bins -> prefer consolidating.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins with residual below mean (consolidate smaller gaps).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin fits or residual is very tight.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            score += 25.0 + 1.5 * open_bins_count as f64; // discourage opening when fits exist
        }
    }

    // Late in the stream: be slightly more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
