pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: small post_residual is good, but dead space below a
    // "useless threshold" should be punished extra (fragmentation).
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64).sqrt() * bin_capacity as f64;
    if waste < 10.0 {
        score += 25.0; // tiny slivers are nearly unusable
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * next_item_size as f64;
    }
    // If next item would leave this bin with awkward remainder, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 8.0;
    }

    // New-bin candidate: penalize opening new bins, but relax the penalty as
    // mean residual of open bins grows (open bins are crowded) and late in stream.
    if is_new_bin {
        let mut penalty = 45.0;
        penalty -= 0.15 * mean_residual;
        penalty -= 20.0 * progress;
        penalty -= 1.5 * open_bins_count as f64;
        score += penalty.max(0.0);
    }

    // Prefer fuller bins overall: compare residual to mean residual.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively.
    score -= 10.0 * progress * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer small post residual (tight fits)
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // late in the stream, tighter packing matters more (post residual penalized super-linearly)
    let tightness_penalty = post_norm * post_norm * (1.0 + 3.0 * progress);
    score += 40.0 * tightness_penalty;

    // Reward near-perfect fills with a smooth cubic bonus
    let fill_bonus = (1.0 - post_norm).powi(3);
    score -= 30.0 * fill_bonus;

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize new-bin candidate unless the item is large (would fragment open bins anyway)
    if bin_residual == bin_capacity {
        let newbin_bias = 20.0
            + 30.0 * (1.0 - item_norm) * (1.0 - item_norm)
            + 10.0 * (1.0 - progress);
        score += newbin_bias;
        // If many fitting bins exist, opening a new bin is wasteful
        score += 5.0 * fitting_bins_count as f64;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 6.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving awkward gaps
        score += 4.0 * post_norm;
    }

    // Discourage spreading residuals far above the mean (fragmentation)
    let dev = post - mean_residual;
    score += 0.05 * dev * dev;

    // Mild penalty on many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular structure on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect/near-perfect fit (post_residual in {0,1,2}) -> strong reward
    if post_residual <= 2 {
        score -= 30.0 + 10.0 * (cap - pr) / cap;
    }

    // Class B: dead space zone — post_residual below smallest possible item (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver penalty
    }

    // Class C: harmonic bands via integer division on post_residual
    // Band thresholds at capacity fractions: (0,25], (25,50], (50,75], (75,100)
    let band = (post_residual * 4) / bin_capacity.max(1);
    let band_bonus: f64 = match band {
        0 => 6.0,           // tiny leftover: tight pack, reward
        1 => 0.0,           // quarter left: neutral
        2 => -2.0,          // half left: mildly useful
        _ => -5.0,          // roomy bin: keep flexible
    };
    score -= band_bonus;

    // Modulo-10 class: residuals divisible by 10 pair well with common item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: can next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain-fit reward, stronger for exact class matches
            let exact = if next_item_size == post_residual { 8.0 } else { 3.0 };
            score -= exact;
        } else {
            // next item won't fit here after placement; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is very full
    if bin_residual == bin_capacity {
        // base new-bin cost
        score = cap as f64;
        // allow new bin when no open bin fits, or when current open bins are nearly full
        let tight = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if tight < 0.25 && post_residual <= 25 {
            score -= 5.0;
        }
    }

    // Progress-aware dead-space weighting: later in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / cap) * 10.0 * progress;

    // Mild preference to fill bins with larger mean residual (consolidate)
    if (mean_residual - pr).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
