    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            // leftover after next item: penalize small unusable remnants
            let rem = (post_residual - next_item_size) as f64;
            if rem < 10.0 {
                score += 25.0 - 2.0 * rem; // tiny remnant is dead space
            } else {
