    if bin_residual == bin_capacity {
        let waste_if_here = (bin_residual - item_size) as f64;
        // Empty bin is neutral-ish; slight penalty so we prefer reusing bins
        // unless the best existing fit leaves a big mismatch.
        score += 12.0 + waste_if_here * 0.1;
