        // (prefer consolidating space in typical bins).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;

        // Reward tight fits (small post_residual) more aggressively.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Late in the stream, close out bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
