    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Many fitting bins -> prefer the tightest one; slight penalty to spread selection.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: penalize bins whose residual is far below the mean
    // (they are "fuller" than average -> good to fill them further).
    let diff = mean_residual - bin_residual as f64;
    score -= 0.5 * diff;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only for poor fits elsewhere.
        score += 30.0;
        // Early stream: new bins are cheaper to open.
        score -= 30.0 * (1.0 - progress);
