    }

    // Prefer bins with below-mean residual (consolidate space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev;

    // New-bin candidate handling: it starts with full residual.
    if bin_residual == bin_capacity {
        // Open a new bin only if item is large or existing bins are crowded / poor fits.
        let fill = item_size as f64 / cap;
        // Penalize opening a new bin by default.
        score += 15.0;
        // But discount the penalty when the item is big or few bins fit it.
        score -= 18.0 * fill * fill;
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        score += 10.0 * progress * (1.0 - fill);
    }

    // Mild preference to reuse existing bins as open-bin count grows.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class reward: post_residual near multiples of common small sizes
    // (e.g. 10, 20, 25, 50) are "reusable" classes; reward them by subtracting.
    let classes: [u32; 6] = [10, 20, 25, 33, 50, 100];
    for c in classes.iter() {
        if post_residual % c == 0 && post_residual > 0 {
            score -= 6.0 + (c as f64) * 0.05;
            break;
        }
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space penalty: tiny but nonzero post_residual is wasted unless it
    // exactly fits the lookahead item (harmonic pairing).
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0; // lookahead harmonically completes this bin
        } else {
            score += 12.0; // dead space
        }
    }

    // Lookahead harmony: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 10.0;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): neutral-to-slightly-high score so it is
    // chosen only when no open bin offers a good harmonic fit. Encourage it
    // when the item is large (poor fit candidates elsewhere).
    if bin_residual == bin_capacity {
        score = post + 5.0;
        if item_size >= 50 {
            score -= 3.0; // large items start fresh bins more readily
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    }

    // Prefer bins below mean residual (tighter bins used first, larger
    // residuals preserved for bigger future items).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post;
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small post-residual gaps that nothing can use.
    // Treat gaps below the minimum plausible item size as pure waste.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 4.0; // unusable sliver => heavy penalty
    } else if post == 0.0 {
        score -= 12.0; // perfect fit: strongly reward exact closure
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize placements that leave large residuals when
    // many bins are already open (encourage consolidation).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += (post / cap) * pressure * 8.0;

    // Lookahead: if next item can reuse the post-residual, reward leaving it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0;
    } else if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post {
        // next item won't fit in the leftover gap: penalize stranded space
        score += (post / cap) * 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so tight fits in open bins win
        score = cap * 0.6 + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Mild stream-progression tilt: later in stream, prefer closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post == 0.0 {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Reward if the next item exactly fits the post residual (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect lookahead match
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how much slack remains after it too.
            let two_step = post_residual - next_item_size;
            score -= 25.0 - 0.3 * two_step as f64;
        } else {
            // Next item won't fit here: penalize dead space, worse for very small leftovers.
            let gap = next_item_size - post_residual;
            score += 10.0 + 0.2 * gap as f64;
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than average is a good squeeze; leaving much more is wasteful.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item would leave a large awkward residual in an existing bin,
    // or when no open bin exists / lookahead suggests a big next item.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        let big_next = next_item_size >= 60;
        if fitting_bins_count == 0 || (poor_fit && !big_next) {
            score -= 55.0; // open a new bin
        } else {
            score += 45.0; // discourage spreading across bins
        }
    }

    // Mild penalty for very tiny unusable leftovers (dead space < 10).
    if post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64) * (post_residual as f64) * 0.5;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Penalize leaving residual too small for the next item (dead space risk).
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.8;
        }
    } else {
        // Last item: closing bins is free, favor tight packing.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize bins that are much tighter than the mean residual only mildly
    // (they are precious); reward using bins with large residuals.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // More open bins => opening new bins is cheaper than fragmenting.
        score -= open_bins_count as f64 * 1.5;
        // Late in the stream, avoid opening bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
    }

    // Mild penalty for placing large items into nearly-full bins when other
    // space exists elsewhere (keep big-item capacity for big items).
    if item_size > 60 && post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = it / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr / cap;
    score += 0.35 * (pr / cap) * (pr / cap);

    // Tight-fit reward: smooth interaction of fill level with post residual
    let tight = fill * (1.0 - fill);
    score -= 0.6 * tight * (br / cap);

    // Stream progress coupling: early on, mild penalty for waste; later, stronger
    let p2 = progress * progress;
    score += (0.15 + 0.45 * p2) * (pr / cap);

    // Mean residual interaction: avoid bins far from the mean in a smooth way
    let dev = (br - mean_residual) / cap;
    score += 0.1 * dev * dev;

    // Last-chance bin bonus (smooth, not piecewise)
    if fitting_bins_count == 1 {
        score -= 0.8;
    } else {
        score -= 0.8 * (-((fitting_bins_count - 1) as f64) * 0.5).exp();
    }

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 0.25 * nx * (1.0 - (gap / cap));
        } else {
            score += 0.2 * (-gap / cap);
        }
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        score += 1.5 + 0.5 * progress;
        if fitting_bins_count <= 1 {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "small" class (wasted space) are penalized; leftovers in "usable"
    // classes (large enough for typical future items) are rewarded.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> perfectly reusable chunk.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> half-harmonic.
    else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Integer-division thresholds on post_residual.
    let q = post_residual / 10; // number of full 10-slots left
    score -= (q as f64) * 0.5;

    // Penalize tiny dead space: post_residual < 10 is nearly unusable.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // If next item could exactly fill the post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic coupling: reward when slack is in a good class
            if slack as u32 % 10 == 0 {
                score -= 10.0;
            }
            score -= slack / cap_f * 5.0;
        } else {
            // next item won't fit here: mild penalty scaled by how far off
            let gap = (next_item_size - post_residual) as f64;
            score += gap / cap_f * 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax late in stream
    // or when many bins are already open and mean residual is low (fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.max(next_item_size) {
            new_bin_penalty -= 0.0;
        }
        if mean_residual < 15.0 && open_bins_count > 2 {
            new_bin_penalty -= 8.0; // fragmentation: fresh bin is attractive
        }
        if post_residual % 10 == 0 {
            new_bin_penalty -= 3.0; // fresh bin leaves clean harmonic residual
        }
        new_bin_penalty += progress * 5.0;
        score += new_bin_penalty;
    }

    // Slight preference for tight fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    // Mean residual coupling: bins far below mean residual are "fuller" -> prefer.
    score -= (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (strict dead-space avoidance).
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling a bin nearly full (residual left is large waste).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 40.0;

    // Open-bins pressure: mildly reward reusing existing bins to cap bin count.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        // Dead space that the next item cannot use: penalize.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 1.5;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when the current fit is bad (large post residual
        // relative to capacity) and many bins are already open.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.5 {
            score -= 35.0 * (waste_ratio - 0.5) * 2.0;
        } else {
            // Good fit exists in an open bin; discourage opening a new one.
            score += 25.0;
        }
    }

    // Slight progression term: as stream advances, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small post_residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if post_residual >= next_item_size {
                // Next item can still fit after this placement: reward
                // proportionally to how close the match is.
                score -= 150.0 / (1.0 + gap);
            } else {
                // Next item would NOT fit: penalize dead space that
                // blocks the lookahead item.
                score += gap * 2.0;
            }
            // Extra penalty if post_residual is a small unusable sliver
            // relative to the lookahead item.
            if post_residual < next_item_size && post_residual <= 10 {
                score += 60.0;
            }
        }
    }

    // Coupling with mean residual: prefer bins tighter than average.
    if (mean_residual - post_residual as f64) > 0.0 {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless
    // the stream is early and the item is large (reserve fresh bins
    // for big items).
    if bin_residual == bin_capacity {
        score += 100.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 60 && progress < 0.5 {
            score -= 140.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 30.0;
        }
    }

    // Mild preference for using bins early in the stream (keeps
    // flexibility later).
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 0.35 * tightness * (item_size as f64);
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver is wasted space
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // this bin would be left with a large, awkward residual anyway.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when beneficial.
        score += 18.0;
        // Fewer open bins relative to stream progress -> cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If existing bins are fragmented (high mean residual), a new bin is fine.
        score -= 0.05 * mean_residual;
        // If next item is large, having a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
        // Opening a bin when many already fit elsewhere is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
    } else {
        // Reward keeping residual space usable for the lookahead item.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 4.0;
        }
        // Penalize bins whose residual is much larger than mean (hoarding space).
        if (bin_residual as f64) > mean_residual * 1.5 {
            score += 3.0;
        }
    }

    // Mild preference to fill earlier-opened bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // early stream: tolerate larger residuals (keep bins flexible);
    // late stream: strongly penalize wasted space.
    let tight_bias = 1.0 + 1.5 * progress * progress;
    score *= tight_bias;

    // Lookahead interaction: reward residual that can still host the next item,
    // penalize residual that is dead space for the next item (smooth ramp).
    if next_item_size > 0 {
        let usable = (pr - next_item_size as f64) / cap;
        let s = usable.clamp(0.0, 1.0);
        score -= 6.0 * s * s * (3.0 - 2.0 * s); // smoothstep reward
        score += 4.0 * (-usable.clamp(-1.0, 0.0)).abs() * item_norm;
    }

    // Last-chance bonus: strongly favor the single fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 - progress);
    }

    // Scarcity pressure: many open bins -> discourage spreading, favor filling.
    let scarcity = open_bins_count as f64 / (open_bins_count as f64 + mean_residual / cap.max(1.0) * 10.0 + 1.0);
    score += 3.0 * scarcity * pr_norm;

    // New-bin candidate: penalize mildly so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) - 2.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction bands
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residual classes that are hard to fill (just above common item sizes)
    let band = (post_residual / 10).min(10) as f64;
    score += band * 0.7;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Modulo-harmonic coupling: reward residuals that are multiples of 10 (harmonic with item granularity)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize odd residuals (less likely to be exactly filled)
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - (leftover as f64) * 0.5;
        } else {
            // next item won't fit here; mild penalty for wasting capacity class
            score += 6.0;
        }
    }

    // Last chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New bin candidate logic: only open a new bin when current fit is poor
    if bin_residual == bin_capacity {
        // Baseline: new bin is moderately attractive
        score = 45.0 + frac * 10.0;
        // Prefer new bin when item is large (poor fit anywhere else likely)
        if item_size > 60 {
            score -= 20.0;
        }
        if item_size >= 50 && post_residual < 50 {
            score -= 10.0;
        }
        // If many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += (fitting_bins_count as f64) * 6.0;
        }
        // If only one fitting bin, strongly discourage new bin
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // Early in stream, prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // Next item large: keep fresh capacity
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: if open bins are generally full, prefer tightening this one
    if mean_residual < 15.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily so we never strand tiny residuals
    // unless the fit is otherwise perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit bonus: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual >= 10 {
        // Usable gap: mild reward for tight-but-usable fits.
        score -= (10.0 - (post_residual as f64).min(40.0) / 4.0).max(0.0);
    }

    // New-bin candidate: this call has bin_residual == bin_capacity.
    // Opening a new bin is only desirable when no (or one last-chance) open
    // bin fits, or when the fit here would strand a large dead gap elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: strongly discourage opening bins while existing ones fit.
        score += 40.0;
        // Pressure from number of open bins: many open bins -> never open more.
        score += 2.0 * open_bins_count as f64;
        // If this bin is the only fitting option, opening new is acceptable-ish;
        // relax penalty so selection can fall through to a new bin when needed.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= (next_item_size as f64 - 50.0) * 0.3;
        }
        // Late in the stream, avoid spawning bins that will end mostly empty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Existing bin that fits: reward using it, especially under pressure.
        score -= 5.0;
        // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins with low residual relative to mean (tighter bins first).
        score += (bin_residual as f64 - mean_residual) * 0.15;
        // Lookahead: if next item fits the post-residual exactly-ish, big bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64) / 40.0).max(0.0);
        }
        // If next item would NOT fit the post-residual, mild penalty for
        // consuming a bin that could serve a bigger future need differently.
        if next_item_size > post_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize small leftover fragments.
        let frag = post_residual as f64;
        score += 20.0 * (1.0 - frag / (bin_capacity as f64 * 0.5)).max(0.0);
    }

    // Reward bins whose residual is already below average (tight, well-used bins).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 8.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 4.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate unless the fit is truly tight.
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) <= 10.0;
        if tight {
            score -= 5.0;
        } else {
            score += 35.0 + 0.2 * post_residual as f64;
        }
    }

    // Early in the stream, slightly discourage hoarding many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 3.0 * (1.0 - progress) * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large fraction.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post_residual that is hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when the item barely fits elsewhere
    // or open bins are already crowded with large residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 100.0 + 30.0 * progress;
        // If next item is large, opening a fresh bin now may pay off.
        if next_item_size > 0 && next_item_size >= 60 && post_residual as f64 >= next_item_size as f64 {
            new_bin_score -= 70.0;
        }
        // If many bins can fit, opening a new bin is wasteful.
        new_bin_score += 8.0 * (fitting_bins_count as f64).min(6.0);
        // If mean residual is large, open bins have plenty of space: keep using them.
        new_bin_score += mean_residual * 0.5;
        score = new_bin_score;
        return score;
    }

    // Lookahead synergy: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 45.0; // perfect pair
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Prefer filling bins with below-average residual (balance toward fullness).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild encouragement to consolidate into fewer bins early on.
    if open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling: tight fits rewarded more as stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 24.0 * tightness.powf(2.0) * (0.4 + 0.6 * progress);

    // Penalize large dead space quadratically, weighted by stream progress.
    score += 18.0 * norm_post * norm_post * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && post >= next_item_size {
        let slack = (post - next_item_size as f64) / cap;
        score -= 14.0 * (1.0 - slack) * (1.0 - slack) * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how far off.
        let gap = (next_item_size as f64 - post) / cap;
        score += 10.0 * gap * gap;
    }

    // Last-chance bonus: smooth function of fitting bins count.
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Penalize bins deviating from mean residual (encourage balanced fill).
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild penalty for opening new bins early; grows with progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress * progress;
        // But if item is large relative to capacity and few bins fit it, allow it.
        if fitting_bins_count <= 1 && norm_item > 0.6 {
            score -= 22.0 * progress;
        }
    }

    // Cubic interaction: post residual vs progress.
    score += 5.0 * norm_post * norm_post * norm_post * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 capture "dead space" quality.
    let residue_class = post_residual % 10;
    // Dead space penalty: residuals that cannot host common small items (1..10) are bad.
    if residue_class != 0 && post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }
    // Favor post_residuals that are exact multiples of 10 (harmonic with capacity 100).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Extra bonus for quarter/half harmonics: 25, 50, 75 residuals fit mid-size items.
    if post_residual == 25 || post_residual == 50 || post_residual == 75 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Harmonic pairing: next item exactly fills remaining space -> near-perfect chain.
            if next_item_size == post_residual {
                score -= 20.0;
            }
            // Fractional harmony: next item leaves a multiple-of-10 residual again.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; slight penalty scaled by overflow amount.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.15;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.05;
    } else {
        score += (residual_f - mean_residual) * 0.05;
    }

    // New-bin candidate: penalize so it's only chosen when all open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the current item leaves a harmonic residual in a fresh bin, soften slightly.
        if post_residual % 10 == 0 {
            score -= 2.0;
        }
    }

    // Late in the stream, consolidate: penalize spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * progress;

    // Small tie-breaker favoring tighter fits (lower post_residual already does this; add mild non-linearity).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but gaps below the typical small item size are waste).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual > 10 && post_residual <= 25 {
        score += 25.0; // marginal gap, only fits small items
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins; encourage
    // filling existing bins when open_bins_count is large.
    score += (open_bins_count as f64) * 1.5;

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer placing into them to consolidate slack.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Lookahead: if the next item can exactly use the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover gap cannot host the next item -> dead space risk
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no good fit exists elsewhere; otherwise penalize
    // opening new bins, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: heavily reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize creating tiny dead spaces that nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: if the NEXT item fits exactly into the post-residual,
    // this placement is excellent — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Chain-friendly: next item fits with room to spare.
            score -= 0.5 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item won't fit here; residual becomes dead space for k=2.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets
    // for filling; loose bins should absorb big items.
    let tightness = (bin_residual as f64) - mean_residual;
    score += 0.4 * tightness;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 60.0 - 40.0 * large_item;
        // Early in the stream, opening bins is cheaper than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            // Big item plus a follow-up: a fresh bin can host both.
            score -= 0.4 * next_item_size as f64;
        }
    }

    // Mild pressure to close out nearly-full bins.
    if post_residual <= 5 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits in existing bins (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving awkward residual.
        score += 0.35 * post_residual as f64 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only good for large items
    // or when existing fits are poor.
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; less so for large items.
        score += 30.0 - 20.0 * fill_ratio;
        // Early in stream, prefer consolidating into open bins.
        score += 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: discourage new bin.
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Slight preference for filling bins with larger residuals first
        // (best-fit flip: prefer smallest residual that still fits).
        score += 0.10 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // early on, waste is cheap-ish (bins will keep filling); late, waste is costly.
    let waste_penalty = x * x * (1.0 - x) * (1.0 + 3.0 * progress);
    score += 40.0 * waste_penalty;

    // Very large post residual (dead space) penalized more as stream advances
    score += progress * (x * x) * 25.0;

    // Perfect fit bonus (smooth, near-zero post residual)
    score -= (1.0 - x).powi(6) * 8.0;

    // Last-chance bin: strongly reward using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Crowding: many open bins -> prefer consolidation (lower score for tighter fills)
    let crowding = (open_bins_count as f64).ln1p();
    score += crowding * x * 3.0;

    // Mean residual coupling: if this bin's residual deviates low from mean, slight reward
    let mean_x = mean_residual / cap;
    score += (x - mean_x) * (5.0 + 5.0 * progress);

    // Lookahead: if next item fits exactly into post_residual, big reward (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score -= (-gap * 12.0).exp() * 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
        // but if no open bin fits well, the base pr=cap score already competes
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=5, or just above half) are near-perfect or
    // half-filled states -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead-space class: leftover <= 10 is nearly unusable (min item 1..100
    // but small items are rare-ish); reward tight fits proportionally.
    if post_residual <= 10 {
        score -= (11 - post_residual) as f64 * 4.0;
    }

    // Half-class: post_residual near cap/2 keeps room for a mid item; reward.
    let half = cap * 0.5;
    let dist_half = (post - half).abs();
    score -= (cap - dist_half) * 0.05;

    // Modular harmonic classes on post_residual: residues mod 10 that match
    // common item-size residues are re-usable.
    let res_mod = post_residual % 10;
    let next_mod = (next_item_size % 10) as f64;
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits exactly into this bin -> strong reward.
        score -= 25.0;
        if res_mod == (next_item_size % 10) {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize if we also waste space.
        score += 6.0;
    }

    // Integer-division thresholds: post_residual in (cap/3, cap/2] is the
    // "awkward third" zone -> mild penalty for creating it.
    if post_residual > bin_capacity / 3 && post_residual <= bin_capacity / 2 {
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin fits badly.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = cap * 0.55;
        // If the item would leave an awkward residual even in a fresh bin,
        // opening is cheap when many bins are open and mean residual is low.
        let fresh_post = cap - item_size as f64;
        if fresh_post < 15.0 {
            score -= 20.0; // near-perfect fresh fit: open happily
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual across open bins is large, discourage new bin.
        score += mean_residual * 0.3;
        // Late in stream, prefer closing out open bins rather than opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for fuller bins overall (tighten mean-residual coupling).
    score -= (cap - (bin_residual as f64)) * 0.1;

    // Harmonic tie-breaker: prefer bins whose residual mod 10 equals item mod 10
    // (classic modular pairing leaves complementary residues).
    if bin_residual % 10 == item_size % 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold another item (min item size 1..100 unknown, but tiny gaps are
    // almost always waste) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 6.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }
    // Reward when the residual can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 6.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, avoid spreading residual
    // capacity; favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.4 * (0.5 + progress);

    // Prefer bins below the mean residual (fill the emptier-tail bins less,
    // keep tight bins tight) — actually favor bins whose residual is BELOW
    // mean (they are already tight): penalize placing into very loose bins.
    if (bin_residual as f64) > mean_residual * 1.25 && bin_residual != bin_capacity {
        score += 5.0;
    }

    // New empty bin candidate: neutral baseline with a mild penalty so it is
    // only chosen when existing bins fit poorly (large dead space or none fit).
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening a new bin is less costly than wrecking
        // a usable residual — soften the penalty as progress increases.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item fills this bin perfectly.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits with some slack left; mild penalty proportional to slack.
            score -= 25.0 - 0.35 * gap;
        } else {
            // Next item won't fit: penalize dead space creation.
            score += 0.6 * gap;
        }
        // Extra penalty if post_residual is a tiny unusable fragment.
        if post_residual > 0 && post_residual < 10 {
            score += 18.0;
        }
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving very large residuals in already-open bins when many bins are open.
    if open_bins_count > 3 && post_residual as f64 > 0.7 * bin_capacity as f64 {
        score += 10.0;
    }

    // Slight progression term: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late in the stream.
        score = score.max(0.0) + 45.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead (k=2): reward bins that can also host the next item,
    // especially when the next item is large (harder to place later).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = next_item_size as f64 / bin_capacity as f64;
            score -= 5.0 + 6.0 * tightness;
        } else {
            // Placing here strands the next item elsewhere; mild penalty.
            score += 2.5;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits,
    // avoid opening a new bin unnecessarily.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Reward near-perfect packing (small dead space is only bad if truly unusable).
    if post_residual < 10 {
        score -= 3.0;
    }

    // New-bin candidate handling: default penalty so we only open a new bin
    // when existing fits are genuinely poor.
    if is_new_bin {
        score += 12.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No open bin can host the item: opening is mandatory.
            score -= 25.0;
        } else if fitting_bins_count == 1 {
            // A single (possibly awkward) fit exists; still allow escape hatch
            // but less aggressively as the stream progresses.
            score -= 14.0 * (1.0 - 0.5 * progress);
        }
        // Late in the stream, slightly favor reusing open bins to close them out.
        score -= 6.0 * progress;
    }

    // Global coupling: prefer bins whose post-residual tracks the mean residual
    // (keeps the bin population homogeneous and reusable).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight time decay: early on, be more tolerant of loose fits to build
    // flexible bin sets; late, demand tightness.
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize leftover space, with non-linear (quadratic) growth.
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Tight-fit reward: strongly subtract when post_residual is small.
    let tight = (cap - pr) / cap; // fill fraction after placement
    score -= 12.0 * tight * tight;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits (keep flexibility); late, demand tightness.
    let flex = (1.0 - progress) * (1.0 - progress);
    score += 8.0 * flex * (pr / cap);
    score -= 10.0 * progress * progress * (1.0 - (pr / cap));

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * progress;
    }

    // Dead-space avoidance: penalize residuals too small for the smallest plausible item.
    let min_item = 1.0f64.min(cap); // effectively 1.0
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (1.0 - pr / 10.0);
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let nxt = next_item_size as f64;
        score -= 6.0 * (nxt / cap) * (1.0 - (pr - nxt) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for fragmenting space.
        score += 2.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if is_new_bin {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let mean_tight = 1.0 - (mean_residual / cap);
        score -= 30.0 * crowding * mean_tight * (0.5 + 0.5 * progress);
        // Penalize opening a new bin early or when many bins can fit the item.
        score += (1.0 - progress) * 20.0;
        score += fitting_bins_count as f64 * 3.0;
        // A fresh bin has full residual 100; neutralize its naturally low base score.
        score += pr * 0.35;
    } else {
        // Mild preference for using more-open bins rather than proliferating bins.
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Mean-residual context: if this bin's post-residual deviates favorably from mean, reward.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev - 4.0 * dev * progress;

    // Small item-size coupling: large items should prefer tight fits even more.
    score -= 5.0 * (isz / cap) * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: residual == capacity means empty bin.
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Harmonic class of post_residual (mod arithmetic on capacity) ----
    // Class 0: post_residual is a multiple of 10 -> clean divisible space, reward.
    // Class 1: post_residual < 10 -> dead space, penalize heavily.
    // Class 2: post_residual in 10..20 -> awkward small gap, mild penalty.
    let dead = post_residual < 10;
    let clean = post_residual % 10 == 0 && post_residual > 0;
    let awkward = !dead && !clean && post_residual < 20;

    if dead {
        score += 30.0;
    }
    if clean {
        score -= 12.0;
    }
    if awkward {
        score += 6.0;
    }

    // Perfect fit: zero waste is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // ---- Harmonic coupling with next item (lookahead, k=2) ----
    // If the next item can exactly fill the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            // next item fits but leaves dead space -> penalize
            score += 15.0;
        } else if next_item_size > post_residual {
            // next item cannot use this residual; residual becomes stranded
            // unless another bin can host it. Mild penalty scaled by strandedness.
            score += (post_residual as f64) * 0.15;
        }
    }

    // ---- Last-chance bin logic ----
    // If this is the only fitting bin, strongly prefer using it over opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // ---- New-bin decision: penalize opening a new bin unless current fits are bad ----
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 20.0;
        // If the item is small relative to capacity, opening a fresh bin wastes it.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.5 {
            score += 15.0;
        }
        // If other bins fit, opening is rarely worth it unless all fits are terrible.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Reward filling existing bins tightly: prefer bins with small residual
        // (best-fit flavor) modulated by harmonic class.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 8.0;
    }

    // ---- Mean residual coupling: if mean residual is high, prefer consolidating
    // into bins rather than leaving scattered space ----
    if mean_residual > 20.0 && !is_new_bin {
        score -= 3.0;
    }

    // Integer-division threshold on post_residual: half-capacity leftovers
    // (residual near 50) are highly reusable, reward them.
    if post_residual >= 45 && post_residual <= 55 {
        score -= 6.0;
    }
    // Quarter-capacity leftovers (~25) are moderately reusable.
    if post_residual >= 22 && post_residual <= 28 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (minimum plausible item size assumed around 10) are pure waste.
    if post_residual < 10 {
        score -= 45.0; // near-perfect fill, strongly favored
    } else if post_residual < 20 {
        // Small gap: likely dead space unless a tiny item arrives later.
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap can host the next item: mild reward proportional to snugness.
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 60.0).max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> consolidate; few open bins -> allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure;

    // Mean residual coupling: if this bin's post-residual is far below the mean,
    // we are tightening a loose bin (good); if far above, we spread waste.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor:
        // penalize new bins moderately so only really bad fits trigger opening.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If the next item is large and this fresh bin can host it comfortably,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Tiny exact-fit bonus: leaving zero residual is the ideal outcome.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size <= post_residual {
            // Next item fits perfectly after this placement: strong reward.
            let gap = post - next_f;
            score -= 30.0 * (1.0 - gap / 60.0).max(0.0);
        } else {
            // Next item would not fit: penalize proportionally to overflow.
            score += 0.25 * (next_f - post).min(80.0);
        }
        // Compare post_residual against mean residual: avoid leaving much more
        // space than average (wasted potential), or much less (dead space).
        let diff = post - mean_residual;
        score += 0.08 * diff;
        // Reward tight fits relative to bin capacity.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        // Last item: just prefer fullest packing.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // typical residuals (open bins would waste a lot of space).
    if bin_residual == bin_capacity {
        let waste_estimate = (bin_residual - item_size) as f64;
        // Penalize opening a new bin; discount if item is huge.
        score += 55.0 - 40.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is large and would fit well in fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
        if waste_estimate < 20.0 {
            score -= 25.0; // large item in fresh bin: low dead space, good idea
        }
    }

    // Slight preference to fill older/smaller-residual bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * mean_residual * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness * (bin_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item (>=1) can use well:
    // small but nonzero post_residual is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: penalize if placing here blocks the next item from fitting
    // in the residual left behind.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * next_item_size as f64;
        }
        // Reward if the leftover still accommodates the next item.
        if next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when existing bins are poor fits
    // or the stream is early with many items remaining to fill the new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = mean_residual < item_size as f64 * 1.1;
        let bonus = if poor_fit { 20.0 } else { 0.0 };
        // New bins are cheap early, expensive late.
        score = 60.0 + 40.0 * progress - bonus + 0.1 * open_bins_count as f64;
    } else {
        // Mild preference for filling bins with larger residuals (balance load),
        // and slight penalty for spreading across many bins.
        score += 0.02 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // to keep the pool of usable bins uniform.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate slack
    // since fewer future items remain to fill gaps.
    let poly = post * post / cap;                 // quadratic term
    let cubic = poly * post / (cap * cap);        // cubic term
    let w_poly = 0.5 + 1.5 * progress;            // grows with progress
    let w_cubic = 2.0 * progress * progress;      // strong late penalty
    score += w_poly * poly + w_cubic * cubic;

    // Smooth interaction: tight fit (post_residual small) is extra valuable
    // when this is the last fitting bin.
    let tightness = 1.0 - post / cap;
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 6.0 * last_chance * tightness * tightness;

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 3.0 * snug * snug;
        } else {
            // penalize residuals that can't hold the next item, scaled by progress
            score += 2.0 * progress * (nxt - post) / cap * cap / cap * cap;
        }
    }

    // Mild pressure to prefer bins that are already open and well-used,
    // penalizing fragmentation relative to mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: keep it mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (10..=80 gcd classes) are more reusable.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0f64;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect fill
    } else {
        for m in [5u32, 10, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmonic_bonus -= 8.0 * (pr as f64 / bin_capacity as f64);
                break;
            }
        }
        // small dead space is bad; large residual is good
        if pr < 10 {
            harmonic_bonus += 25.0;
        }
    }
    score += harmonic_bonus;

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 + 0.3 * slack as f64;
            if slack == 0 {
                score -= 30.0; // chain fill to zero
            }
        } else {
            score += 6.0; // next item won't reuse this residual
        }
        // harmonic match: next item shares a divisor class with residual
        if next_item_size % 5 == 0 && pr % 5 == 0 && next_item_size <= pr {
            score -= 5.0;
        }
    } else {
        // last item: prefer tighter fit, closing bins
        score += 0.5 * pr as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer fuller bins among many open bins (best-fit reinforcement)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Progression: later in the stream, be more aggressive about packing tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // New-bin candidate penalty: only open a new bin if current bin is very full
    // or residual is hopeless dead space.
    if bin_residual == bin_capacity {
        // empty candidate: keep it slightly worse than a decent fit
        score = bin_capacity as f64 * 1.15;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size > bin_residual && next_item_size <= bin_capacity {
            // lookahead suggests saving a fresh bin is useless anyway
            score += 10.0;
        }
        if pr == 0 && next_item_size == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse late in the stream when few chances remain to reuse it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 25 {
        score += progress * 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            score += 20.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins, but allow
    // opening a new bin when this bin is a poor host (large post_residual waste).
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if item leaves a large unusable
        // gap in every existing bin (approximate via fitting pressure).
        if fitting_bins_count <= 1 {
            score -= 30.0; // last-chance bin: opening fresh is fine
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64; // prefer reusing open bins
        }
    } else {
        // Existing bin: mild reward when it is the only fitting option.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins below mean residual (tighter bins get used first).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(4);

    // 2-step lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64)).powi(2);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item cannot use this leftover space; penalize small dead space.
        score += 4.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: keep it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    score -= tightness;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Dead space likely unusable (min item size 10 historically, but items 1..100).
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize proportionally.
        score += (post_residual as f64) * 0.5;
    }

    // Last chance: only fitting bin — avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0)).min(5.0);
    score -= pressure * 0.5;

    // New-bin candidate handling: empty bin should only win when current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins score badly.
        score += 25.0;
        // Early in the stream, opening bins is cheaper (more future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Large item with no good existing fit: new bin is attractive.
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 10.0;
        }
        // If next item is large, fresh capacity helps.
        if next_item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 5.0;
        }
    } else {
        // Reward using bins that are already relatively full.
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Mean residual coupling: high mean residual means slack exists; prefer bins below mean (fuller).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic coupling of post_residual with stream progress.
    // Tight fits matter more early (preserve flexibility later? no — early tight fits
    // keep large residuals concentrated), so weight grows with progress.
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals that are awkward (small but nonzero) — polynomial dip.
    let awkward = (pr as f64 / 25.0 - 1.0).powi(2);
    score += 4.0 * awkward * (1.0 - progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 4.0 * progress;
    }
    // If next item would exactly fill post-residual, extra reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; relax as open bins grow or mean residual is high.
        score += 10.0
            + 0.3 * open_bins_count as f64
            - 0.05 * mean_residual;
        // If current fit is very tight, opening a new bin is less bad.
        if item_size as f64 / bin_residual as f64 > 0.9 {
            score -= 12.0;
        }
    } else {
        // Favor bins whose residual is close to item size (best-fit coupling).
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 5.0 * fit_ratio * fit_ratio;
    }

    // Mild preference for filling fuller bins, scaled by open-bin pressure.
    score -= 0.02 * (bin_residual as f64) * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in the "small dead space" class
    // are valuable; large leftovers are wasteful.
    let frac = post_residual as f64 / cap_f; // 0..1
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes
    match class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 2.0,
        5 => score += 6.0,
        6 => score += 12.0,
        _ => score += 20.0,               // big dead space
    }

    // Exact-fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic on residual: residuals that are multiples of common
    // small item sizes (e.g. 10, 20, 25) are more reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 8.0;
    }
    if r > 0 && r % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the leftover fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0; // perfect chain fit
        } else if next_item_size <= r {
            let nf = next_item_size as f64 / r.max(1) as f64;
            score -= 15.0 * nf; // partial chain fit, proportional
        } else {
            score += 5.0; // leftover too small for lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty when the current stream is early (room to accumulate) or when
    // the item is huge and would leave a very awkward residual in any bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap_f;
        let mut penalty = 40.0;
        if item_frac > 0.7 {
            penalty -= 15.0; // huge items: fresh bin may be cleaner
        }
        if progress < 0.2 {
            penalty -= 10.0; // early stream: cheap to open bins
        }
        if open_bins_count > 8 {
            penalty += 8.0; // too many open bins already
        }
        score += penalty;
    }

    // Slight preference for fuller bins overall
    score -= (bin_residual - post_residual) as f64 / cap_f * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Slight preference for bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream conservatism: avoid leaving awkward gaps near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // Exact match bonus
            let match_quality = 1.0 - ((post - nxt) / bin_capacity as f64).abs();
            score -= 8.0 * match_quality * match_quality;
        } else {
            // Next item cannot follow here: penalize leaving large unusable space
            score += 3.0 * (post / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0;
        // Allow new bin if item is large and would leave a very tight fit elsewhere
        if item_size as f64 / bin_capacity as f64 > 0.7 && fitting_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large unusable leftovers (dead space), especially small post residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving room for the next item if it fits well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5 && fitting_bins_count > 0;
        if poor_fit {
            score -= 30.0; // opening fresh bin is better than wasting space
        } else {
            score += 45.0; // prefer existing bins when they fit reasonably
        }
        // Early in stream, opening bins is cheap; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (larger residual than average).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // tight fits are increasingly valuable late in the stream.
    let coupling = 24.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);
    score -= coupling;

    // Penalize dead space that is too small to be useful later, smoothly.
    let dead = if pr < item_size as f64 { pr * pr / cap } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap).powf(2.0);
            score -= 10.0 * snug * (0.5 + 0.5 * progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize opening a bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) more than linearly.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Harmonic class of the post residual: residues in "dead zones"
    // (very small but nonzero leftovers) are penalized.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 25.0;
    }
    // Modulo-10 class: leftovers that are multiples of 10 are reusable
    // by common item sizes, so reward them.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: post_residual bucketed by how many
    // "typical" items (size ~ 25) could still fit.
    let fits_after = post_residual / 25;
    score -= 6.0 * fits_after as f64;

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // Harmonic check: next item leaves another multiple-of-10 residue
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty if
            // the leftover is large (wasted potential).
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave very tight dead space and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) / 20.0;
        // Default: new bin is unattractive.
        score = (bin_capacity as f64) + 30.0 - pressure - 20.0 * progress;
        // If item is large and current mean residual is small, opening a
        // new bin becomes reasonable.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
        // If next item is also large, keep new bin option cheaper.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight preference to fill emptier bins first (balance residuals).
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that is too small to hold even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is very good. Mild additive term.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // since rejecting it forces a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // next item cannot use the gap; slight penalty
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0 + 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; slight penalty for adding more.
    let res_frac = (bin_residual as f64) / (bin_capacity as f64);
    if res_frac < mean_residual / (bin_capacity as f64) - 0.15 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual -> mild reward scaled by tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0); // tightest follow-up fits favored most
    }
    // Next item cannot use post residual: dead-space penalty, worse when small.
    else if next_item_size > 0 && post_residual > 0 {
        let dead = post_residual as f64;
        score += if dead < 10.0 { 25.0 } else { dead * 0.15 };
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: prefer bins that stay near the mean
    // (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: strongly penalize by default so we prefer existing bins.
    if is_new_bin {
        score += 45.0;
        // But if this bin is the only fitting option, opening a new bin is
        // competitive: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, having few bins, slightly favor consolidation anyway.
        score += (1.0 - progress) * 10.0;
    } else {
        // Last-chance bin (only one fitting bin): reward using it to avoid new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: post residual near zero is good.
    if post <= 10.0 {
        score -= 25.0;
    } else if post <= 20.0 {
        score -= 12.0;
    }

    // Penalize dead space scaled by how unusable it is relative to item range.
    let dead = post / cap;
    score += 30.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap <= 5.0 {
                score -= 35.0;
            } else if gap <= 15.0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here anyway; slight penalty for blocking bins.
            score += 4.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // late in stream, prefer tight packing regardless.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (cap - post) / cap;

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 8.0 * (mean_residual / cap);
    }

    // New-bin candidate handling: empty bin must look unattractive unless item is huge
    // or residuals everywhere are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 20.0; // base cost of opening a new bin
        if fill_ratio > 0.8 {
            score -= 30.0; // huge items deserve fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If mean residual of open bins is small (they're all tight), new bin is fine.
        score -= (30.0 - mean_residual.min(30.0)) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, dead space is heavily penalized.
    let waste_penalty = residual_norm * residual_norm * (1.0 + 3.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Cubic interaction: small residuals late in stream are gold; amplify reward
    let tight_reward = -(1.0 - residual_norm).powi(3) * (1.0 + 2.0 * progress) * cap * 0.3;
    score += tight_reward;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 + 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Deviation from mean residual: prefer bins that keep residual distribution balanced
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap;

    // New-bin candidate handling: empty bin gets a penalty so we prefer open bins,
    // unless the fit is terrible (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * progress;
        // If nothing else fits well, allow opening: reduce penalty when waste would be huge
        if item_size > 0 {
            let would_waste = (bin_residual - item_size) as f64;
            score -= 30.0 * (would_waste / cap).powi(2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues that pair well with
    // common item sizes are cheaper to keep than awkward dead space.
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Dead-space penalty for unusable residuals (< 10 or unmatchable classes)
    if post > 0 && post < 10 {
        score += 50.0;
    }

    // Reward when next item fits exactly into the post residual (perfect pairing)
    if nxt > 0 {
        if nxt == post {
            score -= 60.0;
        } else if nxt < post {
            // fractional fill reward scaled by how much of residual is used
            score -= 30.0 * (nxt as f64 / post.max(1) as f64);
        } else {
            // next item won't fit: penalize, worse for larger overshoot
            score += 0.5 * ((nxt - post) as f64);
        }
        // modulo harmony: post_residual mod next_item_size small => tight packing
        if nxt > 0 {
            let m = post % nxt;
            score -= 2.0 * (nxt as f64 - m as f64) / nxt as f64;
        }
    }

    // Integer-division thresholds on post_residual (harmonic capacity fractions)
    let cap = bin_capacity as f64;
    let frac = post as f64 / cap;
    if frac < 0.25 {
        score += 15.0; // nearly full: very good, keep it low
        score -= 20.0;
    } else if frac < 0.5 {
        score -= 5.0;
    } else if frac > 0.75 {
        score += 10.0; // large residual: mild penalty to prefer tighter bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins already below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - post as f64);

    // Early in stream: encourage opening/filling bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when no good existing fit
        score += 25.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Small coupling: item size harmonic class (multiples of 10 pack well)
    if item_size % 10 == 0 && post % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small to be useful for typical future items.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 30.0 * (1.0 - (post_residual as f64) / (dead_threshold as f64));
    }

    // Gap that cannot even fit the lookahead item is wasted if lookahead exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward gaps that remain usable for the lookahead item.
        score -= 6.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize alternatives implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    // The new-bin candidate has bin_residual == bin_capacity; give it a mild
    // penalty proportional to open_bins_count so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64).sqrt() * 4.0;
    }

    // Mild dispersion penalty: prefer bins whose residual deviates from the mean
    // toward consolidation (smaller residual = more consolidated bin).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 4.0 * dev;

    // Early in the stream, allow more exploration of new bins; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits with small slack -> graded reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot follow into this bin -> penalize proportional to overshoot
        let over = (next_item_size - post_residual) as f64;
        score += 8.0 * (over / bin_capacity as f64);
    }

    // Penalize tiny dead space relative to capacity (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if next_item_size > 0 && next_item_size <= post_residual && post_residual == bin_capacity {
            score += 10.0; // empty bin fits next item too; keep mild penalty
        }
    }

    // Prefer tighter-than-average bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in stream: slightly prefer compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.1 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to remaining slack.
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item would need another bin: penalize blocking large residuals.
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.3;
    score += (1.0 - progress) * post_residual as f64 * 0.15;

    // Global state: many open bins -> favor filling existing bins over opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New-bin candidate: penalize unless residuals are all very tight.
        score += 12.0 + pressure * 0.2;
        if post_residual < 15 {
            score += 10.0; // new bin with dead space is bad
        }
    }

    // Mean residual coupling: high mean residual means bins are loose; prefer tight usage.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: normalize post_residual, penalize quadratically as it grows
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * cap;

    // Smooth coupling with stream progress: late in the stream, tighten packing more aggressively
    score *= 1.0 + 0.35 * progress * (1.0 - progress * 0.5);

    // Lookahead: if the next item fits into post_residual, reward this placement smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = ((pr - nx) / cap).max(0.0);
        let tightness = (nx / cap) * (1.0 - (pr - nx).abs() / cap);
        score -= 8.0 * fit_next.max(0.0).min(1.0) * tightness;
        // Penalize if post_residual is just barely below next item size (wasted gap)
        let gap = (nx - pr).max(0.0) / cap;
        score += 6.0 * gap * (1.0 - gap);
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild penalty when many bins compete, encouraging consolidation
        score += 1.5 * ((fitting_bins_count as f64 - 1.0).min(5.0));
    }

    // Prefer bins with residual below mean residual (denser bins first), smooth coupling
    score += 2.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: penalize opening a new bin smoothly, scaled by how well
    // existing bins could do (post_residual of empty bin is large, so this adds pressure)
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    // Class 0: post_residual == 0 (perfect fill) -> huge reward
    // Class 1: post_residual in 1..=10 (dead space) -> penalize
    // Class 2: post_residual divisible by 25 (quarter harmony) -> reward
    // Class 3: post_residual divisible by 10 (decile harmony) -> mild reward
    // Class 4: post_residual divisible by 5 -> tiny reward
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr < 10 {
        score += 18.0; // dead space penalty
    } else {
        if pr % 25 == 0 { score -= 12.0; }
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 5 == 0 { score -= 2.0; }
        // integer division thresholds: leftover can host next item?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 8.0;
                // exact harmony: next item fills leftover exactly
                if next_item_size == pr { score -= 22.0; }
                // leftover after a hypothetical next placement
                let pr2 = pr - next_item_size;
                if pr2 == 0 { score -= 15.0; }
                else if pr2 < 10 { score += 5.0; }
                else if pr2 % 25 == 0 { score -= 5.0; }
            } else {
                score += 4.0; // leftover too small for lookahead item
            }
        }
    }

    // Fractional fill of the bin: reward high utilization
    let fill = (bin_residual - pr) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when item is large
    // relative to mean residual, or nothing fits well.
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * cap;
        let poor_fit = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual < 10);
        if large || poor_fit {
            score -= 30.0;
        } else {
            score += 35.0; // discourage opening a new bin when fits exist
        }
        // late in stream, opening new bins is cheaper than many half-empty ones
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 { score -= 5.0; }
    }

    // Coupling with mean residual: bins below mean residual are "worse"
    // (more packed already is better though) -> prefer bins with residual
    // close to item_size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    // Prefer bins whose residual is in the same harmonic class as the item
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, hard-to-fill gap)
    // is heavily penalized. Gaps below 10 are essentially unusable since min item is 1,
    // but gaps below ~15 are statistically poor targets; treat tiny gaps as wasted.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit is always excellent.
        score -= 200.0;
    }

    // Reward tight fits: small relative slack.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, discourage opening new bins unless fit is bad.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits into the post_residual, reward it;
    // if next item would leave this bin dead anyway, slight penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: choosing a bin well below mean residual
    // concentrates waste in one bin rather than spreading it.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current item is large relative to capacity
    // (a big item in a fresh bin leaves useful large residual) or when no good fit exists.
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        // Large items benefit from fresh bins; small items should go into open bins.
        score += ratio * 30.0 - 20.0;
        // Late in the stream, keep bins consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // closely matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Perfect match: next item exactly fills this bin afterwards.
            let match_quality = 1.0 - (gap / nxt).min(1.0);
            score -= 25.0 * match_quality;
        } else {
            // Post-residual too small for next item: penalize by how much
            // the opportunity is wasted (dead space relative to next item).
            score += 0.6 * (nxt - post);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean residual are
    // better targets (small residual = tight fit = good packing).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.35 * (mean_residual - post_f);
    } else {
        score += 0.25 * (post_f - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item would leave a large dead space, or when the
    // next item is large and a fresh bin preserves flexibility.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin when the item fits reasonably well here.
        score += 12.0 + 40.0 * fill_ratio;
        // But discount if next item is big and nothing fits well elsewhere.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let post = post_residual as f64;
            if post < nxt * 0.4 {
                // fresh bin keeps large contiguous space for the next item
                score -= 18.0 * (1.0 - fill_ratio);
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Small tie-breaker: prefer fuller bins (smaller residual) overall.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term,
    // but amplify the advantage of very snug placements.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no plausible future item can use.
    // Small residuals (< smallest plausible item) are wasted capacity.
    if post_residual < 10 {
        score -= 8.0; // nearly full bin is great
    } else if post_residual < item_size {
        // residual smaller than current item: hard to reuse
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 10.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when current fit is bad and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64) / cap;
        // Base cost of opening a new bin; reduced when many bins are open and mean residual is low
        let mut open_cost = 18.0 - 6.0 * progress;
        if open_bins_count > 0 {
            let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
            open_cost -= 8.0 * crowding;
        }
        // If item is large, filling a fresh bin is fine; if tiny, opening wastes space.
        open_cost += 6.0 * fit_quality;
        // If other bins exist that fit, discourage new bin more.
        if fitting_bins_count > 0 {
            open_cost += 5.0;
        }
        score += open_cost.max(0.0);
    }

    // Mild preference for balancing residuals: avoid leaving one bin very full
    // while others stay empty-ish when many bins are open.
    if open_bins_count > 1 && bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: prefer tight fits via smooth polynomial in post-residual
    let mut score = pr * (1.0 + 0.9 * fit_ratio * fit_ratio);

    // Stream-progress coupling: early on, tolerate loose fits; late, punish dead space harder
    score += pr * 1.5 * progress * (1.0 - progress) * (fit_ratio - 0.5) * (fit_ratio - 0.5) * 4.0;
    score -= 12.0 * progress * (1.0 - fit_ratio);

    // Penalize bins whose residual drifts far below the mean (wasted capacity)
    score += 0.6 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).max(0.0);
        let miss = (ns - pr).max(0.0);
        score -= 0.35 * gap / cap;
        score += 0.5 * miss / cap * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * fit_ratio * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into coarse "usable slots" classes.
    let slot_class = (post_residual / 10) as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward very tight fits (small dead space) super-linearly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Penalize dead space that is too small for the smallest future item
    // (unusable waste): residual in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo/harmonic coupling: leftover congruent to small remainders
    // wastes capacity; leftovers that are multiples of common item
    // granularities (10, 20, 25, 50) are reusable.
    let pr = post_residual;
    if pr % 50 == 0 && pr > 0 {
        score -= 15.0;
    } else if pr % 25 == 0 && pr > 0 {
        score -= 10.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else {
        // Odd remainders: penalize by how far from the next multiple of 10.
        let waste = 10 - (pr % 10);
        score += waste as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            // Reward proportionally to how well next item fits.
            let fill_after = (pr - next_item_size) as f64;
            score -= (20.0 - fill_after * 0.5).max(0.0);
        } else {
            // Post-residual too small for next item: mild penalty scaled
            // by how much it misses.
            score += ((next_item_size - pr) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive; penalize so it is only chosen
        // when all open bins yield terrible fits (large scores there).
        score += 40.0;
        // But if the item is large (hard to place later), a fresh bin is fine.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Early in the stream, having few bins, opening is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer filling bins that are already mostly full (small residual)
    // — close out bins rather than fragmenting many partially-filled ones.
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.3;

    // Coupling with mean residual: if this bin's residual is far below
    // the mean, it is a "close-out" candidate — reward using it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Slot-class harmonic damping: smooth score by coarse class.
    score += slot_class * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: penalize if the leftover cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make the empty bin expensive unless the current
    // item is a poor fit for existing bins or the fit here would be excellent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If the item would leave a clean, reusable residual, opening is fine.
        if post_residual >= 20 && post_residual % 10 == 0 {
            score -= 20.0;
        }
        // Large items relative to capacity justify a fresh bin.
        if item_size >= 60 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Existing bin: mild reward for tight fit relative to residual.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fit_ratio * 10.0;
    }

    // Slight tie-break toward bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next item.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= look {
            // Next item fits exactly into this bin's leftover -> strong reward.
            let gap = pr - look;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain (post_residual == next_item_size) is ideal.
            if gap == 0.0 {
                score -= 4.0;
            }
        } else {
            // Next item will NOT fit here: penalize leftover dead space,
            // scaled by how much it misses the lookahead.
            let miss = look - pr;
            score += 0.05 * miss.min(50.0);
        }
    }

    // Prefer bins with small residual relative to mean (tight packing).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.10 * (pr - mean_residual).max(0.0);
        score -= 0.05 * (mean_residual - pr).max(0.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item would leave a large unusable gap in every existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default penalty: prefer reusing open bins.
        score += 3.0;
        // But if item is large and leaves huge dead space elsewhere, new bin wins.
        let waste_elsewhere = (bin_capacity as f64 - item_size as f64).max(0.0);
        if waste_elsewhere > 55.0 {
            score -= 4.0;
        }
        // Late in stream, slightly prefer new bins to keep tight bins for small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.6 {
            score -= 1.5 * progress;
        }
    } else {
        // Small bonus for reusing an existing bin (defragmentation).
        score -= 1.0;
    }

    // Reward perfect fills.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Mild preference to keep very small residuals (hard to reuse) from being created.
    if post_residual > 0 && post_residual < 10 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, so subtract a bonus
    // proportional to how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Penalize post-residuals that are small but nonzero (dead space a future
    // item is unlikely to fill). Perfect fit (0) or large leftover are fine.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 12.0 {
        score += 8.0 * (12.0 - pr) / 12.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for very small leftover
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (spread load); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base score high enough that it's only chosen
        // when open bins fit poorly; discount it as stream progresses.
        score += 25.0 * (1.0 - 0.5 * progress);
        // Opening a new bin is better if mean residual of open bins is small.
        score += 0.05 * mean_residual;
        // Many open bins: discourage opening yet another one.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Existing bin: prefer bins whose residual is close to mean (balance),
        // but also reward using up larger residuals when late in stream.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev * (1.0 - progress);
        score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (low post_residual) moderately.
    // Late stream: penalize wasted residual more aggressively (quartic growth).
    let progress_weight = 0.5 + 3.0 * progress * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap * 0.25;

    // Smooth interaction: reward near-full fills (small norm_pr) with a concave bonus.
    let tightness = 1.0 - norm_pr;
    score -= (tightness * tightness * tightness) * cap * 0.35;

    // Penalize residuals that are small but not zero (dead space zone) — smooth via
    // a gaussian-like bump around norm_pr in (0.05..0.25).
    let dead_center = 0.15;
    let dead_width = 0.12;
    let dead_penalty = (-(norm_pr - dead_center) * (norm_pr - dead_center) / (2.0 * dead_width * dead_width)).exp();
    score += dead_penalty * cap * 0.30 * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits smoothly into post_residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here: slight penalty for leaving misleading space.
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty to prefer bins with few alternatives (better packing diversity).
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of smaller residual (consolidate fullness) — smooth quadratic.
    let dev = mean_residual - bin_residual as f64;
    score += 0.02 * dev * dev - 0.05 * dev;

    // New-bin candidate: discourage opening a new bin when progress is low,
    // discourage more as open bin count grows; smooth in progress.
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 6.0 * (1.0 - progress) + 3.0 * open_factor;
        // Allow new bin late in stream if item is large (poor fit elsewhere likely).
        score -= 14.0 * progress * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // ---- New-bin candidate ----
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: leftover space is the real cost.
        score = 0.55 * post;
        // Heavily penalize opening a bin when other bins already fit the item;
        // the larger the set of fitting bins, the worse it is to ignore them.
        score += 22.0 * fitting_bins_count as f64;
        // Reward opening a fresh bin only when the item nearly fills it
        // (small post_residual) or when the next item will slot in cleanly.
        if nxt > 0.0 && nxt <= post {
            score -= 10.0;
        }
        // Harmonic class: leftover divisible into few large chunks is reusable.
        let pr = post_residual;
        if pr > 0 && ((pr % 50 == 0) || (pr % 25 == 0) || (pr % 20 == 0) || (pr % 10 == 0 && pr <= 30)) {
            score -= 5.0;
        }
        // Extremely tight item: almost always worth a dedicated bin.
        if post <= 5 {
            score -= 30.0;
        }
        return score;
    }

    // ---- Existing-bin logic ----

    // Dead-space penalty: residuals in [1,9] are nearly unusable (items >= 1
    // but realistically tiny fragments waste capacity).
    if post > 0.0 && post < 10.0 {
        score += 28.0;
    }

    // Reward if the lookahead item fits into the post residual (chained fit).
    if nxt > 0.0 && nxt <= post {
        score -= 14.0;
        // Extra reward for exact harmonic chaining (post % nxt == 0).
        if nxt > 0.0 && (post_residual % next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    } else if nxt > 0.0 && post > 0.0 {
        // Post residual too small for the next item: mild penalty scaled by
        // how close it is (near-miss wastes more potential).
        score += 6.0 * (1.0 - (post / nxt).min(1.0));
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 16.0;
    } else {
        // When many bins fit, prefer the tightest (post already does this),
        // but add a small tie-breaker based on how full the bin already is.
        score -= 0.08 * (cap - bin_residual as f64);
    }

    // Harmonic class on post_residual mod 10: exact multiples of 10 leave
    // structured space that many item sizes can exploit.
    let m = post_residual % 10;
    if post_residual > 0 {
        if m == 0 {
            score -= 4.0;
        } else if m >= 5 {
            score -= 1.5; // half-class: moderately reusable
        } else {
            score += 2.0; // awkward sliver class
        }
    }

    // Prefer bins whose residual deviates from the mean in the "fuller"
    // direction (consolidate space, keep emptier bins flexible).
    score += 0.03 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in the stream, tighten up: penalize any nonzero residual more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 && post > 0.0 {
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are "dead". Penalize them super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap for items >= 10, but still possible for 1..10 items.
            score += 40.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual <= 20 {
            // Marginal gap: only tiny items fit; strong penalty.
            score += 25.0 * (20.0 - post_residual as f64) / 10.0;
        } else if post_residual <= 35 {
            // Moderately tight gap.
            score += 8.0 * (35.0 - post_residual as f64) / 15.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host next item: penalize proportionally to how close it is.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins (lower score for low open_bins_count fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space is catastrophic).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has zero dead-space risk but
    // incurs open-bin pressure. Make it attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales with how many bins are open.
        score = 30.0 + pressure * 4.0;
        // If the current item would leave a terrible gap in existing bins,
        // opening fresh is relatively better.
        if post_residual > 0 && post_residual < 10 && bin_residual == bin_capacity {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) — small coupling term.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still hold the next item: reward closeness
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap / 10.0);
    } else if next_item_size > 0 {
        // Next item cannot fit in leftover: penalize dead space proportionally
        let dead = (next_item_size - post_residual) as f64;
        score += dead.min(40.0) * 0.8;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Small leftovers are fragile; penalize tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early stream: be more conservative (favor tight fits), late stream: pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize very small dead space that only a tiny item could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Prefer leaving room compatible with the next item.
            let leftover = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - leftover / cap);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow.
            score += 0.15 * (nxt - post_residual as f64);
        }
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly so we
    // only open new bins when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Global residual pressure: when mean residual is large, prefer reusing
    // existing space; when mean residual is small, new bins are less costly.
    score += 0.05 * mean_residual * (1.0 - (post_residual as f64 / cap.max(1.0)));

    // Slight preference to fill bins with larger residual when many bins open.
    score += 0.02 * (bin_residual as f64 - post_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    let norm_next = next_item_size as f64 / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth stream-progress coupling: later in stream, penalize residual more strongly
    let progress_amp = 0.5 + 1.5 * t * t;
    score += progress_amp * pr * pr / cap;

    // Reward tight fits with smooth quartic of fill ratio
    score -= 12.0 * fill.powi(4);

    // Lookahead: reward leaving space usable by next item (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - norm_next * cap;
        let usable = if gap >= 0.0 { gap } else { 0.0 };
        score -= 3.0 * (usable / cap) * (1.0 - t);
        // Penalize exact-waste when next item cannot fit
        let miss = if gap < 0.0 { -gap / cap } else { 0.0 };
        score += 6.0 * miss * miss;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mean-residual deviation coupling (smooth)
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 - fill);

    // New-bin candidate: penalize opening a bin unless current bin would be very tight
    if bin_residual == bin_capacity {
        score = cap - 12.0 * fill.powi(4) + 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), but not perfectly-zero
    // dead space obsession — a small positive residue can host tiny items.
    let mut score = post;

    // Harmonic class of the post-residual: quantize residue into capacity
    // fractions (1/8 buckets). Residues in "awkward" classes (just above a
    // typical small-item size) get penalized; residues in "useful" classes
    // get rewarded.
    let bucket = (post_residual * 8 / bin_capacity.max(1)) as f64; // 0..8 integer class
    let bucket_frac = post as f64 / cap; // fractional fill of residue
    let class_center = (bucket + 0.5) / 8.0;
    let class_dev = (bucket_frac - class_center).abs();
    score += class_dev * 6.0;

    // Reward residues that are harmonic multiples of common item classes
    // (multiples of 10, 20, 25, 50 in 1..100 streams).
    let residue = post_residual;
    let harmonic_bonus = if residue == 0 {
        0.0 // closed bin is fine but no extra reward
    } else if residue % 50 == 0 || residue % 25 == 0 {
        -4.0
    } else if residue % 20 == 0 || residue % 10 == 0 {
        -2.5
    } else if residue % 5 == 0 {
        -1.0
    } else {
        0.5 // awkward non-harmonic residue
    };
    score += harmonic_bonus;

    // Integer-division threshold on next item fit: if the lookahead item
    // fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 8.0; // perfect two-item chain
            } else if next_post <= 10 {
                score -= 4.0;
            } else {
                score -= 2.0 * (1.0 - next_post as f64 / cap);
            }
        } else {
            // Next item cannot follow here: penalize proportionally to how
            // much residue would be stranded.
            score += 1.5 * (post / cap);
        }
    }

    // Last-chance bin dynamics: if this is the only fitting bin, avoid
    // forcing a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 + 2.0 * (1.0 - post / cap);
    }

    // New-bin candidate (empty bin): make it attractive only when the fit
    // would be near-perfect (item close to capacity) or when open bins are
    // all poor hosts.
    if bin_residual == bin_capacity {
        let fill = item / cap;
        // Empty-bin score anchored so it competes: high fill => low score.
        score = cap * (1.0 - fill) - 2.0 * fill;
        if open_bins_count == 0 {
            score -= 10.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size as f64 <= cap - item {
            score -= 1.5; // room for lookahead in fresh bin
        }
        return score;
    }

    // Phase of stream: late in the stream, tighten up (prefer closing bins).
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= phase * 2.0 * (1.0 - post / cap);

    // Slight pressure against spreading across many open bins.
    score += (open_bins_count as f64) * 0.05;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // "leftover" space — using it is good (harmonizes the bin set).
    let dev = (mean_residual - post).abs();
    score -= 0.3 * (1.0 / (1.0 + dev / 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    let util = item_size as f64 / bin_residual as f64;
    if util < 0.5 && bin_residual > 20 {
        score += (0.5 - util) * 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item cannot fit here but this bin is the last chance, force placement.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is low.
    if bin_residual < bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += pressure * 2.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fits = if fitting_bins_count > 0 { fitting_bins_count } else { 0 };
        // Count as poor if existing fitting bins would leave big dead space.
        let poor_fit = util < 0.6 && decent_fits > 0;
        if poor_fit || decent_fits == 0 {
            score -= 20.0;
        } else {
            // Prefer reusing an existing bin that fits reasonably well.
            score += 10.0 + (open_bins_count as f64) * 0.5;
        }
        // Late in the stream, opening a new bin is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits: reward small post_residual quadratically.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 40.0;

    // 2-step lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            // Perfect chain: item fills bin, next item fills remainder
            if slack == 0.0 {
                score -= 45.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap that is too small for the next item.
            let gap_waste = (nxt - pr) / cap;
            score += 25.0 * gap_waste;
        }
    }

    // Compare residual against mean residual across open bins: favor tighter-than-average bins.
    score += 8.0 * (mean_residual - bin_residual as f64) / cap;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
        // But if the fit is very poor (large post residual) and next item is large, allow new bin.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < 0.5 * (next_item_size as f64) {
            score -= 10.0; // still worth using this bin
        }
    }

    // Prefer using already-open bins over opening new ones.
    score += 12.0 * (open_bins_count as f64) / (open_bins_count as f64 + 5.0);

    // Early in the stream, be slightly more willing to open bins (build good structure);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let residual_frac = post_residual as f64 / bin_capacity as f64;

    // Reward high fill ratio: subtract proportional to how much of the bin we use.
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize dead space non-linearly: small post_residuals are fine, large ones waste.
    score += 12.0 * residual_frac * residual_frac;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * combo;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits in this bin now but would not after placement: mild penalty.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the fit
    // in existing bins is poor (large post_residual) or bins are heavily fragmented.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: high, but softened when many open bins exist
        // with large mean residual (fragmentation) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 + 0.35 * open_bins_count as f64;
        new_bin_cost -= 20.0 * progress;
        // If item is large, it fits well anywhere; new bin less necessary.
        new_bin_cost += 10.0 * (1.0 - fill_frac);
        score += new_bin_cost;
    } else {
        // Existing bin: small bonus for preferring already-open bins early on.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Coupling with global state: if this bin's residual is far below the mean,
    // it is a "small" bin best used for tight fits; encourage using it now.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Discard near-zero noise floor: exact fits are excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with smooth non-linear coupling
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Tightness: reward near-exact fills (post_residual close to 0)
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight * tight;

    // Smooth polynomial coupling of post_residual with item size
    let x = pr / cap;
    score += 8.0 * x * x * (1.0 - x) * (it / cap);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving residual too small for the next item (dead space)
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 4.0 * (1.0 - pr / cap);
    }

    // New-bin candidate handling: penalize opening a new bin, more so mid/late stream
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    // Mild pressure from many open bins with large residuals: encourage consolidation
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: fill bins as tightly as possible.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of the leftover: residual modulo 10 buckets.
    // Leftovers in {0, 10, 20, ...} are "harmonic" — likely to host
    // future items drawn from the same granularity class.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        // Odd/waste residues below the smallest item size are dead space.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Integer-division thresholds on post_residual: classify leftover slots.
    let slot_class = post_residual / 10; // 0..10
    // Mid-range leftovers (slots 2..6, i.e. 20..69) are the most reusable.
    if slot_class >= 2 && slot_class <= 6 {
        score -= 6.0;
    } else if slot_class > 6 {
        score += 4.0; // huge leftover means a poor fit happened
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // Bonus if next item harmonically matches leftover class.
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
            // Exact match of next item to leftover is gold.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; leftover risks becoming dead space.
            score += 6.0;
            if post_residual < next_item_size.min(10) {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // current item would leave a badly fragmented open-bin landscape.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it must beat genuinely bad placements.
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to co-load); later, prefer squeezing into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If many bins are already open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large, existing bins have room — discourage new bin.
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // But if this is the only fitting bin situation reversed (none fit well),
        // a new bin is fine: small item into fresh bin keeps residue harmonic.
        if item_size % 10 == 0 {
            score -= 8.0;
        }
    } else {
        // Placing into an existing bin: slight global reward scaled by
        // how fragmented the open-bin set already is.
        if open_bins_count > 4 {
            score -= 5.0;
        }
        // Tighten preference when mean residual is low (bins are filling).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0; // this bin is roomier than average; use it
        }
    }

    // Progress-aware tie-break: late in the stream, avoid leaving many
    // tiny residues across bins (compaction pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (post_residual < 10, or below
    // the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Mid-range dead space: gaps that are too small for typical items
    // (10..80 range scaled: treat < 15 as near-dead, 15..35 as risky).
    if post_residual >= 10 && post_residual < 35 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 25.0);
    }

    // Reward filling bins tightly relative to residual used.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if the item is large
    // relative to capacity (would leave big gaps elsewhere) or no good fits.
    if bin_residual == bin_capacity {
        // Base new-bin cost, modulated by open-bin pressure.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If item nearly fills the new bin, opening is cheap.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 45.0;
        }
        // Late in the stream, opening fresh bins is riskier.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If the next item would fit in the fresh residual, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild pressure to consolidate into fewer bins.
        score -= 0.5 * open_bins_count as f64;
        // Prefer bins with below-mean residual (tighter bins first).
        score -= (mean_residual - bin_residual as f64) * 0.3;
        // Lookahead: if next item fits exactly in the resulting residual,
        // bonus; if next item is bigger than post_residual, slight penalty.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 20.0;
            } else if next_item_size > post_residual {
                score += 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits snugly after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }
    // Penalize post-residual too small for next item (dead space).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.4;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Discourage opening a new bin when decent existing options exist.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // Allow new bin if item is large and fits poorly anywhere.
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Late in stream: be more frugal with bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    score += 0.35 * post_residual as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is wasteful if a decent fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin when open bins exist.
        if open_bins_count > 0 {
            score += 15.0;
            // If another bin fits nearly perfectly, discourage new bin more.
            if fitting_bins_count > 1 && post_residual < 15 {
                score += 20.0;
            }
        }
        // Late in the stream, opening new bins is more acceptable (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // Small item into a fresh bin wastes capacity; penalize.
        if item_size < bin_capacity / 4 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // Perfect pair: post_residual == next_item_size exactly.
            if post_residual as u32 == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space that the next item cannot use.
            let waste = post_residual as f64 - (next_item_size as f64 % bin_capacity as f64);
            score += 0.15 * waste.max(0.0);
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }
    // Prefer bins whose residual is below the mean (tighter bins get filled first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild time decay: early in stream, keep bins flexible (avoid tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: tight fit reward, polynomial in post_residual.
    let mut score = post * post / cap - 0.8 * post;

    // Smooth stream-progress coupling: later in stream, tolerate slightly larger residuals less.
    let progress_coupling = progress * (post / cap) * (post / cap) * 12.0;
    score += progress_coupling;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next > 0.0 {
        let gap = post - next;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 0.02 * (-gap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins moderately; reduce penalty when mean residual is low
        // (open bins are full) or many bins already open.
        score += 10.0 + 0.15 * mean_residual - 0.5 * (open_bins_count as f64);
        // Late in stream, opening fresh bins is cheaper than dead space.
        score -= 8.0 * progress * (1.0 - mean_residual / cap);
    } else {
        // Prefer bins whose residual is closest to item (tight packing).
        let tightness = 1.0 - (bin_residual as f64 - item) / cap;
        score -= 4.0 * tightness * tightness;
        // Slight preference for bins below mean residual (balance).
        score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    // Mild penalty for large dead space relative to smallest plausible item.
    if post > 0.0 && post < 10.0 {
        score += 3.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets.
    // Residuals that are "harmonically useful" (multiples of 10, or large
    // enough to accept common item classes) should be favored.
    let post = post_residual;
    let harmonic_class = (post % 10) as f64;

    // Penalize awkward residuals (not multiple of 10) mildly.
    if post > 0 {
        score += harmonic_class * 0.35;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Dead-space penalty: residuals too small to hold even the smallest
    // possible item (1) are fine at 0, but tiny unusable slivers hurt.
    // With sizes in [1,100], residual < 1 is impossible; residual 1..3
    // is nearly dead space for typical distributions.
    if post > 0 && post < 4 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0; // perfect chaining
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            // reward proportional fit, penalize large slack after next item
            score -= 20.0;
            score += slack * 0.25;
            // harmonic bonus if post - next is a multiple of 10
            if (post - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here: mild penalty if this bin becomes
            // a stranded sliver
            if post < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // would leave open bins badly fragmented, or when many bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Slight bias toward reusing existing bins by default.
        score += 30.0;
        // But if the item is huge and few fitting bins exist, allow new bin.
        if large_item > 0.6 && fitting_bins_count <= 2 {
            score -= 40.0 * large_item;
        }
        // Late in stream with many open bins, prefer consolidation instead.
        if progress > 0.7 && open_bins_count > 4 {
            score += 20.0;
        }
        // If mean residual across bins is small, reusing is cheap; keep new bin penalized.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Tightness reward: prefer bins where the item fills a large fraction
        // of the residual (best-fit flavor).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 30.0;

        // Harmonic integer-division threshold: residual divided into item
        // classes (capacity/4 blocks). Residuals in the same quarter-class
        // as the item fit harmonically.
        let quarter = bin_capacity / 4;
        if bin_residual / quarter == item_size / quarter {
            score -= 6.0;
        }

        // Prefer bins with residual close to but >= item (small waste).
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space zone: gaps that are too small for the smallest plausible item (1..10)
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // up to +60 for near-zero useless gaps
        } else if gap < 20.0 {
            score += 15.0 * (20.0 - gap) / 10.0; // mild penalty for awkward mid gaps
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to residual (high fill ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Open-bins pressure: with many open bins, prefer packing into existing ones
    // over leaving residuals scattered; penalize spread.
    let obp = open_bins_count as f64;
    score += 0.6 * obp * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual as f64 > 0.35 * bin_capacity as f64 {
            score += 20.0; // still bad to waste >35% of a bin
        }
    }

    // New-bin candidate handling: an empty bin is attractive when the current bin
    // would leave a bad gap, or when the next item could use this bin's leftover.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin; decreases as stream progresses
        // (fewer future chances to amortize) and with open-bin pressure.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.5 + 25.0 * (1.0 - progress) + 0.8 * obp;

        // If placing here would create dead space that the next item cannot use,
        // opening a fresh bin becomes more attractive.
        if next_item_size > 0 {
            let next_fits_gap = (post_residual as f64) >= next_item_size as f64;
            if !next_fits_gap && post_residual > 0 {
                score -= 35.0; // open new bin rather than strand the gap
            }
            // If the next item would exactly consume this bin's post residual,
            // keep the item here (chain fit) -> make new bin unattractive.
            if post_residual == next_item_size {
                score += 80.0;
            }
        }
        // If mean residual across open bins is high, packing is going poorly;
        // opening a fresh bin is relatively better.
        if mean_residual > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    } else {
        // Chain-fit reward: leaving exactly the next item's size is excellent.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving a gap the next item can't use but that's mid-sized.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual >= 10 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual), scaled by capacity.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Aggressive 2-step lookahead: reward when post_residual exactly or nearly fits next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect chain: this bin becomes exactly the right size for the next item.
            score -= 45.0;
        } else if diff > 0 {
            // Next item fits in leftover: reward proportional to closeness.
            let closeness = 1.0 - (diff as f64 / bin_capacity as f64);
            score -= 30.0 * closeness;
        } else {
            // Leftover too small for next item: penalize dead space magnitude.
            score += (-diff as f64) * 0.35;
        }
    } else {
        // Last item: only tightness matters; strongly reward minimal post_residual.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.4;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // placing here wastes little. Penalize placing into already-loose bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item nearly fills a bin or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline; discourage unless item is large
        // relative to capacity (avoids fragmenting small items into new bins).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 40.0 * fill_ratio;
        if next_item_size > 0 {
            // A fresh bin is good if next item pairs well with the leftover.
            let leftover = bin_capacity - item_size;
            if next_item_size <= leftover {
                score -= 15.0 * (1.0 - (leftover - next_item_size) as f64 / bin_capacity as f64);
            }
        }
        // Early in stream, opening bins is cheaper (more future use).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for too many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear weighting.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: fill as much as possible.
        score -= 20.0 * tight;
    }

    // Last-chance bin: strongly reward using it before opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * fill_ratio;
    }

    // Penalize wasting a nearly-empty unique fitting bin on a small item late in stream.
    if fitting_bins_count == 1 && !is_new_bin && fill_ratio < 0.25 && progress < 0.5 {
        score += 5.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // item is large (poor fit likely elsewhere) or many bins already fit the item.
    if is_new_bin {
        let open_cost = 30.0 - 20.0 * fill_ratio; // large items cheap to open for
        let crowd_bonus = if fitting_bins_count > 1 { 8.0 + 2.0 * fitting_bins_count as f64 } else { 0.0 };
        score += open_cost + crowd_bonus - 10.0 * progress * fill_ratio;
    } else {
        // Reward placing into bins whose residual deviates from the mean (consolidate).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
        // Slight preference for reusing bins when many are open (reduce bin count pressure).
        score -= 0.02 * open_bins_count as f64;
    }

    // Time-horizon modulation: early stream, be conservative with tight fits
    // (save them); late stream, pack aggressively.
    score += 8.0 * (1.0 - progress) * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    // Late in the stream, tight fits (small post_residual) matter more, so we
    // amplify the reward for small post_residual via a quadratic term.
    let mut score = pr
        - 40.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr)
        + 20.0 * (1.0 - progress) * norm_pr * norm_pr;

    // Penalty when the leftover is unusably small (dead space) - smooth cubic ramp.
    let dead = 1.0 - (pr / 10.0).min(1.0);
    score += 30.0 * dead * dead * dead;

    // Lookahead coupling: reward leaving space that the next item can use,
    // penalize leftovers that are just barely too small for next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // Mild pressure proportional to number of alternatives, smoothed.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets a smooth premium that decays
    // as the stream progresses, so late items prefer filling existing bins.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (open_bins_count as f64).ln().max(0.0));
        score += 60.0 * (1.0 - progress) * openness;
    } else {
        // Slight preference for bins tighter than the mean residual (smooth).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of capacity left after placement.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - frac) * (1.0 - frac);

    // Harmonic class logic: classify post_residual into dead-space bands
    // using integer division on capacity fractions. Residuals below the
    // minimum plausible item size are dead space -> penalize heavily.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold {
        score += 60.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common size classes (e.g. divisible by 10 or 20) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward if next item nearly fills remaining space
            let nfrac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nfrac * nfrac;
        } else {
            score += 20.0;
            // integer-division threshold: post_residual / next_item_size class
            let div = post_residual / next_item_size.max(1);
            if div == 0 {
                score += 10.0; // next item cannot use this residual at all
            }
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // would create bad fits. Penalize opening a new bin, more so when many
    // bins are open or mean residual is large.
    if bin_residual == bin_capacity {
        score += 45.0 + 5.0 * (open_bins_count as f64).sqrt();
        if mean_residual > 30.0 {
            score += 15.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Prefer filling already-open bins; slight bias toward emptier bins
        // when residuals are scarce.
        if mean_residual < 15.0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to item size (best-fit core),
    // scaled by harmonic distance.
    let dist = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * dist;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: gaps too small to hold even the smallest plausible
    // future item are wasted. Penalize small non-zero residuals nonlinearly.
    let min_useful = 1u32.max(next_item_size.min(bin_capacity));
    if post_residual > 0 && post_residual < min_useful {
        // Unusable sliver: heavy penalty proportional to wasted fraction.
        score += (min_useful - post_residual) as f64 * 3.0;
    }

    // Moderate gaps (hard to fill later) get a softer penalty.
    if post_residual > 0 && post_residual < bin_capacity / 3 {
        score += (bin_capacity as f64 / 3.0 - post_residual as f64) * 0.5;
    }

    // Reward residual that still accommodates the lookahead item (keeps options open).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual can't fit lookahead: mild penalty.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: discourage proliferation of many open bins with
    // scattered residuals; a new empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin, scaled by
        // how many bins are already open.
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        // Existing bins get a small bonus, stronger when many bins are open.
        score -= 3.0 + open_bins_count as f64 * 0.5;
    }

    // Early in the stream, be slightly more willing to open bins (build diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Nudge toward bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits: reward low post_residual relative to mean residual.
    score -= 0.35 * (mean_residual - post_residual as f64).max(0.0);

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Reward leaving room for the next item, scaled by closeness of fit.
            let gap = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // Dead space: next item cannot fit in the leftover; penalize proportionally.
            let waste = next_item_size - post_residual;
            score += 0.9 * waste as f64;
        }
    }

    // Penalize creating tiny unusable residuals (dead space below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins by default.
        score += 8.0;
        // But if next item is large and current bins are fragmented, new bin is fine.
        if next_item_size as f64 > mean_residual {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty when many bins are already open (encourage packing density).
    score += 0.15 * open_bins_count as f64;

    // Early stream: be slightly more willing to keep bins tight for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space), non-linearly.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score += 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: reward if next item fits in post_residual (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use: penalize proportionally.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // and the item is large (fewer future chances to place it).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score = 0.55 * bin_capacity as f64
            + 40.0 * mean_fit_gap
            + 25.0 * large_item_bonus
            - 20.0 * progress
            - 2.0 * open_bins_count as f64;
        // If no open bin can fit at all, opening is clearly necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild penalty for leaving awkward mid-range residuals (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64 / cap); // how full the bin becomes

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = (fill * fill * (3.0 - 2.0 * fill)).clamp(0.0, 1.0); // smoothstep
    score -= 18.0 * tightness * (0.5 + progress);

    // Penalize post-residuals that are small-but-unusable relative to typical item scale.
    let dead = (post_residual as f64) * (post_residual as f64) / (cap * cap);
    score += 8.0 * dead * (1.0 - tightness);

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let compat = 1.0 / (1.0 + gap / cap);
        score -= 12.0 * compat;
    } else {
        // End of stream: closing bins tightly is more valuable.
        score -= 6.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean-residual coupling: when open bins are collectively loose, prefer
    // placements that tighten the distribution (avoid fragmenting many bins).
    let mean_gap = (mean_residual - post_residual as f64) / cap;
    score += 5.0 * mean_gap * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity (smooth ramp, no piecewise constant).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 10.0 * (1.0 - size_frac * size_frac);
        // But early in the stream, having few bins makes opening cheaper.
        score -= 4.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-tightness obsession
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: modulo-10 classes behave differently.
    // Residuals in [1..9] are "dead space" classes unless a future item of that class exists.
    let pr = post_residual;
    let dead_class = pr > 0 && pr < 10;
    if dead_class {
        score += 25.0; // penalize creating sub-10 dead space
    }

    // Lookahead coupling: reward if next item exactly fits or fits with tiny slack
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 30.0; // near-perfect chain
            } else {
                score -= (pr - next_item_size) as f64 * 0.15; // mild reward
            }
        } else {
            // next item cannot use this residual; residual class matters more
            score += 5.0;
        }
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    if pr >= half {
        score += 10.0; // leaving half a bin is wasteful when smaller fits exist
    } else if pr >= quarter {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins with high mean residual: encourage consolidation into fuller bins
    if open_bins_count > 3 && (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate handling: it must only win when fits are terrible.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: slightly above a good fit, below a bad fit.
        score = bin_capacity as f64 * 0.9; // 90
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // if next item is big, fresh bin slightly more attractive
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits otherwise: must open new bin
        }
        if dead_class_fallback(item_size, bin_capacity) {
            score -= 10.0;
        }
    }

    // Late-stream tiebreak: close out bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 {
        score += pr as f64 * 0.5; // penalize leaving residual late
    }

    score
}

fn dead_class_fallback(item_size: u32, bin_capacity: u32) -> bool {
    // Large items (>= 3/4 capacity) pair poorly with existing bins; fresh bin ok
    item_size * 4 >= bin_capacity * 3
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (but nonzero) are the worst outcome. Treat "almost full" as good.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0; // hard-to-fill gap
    }

    // Reward tight fits strongly (post_residual already low, add bonus).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open,
    // encourage opening a new bin when few are open and fit would be poor.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize leaving a medium gap slightly more
            score += 3.0;
        }
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline with
    // mild penalty so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_pressure;
        // If no existing bin fits, the new bin call is the only candidate anyway;
        // if fits exist but are poor (high dead space), this stays competitive.
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 5.0; // room for lookahead in fresh bin
        }
    }

    // Progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Perfect two-item closure: huge reward
        if post_residual == next_item_size {
            score -= 150.0;
        }
        // Next item fits exactly with zero waste after pairing
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 40.0;
        }
    }

    // Penalize dead space relative to mean residual: creating much smaller-than-average residual
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score += 0.8 * (mean_residual - post_f);
    } else {
        score -= 0.3 * (post_f - mean_residual);
    }

    // Penalize very small unusable residuals (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }
    // Reward full closure
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bins are quite full
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin early in stream or when mean residual is small (bins nearly full)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        if mean_residual < 25.0 {
            score -= 60.0;
        }
    }

    // Mild tight-fit reward: prefer bins where item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }
    // Penalize leaving a gap that exactly nothing useful can follow (small dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should generally lose to decent fits,
    // but win when fits are very loose or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else if post_residual as f64 > mean_residual * 0.5 && next_item_size > post_residual {
            score -= 10.0; // open bins would waste too much; fresh bin is fine
        }
    }

    // Progress-based pressure: late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Prefer filling bins that are already relatively empty (balance residuals)
    // so very full bins stay available for tiny future items.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fit preferred (small post residual)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // early stream -> tolerate larger residuals less strictly, late stream -> pack tight
    let tightness = 1.0 + progress * progress * 2.0;
    score *= tightness;

    // Smooth quadratic penalty on normalized residual, modulated by progress
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward bins that are already well-utilized (small residual before placement)
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= fill_ratio * fill_ratio * 8.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalty for opening a new bin when open bins exist and fit
    let is_new_bin = bin_residual == bin_capacity && open_bins_count > 0;
    if is_new_bin {
        // Smooth penalty: cheaper to open a new bin when post-residual of this
        // item in a new bin is small (item large) and mean residuals are large
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        let openness = (mean_frac - item_frac).max(0.0);
        score += 40.0 - 35.0 * openness * openness - 20.0 * item_frac * item_frac;
        // Late in the stream, prefer consolidating into open bins
        score += 15.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post residual, reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 - diff / cap;
        if fit_quality > 0.0 {
            score -= fit_quality * fit_quality * 12.0;
        }
        // Penalize leaving residual just below next item (dead space)
        if pr > 0.0 && pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: residual divisible by 10 leaves reusable harmonic classes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.05 * slack;
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space below smallest class
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate penalty: prefer existing bins unless current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 15.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            penalty = 0.0;
        } else if fitting_bins_count == 1 {
            penalty -= 10.0;
        }
        // Large items relative to capacity are fine to start fresh bins for.
        if item_size * 2 >= bin_capacity {
            penalty -= 5.0;
        }
        // If mean residual across open bins is small, opening a bin is less wasteful.
        penalty -= (mean_residual / bin_capacity as f64) * 5.0;
        score += penalty.max(0.0);
    }

    // Mild normalization: compare against mean residual to break ties toward balance.
    score += 0.02 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps (< 10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score += open_bins_count as f64 * 6.0 + progress * 20.0;
    } else {
        score -= open_bins_count as f64 * 1.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (concentrate filling), penalize dipping into fat bins for small items.
    if (bin_residual as f64) > mean_residual && item_size < 40 {
        score += 6.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // creates a gap the next item can't use
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little waste
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small unusable dead space (unless it matches next item)
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 20.0;
    }

    // Reward bins tighter than the mean residual (better fits)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = fitting_bins_count as f64;
        // Prefer new bin when many bins fit (good spread) or item is large
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * item_frac - 10.0 * pressure * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
    }

    // Mild tie-breaking toward tighter existing bins
    score += (bin_capacity as f64 - residual_f) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving small, hard-to-use dead space (residual in [1..15] is wasteful,
    // unless the lookahead item can use it).
    if post_residual > 0 && post_residual < 15 {
        let usable_by_next = next_item_size > 0 && next_item_size <= post_residual;
        if !usable_by_next {
            score += 12.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // Extra reward if the next item exactly consumes the leftover.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && next_item_size > bin_capacity {
        // Next item can't fit anywhere anyway; ignore lookahead penalty.
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate logic: an empty bin should only win when the current fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 20.0;
        // Opening a bin is more attractive early in the stream (more future items to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Attractive if the item is huge relative to capacity (few bins can pair it later)
        // or if no tight fit exists elsewhere.
        if fill_ratio < 0.5 {
            score += 15.0;
        }
        // If many bins are open with slack, discourage proliferation.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Mild preference for reusing bins that are already fairly full (best-fit flavor).
        let used_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * used_ratio;
    }

    // Global balance: prefer bins whose residual is below the mean (concentrate slack),
    // spreading large residuals into fewer, more usable bins.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Endgame: near the end of the stream, tight fits matter most; new bins are costly.
    if total_items > 0 && step_index + 2 >= total_items {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    // Base: reward tight fits (low post_residual), non-linearly.
    let mut score = (pr / cap).powi(2) * cap;

    // Smooth coupling: post_residual scaled by stream progress — later in stream,
    // dead space matters more (fewer future chances to fill it).
    score += (pr / cap).powi(3) * cap * (0.5 + progress);

    // Interaction: post_residual vs next item size — reward residuals that
    // leave room for the upcoming item (smooth quadratic proximity).
    let gap = (pr - next_ratio * cap).abs() / cap;
    score -= (1.0 - gap).max(0.0).powi(2) * 8.0;

    // Penalize very small unusable residuals smoothly (dead space).
    let dead = (10.0 - pr.min(10.0)) / 10.0;
    score += dead.powi(2) * 12.0;

    // Last-chance bonus: only one fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Mild penalty for opening new bins late in stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins already below mean residual (consolidation).
        score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.05;
    }

    // Small fit-quality term: bigger items in tighter bins preferred.
    score -= fit_ratio * pr * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes based on integer division
    // Items 1..=100, capacity 100. Post-residual buckets define "usability" of leftover.
    let post = post_residual;
    let harmonic_class = post / 10; // 0..=10 harmonic bucket

    // Penalize dead space that likely cannot be filled:
    // leftover in (0..10) is nearly unusable -> heavy penalty
    if post > 0 && post < 10 {
        score += 40.0;
    }
    // Harmonic class weighting: mid-range leftovers are moderately valuable
    score += harmonic_class as f64 * 0.5;

    // Reward near-perfect fits (small but usable leftover)
    if post == 0 {
        score -= 100.0; // perfect fit is ideal
    } else if post <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 60.0;
        } else if next_item_size < post {
            let gap = post - next_item_size;
            // reward proportionally to how well next item nests
            score -= (20.0 * (1.0 - gap as f64 / 100.0)).max(0.0);
            // penalize if next item would leave another dead sliver
            if gap < 10 && gap > 0 {
                score += 10.0;
            }
        } else {
            // next item cannot fit here; leftover should stay large/flexible
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins -> prefer consolidation, penalize spreading
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.3;
    }

    // Mean residual coupling: bins far below mean residual are "wasted" capacity;
    // prefer bins whose residual is close to item_size (tight fit relative to fleet)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // Modulo-based harmonic coupling on post_residual:
    // leftovers divisible by common item sizes (10, 20, 25, 50) are more reusable
    if post % 10 == 0 && post > 0 {
        score -= 6.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 4.0;
    }
    if post % 50 == 0 && post > 0 {
        score -= 4.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    // Make it attractive only when current fit is poor (large post_residual dead space
    // or item barely fits leaving unusable sliver), otherwise discourage.
    if bin_residual == bin_capacity {
        let poor_fit = post < 10 && post > 0
            || (next_item_size > 0 && next_item_size > post && post > 0 && post < 20)
            || bin_residual < item_size * 2 && item_size > 70;
        if poor_fit {
            score -= 30.0;
        } else {
            // default: prefer existing bins
            score += 20.0 + 0.1 * (open_bins_count as f64);
        }
    }

    // Stream progression: early in stream, keep bins flexible (favor larger leftovers slightly)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += post as f64 * 0.05; // early: flexibility matters less, still prefer tight
    } else {
        score += post as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap that cannot fit even the smallest plausible item is "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // awkward gap, hard to fill
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill, strongly rewarded
    }

    // Reward tight fits: item consuming a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoiding wasted capacity elsewhere).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * (1.0 - progress));
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure and remaining stream.
        score += 30.0 + pressure * 2.0;
        // But if no open bin fits well (large dead space elsewhere), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Using an existing bin relieves pressure slightly.
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's remainder; slightly penalize leaving a gap
        // that is close-but-unusable for the lookahead item.
        let gap = post_residual as f64;
        if gap >= next_item_size as f64 * 0.7 && gap < next_item_size as f64 {
            score += 15.0;
        }
    }

    // Mean residual coupling: prefer placing into bins with below-average residual
    // (concentrate emptiness into few bins, keeping others tighter).
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-item closure
        } else if post_residual >= next_item_size {
            // next item still fits: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.15;
        } else {
            // dead space the next item cannot use: penalize small leftovers
            let waste = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 15.0; // tiny unusable remnant
            } else {
                score += waste * 0.05;
            }
        }
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (keeps big-capacity bins free for large items).
    score += 0.10 * (mean_residual - bin_residual as f64).max(0.0) - 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish score so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (1.0 + 0.5 * progress) - 5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin supports clean 2-item packing
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit. Squared dead-space penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Reward if the lookahead item fits into the post residual (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    }
    // Penalize leaving a gap that the next item almost-but-doesn't fit (wasted chain).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins with slack: encourage consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += mean_residual * 0.05 * (1.0 - progress);
    }

    // Late in the stream: avoid opening new bins; squeeze into existing ones.
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // New-bin candidate: make it unattractive unless no decent alternative exists.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Early stream: opening a bin is cheaper.
        score -= 40.0 * (1.0 - progress);
        // If many bins already open and mean residual is high, definitely avoid new bin.
        score += mean_residual * 0.1;
    }

    // Prefer bins whose residual is close to item_size (near-perfect fills).
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs();
    score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Tight fit reward: strongly favor bins whose post residual is small,
    // with a smooth non-linear (quartic-ish) coupling.
    let tight = (1.0 - post_frac).powi(4);
    score -= 30.0 * tight;

    // Penalize dead space: post residual too small to ever fit another item
    // (min item size 1, but small slivers are still wasteful) — smooth penalty
    // that grows as post residual shrinks toward unusable sliver sizes.
    let sliver = if post_frac < 0.1 { (0.1 - post_frac) / 0.1 } else { 0.0 };
    score += 12.0 * sliver * sliver;

    // Reward filling a bin nearly exactly (post_residual == 0 ideal).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * (1.0 - gap).powi(2);
    } else if next_item_size > post_residual {
        // Next item won't fit here; mild penalty scaled by how far off it is.
        let miss = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 8.0 * miss.min(1.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    // Prefer it only when the item is large relative to capacity or late in
    // the stream, otherwise penalize so existing bins get used.
    if bin_residual == bin_capacity {
        let large_item = item_frac.powi(2);
        score += 15.0 * (1.0 - large_item) * (1.0 - 0.5 * progress);
        // If no open bin really fits well (large post residuals everywhere),
        // opening a fresh bin is attractive — smooth coupling with mean_residual.
        let mean_frac = mean_residual / bin_capacity as f64;
        score -= 10.0 * mean_frac * mean_frac;
        // Early stream with few bins: encourage opening bins to build a pool.
        score -= 5.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / 10.0).max(0.0);
    } else {
        // Mild preference for bins with smaller residual (better packing),
        // smoothly coupled with stream progress.
        score += 6.0 * residual_frac * (0.5 + 0.5 * progress);
    }

    // Global pressure: as stream progresses, push toward tighter packing
    // via a smooth polynomial in progress.
    score -= 4.0 * progress * (1.0 - post_frac).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" modular classes (multiples of small sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Class A: leftover divisible by 10 -> still highly reusable
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Class B: leftover divisible by 5 -> moderately reusable
        else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Class C: leftover in awkward band (1..=9 non-divisible) -> dead space risk
        if pr < 10 {
            score += 25.0;
        }
    }

    // Perfect fit: zero waste is always best.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: the smaller the leftover fraction, the better (best-fit core),
    // scaled nonlinearly.
    let tight = (post_residual as f64) / cap;
    score += 20.0 * tight * tight;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item can exactly consume the post residual,
    // this placement is harmonically ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward, scaled by how well it splits
            let r = post_residual % next_item_size.max(1);
            score -= 8.0 - (r as f64) * 0.1;
        } else {
            // next item cannot use the leftover: penalize large unusable leftovers
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // New-bin candidate (empty bin): baseline score so it wins only when all open
    // bins have poor fits (large scores from dead-space penalties).
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        // open fewer new bins when existing bins are on average roomy
        score += mean_residual * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin is attractive if next item is large (likely needs fresh space)
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Slight preference to fill bins with more items already (fewer open bins is better)
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty: dead space that no future item (min size 1) can fill usefully.
    // Gaps in (0, threshold) are "unusable slivers" depending on stream progress.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize small-but-nonzero gaps quadratically,
    // scaled by how "late" in the stream we are (less chance to reuse them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (2.0 + 8.0 * progress);
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer using existing bins when many are open,
    // making new bins less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well (last chance), new bin is fine.
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if post residual is smaller than next item but nonzero (blocks chaining).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Mean residual coupling: bins far from the mean residual get a nudge
    // toward homogenization of residual sizes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest plausible item.
        let dead_penalty = (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        score += dead_penalty;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: next item exactly fills this bin.
            score -= 800.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward proportional closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty scaled by overflow gap.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Compare post_residual to mean residual: favor leaving residual near average
    // (balanced packing), penalize leaving much less than mean (wasteful tightness
    // when unnecessary) or much more (poor fill).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: its residual is full capacity.
        // Penalize opening new bins when decent fits exist.
        if fitting_bins_count > 0 && next_item_size > 0 {
            score += 120.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Slight preference for bins already partially filled when many bins are open
    // (encourage consolidation).
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space that nothing (min size 1..) can reuse well,
    // but tiny residuals (<10) are effectively closed bins — mildly OK.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; leaving large gap is wasteful.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is costly; make empty bin
    // attractive only when current bins would leave bad fits.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let waste_if_placed_here = (bin_capacity - item_size) as f64;
        let best_open_waste = (bin_residual - item_size) as f64; // this call is the empty bin
        let _ = best_open_waste;
        // Base cost of a fresh bin, discounted late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 18.0 + waste_if_placed_here * 0.15;
        new_bin_cost *= 1.0 - 0.3 * progress;
        // If many open bins, opening more spreads residuals; penalize.
        new_bin_cost += open_bins_count as f64 * 1.5;
        score += new_bin_cost * (1.0 - open_pressure * 0.5);
        // If no bin fits, empty bin must win: remove penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Prefer bins with residual close to mean (balance load) slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild preference for fuller bins globally.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with smooth polynomial modulation by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: penalize mid-range residuals more as stream advances
    // (dead space becomes costlier late in the stream).
    let mid = (norm_pr * (1.0 - norm_pr) * 4.0).max(0.0);
    score += 30.0 * mid * mid * progress;

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score += 5.0 * norm_pr * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - item_size as f64 / cap);
        // Late in stream, reuse bins more aggressively.
        score += 10.0 * progress;
    }

    // Mild diversity penalty: avoid concentrating residual variance.
    score += 0.5 * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "reusable" classes (multiples of small denominators of capacity) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class-1: residual that can exactly hold common future sizes (multiples of 10/20/25).
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space: small but nonzero residuals are nearly useless (items >= 10 in classic,
    // but sizes 1..100 unknown, so weight by relative deadness).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Harmonic coupling with next item: does post_residual exactly admit next_item_size?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let gap = pr - n;
            if (gap as u32) % 10 == 0 || gap == 0.0 {
                score -= 8.0; // next item also fits harmonically
            } else {
                score -= 2.0;
            }
            // Bonus when next item exactly fills the bin afterwards.
            if gap == 0.0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here; penalize less if residual is still reusable class.
            if reusable {
                score += 1.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Cheaper to open a new bin early in the stream (more future value in fresh space).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins are open and mean residual is fragmented, opening fresh is more attractive.
        score -= (open_bins_count as f64).min(10.0) * 0.8;
        score += (mean_residual - cap * 0.5).max(0.0) * 0.05;
        // Perfect fit is never beaten by a new bin.
        if post_residual == 0 {
            score += 100.0;
        }
        if fitting_bins_count == 1 {
            score += 60.0; // never open when this is the only fitting bin
        }
    }

    // Slight preference for tighter existing bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to ever be usable
    // (below the typical minimum item size) are heavily penalized, but
    // exact zero is already handled above.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Penalize moderately small gaps that likely become dead space
    // (unusable for most items), scaled by how tight the gap is.
    if post_residual > 0 && post_residual <= 30 {
        score += (31 - post_residual) as f64 * 3.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // Lookahead dead space: post-residual positive but smaller than next item
    // while next item would otherwise fit here — mild penalty for stranding.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_residual {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        // Undo dead-space penalty partially when there is no alternative.
        if post_residual > 0 && post_residual < 10 {
            score -= 150.0;
        }
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    // The new-bin candidate has bin_residual == bin_capacity; make it
    // attractive only when open bins are scarce or fit would be poor.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 12.0;
        if post_residual > 0 && post_residual < 10 {
            score += 300.0; // opening a bin for a tiny-gap item is wasteful
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: new bin is fine
        }
    }

    // Prefer filling bins that are already relatively full (low residual
    // before placement) — best-fit flavor with mean-residual coupling.
    score += (bin_residual as f64 - mean_residual).max(-50.0) * 0.8;

    // Slight stream-progression dampening: early on, be a bit more open
    // to new bins (uncertain future), late on, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if post >= nxt {
            // Perfect match: next item fills bin completely -> huge reward.
            if diff < 0.5 {
                score -= 200.0;
            } else {
                score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item cannot fit here; penalize leftover dead space, more for small leftovers.
            let waste = nxt - post;
            score += 0.6 * waste;
        }
        // Slight bonus if post residual is small and unusable anyway (tight fit now).
        if post < 10.0 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from mean.
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (post - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin if item leaves large awkward residual in existing bins.
        if post_residual >= 60 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to hold even the next item,
    // but only when the leftover is genuinely unusable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (post_residual as f64);
    }

    // Reward saving room for the lookahead item: if next item fits in post
    // residual, this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 10.0 * (1.0 - (chain_waste as f64) / (bin_capacity as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is badly fragmented.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // If existing bins have plenty of room on average, discourage new bin.
        let room = avg_open - item_size as f64;
        if room > 20.0 {
            score += 30.0 + 0.3 * room;
        } else {
            score += 8.0;
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for filling bins that are already partially used
    // when many bins are open (consolidation pressure).
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));
    }

    // Penalize placements leaving exactly awkward mid-range residuals
    // (hard to fill later with typical item sizes).
    let pr = post_residual;
    if pr >= 1 && pr <= 9 {
        score += 4.0;
    } else if pr >= 51 && pr <= 60 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling: penalize mid-range residuals more at low progress,
    // reward tight fits (small pr) increasingly as stream progresses.
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 30.0 * quad * (1.0 - progress);
    score -= 40.0 * cube * progress;

    // Interaction of post_residual with mean residual: prefer bins whose residual
    // deviates from the mean (keeps diversity of gap sizes).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev.abs() * (1.0 - progress);

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 35.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, more when many
    // bins could fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * (fitting_bins_count as f64).sqrt() * (1.0 - progress);
    }

    // Slight preference for filling fuller bins (small residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: penalize residuals that are "awkward"
    // classes (small, hard-to-fill leftovers), reward classes that pair well
    // with common item sizes.
    let pr = post_residual;
    let quarter = bin_capacity / 4;      // 25
    let tenth = bin_capacity / 10;       // 10
    let half = bin_capacity / 2;         // 50

    // Dead space: residual too small to ever be useful (< 10)
    if pr > 0 && pr < tenth {
        score += 60.0;
    }

    // Residual exactly on a harmonic grid point (divisible by 10 or 25)
    // is more reusable.
    if pr % tenth == 0 {
        score -= 8.0;
    }
    if pr % quarter == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward leaving room for the next item, scaled by how snugly it fits
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - 0.1 * slack;
        } else {
            // Penalize blocking the next item
            score += 15.0;
        }
        // Harmonic pairing: next item exactly divides remaining space
        if pr > 0 && next_item_size > 0 && pr % next_item_size == 0 && pr > next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins have very tight residuals and the item is large.
    if bin_residual == bin_capacity {
        let tight = mean_residual < (item_size as f64 + 5.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        if tight && item_frac > 0.6 {
            score -= 30.0;
        } else {
            // Prefer reusing an open bin in general
            score += 25.0;
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual - pr as f64).signum();

    // Mild penalty proportional to waste relative to capacity
    score += 0.3 * (pr as f64 / bin_capacity as f64) * (pr as f64 / bin_capacity as f64) * 20.0;

    // Prefer bins whose residual is close to the item (snug fit)
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, the min item size)
    // are worthless; anything below ~20 is likely dead. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits: exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit detection against the lookahead item: leaving exactly
    // next_item_size keeps the bin fully usable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that can't fit the next item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, allow it more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.5;

    // New-bin candidate: neutral-ish baseline, but attractive when the mean
    // residual across open bins is too small to be useful.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 50.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size >= item_size && mean_residual < next_item_size as f64 {
            score -= 10.0; // big next item, little room anywhere
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit)
    // relative to mean residual dispersion.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (2-step lookahead perfect fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.25;
    }
    // Penalize if post_residual is small but nonzero and next item can't use it (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // Penalize creating tiny unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive if open bins are scarce or fit is perfect for lookahead
    if bin_residual == bin_capacity {
        let perfect = next_item_size > 0 && post_residual == next_item_size;
        if perfect {
            score -= 30.0;
        } else if open_bins_count == 0 {
            score -= 10.0;
        } else if fitting_bins_count == 1 {
            score -= 2.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 1.5;
        }
    }

    // Mild preference to fill fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (item_size as f64 / bin_capacity as f64) * (5.0 + 5.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Reward filling a bin nearly completely.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Lookahead: penalize if the next item would fit badly in the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving space exactly usable by the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize blocking the next item if this bin was a good host otherwise.
            score += 8.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 && mean_residual > item_size as f64 * 1.5 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should only win
    // when no open bin offers a decent fit. Penalize it proportionally to how much
    // usable space already exists in open bins.
    if bin_residual == bin_capacity {
        let usable = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 55.0 + 15.0 * usable.min(5.0);
        // Late in the stream, opening a new bin is less harmful (less time to exploit it anyway).
        score -= 20.0 * progress;
    } else {
        // Slight preference for bins already partially filled (waste-avoidance).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Mild time-dependent urgency: early on, be choosy; later, accept decent fits.
    score -= 5.0 * progress * (1.0 - tightness);

    // Tie-breaker: prefer bins with residual close to the item (exactness measure).
    score += 0.05 * (bin_residual - item_size).min(bin_capacity) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: reward tight fits (low post residual), with smooth polynomial shaping
    let mut score = norm_pr * (1.0 + 1.5 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling of post-residual with stream progress:
    // later in the stream, waste matters more (smooth polynomial ramp)
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 2.0 * norm_pr * norm_pr;

    // Penalize bins whose residual deviates from mean (fragmentation pressure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev * dev.abs();

    // Reward using nearly-full bins (small residual relative to item)
    score -= 0.8 * fit_ratio * (1.0 - norm_pr);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly into post residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 1.2 * (1.0 - gap) * (1.0 - gap);
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's only
    // chosen when all open bins would leave large dead space
    if bin_residual == bin_capacity {
        score += 1.5 + urgency * 1.5 - 0.5 * fit_ratio;
    }

    // Slight penalty for too many open bins (encourage consolidation)
    score += 0.01 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality via modulo classes
    let pr = post_residual;
    let small_waste = pr < 10; // nearly perfect fit
    let harmonic_class = pr % 10; // residue class mod 10

    // Reward near-perfect fits strongly
    if small_waste {
        score -= 25.0 + (10 - pr) as f64 * 2.0;
    }

    // Penalize awkward residues that few item sizes can reuse (odd residues, primes-ish)
    let awkward = (harmonic_class == 1 || harmonic_class == 3 || harmonic_class == 7) && pr > 0;
    if awkward {
        score += 8.0;
    } else if pr % 5 == 0 && pr > 0 {
        // round-number residuals are reusable by many sizes
        score -= 6.0;
    }

    // Integer-division thresholds: how many "typical" items still fit
    let fits_quota = pr / 20; // items of size ~20
    score -= fits_quota as f64 * 1.5;

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // bonus if post residual exactly matches next item's class
            if post_residual % 10 == next_item_size % 10 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // creates dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins that are already well used (low residual fraction)
    let residual_frac = bin_residual as f64 / cap_f;
    score += residual_frac * 12.0;

    // Progress pressure: later in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += residual_frac * progress * 8.0;

    // Mean residual coupling: if this bin is below mean residual (more filled), reward
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: penalize opening unless residual situation is dire
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is OK if item is large and few bins fit it
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= 50 && item_size >= 50 {
            score -= 10.0; // pair two big items? no — keep separate bins
        }
        // early stream: allow more bins
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    // Many open bins: discourage spreading, favor consolidation
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable dead space (gaps that no item can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: prefer compacting into fewer bins when stream is early.
    let progress = step_index as f64 / total_items as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins below the mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Mild penalty for opening a brand-new bin when it's not necessary.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bin if it would create a perfect slot for the next item.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead bonus: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward tight-ish matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit in this bin's leftover; penalize large leftovers
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Favor bins tighter than the mean residual (good fits), penalize loose bins.
    let diff = mean_residual - bin_residual as f64;
    score += 0.35 * diff;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when it isn't needed, unless residual is tiny/dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New-bin candidate: only attractive if the item is huge and leftover would be dead space
        let dead = (post_residual as f64) < 10.0;
        if dead && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild preference for consolidating into fewer bins late in the stream.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual), with a convex penalty
    // so that large dead space is punished super-linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Exact fit is a jackpot: heavily reward filling a bin completely.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, mild penalty for using a scarce-capacity bin
        // (keep big residuals for future big items).
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead (k=2): if the next item fits exactly in the post-residual,
    // reward this placement (chain packing). If next item would fit better
    // elsewhere (i.e., post_residual is awkwardly small for it), slight penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.15 * slack;
        } else {
            // next item cannot fit here; leaving tiny unusable residue is fine,
            // leaving mid-sized residue is worse.
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    // or open bins are crowded with large residuals.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: moderate.
        score = bin_capacity as f64 * 0.6;
        // If many bins already fit the item, opening a new bin is wasteful.
        score += 8.0 * fitting_bins_count as f64;
        // If mean residual is high (bins are loose), new bin less attractive.
        score += 0.25 * mean_residual;
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Big items (hard to place later) justify a fresh bin early.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If only one bin fits and it's not this one, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Global pressure: when many bins are open, encourage consolidation into
    // existing bins rather than spreading.
    score += 0.02 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (minimize waste ratio).
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, normalized non-linearly.
    let mut score = (pr / cap).powf(1.6) * 100.0;

    // Smooth coupling with stream progress: tighter fits matter more later.
    score += (pr / cap) * (1.0 + progress * progress) * 20.0;

    // Penalize dead space relative to mean residual of open bins.
    score += ((pr - mean_residual) / cap).abs() * 10.0;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr - nxt <= cap * 0.5 {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else if pr < nxt && pr > 0.0 {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless no open bin fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 60.0; // forced to open a bin
        } else {
            // Smooth penalty that grows with stream progress and open bins.
            score += 25.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: dead space analysis ---
    // Residuals that cannot accommodate the smallest plausible items are "dead".
    // Class A: post_residual == 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class B: tiny residual (1..=5) -> nearly dead, mild reward (low waste)
        if post_residual <= 5 {
            score -= 25.0;
        }
        // Class C: residual in (5, 10) -> dead zone (items >= 10), penalize
        else if post_residual < 10 {
            score += 45.0;
        }
        // Class D: modulo structure on residual vs common item sizes
        // reward residuals divisible into useful chunks (multiples of 10)
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        } else {
            // awkward residual: penalize proportional to distance from next multiple of 10
            let dist = 10 - (post_residual % 10);
            score += dist as f64 * 1.5;
        }
    }

    // --- Lookahead coupling: does this placement serve the next item? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: reward, scaled by tightness of the two-item packing
        let pair_waste = (post_residual - next_item_size) as f64;
        score -= 20.0 - pair_waste.min(20.0) * 0.5;
        if (post_residual - next_item_size) == 0 {
            score -= 15.0; // perfect two-item chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: if residual is dead-ish, penalize more
        if post_residual < 10 {
            score += 20.0;
        } else {
            score += 3.0;
        }
    }

    // --- Last-chance logic: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // strongly prefer using the only fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high, so we only open when fits are bad.
        score = cap * 0.9 + open_bins_count as f64 * 2.0;
        // If no existing bin fits (fitting_bins_count == 0), opening is necessary:
        // this call only happens when at least it fits, so check last-chance.
        if fitting_bins_count == 1 {
            score += 40.0; // still worse than using the single fitting bin
        }
        // If next item is large, opening fresh bin may be attractive
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // --- Congestion modulation: many open bins -> prefer consolidation ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64 / 20.0).min(3.0);
    score += crowding * (1.0 + progress);

    // --- Mean residual coupling: placing into a bin far below mean residual
    // helps balance; placing into already-small-residual bins wastes little ---
    let res_frac = post_residual as f64 / cap;
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    // Slight preference for filling larger-residual bins early (keep small bins flexible)
    score += res_frac * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Strict dead-space avoidance: post_residual in the "unusable" band
    // (small gaps that likely can't host future items) is heavily penalized.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Mid-range gaps (13..30) are semi-dead for large-item streams: mild penalty.
    if post_residual > 12 && post_residual <= 30 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a good fit, or when the next item would benefit from
    // a fresh bin.
    if bin_residual == bin_capacity {
        // Default: discourage opening new bins (open_bins_count pressure).
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the current item leaves a terrible gap elsewhere, or the
        // next item is large, a fresh bin becomes attractive.
        if next_item_size > 0 {
            if next_item_size as f64 > mean_residual {
                score -= 55.0;
            }
            // Reserve room: if item + next item nearly fill a bin, prefer fresh bin.
            if item_size as f64 + next_item_size as f64 >= bin_capacity as f64 * 0.9 {
                score -= 70.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Open-bins pressure: penalize bins that fragment the mean residual badly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next_fits = (next_item_size as u32) <= post_residual;
        if next_fits {
            // Reward tight 2-step packing: smaller leftover after the hypothetical next placement.
            let two_step_leftover = post_residual as f64 - next_item_size as f64;
            score -= 40.0 * (1.0 - two_step_leftover / bin_capacity as f64);
            if two_step_leftover == 0.0 {
                score -= 60.0; // perfect 2-item closure
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space proportionally.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // No lookahead available (last item): just minimize waste.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when plenty of open bins exist and the item fits well elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's only chosen when open bins are poor fits.
        score += 30.0;
        if fitting_bins_count > 0 {
            score += 20.0 * (fitting_bins_count as f64);
        }
        // Slightly more willing to open bins early in the stream (build flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Mild reward for high fill ratio of the current bin.
    score -= 8.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (small post-residual).
    let fit_ratio = 1.0 - post / cap;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical future item.
    if post > 0.0 && post < 10.0 {
        score += 40.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits perfectly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            if gap < 10.0 {
                score -= 25.0; // chains nicely
            }
        } else {
            score += 8.0 * ((nxt - post) / cap); // next item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: default penalty, relaxed when the item is large
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frag = mean_residual / cap;
        let item_frac = item_size as f64 / cap;
        let mut new_pen = 20.0;
        // Large items justify fresh bins; fragmented state also favors fresh bins.
        new_pen -= 25.0 * item_frac;
        new_pen -= 15.0 * (frag - 0.5).max(0.0);
        // Early in stream, keep bins open (fewer bins); late, allow opening.
        new_pen += 10.0 * (1.0 - progress);
        // If no other bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            new_pen -= 30.0;
        }
        score += new_pen.max(-50.0);
    }

    // Mild penalty for spreading across too many open bins when residuals are large.
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64 - 3.0) * (mean_residual / cap);
    }

    // Tie-break: prefer bins with lower residual (fill fuller bins first).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes progressively more costly.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 30.0 * coupling;

    // Cubic tight-fit reward: reward very small post_residuals smoothly.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight * (0.5 + progress);

    // Lookahead: reward if the next item can use the post-residual exactly or nearly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let gap = (pr - n) / cap;
            score -= 18.0 * (1.0 - gap * gap) * (0.4 + 0.6 * progress);
        } else {
            // next item cannot fit here; penalize proportionally to overshoot
            let over = (n - pr) / cap;
            score += 10.0 * over * over;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for bins that are already much emptier than average
    // (prefer packing into tighter bins, keep roomy bins flexible).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - 0.5 * progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable when the item fits poorly everywhere
        // (large post_residual relative to capacity) or when few bins are open.
        let poor_fit = (item_size as f64 / cap).powi(2);
        score += 15.0 * (1.0 - poor_fit) - 8.0 * (1.0 - open_bins_count.min(10) as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: quarter / fifth / tenth divisions of capacity
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Reward exact harmonic fits (dead space elimination)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % tenth == 0 {
        score -= 12.0;
    } else if post_residual % fifth == 0 {
        score -= 8.0;
    } else if post_residual % quarter == 0 {
        score -= 5.0;
    }

    // Penalize tiny unusable dead space (below smallest item scale)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dead space relative to capacity fraction
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * dead_frac * 30.0;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item would have fit current bin but not after placement — mild penalty
        score += 6.0;
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / tenth;
    match cls {
        0 => score += 15.0,   // nearly full: good, but tiny gap handled above
        1 => score += 5.0,
        2 => score -= 2.0,
        3 => score -= 4.0,
        _ => {}               // large residuals: keep base cost
    }

    // New-bin candidate: prefer it only late in stream or when all open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tight = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(0.0);
        // penalize new bin when existing bins are roomy; reward when tight
        score += 20.0 * (1.0 - avg_tight) + 15.0 * (1.0 - progress) - pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative — allow new bin
        }
    }

    // Mean residual coupling: avoid making the mean residual worse than it already is
    if post_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 4.0;
    }

    // Small tie-breaker favoring earlier bins as stream progresses
    score -= (step_index % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver of dead space
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 45.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Small-but-usable gaps are risky: only worth it if the lookahead item fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 18.0;
        }
    }

    // Reward a fit that also accommodates the next item (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; a new empty
    // bin candidate (residual == capacity) should only win when fits are poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        score = bin_capacity as f64 * 0.9 + (open_bins_count as f64) * 4.0;
        if post_residual >= 10 && post_residual <= 25 { score += 0.0; }
        // Make new bin attractive only if all existing fits create dead space.
        if fitting_bins_count == 0 { score -= 30.0; }
    } else {
        // Penalize bins whose residual deviates far above the mean (hoarded space).
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 { score += dev * 0.05; }
    }

    // Mild late-stream conservatism: near the end, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact/near-exact fit reward: tiny post-residual is gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Dead-space penalty: post-residual below smallest plausible item (1..10)
    // is nearly unusable, but the exact-zero case is already rewarded.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs();
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 55.0; // perfect chain fit
        } else if lookahead_gap <= 5 {
            score -= 25.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 && (post_residual as i64 - next_item_size as i64) <= 10 {
            score -= 10.0; // next item fits with small leftover
        } else {
            // post-residual can't host next item: mild penalty scaled by gap
            score += (lookahead_gap as f64).min(80.0) * 0.08;
        }
    }

    // Prefer filling bins that are already relatively empty (large residual used well)
    // i.e. bins whose residual is high get a slight preference to be drained.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score -= residual_frac * 8.0;

    // Mean-residual coupling: placing in a bin above mean residual reduces fragmentation.
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible, handled above).
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: slight penalty so the best-fit logic still discriminates
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Only attractive if current item is large (poor fit likely elsewhere) —
    // penalize opening new bins when many open bins exist and item is small.
    if bin_residual == bin_capacity {
        let open_penalty = open_bins_count as f64 * 3.0;
        let size_bonus = (item_size as f64 - 50.0) * 0.5;
        score += open_penalty - size_bonus + 10.0;
    }

    // Late-stream consolidation: near the end, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits perfectly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        score -= 30.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty for creating a chain of small residuals.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Reward filling bins when many bins are already open (consolidation pressure).
    if open_bins_count > 2 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill_ratio * (open_bins_count.min(20) as f64).ln();
    }

    // Prefer bins whose residual is below the mean residual (use up the emptier bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Early in the stream: be more willing to open new bins for large items to keep
    // flexibility; late in the stream: squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately so it's chosen only when open bins fit badly.
        score += 15.0;
        // Early stream: new bins are cheaper; late stream: expensive.
        score += 20.0 * progress;
        // Large items justify fresh bins more (less likely to waste capacity).
        if item_size > bin_capacity / 2 {
            score -= 12.0 * (1.0 - progress);
        }
    } else {
        // Late stream: extra reward for using existing bins.
        score -= 10.0 * progress;
    }

    // Slight preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer tight fits (small post_residual), non-linearly scaled.
    let mut score = pr.powf(1.4);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter packing matters more (waste is amplified).
    let coupling = pr * pr / cap * (0.5 + 1.5 * progress);
    score += coupling;

    // Reward filling a bin nearly completely (post_residual < item_size/2 threshold via smooth term).
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness.powf(3.0);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize unless current bin fit would be terrible.
    if is_new_bin {
        let fit_quality = pr / cap; // = 1 - item/cap for a new bin
        let penalty = 15.0 + 25.0 * (1.0 - fit_quality).powf(2.0) * (0.5 + progress);
        score += penalty;
        // If no open bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - gap / cap);
    } else if next_item_size > post_residual {
        // Dead-space creation relative to lookahead: penalize unusable leftover.
        score += 3.0 * pr / cap;
    }

    // Mild preference to spread across fewer bins when many are open with slack.
    if !is_new_bin {
        score -= 0.5 * (bin_residual as f64 - mean_residual).max(0.0) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo small divisors.
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;

    // Reward post residuals that sit in "usable" harmonic classes.
    // Residuals that are multiples of 10 or 25 pair well with typical item sizes.
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 25 == 0 { score -= 4.0; }
        if r % 5 == 0 { score -= 2.0; }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 40.0;
    }

    // Penalize tiny dead space (< 10) that no item can ever use.
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Dead-space penalty grows with unusable remainder fraction.
    score += (m4 / 4.0) * 2.0 + (m10 / 10.0) * 3.0 + (m25 / 25.0) * 2.0;

    // Tight fit reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained harmonic closure).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size < r {
            let chain = (r - next_item_size) as f64;
            // Prefer chains leaving residuals in good classes.
            if chain % 10 == 0 { score -= 10.0; }
            else if chain < 10 { score += 15.0; }
            score += chain * 0.15;
        } else {
            // Next item cannot use this bin's remainder; slight penalty.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins by default; discount when open bins are nearly full.
        score += 30.0 - mean_fill * 35.0 - progress * 5.0;
        // Large items justify fresh bins more.
        score -= fill_ratio * 10.0;
    }

    // Slight bias toward consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead gap that almost nothing can use
    } else if post_residual < 20 {
        score += 12.0; // risky small gap
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit here; gap likely wasted
    }

    // Prefer bins below mean residual (already tight bins) to consolidate.
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-positive so it only wins
    // when open bins have terrible fits (dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in stream: prefer closing bins tightly, less new-bin appetite.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not too tight to be useless.
    let tight_fit_bonus = (bin_capacity as f64 - post_residual as f64) * 0.05;
    score -= tight_fit_bonus;

    // 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if diff < 0.5 {
            score -= 40.0;
        } else {
            // Penalize mismatch scaled by how far off we are.
            score += diff * 0.6;
            // If next item cannot fit in post_residual, penalize dead space.
            if (post_residual as i64) < (next_item_size as i64) {
                score += (next_item_size as f64 - post_residual as f64) * 0.8;
            }
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    // (fragmentation) unless it's a near-perfect fit.
    let mean_diff = mean_residual - post_residual as f64;
    if mean_diff > 0.0 {
        score += mean_diff * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if lookahead suggests a fresh bin can host both item and next item
        // with room to spare, make it attractive for large items.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, prefer existing bins more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Slight preference for bins with residual close to item needs among many open bins.
    if open_bins_count > 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual waste quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // reward leaving a usable gap for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Dead-space penalty for small unusable residuals (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer filling bins that are already relatively full vs sparse bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Global state coupling: when mean residual is high, discourage spreading;
    // when many bins are open, favor consolidation into existing bins.
    if open_bins_count > 0 {
        let consolidation = mean_residual / bin_capacity as f64;
        score += consolidation * 5.0;
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate logic: only attractive when existing fits are poor
    // (large post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: new bins are cheap; later: discourage opening new bins
        score += 20.0 * (1.0 - progress);
        // If item is small relative to capacity, opening a new bin wastes space
        score += (bin_capacity - item_size) as f64 * 0.3;
        // If next item is large, a fresh bin is valuable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild time-horizon term: late in stream, tighten packing further.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 + progress) - prn * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly as the stream progresses
    let tight_bonus = -(1.0 - prn) * (1.0 - prn) * (0.3 + 0.7 * progress) * cap * 0.1;

    // Penalize dead space that next item cannot use
    let dead = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 { gap * gap / cap } else { 0.0 }
    } else { 0.0 };

    // Last-chance bin: strong reward to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -2.0 * (1.0 - prn) } else { 0.0 };

    // Mild pressure toward consolidating into existing bins
    let consolidation = -0.05 * (mean_residual / cap).ln().max(-3.0);

    let mut score = pr + poly * cap * 0.5 + tight_bonus + dead + last_chance + consolidation;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean"
    // fractions of capacity (good pairing targets), penalize awkward ones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Modulo classes on capacity (100): residuals divisible by 10 or 25
        // are classic pairing targets for typical item sizes.
        if pr % 25 == 0 { score -= 8.0; }
        else if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 2.0; }
        else { score += 3.0; } // awkward residual, penalize

        // Integer-division thresholds: small residuals are dead space.
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 10.0; }
        else if pr <= 30 { score -= 4.0; } // sweet zone for next small items
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (harmonic match with k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size; // residual after both items
            if npr % 10 == 0 { score -= 10.0; }
            if npr < 10 { score += 6.0; } // would create tiny dead space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 20.0 + 40.0 * (1.0 - progress) * tightness;
        // If item is large, a fresh bin is less wasteful.
        if item_size > bin_capacity / 2 { score -= 15.0; }
    }

    // Mild tie-break: prefer bins with lower residual among similar options.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 35 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space becomes less forgivable as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    // Pressure from number of open bins: prefer reusing bins when many
    // are already open (avoid bin proliferation).
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item
    // would leave a large, useful residual in an open bin is impossible,
    // or the item fits badly everywhere. Base penalty for opening new bin:
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large, a fresh bin is fine (large items pack
        // well together).
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no open bin fits well (all would leave tiny residuals),
        // opening a new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 10.0;
        }
    }
    // If next item cannot fit in the post residual, slight penalty for
    // fragmenting space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins whose residual is close to the mean (keep pool uniform),
    // mildly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual equals the next item's size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near-match: next item still fits in the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.25;
    }
    // Next item won't fit in leftover: penalize proportionally to wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize tiny dead space (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward filling bins tightly relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.15;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate handling: only open a new bin if it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If this is the last fitting bin opportunity, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Large items relative to capacity favor fresh bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Early in stream, more open bins already exist -> discourage new bins.
        if open_bins_count > 4 {
            score += 5.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild stream-progress term: later items prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can't hold a typical future item:
    // if post_residual is small but nonzero, it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 3.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global residual pressure: if mean residual across open bins is high,
    // we should consolidate into existing bins rather than spreading.
    let residual_pressure = mean_residual / bin_capacity as f64;
    score += 10.0 * residual_pressure * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when open bins already fit the item well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 30.0;
        // If few bins fit this item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Large items justify fresh bins more (less future flexibility).
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild time-horizon term: early on, keep bins balanced; late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Discourage excessive bin proliferation early.
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Reward filling the bin deeply as stream progresses (close bins early).
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly.
    let dead = post / cap;
    score += 40.0 * dead * dead * dead * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap) * (0.5 + progress);
        } else {
            score += 15.0 * (1.0 - post / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless existing bins are very fragmented
    // (high mean_residual spread) or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / cap;
        score += 20.0 + 10.0 * fragmentation - 8.0 * (item / cap) * (0.5 + progress);
    } else {
        // Slight preference for bins tighter than the mean.
        let diff = mean_residual - bin_residual as f64;
        score += 4.0 * diff / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (modular arithmetic) ---
    // Residuals divisible by common item sizes are "reusable"; odd residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // residuals that are multiples of 10 align with a coarse item grid -> usable
        if class == 0 {
            score -= 6.0;
        } else if class == 5 {
            score -= 2.0;
        } else {
            // awkward residual: penalize proportionally to how small it is
            score += (10 - class) as f64 * 0.8;
        }
        // tiny un-usable slivers (below min item size 10) are pure dead space
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64 * 2.0;
        }
    } else {
        // perfect fit: strongly rewarded
        score -= 40.0;
    }

    // --- Integer-division thresholds: can next_item_size fit exactly into post_residual? ---
    if next_item_size > 0 && pr >= next_item_size {
        let q = pr / next_item_size;
        let r = pr % next_item_size;
        // exact chaining of the lookahead item is excellent
        if r == 0 {
            score -= 18.0 + 4.0 * q as f64;
        } else if r < 10 {
            // chain leaves a tiny sliver -> bad
            score += 12.0;
        } else {
            score -= 5.0 + (r as f64).ln() * 2.0;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // this bin becomes useless for the lookahead item: mild penalty
        score += 8.0;
    }

    // --- Last-chance bin: avoid opening a new bin when this is the only fit ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing fits are poor.
        // Base penalty keeps it behind any decent existing fit.
        score += 55.0;
        // But if the item is huge, a fresh bin gives max future flexibility
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, fewer future items -> fresh-bin flexibility worth less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // --- Fragmentation pressure: prefer bins whose residual deviates from mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer filling fuller (smaller residual) bins slightly more than raw residual does
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Many open bins: encourage closing them out (fill tightest first)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness);

    // Lookahead: if next item fits exactly into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins,
    // i.e. favor using existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Mean-residual coupling: bins with below-average residual are already
    // "used up"; prefer placing into bins with residual near the item.
    if (bin_residual as f64) < mean_residual {
        score += 10.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate: must be expensive unless the item is huge relative to
    // any existing fit or existing bins are nearly full.
    if bin_residual == bin_capacity {
        let base_new_bin = 60.0 + 0.5 * open_bins_count as f64;
        // If the item would leave a large usable gap anyway, a fresh bin is fine.
        let fresh_fit_bonus = if post_residual >= 10 { -20.0 } else { 0.0 };
        score = base_new_bin + fresh_fit_bonus + post_residual as f64 * 0.5;
        // If no other bin fits, opening is cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0;
        } else if post_residual as f64 > nxt {
            // leftover can still host next item: partial reward by tightness
            let gap = post_residual as f64 - nxt;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 8.0 + 0.15 * (nxt - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: keep bins with typical slack.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist, more so early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress) + open_bins_count as f64;
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post-residual), with a quadratic dead-space penalty.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frag * frag;

    // Reward filling bins nearly exactly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item fits poorly everywhere else. Penalize new bins mildly,
    // but discount the penalty when the item is large relative to residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 14.0 * tightness;
        // If lookahead item is large and this bin is fresh, opening may be fine.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item could use the post-residual, reward
    // leaving exactly that much space; penalize residuals just barely too small.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size && pr <= next_item_size + 10 {
            score -= 8.0;
        } else if pr > 0 && pr < next_item_size {
            score += 6.0; // dead space that next item can't use
        }
    }

    // Prefer placing into bins with larger residuals when many bins are open
    // (consolidate waste), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // Late in the stream, be more conservative: avoid opening extra bins.
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 10.0 * (progress - 0.8) * 5.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (small post_residual strongly rewarded);
    // later, dead space matters even more, so scale the reward up with progress.
    let fill_ratio = pr / cap;                       // 0 = perfect fit, 1 = empty bin
    let progress_poly = 0.5 + 1.5 * progress * progress;  // smooth, no piecewise constants
    score -= progress_poly * (1.0 - fill_ratio) * (1.0 - fill_ratio) * 30.0;

    // Penalize very small residuals (unusable dead space) with a smooth quadratic bump
    let dead = (12.0 - pr).max(0.0) / 12.0;
    score += dead * dead * 25.0;

    // Reward last-chance bins (only one fitting bin left) with smooth coupling
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward if the next item can use the post_residual
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let tight = 1.0 - gap / cap;
            score -= 12.0 * tight * tight;
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            score += (-gap / cap) * 10.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Slight penalty for opening a new bin when many bins are open and could fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual (mod 10 buckets)
    let pr = post_residual as u32;
    let small = pr <= 5;
    let medium = pr > 5 && pr <= 15;
    let large = pr > 15;
    if small { score -= 18.0; }
    else if medium { score -= 6.0; }
    else { score += (pr as f64 - 15.0) * 0.35; }

    // Exact fill jackpot
    if pr == 0 { score -= 40.0; }

    // Integer-division threshold on item size (harmonic classes of capacity fractions)
    let q = item_size * 4 / bin_capacity; // 0..=3
    match q {
        0 => score += 2.0,   // tiny item: prefer leftover bins
        1 => score -= 1.0,
        2 => score -= 3.0,
        _ => score -= 5.0,   // big item: prioritize placing it
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits into leftover: reward proportional to utilization
            score -= (next_item_size as f64 / cap) * 12.0;
            // harmonic class of (pr - next) mod 10
            let rem = pr - next_item_size;
            if rem <= 5 { score -= 8.0; }
            else if rem > 20 { score += 3.0; }
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5; // prefer emptier/more-flexible bins less
    }

    // New-bin candidate handling: only attractive if current bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins unless many open bins are nearly full
        let fragmentation = mean_residual / cap;
        score += 25.0 + fragmentation * 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big pair coming: fresh bin may be wise
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 5.0; // endgame: avoid new bins
        }
    }

    // Mild preference to drain bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized,
    // moderately small gaps (10..30) are mildly penalized since they rarely fit future items.
    if post > 0.0 && post < 10.0 {
        score += 25.0; // worst outcome: nearly-full bin with a sliver wasted
    } else if post < 30.0 {
        score += 8.0 * (30.0 - post) / 20.0;
    } else if post > 50.0 {
        // large leftover is fine (reusable), slight reward relative to base
        score -= 3.0;
    }

    // Perfect fit bonus
    if post == 0.0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin should only win when the best existing fit is bad.
    // Base new-bin score is high (post == cap), penalize further with open-bin pressure,
    // but discount if the next item is large and this bin's post-fit residual is small.
    if bin_residual == bin_capacity {
        score = cap + 10.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && (next_item_size as f64) > post {
            // next item cannot fit in a fresh placement of current item in a new bin anyway;
            // a new bin still gives full residual for it, so soften
            score -= 15.0;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // never open a new bin when it's the only fitting option
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 {
        // next item won't fit here; small penalty scaled by wasted potential
        score += 3.0 * (next_item_size as f64 - post) / cap;
    }

    // Open-bin pressure: mild penalty for scattering across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * open_bins_count as f64 * progress;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // rewarding consolidation of small residuals.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead: next item fits into the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tightness of the 2-step fit.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit: penalize dead space more strongly.
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        score += 0.35 * dead;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (good fits), discourage loose bins.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * mean_gap;

    // Early in stream: be more willing to open bins / keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Empty new-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 {
        (step_index as f64 / (total_items as f64 - 1.0)).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: best-fit greedy term (smaller leftover = lower score = better).
    let mut score = pr;

    // Perfect fill: completely closed bin is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling (k=2): shape the leftover around the next item.
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            // Leftover stays usable; stronger reward as the chain tightens.
            score -= 5.0 + 9.0 * (n / pr);
            if next_item_size == post_residual {
                // Exact two-item chain: can justify even opening a fresh bin.
                score -= 35.0;
            }
        } else {
            // Leftover is dead with respect to the lookahead item; worse late in the stream.
            score += 4.0 * (1.0 - pr / n) * (0.5 + progress);
        }
    }

    // Sliver residuals are likely stranded waste; the penalty grows as the stream ends.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * (0.4 + 0.5 * progress);
    }

    // Consolidation: prefer bins fuller than the fleet average.
    let dev = (mean_residual - bin_residual as f64) / cap;
    if dev > 0.0 {
        score -= 2.5 * dev.min(1.0);
    }

    if is_new_bin {
        // Fresh-bin candidate: mild discount for large items, but penalize opening
        // when open bins collectively hold plenty of space or are numerous.
        score -= 4.0 * (item / cap) * (item / cap);
        score += 9.0 * (mean_residual / cap).clamp(0.0, 1.0);
        score += 0.7 * open_bins_count as f64;
        if fitting_bins_count >= 2 {
            // Other candidates exist, so opening a new bin needs strong justification.
            score += 1.5;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance open bin: using it avoids opening a brand-new bin.
        score -= 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Tight-fit reward amplified over time
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight * (0.3 + 0.7 * progress);

    // Penalize residuals that cannot fit the next item (lookahead dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 10.0 * progress;
    }
    // Bonus if post_residual still accommodates next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (pr / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild penalty when bin deviates from mean residual (fragmentation control)
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize mildly unless current bin is unusable
    if bin_residual == bin_capacity {
        let bad_fit = (bin_residual < item_size) as i32 == 1;
        score += if bad_fit { -20.0 } else { 6.0 + 10.0 * progress };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better, but dead space below
    // the minimum useful size (harmonic class of small items) is wasted.
    let min_item = 10.0f64;
    if post_residual > 0 {
        if (post_residual as f64) < min_item {
            // Unusable sliver: heavy penalty (dead space forever).
            score += 60.0;
        }
    } else {
        // Perfect closure of the bin: strong reward.
        score -= 40.0;
    }

    // Harmonic class: post_residual bucketed by integer division into
    // capacity-fraction classes. Residuals in mid classes are reusable.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 25; // classes: 0..=4 over capacity 100
        match class {
            0 => score += 25.0,          // 1..24: hard to reuse
            1 => score -= 5.0,           // 25..49: decent
            2 => score -= 10.0,          // 50..74: good
            3 => score -= 8.0,           // 75..99: fine
            _ => {}
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly prefer this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.15 * slack;
        } else {
            // Next item cannot follow here; penalize proportionally to
            // how much residual would be stranded.
            score += 0.2 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): only attractive when existing bins
    // fit poorly or residuals are globally low.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= cap; // must open a bin
        }
        // Open new bin when mean residual across open bins is small
        // (fragmented state) and stream is still long.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (mean_residual / cap) * 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is larger, a fresh bin keeps room for it.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let p = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rem = (1.0 - p).clamp(0.0, 1.0);

    let mut score = r;

    // Strict dead-space avoidance: a small positive gap is likely unusable.
    // Hump peaks for tiny gaps, decays to zero at the dead-zone edge (12),
    // slightly stronger early in the stream when avoiding waste pays off most.
    if r > 0.0 && r < 12.0 {
        let t = 1.0 - r / 12.0;
        score += 40.0 * t.powf(1.2) * (0.8 + 0.4 * rem);
    }

    // Perfect fit: strong reward, slightly stronger for large items
    // (consuming a large residual exactly is the best possible outcome).
    if r == 0.0 {
        score -= 6.0 + 0.02 * item_size as f64;
    }

    // Lookahead (k=2): reward gaps that can chain the next item,
    // tightest chain wins; penalize gaps the next item just misses.
    if next_item_size > 0 && r > 0.0 {
        let n = next_item_size as f64;
        if r >= n {
            let slack = r - n;
            score -= (18.0 + 0.6 * n) * (1.0 - slack / 120.0).max(0.0);
        } else {
            score += ((n - r) * 0.08).min(6.0);
        }
    }

    // Last-chance consolidation: if this is the only open bin that fits,
    // rejecting it means stranding its residual AND paying for a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins that are fuller than the current average (consolidation).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    if is_new_bin {
        // Opening a new bin: pay a fixed cost, plus pressure from the number
        // of already-open bins, plus a cost that grows as the stream is
        // consumed (fewer future items left to amortize the fresh capacity).
        // A small discount recognizes that a large pristine leftover is valuable.
        score += 4.0
            + 0.9 * open_bins_count as f64
            + 22.0 * p
            + 0.6 * fitting_bins_count as f64;
        score -= 0.12 * r;
    } else {
        // With many open bins, gently discourage leaving large slack behind.
        score += 0.15 * open_bins_count as f64 * (r / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to slack consumed
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit in the remaining space: penalize small leftovers
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.6 * (mean_residual - post_residual as f64).max(0.0);

    // Penalize creating tiny unusable dead space (waste zones)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if current item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 200.0;
        }
        // If the best alternative is poor (no bin gives near-exact fit), allow new bin
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Slight penalty for very small items placed in nearly full bins (reserve space)
    if item_size < 20 && bin_residual < 30 {
        score += 15.0;
    }

    // Late-stream consolidation: prefer filling bins tighter as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize very small post-residuals that are still unusable dead space
    // (below the smallest plausible item, ~1..10 range) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Post-residual too small for the next item: mild penalty scaled by waste.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item in the stream: any residual is pure waste; minimize it hard.
        score *= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when open bins
    // are congested (few fitting bins) or mean residual is very low.
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let urgency = congestion * 0.6 + mean_tight * 0.4;
        // Base penalty for opening a new bin, discounted by urgency.
        score += 55.0 * (1.0 - urgency);
        // Late in the stream, opening new bins is more wasteful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild preference for bins already below mean residual (balance avoidance
    // of fragmenting many bins at once).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Global load factor: with many open bins, favor consolidation into
    // existing bins rather than spreading.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base tightness reward: strongly favor small post_residual via non-linear shaping.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness.powi(3);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post > 0.0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap;
        } else {
            // Reward residuals that can still host the next item.
            score -= 4.0 * (1.0 - post / cap) * (nxt / cap);
        }
    } else if next_item_size == 0 {
        // End of stream: residual is pure waste.
        score += 8.0 * post / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
        score -= 6.0 * progress;
    }

    // Stream-progress coupling: early on, keep bins flexible (prefer larger post_residual
    // less aggressively); late, squeeze hard since future reuse is limited.
    let squeeze = 0.5 + 0.5 * progress;
    score += (1.0 - squeeze) * 4.0 * (post / cap);

    // Mean-residual coupling: if this bin is much tighter than average, it is valuable
    // to fill now; if looser than average, defer slightly.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev;

    // New-bin candidate handling: empty bin gets a moderate default so it wins only
    // when all open bins are poor fits (their scores drop below this via bonuses).
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0 * (1.0 - progress) - 4.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 15.0; // no open bin fits: opening is right
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (mod 10 buckets) ---
    // Residuals in "dead" classes (1..9, 11..19 style slivers) are hard to fill.
    let pr = post_residual;
    let class = pr % 10;
    let dead = pr > 0 && pr < 10;
    if dead {
        score += 60.0; // unusable sliver
    } else if class != 0 && pr < 30 {
        score += 12.0 + (10 - class) as f64; // awkward small residual
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 150.0;
    }

    // --- Lookahead coupling: does next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward tight coupling
            score -= 25.0 + (pr - next_item_size) as f64 * 0.5;
            if next_item_size == pr {
                score -= 60.0; // chain of perfect fits
            }
        } else {
            // next item cannot use leftover: penalize proportionally to waste
            let waste = pr as f64;
            score += waste * 0.35;
            // if next item would fit a fresh bin exactly, opening a new bin is attractive
            if bin_capacity >= item_size + next_item_size {
                score += 10.0;
            }
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 {
        score -= 40.0; // strongly prefer using the only fitting bin
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // --- Fractional capacity classes ---
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.10 {
        score += 30.0; // near-dead zone below 10% capacity
    } else if frac >= 0.10 && frac <= 0.20 {
        score -= 8.0; // usable small pocket
    }

    // --- Stream progression: tighten up near the end ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // --- Bin-count pressure: reuse open bins when many are open ---
    score += open_bins_count as f64 * 0.8;

    // --- Mean residual alignment: prefer bins near the mean (balanced packing) ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (size 1) are pure waste; gaps below a "useful threshold"
    // (items >= 10 in classic streams) are heavily penalized.
    let dead_threshold = 9u32;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < dead_threshold {
        // Unusable sliver of dead space: strong penalty.
        score += 45.0 + 8.0 * (dead_threshold - post_residual) as f64;
    } else {
        // Usable leftover: mild reward proportional to tightness.
        score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // rather than fragmenting capacity further.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (a relatively full bin), it is a good candidate to close out.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 && resid_f < mean_residual {
        score -= 0.3 * (mean_residual - resid_f);
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward creating that "designed" gap; if post-residual is smaller than
    // the next item but nonzero, it risks becoming dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 25.0; // next item nearly fills the gap: excellent
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 {
            score += 12.0; // next item can't use this gap
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give it a baseline penalty so it is chosen
    // only when open-bin scores are pushed up by dead-space penalties.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the resulting residual -> reward proportional to tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tight / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item would NOT fit: penalize dead space relative to bin capacity.
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize post_residual much larger than mean residual (wasteful fit).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if current bin would leave a large,
    // next-item-incompatible gap; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        let next_fits = next_item_size > 0 && next_item_size <= post_residual;
        if waste > 0.5 && !next_fits {
            score -= 5.0; // acceptable fresh bin for a bad-fit situation
        } else {
            score += 45.0; // discourage new bins when a decent fit exists
        }
    }

    // Late in stream: consolidate, prefer tight fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) super-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: residual can host next item; reward proportionally.
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Bad: dead space blocks the next item.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening new bins is penalized more as the stream progresses.
        score += 25.0 + 30.0 * progress;
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a fresh bin is reasonable: reduce the penalty.
        let mean_fit = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        if mean_fit < item_size as f64 / bin_capacity as f64 {
            score -= 35.0;
        }
        // If many bins fit the item, opening a new bin is wasteful.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor)
    // relative to the average open bin.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Slight consolidation pressure: prefer placing into bins when many are open.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Reward perfectly exact fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress);
    score += 20.0 * poly;

    // Tight fit reward, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.3 + progress);

    // Penalize wasted residual when a lookahead item could use it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 8.0 * (1.0 - progress) * ((nxt - pr) / cap);
        } else {
            score -= 6.0 * (1.0 - nxt / cap) * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: prefer it only when open bins are heavily fragmented
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 12.0 - 18.0 * frag * frag;
    } else {
        // Slight penalty scaling with number of open bins to encourage consolidation
        score += 0.4 * open_bins_count as f64 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual).
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64);

    // Harmonic classes on post_residual: bins whose residual falls into "usable"
    // classes (multiples of common small sizes) are preferred.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect closure
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr < 10 {
        15.0 // dead space class
    } else {
        4.0
    };
    score += class_bonus as f64;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Slight preference to fill bins with low residual overall (harmonic of mean).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Progression coupling: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead: f64 = if post_residual == 0 {
        -60.0 // perfect fit is excellent
    } else if post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 4.0 // tiny gap = wasted bin
    } else if post_residual < 25 {
        12.0 + (25 - post_residual) as f64 * 1.5
    } else {
        0.0
    };
    score += dead;

    // Reward relative tightness of the fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last fitting bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 10.0; // blocks next item with a useless gap
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: only attractive when no open bin is a good host
    // (i.e., this call itself is the empty bin and residuals elsewhere are tight).
    if bin_residual == bin_capacity {
        let base = 55.0 + 1.5 * open_bins_count as f64;
        score = base + post_residual as f64 - 30.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when the next item exactly consumes the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: next item seals this bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer leaving a residual that still fits the next item,
            // but penalize large leftover slack (dead space)
            score -= 25.0 - 0.15 * slack;
        } else {
            // next item won't fit here; penalize tiny unusable residuals
            let waste = post_residual as f64;
            score += (12.0 - waste).max(0.0) * 0.8;
        }
    }

    // Compare against mean residual: bins with residual far above mean are
    // better targets (they have more room), bins near mean are average.
    let dev = (bin_residual as f64 - mean_residual);
    score -= 0.08 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when plenty of bins fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (fitting_bins_count as f64);
        // but a new bin is attractive if the item is large relative to residual
        // of typical open bins (mean_residual small => item barely fits anywhere)
        if (item_size as f64) > mean_residual + 0.5 * (bin_capacity as f64 - mean_residual) {
            score -= 22.0;
        }
    }

    // Late in the stream, tighten packing: prefer bins that end up nearly full.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small waste relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.2;
    }
    // If next item would not fit here, mildly penalize leaving a large awkward gap.
    if next_item_size > post_residual && post_residual < 10 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize the brand-new empty bin candidate unless open bins are poor fits.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (bin_residual as f64 - item_size as f64) - mean_residual.max(0.0);
        score += 10.0;
        // If mean residual across open bins is small (bins are full-ish), new bin is less bad.
        score -= mean_residual * 0.05;
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // If this new bin would fit the next item too, it's more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        let _ = avg_fit_gap;
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor).
        score += (bin_residual as f64 - item_size as f64).abs() * 0.1;
        // Slight preference for bins below mean residual (concentrate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // With many open bins, encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic) waste growth.
    let mut score = pr + 20.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: post residual weighted by stream progress (late items -> tighter packing).
    score += (0.5 + 1.5 * progress) * pr * (it / cap);

    // Reward good fit: small post residual relative to item size.
    score -= 15.0 * (1.0 - norm_pr) * (it / cap) * (it / cap);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Many fitting bins: mild penalty to prefer tighter, fuller bins.
    score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: prefer bins below mean residual (fuller than average).
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;

    // Lookahead: if next item fits exactly into post residual, reward heavily.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - ((pr - ns) / cap).abs();
            score -= 12.0 * fit_quality;
        } else {
            // Dead space risk: post residual too small for next item.
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // New-bin candidate: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score = pr + 8.0 - 10.0 * (it / cap) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // small classes (0, or divisible chunks) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr % 10 == 0 {
        score -= 8.0; // round leftover, likely reusable
    } else if pr < 10 {
        score += 12.0; // dead space sliver
    }

    // Modulo class of next_item_size vs post_residual: lookahead fit reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here; penalize more if leftover is awkward
            let cls = pr % (next_item_size.max(1));
            score += cls as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many bins are already open and mean
    // residual is large (fragmentation).
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to aggregate slack
        score += open_bins_count as f64 * 1.5 + mean_residual * 0.2;
        // but discount if current item is huge and mean residual too small
        if (item_size as f64) > mean_residual + 1.0 {
            score -= 40.0;
        }
    }

    // Fraction-of-capacity coupling on post_residual.
    let frac = post_residual as f64 / cap;
    score += frac * frac * 10.0;

    // Integer-division threshold: bins with residual >= half capacity are
    // flexible; slight reward to keep them attractive.
    if post_residual >= bin_capacity / 2 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Stream progression: tighten packing toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling with next item: if the leftover can host the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + post_residual as f64 - next_item_size as f64;
    } else if next_item_size > 0 {
        // leftover too small for lookahead: mild penalty scaled by waste
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual context: penalize placing into bins already below mean residual
    // (keeps large-capacity bins available for big items).
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current fit is bad
    // (large dead space) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // base new-bin score: slightly worse than a decent existing fit
        score = 20.0 + 15.0 * bad_fit + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin fits lookahead well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how snugly it fits.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack_after_next * 1.5;
        } else {
            // Next item will NOT fit here: penalize leaving a gap smaller than next item.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Penalize dead space relative to mean residual (fragmentation avoidance).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make empty bins attractive only when placement would be poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or with few bins.
        score = (bin_capacity as f64) * 0.9
            - (step_index as f64 / total_items.max(1) as f64) * 50.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin trivially fits the next item; slight reward.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance dynamics: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit, or when open bins are mostly full / fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: opening a new bin is expensive.
        score += 20.0;
        // More attractive late in the stream (less future to amortize, keep tight bins free).
        score -= 14.0 * progress;
        // Attractive if open bins are crowded on average.
        score -= 0.15 * mean_residual;
        // Attractive if few bins can fit the item.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin is useful.
        if next_item_size > 50 {
            score -= 8.0;
        }
    } else {
        // Existing-bin fit: penalize using a bin whose post-residual would be
        // useless for the (known) next item.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste.min(40.0);
        }
        // Reward spreading across many open bins when they are numerous.
        score -= 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild global pressure: when mean residual is low overall, conserve space
    // by penalizing placements that leave large leftovers relative to mean.
    score += 0.08 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let pr2 = fit_norm * fit_norm;
    let pr3 = pr2 * fit_norm;

    // Base: reward tight fits (low post residual), with non-linear polynomial shaping.
    let mut score = pr
        - 22.0 * pr2
        + 14.0 * pr3;

    // Dead-space penalty: residuals too small to fit typical items are wasted.
    let dead_threshold = 20.0 + 15.0 * progress;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * (1.2 - 0.6 * progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: bonus if next item fits the post residual (chaining),
    // penalty if it almost fits but doesn't (fragments the bin).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else if pr > 0.0 && nxt - pr < 25.0 {
            score += 5.0 * (nxt - pr) / 25.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating from the mean when many bins open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count.min(20) as f64) / 20.0;

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    score -= 8.0 * progress * (1.0 - fit_norm);

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod 10 buckets.
    // Residuals that are multiples of 10 are "clean" classes and are
    // cheaper to keep, since future items (10..80 grid) align well.
    let cls = post_residual % 10;
    score += match cls {
        0 => -6.0,
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 3.0,
        _ => 0.0,
    };

    // Integer-division thresholds: reward leaving a slot big enough for
    // the lookahead item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 4.0 + (slack as f64).min(10.0) * 0.3;
        } else {
            score += 5.0;
            // Dead space that cannot hold the next item at all.
            if post_residual < next_item_size / 2 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Tight fit bonus: near-exact packing is always good.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= tight * tight * 10.0;

    // Prefer denser bins when many bins are open (consolidation pressure).
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    // New-bin candidate: only attractive when nothing fits well
    // (large unavoidable dead space) or late in the stream with no
    // last-chance urgency. Penalize opening a bin when a decent fit exists.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size.min(bin_capacity)) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0; // an open bin could host the next item too
        }
        if waste < 20.0 {
            score += 25.0; // opening a bin for a big item into empty space is wasteful if any open bin fits
        }
        if fitting_bins_count == 0 {
            score -= 15.0; // no alternative: new bin is fine
        }
        if step_index as f64 / total_items as f64 > 0.9 && fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are waste.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < dead_threshold.max(10) {
        // Unusable sliver: penalize hard, scaled by how close it is to useless.
        score += 40.0 + (dead_threshold.max(10) - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // unless it creates a large dead gap.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < dead_threshold.max(10) {
            score -= 30.0; // still better than a fresh bin mostly
        } else {
            score -= 20.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer compacting into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // New-bin candidate: make it expensive, but allow it for large items
    // or when the fit into this (empty) bin would leave a big gap anyway.
    if bin_residual == bin_capacity {
        // post_residual here = capacity - item_size; big item => lower score.
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        score += 25.0 + mean_residual * 0.1 - fill_fraction * 45.0;
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 10.0; // new bin keeps room for next item
        }
    }

    // Coupling: prefer bins whose residual is far from mean (heterogeneous packing)
    // when the item fits tightly, to preserve average-sized slots.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= (tightness * dev) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual), but with a soft cap
    // so tiny residuals don't dominate everything else.
    score = score.powf(1.25);

    // ---- 2-step lookahead: match post_residual against next_item_size ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            // Perfect 2-chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if post > next {
            // Next item fits with slack left over: reward proportional to how
            // small the leftover dead space is (post - next).
            let leftover = post - next;
            score -= 25.0 - leftover.min(30.0) * 0.6;
        } else {
            // Next item does NOT fit: penalize more the closer post_residual
            // is to next_item_size (tempting but wasted space).
            let gap = next - post;
            score += gap.min(40.0) * 0.45;
        }
    } else {
        // Last item of the stream: any residual is pure waste; tightest fit wins.
        score += 0.0;
    }

    // ---- Contextual coupling with mean residual ----
    // If this bin's residual is far above the mean, it's a "loose" bin:
    // prefer to dump the item here to consolidate space.
    let resid_diff = bin_residual as f64 - mean_residual;
    score -= (resid_diff * 0.15).max(-20.0);

    // ---- Last-chance bonus: only bin that fits the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Opening a new bin is expensive; strongly favor using this bin
        // unless the fit is terrible (huge post_residual).
        let waste = post_residual as f64;
        if waste <= 10.0 {
            score -= 35.0;
        } else {
            score -= 35.0 - (waste - 10.0).min(50.0) * 0.7;
        }
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: attractive when the item is large or no open bin fits
        // well, unattractive when existing bins can absorb the item cleanly.
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        } else if next_item_size > 0 && post_residual as f64 <= next_item_size as f64 {
            score += 15.0; // an open bin already chains well; don't open new
        } else {
            score -= 10.0 * large_item;
        }
        // Early in the stream, building fresh bins is cheap; later, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 12.0;
        // Many open bins: prefer reusing over opening yet another.
        score += (open_bins_count as f64).min(20.0) * 0.4;
    }

    // Small tie-breaker toward filling bins with more residual consumed.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Tightness reward: prefer bins where the item fills most of the residual ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // --- Exact / near-exact fit reward ---
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // --- Lookahead (k=2): reward leaving a gap that fits the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Gap is reusable by the next item: strong bonus scaled by how snugly it fits.
            let snug = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * snug;
        } else if post_residual > 0 {
            // Dead space too small for the next item: penalize proportionally to progress.
            score += 8.0 + 12.0 * progress;
        }
    }

    // --- Last-chance bonus: only one open bin can fit the item ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Discourage spreading across many open bins when mean residual is large ---
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // --- Prefer bins whose residual is close to the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- Late-stream consolidation: favor filling existing bins harder near the end ---
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Opening a new bin is attractive when the item is large relative to capacity
        // (few bins could host it) or when it would leave a useless sliver elsewhere.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 70.0 * large_item * large_item;
        // Early in the stream, new bins are cheap insurance; later, avoid proliferation.
        score += 40.0 * progress;
        // If the item fits nowhere else, the new bin must win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth interaction of post_residual with stream progress:
    // late in the stream, tighter packing (small post) matters more.
    score += 12.0 * norm_post * progress * (1.0 - progress + 0.25);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += (nxt - post) * (0.5 + 0.5 * progress);
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= (1.0 - post / cap) * 2.0;
        }
    }

    // Reward filling a bin nearly exactly (smooth exponential bonus).
    score -= 6.0 * (-3.0 * norm_post).exp();

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Open a new bin only if existing fits are poor (large post_residual elsewhere)
        // or few bins are open. Penalize opening by default.
        let mut penalty = 14.0 + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            penalty = -100.0;
        } else if fitting_bins_count == 0 {
            penalty = -50.0;
        } else {
            // If mean residual of open bins is already tight, new bin is more attractive.
            penalty -= (mean_residual / cap).min(1.0) * 6.0;
            // If the item would leave a large unusable gap in any existing bin,
            // the base score already reflects that; dampen the new-bin penalty.
            penalty -= (post / cap) * 4.0;
        }
        score += penalty;
    }

    // Mild penalty for scattering across many open bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Small tie-breaker preferring bins with larger residual used well.
    score += 0.01 * (bin_residual as f64) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the smallest item class are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Harmonic class of the leftover: residual divisible into common size
    // classes (10/20/25/50) is reusable, odd leftovers are not.
    let pr = post_residual;
    if pr >= 10 {
        let reusable = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if reusable {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Integer-division tier: chunk the residual into coarse bands.
        let tier = pr / 10; // 0..10
        score += (tier as f64 - 5.0) * 2.0; // prefer mid/large leftovers slightly less tight
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0;
            // exact modular match between leftover and next item
            if pr == next_item_size {
                score -= 30.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for very large items that
        // would leave unusable slivers elsewhere, or when existing bins are tight.
        if item_size >= 60 {
            score -= 20.0;
        } else {
            score += 55.0 + (60u32.saturating_sub(item_size)) as f64;
        }
        // If many bins already fit the item, opening another is wasteful.
        if fitting_bins_count > 1 {
            score += 80.0;
        }
        // Progress-scaled mild preference to consolidate late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (keeps larger residuals available for future large items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // A post_residual that is too small to hold even a modest future item
    // is "dead space" -> heavy penalty proportional to how useless it is.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward tight fits (small non-dead leftovers) super-linearly.
    if post_residual >= dead_threshold {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation
    // into existing bins; discourage opening yet another bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open
        // or late in the stream, unless mean residual is very low
        // (i.e., existing bins are nearly full anyway).
        let mean_r = mean_residual.max(0.0);
        let relief = (mean_r / bin_capacity as f64).min(1.0);
        score += 30.0 + 12.0 * pressure + 20.0 * progress - 25.0 * relief;
    } else {
        // Existing bins get a mild bonus scaled by open-bin pressure.
        score -= 4.0 * pressure;
    }

    // Lookahead coupling: if the next item fits nicely into the post
    // residual, reward this placement; if the next item would be blocked
    // by the post residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual < dead_threshold {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer post_residual that exactly matches next item (2-step lookahead).
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += match_gap * 0.8;

        // Perfect two-step fill is excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small waste left afterwards.
        else if next_item_size < post_residual {
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 12.0;
            }
            score += after_next as f64 * 0.15;
        }
        // Next item would NOT fit here after placement: penalize dead space more
        // if this bin is small-residual anyway (unusable gap).
        else {
            score += (next_item_size - post_residual) as f64 * 0.35;
            if post_residual < 10 {
                score += 8.0; // tiny dead space, likely unusable
            }
        }
    }

    // Relative-to-mean residual coupling: bins with residuals near the mean are
    // "typical"; prefer filling bins below mean residual (tighter bins) when the
    // item fits well, penalize opening gaps far above mean.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += dev * 0.25;
    } else {
        score += dev * 0.10; // slight reward for below-mean residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is huge relative
    // to capacity or no open bin is a good fit.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        score += 30.0;
        if frac > 0.6 {
            score -= 22.0 * (frac - 0.6) / 0.4; // big items: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // forced
        }
        // Early in stream, opening bins is cheaper (more future to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large and won't fit a fresh bin's remainder well, discourage.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 5.0;
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    // Waste-avoidance: penalize leaving residuals in the awkward 11..=30 zone
    // (classic worst-fit dead zone for items >= 10).
    if post_residual >= 11 && post_residual <= 30 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer small post residual (tight fit), but not zero-ish dead space
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (waste <= 10)
    if post_residual <= 10 {
        score -= 25.0 - (post_residual as f64) * 1.5;
    } else if post_residual > 40 {
        // Penalize leaving large unusable gaps
        score += (post_residual as f64 - 40.0) * 0.6;
    }

    // Lookahead: reward if the next item fits exactly into post_residual (k=2 chaining)
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack * 0.15; // good chain, less reward for slop
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in the stream, be greedier (favor tight fits harder)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Global state: many open bins with high mean residual -> discourage spreading,
    // favor filling existing bins rather than opening new ones
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 + mean_residual * 0.02;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // Default penalty: opening a new bin is usually worse than a decent fit
        score += 15.0;
        // But if the item is huge relative to residual space available elsewhere,
        // a fresh bin may be best: reduce penalty for very large items
        if item_size >= 70 {
            score -= 18.0;
        }
        // If many bins are open and mean residual is low, opening fresh is reasonable
        if open_bins_count > 3 && mean_residual < 20.0 {
            score -= 10.0;
        }
        // Late in stream, prefer closing out existing bins
        if progress > 0.8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post residual).
    let mut score = post;

    // Smooth quadratic penalty on wasted space, amplified late in the stream.
    let waste_frac = post / cap;
    score += 8.0 * waste_frac * waste_frac * (0.5 + progress);

    // Coupling with mean residual: avoid dumping items into bins whose
    // residual deviates strongly (keeps residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - waste_frac);
    }

    // Lookahead: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // Next item cannot fit here; slight penalty for stranded space.
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = (bin_residual as u64) == (bin_capacity as u64);
    if is_new_bin {
        // Mild baseline cost for opening a bin, reduced when the current
        // fit elsewhere would be terrible (large post residual) or when
        // many bins are already open and consolidation is hard.
        let poor_fit_pressure = (post / cap) * 0.0; // post here equals cap - item
        let _ = poor_fit_pressure;
        let new_item_post = cap - item_size as f64;
        // Prefer new bin only if it yields a very tight fit while existing
        // bins would strand lots of space (proxy: mean residual is large).
        score = 15.0 + new_item_post
            - 10.0 * (1.0 - new_item_post / cap)
            - (mean_residual / cap) * 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction bands. Leftovers in the smallest band are "perfect".
    let pr = post_residual;
    let band = (pr * 4) / bin_capacity; // 0..=3 harmonic class
    match band {
        0 => score -= 30.0,                    // near-perfect fit
        1 => score -= 8.0,                     // usable leftover
        2 => score += 5.0,                     // awkward leftover
        _ => score += 20.0,                    // large dead space
    }

    // Modulo-style penalty: leftover that no plausible item class (multiples
    // of 10) can exploit is dead space.
    if pr % 10 != 0 {
        score += (10 - pr % 10) as f64 * 0.6;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward leaving a residual that the next item can
    // exactly fill (harmonic match), penalize blocking it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the current stream is early or open bins
    // are all fairly full (mean residual low), to spread load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let spread_benefit = (mean_residual / cap) * 40.0;
        score = cap - item_size as f64; // baseline = post_residual of empty bin
        score -= spread_benefit * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 30.0; // never steal a last-chance bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Mild pressure against accumulating many half-full bins late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the minimum item (1..100 range, use 10 as soft floor)
    let dead = (post_residual > 0 && post_residual < 10) || (post_residual >= 10 && post_residual < item_size.min(10).max(1));
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny gap almost certainly wasted
    }

    // Reward tight fits (small post_residual) more aggressively than linear
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 3 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // gap likely unusable for next item
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Prefer bins tighter than the mean residual
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: baseline cost so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // but if item is large, new bin is more attractive (keeps small bins for small items)
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large unusable dead space: small post-residual is good.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Lookahead: strongly reward bins where the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item won't fit: penalize wasted residual relative to next item
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (post_residual large relative to typical residuals) or bin is empty anyway.
    if bin_residual == bin_capacity {
        // empty new bin: neutral-ish baseline; penalize slightly so existing
        // bins with decent fits win, but allow it when mean residual is large.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        if mean_residual > 40.0 {
            score -= (mean_residual - 40.0) * 0.5;
        }
    } else if post_residual as f64 > mean_residual * 1.5 && post_residual < 10 {
        // very tight fit relative to mean: extra reward
        score -= 8.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly: small post_residual is much better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize creating dead space that no plausible next item can use.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64) > gap {
            // Lookahead item cannot fit here -> dead space risk.
            score += 0.35 * gap;
        } else {
            // Lookahead chains nicely into this bin.
            let chain = 1.0 - (gap - next_item_size as f64) / bin_capacity as f64;
            score -= 10.0 * chain;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Many fitting bins: mild penalty to keep flexibility (avoid fragmenting choice).
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // Coupling with global state: if mean residual is large, prefer filling
    // bins below the mean (consolidation); above the mean is less urgent.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.12 * dev;

    // Time horizon: early in the stream, be conservative about opening new bins
    // (many items remain to fill residual space); late, prioritize tight fits only.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate.
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is penalized more when many bins are open early on,
        // but rewarded when the item fits poorly everywhere (high post_residual
        // alternatives already penalized via their own scores).
        score += 30.0 + 1.5 * open_pressure * (1.0 - 0.5 * progress);
        // Late in the stream, new bins are cheaper to open since fewer items remain
        // to exploit residual space.
        score -= 12.0 * progress * progress;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.15 * item_size as f64;
    } else {
        // Existing bin: early on, reward keeping bins balanced (avoid many tiny residuals).
        score += 3.0 * progress;
    }

    // Small penalty on very small residuals left behind (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit preferred (small post_residual)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize very tight fits slightly),
    // late in stream, strongly prefer tight fits.
    let tightness = pr / cap;
    let phase = progress * progress;
    score += (0.5 + 6.0 * phase) * tightness * tightness * cap;
    score -= (1.0 - phase) * (tightness * (1.0 - tightness)) * cap * 0.3;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (pr / cap).clamp(0.0, 1.0);
    score += 4.0 * dead * (1.0 - dead) * (1.0 - progress);

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        score += 1.5 * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits -> use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.4 * ((mean_residual - pr).abs() / cap);

    // New-bin candidate: discourage opening a new bin unless current item is large
    // relative to capacity (smooth, no piecewise constants)
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / cap;
        score = cap + 10.0 * (1.0 - load_ratio) - 4.0 * progress;
        if fitting_bins_count == 1 {
            score += 20.0; // never open new bin when an existing bin is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction bands.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space band: residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Sweet-spot bands (residual likely reusable): reward low post_residual in [10, 40].
    if post_residual >= 10 && post_residual <= 40 {
        score -= 12.0;
    }

    // Modulo-10 harmonic class of post_residual: multiples of 10 are "harmonic" slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual > 0 {
        // Off-harmonic residual: penalize proportional to distance from lower multiple of 10.
        let dist = post_residual % 10;
        score += dist as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue: mild reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - tight * 0.3;
        } else {
            // next item cannot use this bin's residue: penalize large unusable residue
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline attractiveness only when
    // open bins would create bad fits (large post_residual waste).
    if bin_residual == bin_capacity {
        // Neutral-ish score: slightly worse than a tight fit, better than terrible fits.
        score = cap - item_size as f64; // = post_residual for empty bin anyway
        score += 5.0; // mild bias toward filling existing bins when fits are decent
        if item_size as f64 / cap > 0.7 {
            // Large item into fresh bin is natural: reward.
            score -= 15.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    // Many open bins: encourage filling rather than spreading.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean (already tight), reward.
    let dev = mean_residual - bin_residual as f64;
    score += dev.max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.88;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact fill.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to how snugly it fits.
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for the next item.
            // Penalize more when the dead space is large (unusable).
            score += 30.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: only current fill matters; already covered by post_residual.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is
    // below average (tighter bin) is preferred to keep large residuals open.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or many bins are open and fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size as f64 > 0.75 * bin_capacity as f64 {
            score -= 50.0; // huge item: fresh bin is fine
        }
        if open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 120.0; // nothing fits anywhere, must open
        }
    }

    // Late in the stream, consolidation matters more: tighten scoring.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) wins.
    // Normalize dead space relative to capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, higher = tighter
    score -= 2.0 * fit_ratio * post; // reward bins where item fills a large fraction

    // Penalize post_residual that is small-but-unusable relative to typical item sizes.
    // Dead space in (0, 10) is nearly unusable; in [10, 30) it's marginal.
    if post > 0.0 {
        if post < 10.0 {
            score += 15.0; // tiny sliver: wasted capacity
        } else if post < 30.0 {
            score += 5.0;
        }
    }

    // Lookahead coupling: if the next item could use the post_residual, reward leaving it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // leftover is useful for the known next item -> reward proportionally
            let usefulness = 1.0 - ((post - nxt) / cap);
            score -= 8.0 * usefulness;
        } else {
            // leftover too small for next item -> penalize creating dead space
            score += 6.0;
        }
    } else {
        // Last item: prefer the bin that ends with the least waste overall.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It naturally has a large post_residual; add a mild extra penalty so that
    // opening a new bin only wins when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Global state: many open bins with slack -> prefer consolidating into existing bins.
    let slack_pressure = open_bins_count as f64 * (mean_residual / cap);
    score += 2.0 * slack_pressure * (post / cap);

    // Time horizon: late in the stream, avoid opening new bins and prefer filling bins
    // as tightly as possible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post / cap);

    // Small tie-breaker toward bins with below-average residual (more filled bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate
    // slightly larger residuals since bins are already committed.
    let progress_coupling = pr * (0.25 + 0.75 * progress * progress);

    // Penalty for dead space that is too small to be useful later.
    // Smoothly ramped: residuals below ~1/3 of capacity are increasingly bad.
    let dead_zone = {
        let x = (cap * 0.35 - pr).max(0.0) / cap;
        18.0 * x * x
    };

    // Perfect-fit reward: smooth peak at post_residual == 0.
    let perfect = -14.0 * (-pr / 6.0).exp();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (penalize new-bin candidate implicitly).
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // New-bin candidate: post_residual == bin_residual == capacity.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    let new_bin_penalty = if is_new_bin {
        // Opening a new bin is fine for big items or when nothing fits well,
        // but discouraged when a decent fit exists.
        10.0 + 20.0 * (1.0 - item_size as f64 / cap) - 15.0 * progress
    } else {
        0.0
    };

    // Lookahead: reward leaving a residual that still fits the next item.
    let lookahead = if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            -6.0 * (1.0 - pr / cap)
        } else {
            // Small residual unusable by next item: mild penalty.
            4.0 * (ns - pr) / cap
        }
    } else {
        0.0
    };

    // Divergence from mean residual: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and flexible), smooth quadratic term.
    let mean_coupling = 0.08 * (pr - mean_residual) * (pr - mean_residual) / cap;

    base + progress_coupling + dead_zone + perfect + last_chance + new_bin_penalty + lookahead + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: minimize post_residual, strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic classes: classify post_residual by modulo classes of common item sizes.
    // Residuals that are likely to be filled by future items (small classes) are good.
    let pr = post_residual;
    if pr > 0 {
        // Class A: residual divisible into common chunks (multiples of 10/20)
        if pr % 10 == 0 {
            score -= 4.0;
        }
        if pr % 20 == 0 {
            score -= 3.0;
        }
        // Class B: residual is a "dead" odd size unlikely to be matched
        if pr < 10 {
            score += (10 - pr) as f64 * 0.8; // dead space penalty grows as residual shrinks below 10
        }
        // Integer-division thresholds: residual in [11,19] is awkward (fits nothing common)
        if (11..20).contains(&pr) {
            score += 2.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.3;
        } else {
            // next item won't fit here; slight penalty for wasting this bin's potential
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // existing bins unless the fit is poor. The penalty decays as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 - 6.0 * progress;
        // Opening a new bin is better when many bins are open with high mean residual
        // (fragmentation) — allow new bin then.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 8.0;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Mild preference to fill bins with low residual first (consolidate fragmentation).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Prefer bins when many alternatives exist (keep flexibility elsewhere).
    if fitting_bins_count > 2 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (they become waste).
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual is naturally close to the item size
    // (tight fit relative to what the bin offers).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= tightness * 0.5;

    // Last chance: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item would fit better in a fresh bin than here.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation
    // into existing bins; a fresh empty bin should be less attractive
    // unless the fit is poor elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure from open bins.
        score += 15.0 + open_bins_count as f64 * 4.0;
        // But if mean residual is large (existing bins are roomy),
        // opening a new bin is less costly relative to wasting space.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening new bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 20.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild bonus for bins below mean residual (balancing load across bins).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) but punish near-zero dead space
    // that can never host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward a bin whose post_residual exactly or closely
    // matches the next item size (chains two items into one bin).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strong reward, tighter match = better.
            score -= 18.0 * (1.0 - diff / (bin_capacity as f64));
            if diff == 0.0 {
                score -= 15.0; // perfect two-item chain
            }
        } else {
            // Post-residual too small for the next item: mild penalty for
            // leaving space that the lookahead cannot use.
            score += 4.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // looser; prefer packing into bins already below-average residual so
    // large-capacity bins stay available for big future items.
    let rel = bin_residual as f64 - mean_residual;
    score += 0.08 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open new bin
        } else if fill_ratio > 0.6 {
            // Large item: fresh bin keeps flexibility, moderate discount.
            score -= 6.0 * fill_ratio;
        } else {
            // Small item into a fresh bin wastes capacity: penalize.
            score += 20.0 * (1.0 - fill_ratio);
        }
    }

    // Mild stream-phase adaptation: early on, keep bins open and flexible;
    // late in the stream, pack aggressively (tight fits matter more).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * phase * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + 0.5 * open_bins_count as f64;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space that next item can still use.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_match = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack_match / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize proportionally.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from the mean residual (imbalance in open-bin pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild bonus for using bins with larger residuals when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 40.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 12.0 * (1.0 - post_residual as f64 / nxt.max(1.0)) * (1.0 - 0.5 * progress);
        } else {
            // Reward leaving space exactly usable by next item.
            let fit_quality = 1.0 - ((post_residual as f64 - nxt) / cap);
            score -= 8.0 * fit_quality * fit_quality;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Deter spreading across many open bins when mean residual is small.
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap);

    // Smoothly discourage opening a new bin as the stream progresses,
    // unless residual is genuinely tight (interaction term).
    let new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin {
        score += 10.0 + 30.0 * (1.0 - progress) * (1.0 - tightness);
        // Allow new bin when existing bins would leave large unusable gaps.
        if post_residual as f64 > 0.35 * cap {
            score -= 15.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits rewarded (harmonic residue classes)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Classify post_residual into harmonic bands via integer division
    let band = post_residual / 10; // 0..=10
    score += band as f64 * 6.0;

    // Small dead space (< smallest item, 10) is unusable: strong penalty
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // Next-item coupling: reward leaving residue that fits next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 90.0;
            } else if slack <= 10 {
                score -= 30.0;
            } else {
                score += slack as f64 * 0.4;
            }
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate: neutral-ish score; prefer it only when existing bins fit poorly
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        if post_residual == 0 { score -= 5.0; }
        if fitting_bins_count == 1 { score += 120.0; } // keep using the last bin instead
        if next_item_size > 0 && next_item_size >= item_size && post_residual < next_item_size {
            score -= 20.0; // fresh bin may serve the upcoming item
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Mean residual context: if this bin is far below mean residual, it's a good filler
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Modulo tie-breaking on residual classes (harmonic spacing)
    score += (post_residual % 7) as f64 * 0.5;
    score -= (next_item_size % 5) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be usable
    // by typical future items are heavily penalized (wasted capacity).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual <= 20 {
            score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        } else {
            // Larger leftovers are partially reusable; mild penalty decaying with size.
            score += 4.0 * 20.0 / post_residual as f64;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to the current residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading; penalize slightly per open bin.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and the lookahead item is also large, so the
    // fresh capacity can be used efficiently.
    if bin_residual == bin_capacity {
        let base = 60.0;
        let item_need = item_size as f64 / bin_capacity as f64;
        let lookahead_need = if next_item_size > 0 { next_item_size as f64 / bin_capacity as f64 } else { 0.0 };
        score = base - 20.0 * item_need - 15.0 * lookahead_need;
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open already, opening another is costly.
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead synergy: if the next item exactly matches this bin's
    // post_residual, reward keeping that space available (don't waste it on
    // a loose fit now).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // Penalize if this placement leaves a gap the next item just barely
    // misses (dead space from the lookahead's perspective).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild nudge toward bins whose residual is near the mean (balanced load).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap <= 5 {
            score -= 55.0;
        } else if gap <= 15 {
            score -= 20.0;
        } else {
            // Penalize leaving residual that no plausible item can use.
            if post_residual < 10 && post_residual > 0 {
                score += 30.0;
            }
        }
        // If next item won't fit this bin after placement, mild penalty.
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // But if the only fitting bin would leave big dead space, new bin is fine.
        if post_residual == bin_capacity - item_size {
            if item_size >= 60 {
                score -= 30.0; // big item into fresh bin is good
            }
            if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size > post_residual {
                score -= 25.0;
            }
        }
        // Later in the stream, be more willing to open bins (spread residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight preference for more-filled bins overall.
    score += 0.15 * (bin_residual as f64 - (bin_capacity as f64 - item_size as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates the ranking.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(3) * 2.0;

    // Penalize wasteful dead space relative to the item size.
    let dead = post_residual as f64 / item_size.max(1) as f64;
    score += dead * dead * 5.0;

    // Lookahead: bonus if the next item can pair into post_residual (perfect chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + next_item_size as f64 / 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Small unusable residual but next item is big: mild penalty.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // no open bin well (post_residual in a fresh bin is huge anyway, but
    // make the threshold explicit and state-aware).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        let mut penalty = 20.0 + crowd * 2.0 + (1.0 - progress) * 10.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        penalty += (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
        // If many bins already fit the item, opening a new one is clearly bad.
        penalty += (fitting_bins_count as f64) * 6.0;
        // If the next item is large and would never fit leftovers, a fresh bin
        // can be reasonable: soften the penalty.
        if next_item_size >= item_size && next_item_size > 60 {
            penalty *= 0.6;
        }
        score += penalty;
    }

    // Mild preference for balancing load across many open bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual, non-linearly.
    let tightness = 1.0 - (post / cap);
    score -= 60.0 * tightness * tightness * tightness;

    // Dead-space penalty for residuals too small to be reusable later.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let best_existing = if fitting_bins_count > 0 { post } else { cap };
        let waste_threshold = cap * 0.35;
        if fitting_bins_count > 0 {
            // Penalize new bin mildly; more so early in the stream.
            score += 15.0 + 30.0 * (1.0 - progress);
            // If item fits an open bin with reasonable tightness, discourage new bin.
            if item_size as f64 >= waste_threshold {
                score += 20.0;
            }
        } else {
            score -= 10.0;
        }
        let _ = best_existing;
    }

    // Lookahead coupling: if next item can use the post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 18.0 * (1.0 - slack * slack);
        } else if post > 0.0 {
            // post_residual too small for next item: penalize proportionally.
            score += 12.0 * (1.0 - post / cap);
        }
    }

    // Mean-residual context: prefer bins below mean residual (concentrate fill).
    if bin_residual != bin_capacity {
        let dev = (residual - mean_residual) / cap;
        score += 8.0 * dev;
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Smooth non-linear coupling of post_residual with progress.
    score += 10.0 * (post / cap) * (1.0 - (post / cap)) * (progress - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "small"
    // residue classes relative to capacity quarters are more valuable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = post_residual / quarter; // 0..=4 harmonic class
    match cls {
        0 => score -= 12.0,                       // nearly full: excellent
        1 => score -= 6.0,                        // leftover <= quarter
        2 => { if post_residual == half { score -= 4.0; } } // exact half keeps symmetry
        3 => score += 6.0,                        // awkward large leftover
        _ => {}
    }

    // Exact-divisibility bonuses: leftover that divides evenly into
    // plausible item sizes is reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this leftover: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly prefer filling it rather than opening new.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when this bin is a bad fit
    // (large post_residual waste) or few alternatives exist.
    if bin_residual == bin_capacity {
        score = post_residual as f64; // = capacity
        // Base penalty for opening a new bin.
        score += 15.0;
        // Relax penalty late in stream or when bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        if mean_residual < (bin_capacity as f64) * 0.25 {
            score -= 8.0; // open bins are nearly full; new bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open
        }
    }

    // Mild preference to consolidate across many open bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to host typical
    // future items are heavily penalized.
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    }

    // Reward large leftover space (flexibility for future items).
    score -= (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Tight fit reward: fraction of residual consumed by the item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving a gap that blocks it
            score += 5.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bin residuals are badly fragmented or item barely fits nowhere well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If many bins fit the item, opening new bin is wasteful.
        score += fitting_bins_count as f64 * 10.0;
        // If mean residual is large and fragmented, new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // Late in stream, prefer compacting into existing bins.
        score += progress * 15.0;
        // If next item is large, a fresh bin gives it room.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-perfect 2-step match (small slack left for the next item).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }

    // Penalize leaving residual that no plausibly-arriving item can use
    // (dead space below the minimum item size of 10... but sizes go down to 1,
    // so weight small residuals relative to mean residual instead).
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 8.0;
    }

    // Last chance: only this bin fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when the item fits an existing bin well
    // (new bin has residual == capacity; discourage unless current bin leaves big waste).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        // Allow new bin if it would be a perfect 2-step match anyway.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Early in the stream, having few bins, opening is cheaper.
        if open_bins_count <= 2 {
            score -= 6.0;
        }
    }

    // Mild preference for tighter existing fits (smaller post_residual already
    // dominates, but reward high fill ratio slightly).
    score -= (item_size as f64 / bin_capacity as f64) * 3.0;

    // Progression: later in stream, be more conservative about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; leftover is dead unless tiny.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing ones rather than opening more.
    score += 0.15 * open_bins_count as f64;

    // Relative residual vs mean: prefer bins with less residual (more filled).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more conservative (favor tight fits
    // to keep flexibility); late in the stream, just pack densely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // New-bin candidate: make it moderately attractive only when the item
    // would leave a large post_residual in every open bin, or when few bins
    // are open. Otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let mut nb = 45.0;
        // Attractive if current bin would be badly fragmented.
        if post_residual >= 40 { nb -= 25.0; }
        if open_bins_count == 0 { nb -= 45.0; }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            nb -= 20.0;
        }
        // Late stream: avoid opening bins unnecessarily.
        nb += 20.0 * progress;
        score = score.min(score) + 0.0; // keep base comparison
        return nb + score * 0.0 + post_residual as f64 * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus shrinking score as post_residual -> 0
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead / cap).powi(2) * cap;
    }

    // Smooth non-linear coupling with stream progress: later in the stream,
    // prefer using existing bins more aggressively (pack tighter).
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / cap);

    // Last-chance bin: strongly favor it to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // mild penalty per competing bin to prefer best-fit among many
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual as u32 {
        // post-residual likely dead space for next item
        score += 2.0 * (post_residual as f64 / cap);
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // allowed late when open bins have large residuals (poor fits).
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / cap;
        score = cap * 0.6 + 10.0 * open_pressure - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible into coarse chunks
    // is more reusable than awkward remainders.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward small post_residual (tight fit) super-linearly.
    score -= 40.0 * (1.0 - frac).powi(3);

    // Modulo-10 harmonic class of the leftover: multiples of 10 are "clean" classes.
    let class = post_residual % 10;
    score += class as f64 * 0.8;

    // Leftovers in a "good" harmonic band (10..=30) are highly reusable.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another awkward gap
            let nxt_post = post_residual - next_item_size;
            score += nxt_post as f64 * 0.3;
            if nxt_post % 10 == 0 && nxt_post > 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless leftovers are hopeless.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if all open bins would leave tiny dead space, allow new bin.
        if fitting_bins_count > 0 {
            let tight = post_residual == 0; // empty bin always leaves full residual; neutral
            let _ = tight;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.2 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, be greedier: minimize post_residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - frac);

    // Integer-division threshold: leftover that can hold at most one more
    // medium item (<=50) is nearly dead if next item is large.
    if post_residual < 50 && next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score *= 1.0;

    // Penalize "dead space": gaps too small to be useful later.
    // A residual gap is dead if smaller than the minimum plausible item (say 1..10)
    // or smaller than a typical item chunk. Treat gap < 10 as fully dead.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0; // dead space penalty: this bin becomes useless
    } else if gap < 20.0 {
        score += 25.0 * (1.0 - gap / 20.0); // semi-dead zone
    }

    // Reward near-perfect fits strongly.
    if gap == 0.0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into the resulting gap, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0; // gap remains usable
        } else {
            score += 15.0; // next item won't fit here -> gap likely wasted
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Opening a new bin is attractive when the item fits poorly everywhere;
    // make the new bin score neutral-to-slightly-high so it only wins when
    // existing fits are penalized (dead space / wasted lookahead).
    if bin_residual == bin_capacity {
        // Mild penalty so tight fits into open bins still win,
        // but poor fits (dead space penalties above) lose to a fresh bin.
        score += 20.0;
        // Pressure: many open bins -> discourage opening more.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (mild, to avoid bin proliferation).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: if this bin is far below mean residual (already tight),
    // slightly discourage; bins with large residual should absorb items.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New empty bin candidate: penalize so it's only chosen when open bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; lower when the item is large (good use of fresh space).
        score = bin_capacity as f64 + 25.0 - item_size as f64 * 0.3;
        // If the next item would fit perfectly in the leftover, opening is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // When this bin is the ONLY fitting option, opening a bin is far preferable.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        if pr == ni {
            score -= 30.0; // perfect chaining: next item fills this bin exactly
        } else if pr >= ni {
            score -= 10.0 - ((pr - ni) as f64 * 0.15); // next item still fits, mild reward
        } else {
            // leftover too small for the next item: penalize proportional to mismatch
            score += (ni - pr) as f64 * 0.25;
        }
    }

    // Dead-space penalty: residuals below the minimum item size are wasted.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than average (better consolidation).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Slight preference for filling bins early in the stream to keep many bins open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that likely cannot be reused by the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward if the next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let mut nb = 20.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 {
            // A fresh bin is more attractive when the next item is large,
            // since a fresh bin can host it fully.
            if next_item_size as f64 > mean_residual {
                nb -= 6.0;
            } else {
                nb += 4.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * progress;
        score += nb;
    }

    // Mild pressure to prefer bins with residual already below mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Prefer filling nearly-full bins harder as the stream progresses.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: reward tight fit via non-linear decay of post_residual.
    let mut score = 1.0 - (-norm_pr * 3.0).exp();

    // Smooth polynomial coupling: post_residual^2 grows penalty, modulated by progress.
    score += 0.8 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction: dead space is worse later in the stream.
    score += 0.5 * norm_pr.powi(3) * progress;

    // Reward filling a bin deeply (small residual relative to item placed).
    score -= 0.6 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus: strongly prefer the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else {
        // Slight preference when few bins can fit (avoid scattering).
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize if post_residual cannot fit the next item while a new bin could.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if pr < nx {
            score += 0.4 * (nx - pr);
        } else {
            score -= 0.2 * (1.0 - (nx - pr).abs());
        }
    }

    // Stream-progress coupling with mean residual: late stream, tighten everything.
    score += 0.3 * progress * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: penalize mildly early, more later (prefer consolidation).
    if bin_residual == bin_capacity {
        score += 0.5 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Prefer post_residuals that are multiples of common item sizes (harmonic fit)
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect fill
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -6.0
    } else if post_residual % 25 == 0 {
        -10.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space: small but nonzero post_residual
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

