        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 25.0; // open bins nearly full -> new bin good
        }
    }

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.3;
        }
    }

    // Integer-division threshold on post_residual classes
    let class = post_residual / 20; // 0..5 classes
    score += class as f64 * 2.0;

    // Slight preference to fill bins with larger residual first (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    // Progress coupling: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual coupling: keep residuals balanced
    score += (mean_residual - post).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let mut score = r;

    // Perfect fit: overwhelming reward (no dead space created at all).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: a tiny leftover gap (sliver) is almost
    // certainly unusable by future items -> heavy penalty, growing as the
    // stream progresses (late waste can never be repaired).
    if post_residual > 0 && post_residual < 10 {
        let severity = if next_item_size > 0 { 1.0 } else { 0.3 };
        score += (40.0 + 40.0 * progress) * severity;
    }

    // Lookahead coupling (k=2): judge the gap by whether the next item can use it.
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as f64;
        if n > r {
            // Gap is dead with respect to the lookahead item.
            score += 0.25 * r * (0.5 + progress);
        } else if n == r {
            // Sets up a perfect fit on the next step: strong reward.
            score -= 250.0;
        } else {
            // Gap will likely be partially reused: mild reward.
            score -= 0.35 * n;
        }
    }

    // Last-chance pressure: if this is the only open bin that fits the item,
    // using it avoids opening a new bin (never reward the fresh-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0 + 50.0 * progress;
