    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with pressure from the number of open
        // bins and with stream progression (reluctance to spawn bins late).
        score += 30.0 + 3.0 * open_bins_count as f64 + 25.0 * progress;
    } else {
        // Mild tie-breaker: slightly prefer bins that are tighter than the
        // current mean residual (consolidation tendency).
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.02 * dev;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
