    }

    if is_new_bin {
        // Opening a new bin carries a cost that grows as the stream progresses
        score += 14.0 + 18.0 * progress;
        if fitting_bins_count == 0 {
            // No open bin can take the item: new bin is effectively forced
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly prefer the only open bin that fits,
        // avoiding an unnecessary new bin
        score -= 22.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact-fit reward: leaving almost nothing behind is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this is a chain placement — reward it heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // If next item cannot fit here anyway, mild penalty for wasting lookahead room.
        if post_residual < next_item_size && post_residual > 0 {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so that any decent existing fit wins.
        score += 30.0;
        // But if the item leaves a large awkward residual in a new bin anyway,
        // and there are many open bins, discourage opening yet another bin.
        if open_bins_count > 3 {
            score += 5.0 * (open_bins_count as f64).ln();
        }
        // Early in the stream, opening bins is cheap (parallelism useful).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean residual (consolidate fullness).
    if !is_new_bin {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Mild penalty per open bin to discourage bin proliferation indirectly.
    score += 0.5 * open_bins_count as f64;

    // Slight time-varying exploration term (deterministic, grounded in step_index).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Tight fits are rewarded more strongly later in the stream
    score -= (1.0 - norm_pr).powi(2) * cap * (0.5 + t);
    // Penalize dead space that cannot fit a typical next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let waste = (pr - nxt).max(0.0);
        score += waste * (0.2 + 0.3 * norm_pr);
        // Reward leaving room exactly for the next item
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap).powi(3);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * t;
    }
    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * (1.0 - norm_pr) * 0.5;
    // New-bin candidate: prefer it only when it offers perfect future packing
    if bin_residual == bin_capacity {
        score = cap - 0.5 * pr + 15.0 * (1.0 - t) + if nxt > 0.0 { (nxt / cap) * 10.0 } else { 0.0 };
    }
    // Smooth non-linear coupling of residual with stream progress
    score += 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - 2.0 * t).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form tight pairings are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_fraction = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill fraction (quadratic bonus).
    score -= 40.0 * fill_fraction * fill_fraction;

    // Harmonic residue classes: post_residual in {0..5} is a near-perfect close.
    let residue = post_residual % 10;
    match residue {
        0 => score -= 25.0,
        1 | 2 | 3 => score -= 12.0,
        4 | 5 | 6 => score -= 4.0,
        _ => score += 6.0, // 7..9: awkward dead space
    }

    // Lookahead harmony: can next_item_size land exactly (or near) in the gap?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
            // Perfect harmonic pair: post_residual == next_item_size
            if post_residual == next_item_size as u32 {
                score -= 30.0;
            }
            // Integer-division harmony: gap divides next item into k>=1 chunks
            let k = post_residual / next_item_size.max(1);
            if k >= 2 {
                score -= 8.0 * (k.min(4) as f64);
            }
        } else {
            // Next item cannot fit here: mild penalty scaled by overflow size
            score += 0.15 * (ni - pr).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): post_residual == bin_capacity.
    // Penalize it so it only wins when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening fresh bins is less wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * progress;
        // If many bins are open, prefer consolidating into them.
        score += 1.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins deviating below mean (tighten tightest bins).
    score += 0.25 * (mean_residual - pr).max(-60.0).min(60.0);

    // Tiny penalty on very small absolute waste to break ties toward exact fits.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space: a gap smaller than the minimum item size (1) is unusable.
    // Small non-zero gaps are tolerable, but any gap that no item can ever
    // fill is pure loss, so nudge such placements slightly worse than
    // equally-sized usable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Lookahead (k=2): reward gaps that can still host the next item,
    // penalize gaps that are large enough to be "wasted" but too small
    // for the incoming item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 0.6 * next_item_size as f64;
        } else if post_residual >= next_item_size.min(10) && post_residual >= 10 {
            score += 1.5;
        }
    }

    if is_new_bin {
        // Opening a new bin wastes capacity: penalize, and more so when
        // many bins are already open (consolidation pressure).
        score += 10.0 + 0.08 * open_bins_count as f64;
    } else {
        // Favor packing into existing bins; pressure grows with bin count.
        score -= 0.15 * open_bins_count as f64;

        // Last chance: this is the only bin that fits the item.
        // Placing here avoids opening a new bin — reward strongly.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Relative tightness bonus: the fuller the bin becomes, the better,
    // independent of absolute residual (couples with the base term).
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / tight fit reward: heavily favor bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Small dead space (< minimum item size) is nearly a perfect fit.
        score -= 25.0;
    }

    // 2-step lookahead: if the next item exactly fits the post_residual,
    // this placement sets up a perfect follow-up — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize wasted potential proportional
            // to how much of post_residual is unusable for the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }

        // Chain bonus: current item + next item almost fill the bin.
        let two_step = (item_size + next_item_size) as f64;
        if two_step >= bin_residual as f64 {
            score -= 10.0;
        }
    }

    // Compare against mean residual: bins with residual below mean are "tight"
    // candidates; using them keeps loose bins available for awkward items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: an empty bin should only win when no open bin
    // gives a good fit. Penalize the empty bin by default, but relax the
    // penalty when the item would leave large dead space in every fitting bin.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let relief = 25.0 * large_item;
        // If few bins fit and post_residual would be big, opening fresh helps.
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (post_residual as f64) / (bin_capacity as f64)
        } else {
            0.0
        };
        score += base_penalty - relief - 20.0 * poor_fit_elsewhere;
    }

    // Late-stream pressure: as the stream progresses, consolidate into open
    // bins more aggressively to avoid leaving many partially-filled bins.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    // Mild penalty for proliferating bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: small post_residual is best.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * (1.0 - tight * tight);

    // Penalize leaving awkward dead space (small but nonzero leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current bins would leave very poor fits or are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_existing = (bin_residual - item_size) as f64 > 0.0
            && (bin_residual - item_size) < 10;
        // Prefer new bin when few bins open or late in stream with bad fits elsewhere.
        let bias = 20.0 + 15.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if poor_fit_existing || fitting_bins_count == 0 {
            score -= 10.0; // new bin is fine
        } else {
            score += bias; // discourage wasteful new bins
        }
        // Empty bin has zero waste; keep baseline comparison fair.
        score -= 5.0;
    }

    // Global state coupling: when mean residual is high, prefer packing into
    // existing capacity rather than fragmenting.
    if mean_residual > (item_size as f64) * 1.5 {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Mild time-horizon term: early on, keep bins flexible (avoid over-tight);
    // later, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    } else if progress > 0.7 {
        score -= 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap (many future items may fill gaps); late, waste is costly.
    let waste_weight = 0.5 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress) * post / cap;
    score += waste_weight * (post / cap) * (post / cap) * cap * 0.35;

    // Reward tight fits (small post_residual) with smooth decay.
    let fit_ratio = 1.0 - (post / cap);
    score -= 12.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use (sizes >= 1).
    if post > 0.0 && post < 1.0 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty so crowded competition doesn't dominate; spread load.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits in post_residual, reward leaving a usable gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack_fit = 1.0 - ((post - nxt) / cap).abs();
            score -= 10.0 + 8.0 * slack_fit * progress;
        } else {
            // Next item won't fit here; penalize gaps slightly smaller than next item.
            score += 4.0 * (1.0 - (nxt - post) / cap) * (0.5 + progress);
        }
    }

    // New-bin candidate handling: penalize opening a bin unless current bin is a poor fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin, reduced when existing bins are nearly full.
        let mean_r_norm = mean_residual / cap;
        score += 30.0 - 20.0 * (1.0 - mean_r_norm) * (1.0 - mean_r_norm);
        // Late in stream, prefer closing out bins rather than opening more.
        score += 10.0 * progress;
        if fitting_bins_count == 1 {
            // Never open a new bin when a last-chance bin exists.
            score += 100.0;
        }
    }

    // Mild preference to balance load across open bins.
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // Smooth normalization penalty on residual vs mean residual deviation.
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small nonzero residuals are nearly unusable
    // (items are >= 1, but tiny leftovers waste capacity).
    if post_residual > 0 {
        let dead_zone = 6u32;
        if post_residual <= dead_zone {
            score += 60.0 * (dead_zone - post_residual + 1) as f64;
        }
    }

    // Harmonic class logic: residuals divisible by 10 align with
    // typical item sizes (multiples of 10), making them reusable.
    let class = post_residual % 10;
    score += class as f64 * 4.0;

    // Residuals that exactly match the lookahead item size are prime:
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // Residual that fits next item comfortably (class match with slack).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }
    // Residual too small for the next item: it becomes dead space soon.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (pristine bin): only attractive when existing
    // bins would leave bad fits or when bins are crowded.
    if bin_residual == bin_capacity {
        let base = 45.0;
        // Cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + 40.0 * progress + 5.0 * open_bins_count as f64;
        if post_residual == bin_capacity {
            score -= 10.0; // neutral-ish; real bins with good fits beat it
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big lookahead item: fresh bin useful
        }
    }

    // Tie-breaking toward tighter bins when residuals are close.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Semi-usable gap: moderate penalty scaled by how far from usable.
        score += (25 - post_residual) as f64 * 0.8;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fills (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open-bin pressure: penalize creating/using bins when many are open,
    // but favor filling existing bins when bin count is high.
    if bin_residual != bin_capacity {
        // Existing bin: reward using it, more so under high open-bin pressure.
        score -= 5.0 + open_bins_count as f64 * 0.5;
    } else {
        // New-bin candidate: penalize unless few bins open or item is large.
        score += 10.0 + open_bins_count as f64 * -0.3;
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps a balanced pool of gaps for future items).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.2;

    // Early stream: be less picky; late stream: tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize mildly so we only open a new bin when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a bin is attractive if next item is large and current post_residual can't hold it.
        if next_item_size > post_residual {
            score -= 20.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect follow-up fit: strong reward.
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // Dead space: post_residual too small for the next item and below min item size.
        if post_residual < next_item_size && post_residual < 10 {
            score += 35.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Reward last-chance bins (only fitting bin) to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (pack into emptier-of-space bins),
    // keeping larger residuals for future big items.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for leaving little dead space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Perfect / near-perfect fill reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item can also fit in the leftover space
    // (chains items into the same bin); penalize leftovers that fit nothing.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 && (post_residual as u32) < 10 {
            // dead space too small for any realistic item
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins among many open bins (best-fit-like pressure).
    score -= 0.3 * (1.0 - (bin_residual as f64) / cap) * (open_bins_count as f64).sqrt();

    // Penalize bins whose residual is far above the mean (avoid hoarding space
    // in nearly-empty bins when tighter options exist).
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0);

    // New-bin candidate: default penalty so a fresh bin is opened only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening bins is riskier (waste carries to the end).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If nothing else fits, the new bin must be chosen regardless.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: be slightly more willing to spread items (keeps flexible
    // residuals for future large items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on post_residual (dead space grows quadratically).
    let mut score = post * post / cap;

    // Smooth cubic coupling: large residuals late in the stream are increasingly bad.
    score += (post / cap).powi(3) * cap * (0.5 + progress);

    // Reward tight fills: interaction between item size and post residual.
    score -= (item / cap) * (cap - post) * 0.35;

    // Last chance bin: strong reward so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Discard fragmentation relative to mean residual: bins far below mean waste capacity.
    score += 0.15 * (mean_residual - res).max(0.0);

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = (res - cap).abs() < 1e-9;
    if is_new_bin {
        // Penalize opening a new bin; relax as stream progresses and when few alternatives.
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        score = cap * 0.9 - 30.0 * progress * scarcity - 12.0 * scarcity;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: how the leftover space decomposes
    // into capacity-fraction buckets. Residues that align with common item
    // classes (multiples of 10/20) are more reusable -> reward them.
    let post_u = post_residual;
    let harmonic_bucket = (post_u / 10).min(10) as f64;
    let harmonic_align = if post_u % 10 == 0 { 6.0 } else { 0.0 };
    if post_u > 0 {
        score -= harmonic_align + harmonic_bucket * 0.4;
    }

    // Tight fits are excellent: strong reward as post_residual approaches 0.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 18.0;

    // Perfect fill gets a big bonus.
    if post_u == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that is too small for the smallest plausible
    // next item (harmonic class floor of 1..=10). Tiny unusable slivers hurt.
    if post_u > 0 && post_u < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item's harmonic class (integer division
    // by 10) matches the post-residual's class, this bin is likely reusable.
    if next_item_size > 0 && next_item_size <= post_u {
        let next_class = (next_item_size / 10).max(1) as f64;
        let post_class = (post_u / 10).max(1) as f64;
        let class_match = (next_class - post_class).abs();
        score -= (1.0 / class_match.max(1.0)) * 7.0;
        // Exact next-fit bonus
        if next_item_size == post_u {
            score -= 12.0;
        }
    } else if next_item_size > post_u && post_u > 0 {
        // Next item cannot use this leftover: mild penalty for stranded space.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is wasteful while good
    // open bins exist, unless the current item is large and residuals are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        // Penalize new bins when existing bins are roomy or many bins are open.
        score += 14.0 + open_bins_count as f64 * 0.6 + pressure * 10.0;
        // Late in the stream, or when the item is huge (little would be left
        // anywhere), a fresh bin is more acceptable: reduce the penalty.
        let large_item_bonus = if item_size >= 60 { 10.0 } else { 0.0 };
        score -= large_item_bonus + progress * 6.0;
        // Harmonic check: an empty bin wastes its full harmonic range; if the
        // item is small, that waste is severe.
        let waste = (cap - item_size as f64) / cap;
        score += waste * 6.0;
    }

    // Mild global congestion term: spread load when many bins compete.
    score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit even the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // hard penalty for unusable slivers
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Tight fit bonus: reward placements leaving small but still usable gaps.
    if post_residual > 0 && post_residual <= 20 {
        score -= 12.0;
    }

    // Prefer bins whose residual matches the item closely (low fragmentation).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Lookahead coupling: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by this placement, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or mean residual is too small to be useful for future items.
    if bin_residual == bin_capacity {
        let mean_useful = mean_residual;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else if mean_useful < 25.0 || fitting_bins_count == 0 {
            score -= 20.0; // open bins nearly useless, fresh bin is fine
        } else {
            score += 35.0; // prefer existing bins generally
        }
        // Late in stream, opening new bins is less costly than hoarding dead space.
        if progress > 0.7 && post_residual == bin_capacity as f64 as u32 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits exactly into the leftover space left after the following placement
    // (2-step chain fit): post_residual - next_item_size leaves another usable chunk.
    if next_item_size > 0 && post_residual > next_item_size {
        let chain_left = post_residual - next_item_size;
        if chain_left >= 10 {
            score -= 12.0;
        }
    }

    // Penalize dead space: leftover too small for the next item (likely wasted).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Penalize very tight but unusable leftovers relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.3 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the current item is large relative to
    // capacity or open bins are all fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let tight_bins = mean_residual < item_size as f64;
        if tight_bins {
            score -= 15.0;
        } else {
            score += 20.0; // discourage opening new bins when fits exist
        }
    }

    // Early in the stream, keep bins open and flexible (avoid fragmenting early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; leftover becomes dead space
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good existing option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 + 20.0 * progress;

        // If only this new bin fits, we must open it.
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Global pressure: many open bins with high mean residual -> prefer using
    // existing capacity rather than fragmenting further.
    score += mean_residual * 0.05;
    if open_bins_count > 8 {
        score -= 5.0; // encourage consolidating into existing bins
    }

    // Slight preference for bins whose residual is close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: normalized post residual with quadratic coupling to progress
    let mut score = fit_frac * (1.0 + 1.5 * progress + 0.8 * progress * progress);

    // Non-linear dead-space penalty: residual below typical next item becomes costly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let unusable = ((nxt - post) / cap).max(0.0);
        let waste_term = unusable * unusable * 40.0 * (1.0 - progress * 0.5);
        score += waste_term;
        // Reward if post_residual exactly accommodates next item smoothly
        let match_term = 1.0 - ((post - nxt).abs() / cap);
        if match_term > 0.0 {
            score -= 3.0 * match_term * match_term * (1.0 + progress);
        }
    }

    // Last-chance bin bonus (smoothly weighted by fitting scarcity)
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 + 0.5 * progress);
    } else {
        score -= 2.0 / (fitting_bins_count as f64);
    }

    // Penalize bins far from mean residual (fragmentation of packing structure)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: smooth penalty that relaxes when existing fits are poor
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (post_residual as u32 == bin_capacity - item_size);
    if is_new_bin {
        let fit_quality = fit_frac; // = (cap - item)/cap, high for small items
        let poor_fit_existing = if nxt > 0.0 {
            ((nxt - post).max(0.0) as f64) / cap
        } else {
            fit_quality
        };
        score += 8.0 + 25.0 * fit_quality - 30.0 * poor_fit_existing * (1.0 + progress);
    }

    // Mild reward for tightening packing as stream progresses
    score -= (item_size as f64 / cap) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals divisible by large chunk sizes are more likely to host future items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fit, excellent
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 // awkward residual
    };
    score += harmonic_bonus;

    // Penalize residuals below the minimum item size (dead space), unless zero.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize more if residual is small and stranded
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we prefer
    // reusing open bins with good fits, but not when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    // Mild pressure toward consolidating into bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Progress-based tightening: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100 - post_residual.min(100)) as f64 * 0.05;

    // Integer-division threshold: reward placing into bins where item fills >= half the residual.
    if item_size * 2 >= bin_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last chance bin before opening a new bin: strong bonus.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: fewer open bins favored, especially late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.5 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced use).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: make empty bin attractive only when current bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit {
            score -= 45.0; // opening new bin beats creating dead space
        } else {
            score += 20.0 + 3.0 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when the item
    // is large relative to capacity or no good fits exist; otherwise penalize.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 30.0 * fill_frac;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        return score;
    }

    // Perfect fit reward: post_residual exactly matches the next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits comfortably in the residual left behind (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(40.0) * 0.4;
    } else if next_item_size > 0 {
        // Dead space: next item cannot use what's left.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins that are already tight (below-average residual).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for packing into existing bins as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress);

    // Mild penalty for tiny unusable residuals.
    if post_residual < 10 {
        score -= 8.0; // near-perfect closure is excellent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
