    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0; // chain of perfect fits
        } else if (gap as f64) < 10.0 {
            score += 3.0; // next item leaves tiny unusable sliver
        } else {
            score -= 2.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here; leftover is dead space for the horizon
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is costly; only attractive
    // when open bins are congested (few fitting bins, high mean residual usage).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = if open_bins_count > 0 {
            1.0 - (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            0.0
        };
        // Base penalty for opening a new bin; shrinks when existing bins are tight
        // (congestion low) and many bins already fit the item poorly.
        let mut new_bin_penalty = 25.0;
        new_bin_penalty -= 10.0 * (1.0 - congestion);
        if fitting_bins_count > 1 {
            new_bin_penalty += 15.0; // plenty of alternatives; don't open
        }
        // Late in the stream, prefer consolidating into open bins.
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Slight preference for bins with residuals far from mean (diversity of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual, with a non-linear (quadratic) coupling
    // that grows as the stream progresses (tighten packing later in the stream).
    let mut score = pr * (1.0 + 1.5 * progress) + 0.008 * pr * pr * (0.5 + progress);

    // Normalized post-residual smooth interaction: penalize large fractions of
    // the bin left over, more strongly as progress increases.
    let pr_frac = pr / cap;
    score += 40.0 * pr_frac * pr_frac * (0.3 + progress);

    // Perfect fit reward (smooth, non-linear): strongly subtract when post_residual
    // is a small fraction of capacity.
    score -= 30.0 * (1.0 - pr_frac).powi(8) * (1.0 + progress);

    // Penalize wasting a large residual on a small item: coupling of fill ratio.
    let fill = item / cap;
    score -= 20.0 * fill * fill * (1.0 - pr_frac);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate penalty: opening a new bin should only win when the fit
    // into existing bins is terrible. A fresh bin has post_residual == capacity - item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 20.0 * (1.0 - progress) + 0.15 * mean_residual;
        // Allow new bin when item is large relative to capacity (hard to place later).
        score -= 30.0 * fill * fill;
    }

    // Lookahead coupling: if the next item could exactly use this bin's post
    // residual, reward leaving that residual (subtract).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        let match_frac = 1.0 - (diff / cap).min(1.0);
        score -= 18.0 * match_frac * match_frac * match_frac;
    }

    // Mild diversity pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small remainders are "dead space".
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable.
    let pr = post_residual;
    let reusable = (pr != 0) && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0);
    if reusable {
        score -= 8.0;
    }

    // Penalize odd/awkward remainders (non-multiples of 5 waste space).
    if pr % 5 != 0 {
        score += 5.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Extra reward for exact harmonic match.
        if pr == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > pr {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred when they fit well.
        score += 20.0;
        // If item is large relative to capacity, opening fresh is reasonable.
        if item_size as f64 > 0.6 * cap_f {
            score -= 25.0;
        }
        // Many open bins with high mean residual: consolidate instead.
        if open_bins_count > 0 && mean_residual > 0.5 * cap_f {
            score += 15.0;
        }
        // Early in stream, opening bins is cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 5.0;
        }
    }

    // Mild penalty for leaving fractionally mid-range residuals.
    if frac > 0.25 && frac < 0.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item are essentially wasted -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (nothing of size >=10 can fit).
            score += 60.0;
        } else if post_residual < 25 {
            // Small gap: only usable by tiny items; moderate penalty scaled
            // by how far below a comfortable threshold we are.
            score += (25.0 - post_residual as f64) * 1.5;
        }
    } else {
        // Perfect fill is highly desirable.
        score -= 40.0;
    }

    // Tight-fit reward: the less slack left relative to the item, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new bins; when few bins are open, allow more freedom.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and remaining
        // stream length so late in the stream we avoid opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + pressure * 8.0 + progress * 20.0;
        // If no open bin fits well, allow the new bin more readily.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Lookahead coupling: if the next item could use the post-residual gap,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Slight bonus for bins below mean residual (balancing residuals).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but don't blindly minimize.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead matching ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: bin becomes exactly filled by next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Small gaps after next item still good; decaying reward.
            score -= 25.0 * (-gap / 20.0).exp();
        } else {
            // Next item cannot fit here; penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // Last item: just prefer tightest fit.
        score -= 10.0;
    }

    // ---- Dead space penalty: very small unusable residuals ----
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // ---- Relative to mean residual: prefer bins that are already low ----
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // ---- Last chance bonus: only fitting bin, avoid opening new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: attractive if current item is large relative to capacity
        // or lookahead suggests a fresh bin packs better, otherwise discourage.
        let large_item = item_size as f64 / bin_capacity as f64;
        let lookahead_fresh = if next_item_size > 0 {
            (item_size + next_item_size) as f64 <= bin_capacity as f64
        } else { false };
        if large_item > 0.6 || lookahead_fresh {
            score -= 5.0 + 10.0 * large_item;
        } else {
            score += 30.0; // discourage opening new bin for small items
        }
    }

    // ---- Late stream: tighten packing as we near the end ----
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // ---- Mild penalty when many bins open (encourage consolidation) ----
    score += 0.5 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to hold the next item (or typical small item).
    let min_useful = if next_item_size > 0 { next_item_size.min(80) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: only bin that fits the item — avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity) should generally
    // be less attractive than a decent existing fit, but attractive when no bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for opening a new bin.
        score += 15.0;
        // If current item is large, opening fresh space is more valuable.
        score -= 0.08 * item_size as f64;
        // If mean residual across open bins is large, we have room already; penalize more.
        score += 0.05 * mean_residual;
        // Early in the stream, opening bins is cheaper (long future to use them).
        score -= 6.0 * (1.0 - progress);
        // If this is the only fitting option context (few fitting bins), soften penalty.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Mild pressure to fill bins when many are open.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits, non-linearly amplified over the stream.
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - post / cap));

    // Quadratic dead-space penalty, stronger late in the stream.
    score += 0.35 * (post / cap).powi(2) * cap * (0.5 + progress);

    // Reward bins that are relatively full already (small residual before placement).
    score -= 0.2 * (1.0 - bin_residual as f64 / cap) * item;

    // Lookahead: penalize leaving residual that only marginally fits the next item
    // (fragmentation risk), reward residual that cannot fit next item (clean closure).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let margin = post - nxt;
        if margin >= 0.0 {
            // residual that tempts a marginal next fit: penalize small positive margins
            score += 0.5 * (1.0 - (margin / cap).abs()).max(0.0) * (1.0 + progress);
        } else {
            // residual too small for next item: mild reward, scaled by wasted fraction
            score -= 0.15 * (-margin / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate: make it attractive only when open-bin fits are poor
    // (large post_residual relative to capacity). Smooth coupling with mean residual.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = post + 1.5 + openness * 0.3
            + 0.4 * (mean_residual / cap) * cap
            + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 residue captures "how close
    // to a common item-size divisor" the leftover space is.
    let residue_class = post_residual % 10;
    // Dead-space classes: residuals like 1..9 are nearly unusable for items >=10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver, unusable
    } else {
        // Reward residuals that are multiples of 10 (harmonic alignment)
        score -= (10 - residue_class) as f64 * 1.5;
    }

    // Reward exact fit
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic check: does post_residual % next_item_size leave a small tail?
        if next_item_size > 0 && post_residual >= next_item_size {
            let tail = post_residual % next_item_size;
            if tail == 0 {
                score -= 25.0;
            } else if tail < 10 {
                score += tail as f64 * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin fits well. Give it a moderate
    // baseline so well-fitting open bins beat it, but a poor open bin
    // (large penalty above) does not.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55
            + (open_bins_count as f64) * 0.3
            - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // opening fresh space helps a big follower
        }
        if fitting_bins_count == 1 {
            score += 100.0; // don't abandon the only fitting bin
        }
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits
    // to avoid scattering residual capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0; // neutral early
    score += progress * (post_residual as f64) * 0.2;

    // Prefer bins below mean residual (tighter than average) slightly.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11.0 - post_residual as f64) * 12.0; // tiny gap => big penalty
        } else if post_residual < 20 {
            score += 8.0;
        }
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; few bins => consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (1.0 - progress * 0.5);

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(11) {
        score += 6.0; // creates dead space for the known next item
    }

    // Deviation from mean residual: prefer bins whose residual is close to mean (balanced packing),
    // but allow using large-residual bins when few bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New empty bin candidate: default cost = full capacity plus open-bin pressure,
    // so it wins only when every open bin would create severe dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if the next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    } else {
        // Last item: prefer any bin that fits, avoid opening a new bin
        score -= 50.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only open a new bin when item is large
    // relative to residual spread, or no bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        // Opening a new bin is expensive: penalize, but less when item is large
        // and mean residual across bins is fragmented
        score += 60.0;
        score -= 20.0 * fit_quality;
        score -= 15.0 * progress;
        // If mean residual is small (bins are full), new bin is more acceptable
        score -= 0.3 * (mean_residual / bin_capacity as f64);
        // If many bins already open, mild extra penalty to consolidate
        score += 1.5 * open_bins_count as f64;
    }

    // Slight preference to fill bins with larger residuals when many are open
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream, tighter fits (small post_residual) matter more:
    // reward small residuals with a progress-weighted cubic term.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 30.0 * tight * (0.3 + 0.7 * progress);

    // Penalize dead space: residuals too small to be useful later.
    // Smooth penalty peaking around mid-range residuals via quartic shaping.
    let half = cap / 2.0;
    let dead = ((pr - half) / cap).powi(4);
    score += 12.0 * dead * (1.0 - progress);

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 20.0 * (nx / cap) * (0.5 + 0.5 * progress);
        } else {
            // penalize leaving a residual that just barely fails to fit next item
            let gap = ((nx - pr) / cap).powi(2);
            score += 8.0 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing),
    // smoothly penalized by squared deviation.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + progress);

    // Slight pressure against scattering across many bins early on.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer
    // division thresholds into "usable" vs "dead" capacity classes.
    let q = post_residual / 10; // coarse harmonic class (0..=10)
    let class_penalty = match q {
        0 => -40.0,                       // near-perfect fit
        1 => -25.0,                       // excellent
        2 => -15.0,                       // good
        3 => -8.0,                        // decent
        4 | 5 => -2.0,                    // neutral mid leftovers
        6 | 7 => 6.0,                     // awkward gap
        8 => 14.0,                        // bad: fits only tiny items
        _ => 22.0,                        // nearly empty bin wasted
    };
    score += class_penalty;

    // Dead-space coupling: leftover that no plausible next item can use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Unusable for the immediate successor: penalize proportionally,
        // but less harsh if a later small item could still use it.
        let frac = (next_item_size - post_residual) as f64 / cap;
        score += 30.0 * frac;
    }

    // Reward exact-looking fits: post_residual that divides cleanly into
    // small harmonic units (multiples of 10) are easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits: scale by competition.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when all open bins are poor fits (or it's the last chance).
    if bin_residual == bin_capacity {
        let base = 45.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let late = 25.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        let lookahead = if next_item_size > 60 { -12.0 } else { 0.0 };
        score += base + late + lookahead;
        // Never let the new-bin candidate win when a real last-chance fit exists.
        if fitting_bins_count <= 1 {
            score += 60.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer tight packing.
    score += 0.15 * open_bins_count as f64;

    // Slight preference to align bin residual toward mean (balance spread).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (low post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small leftover gaps (< 10, or below the
    // smallest plausible item) are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor filling existing bins (new-bin candidate has max residual,
    // so this biases against opening new bins when open bins suffice).
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly into post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Progression: early in the stream, be more tolerant of opening
    // bins (long future to use them); late, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, but
        // acceptable early when existing residuals are fragmented.
        score += 15.0 - 10.0 * progress;
        // If mean residual across open bins is small (fragmented),
        // opening a new bin is less attractive since consolidation is cheap.
        if mean_residual < item_size as f64 {
            score += 20.0;
        }
    }

    // Mild preference for bins with residual close to item (best fit
    // tiebreak) via penalizing excess slack relative to mean.
    if bin_residual < bin_capacity {
        let slack_excess = bin_residual as f64 - item_size as f64;
        if slack_excess > mean_residual {
            score += (slack_excess - mean_residual) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 30.0;
        } else if gap <= 5 {
            score -= 15.0;
        } else {
            score += gap as f64 * 0.3;
        }
        // If post_residual can't hold next item, small penalty so a bin
        // that chains better wins ties
        if (post_residual as u32) < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize tight bins relative to mean residual (waste of scarce space)
    if (bin_residual as f64) < mean_residual * 0.6 {
        score += 6.0;
    }

    // New-bin candidate: default slightly worse than a decent existing fit,
    // but attractive when no bin fits well
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh bin preserves room for big upcoming items
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Early stream: keep bins loose for future flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 14.0 * chain_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: penalize.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item barely fits
    // anywhere else or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // New bin leaves waste = C - item_size; penalize proportionally,
        // relax slightly early in the stream.
        score = waste * (1.15 - 0.25 * progress) + 10.0;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 8.0; // fresh bin can also chain the next item
        }
    }

    // Mild penalty for fragmenting bins with large residuals when many
    // alternatives exist.
    if bin_residual != bin_capacity && (bin_residual as f64) > mean_residual * 1.6 && open_bins_count > 2 {
        score += 3.0;
    }

    // Reward using bins whose residual is close to item_size (best-fit flavor).
    score -= 4.0 * (1.0 - ((bin_residual - item_size) as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Dead-space penalty grows with stream progress (late waste hurts more)
    let dead = (post - 0.0).max(0.0);
    score += 8.0 * norm_post * norm_post * (0.5 + progress);

    // Perfect-fit bonus: quadratic reward near zero residual
    score -= 6.0 * (1.0 - norm_post).powi(2) * norm_post;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Crowding: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln1p();
    score -= 1.5 * crowd * (1.0 - norm_post);

    // Mean-residual coupling: penalize bins far from the fleet mean (fragmentation)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: reward leaving room for the next item; penalize stranding it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 3.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            score += 2.0 + 3.0 * progress;
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing residuals are poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 4.0 * mean_residual / cap - 6.0 * progress;
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty grows superlinearly for small unusable residuals.
    if post_residual > 0 && post_residual < eighth {
        score += (eighth - post_residual) as f64 * 2.5;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Harmonic class: residuals that are exact divisors of capacity are reusable.
    if bin_capacity % post_residual.max(1) == 0 {
        score -= 6.0;
    }
    // Modulo class penalty: residual in "awkward" band (just above quarter).
    let m = post_residual % quarter.max(1);
    if m > 0 && m < 6 {
        score += m as f64 * 1.5;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Integer-division threshold: near-exact pairing is excellent.
            if post_residual - next_item_size < 4 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item could still fit here if we don't waste space; slight penalty
            // for consuming a bin that the future item needs.
            score += 5.0;
        }
    }

    // Last chance: only this bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented or the item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs();
        if item_size >= 70 {
            // Huge item: fresh bin often best unless an exact fit exists elsewhere.
            score += 15.0;
        } else {
            score += 30.0 + fragmentation * 0.3 - progress * 5.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins overall (low residual relative to mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible next item (or the lookahead item) are wasted space.
    let min_useful = if next_item_size > 0 && next_item_size < item_size {
        next_item_size
    } else {
        item_size.min(20)
    };
    if post_residual > 0 && post_residual < min_useful {
        // Small unusable gap: penalize proportionally to how close it is to being useless
        score += 25.0 * (1.0 - (post_residual as f64) / (min_useful as f64));
    }

    // Reward tight fits strongly (post_residual near zero)
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if this bin can also fit the next item after placement,
    // reward it; if not, and the gap left is small, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins implicitly since a new bin has max residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (concentrate packing into emptier-relative-to-mean bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: bin_residual == bin_capacity. Only attractive when
    // existing fits would create heavy dead space; base cost keeps it competitive
    // only when open bins are few or fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // new bin can host a clean pair
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills the post-residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this placement: mild reward proportional to fit tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item cannot use the post-residual: penalize wasted potential.
            score += 60.0;
        }
    }

    // Tight fit reward relative to capacity: small post_residual is good.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += 150.0 * post_frac * post_frac;

    // Relative-to-mean-residual matching: prefer bins whose residual is close to the item,
    // i.e. post_residual close to mean_residual keeps the bin population balanced.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 120.0;
        // More open bins -> discourage spreading further.
        new_bin_penalty += 15.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; late in the stream, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 200.0 * progress;
        // If next item is large, a fresh bin may be valuable for it.
        if next_item_size > 0 && next_item_size >= 50 {
            new_bin_penalty -= 100.0;
        }
        score += new_bin_penalty;
    }

    // Small bonus for using bins with larger residuals (best-fit style among non-empty).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to hold the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // hard-to-fill remnant
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward for near-exact two-item packing
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 4.0; // next item won't chain here
        }
    } else {
        // Last item: minimize waste aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: when many bins are open, discourage spreading; favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * (1.0 - progress);

    // Prefer bins with residual above the mean (keep balanced bins available).
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when all fits look bad.
    if bin_residual == bin_capacity {
        // Slight early bias toward opening bins while stream is young and cheap;
        // late in the stream, discourage opening unless item is large.
        score = 40.0 - 15.0 * progress + 0.2 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: minimize post residual, with non-linear tightening as stream progresses.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Strong quadratic penalty on large dead space (wasted capacity).
    score += 0.004 * pr * pr;

    // Reward near-perfect fits: subtract a bonus that grows as post_residual -> 0.
    score -= 8.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Penalize bins whose residual deviates from the mean residual (keeps bin family coherent).
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance boost: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild reward when many bins fit (encourages spreading load intelligently).
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) == (next_item_size as u64) {
        score -= 12.0;
    } else if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate handling: brand-new empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when alternatives are scarce or
        // the item is huge and would leave unusable fragments elsewhere.
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let big_item = item_size as f64 / cap;
        // Default: new bin is penalized so existing bins win.
        score = 30.0 + 20.0 * (1.0 - progress);
        // But if item is very large relative to capacity, opening a fresh bin is fine.
        score -= 35.0 * big_item * big_item;
        // If this is effectively the last chance (or few alternatives), allow new bin.
        score -= 40.0 * scarcity;
        // Late in the stream, prefer consolidating: keep penalty high.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near the small-item band (1..10)
    // are "dead space" classes — penalize them so bins whose leftover cannot
    // host a typical small item sink in priority.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        if class >= 1 && class <= 4 {
            score += 6.0 - class as f64; // awkward residue: 1..4 leftover
        } else if class >= 5 && class <= 9 {
            score -= 2.0; // residue likely reusable by a 5..9 chunk
        }
        // Exact decade residuals (pr % 10 == 0) are ideal: strong reward.
        if class == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds: how many "unit blocks" of 10 remain.
    let blocks = pr / 10;
    score -= blocks as f64 * 1.5;

    // Lookahead coupling: if the next item fits the post residual exactly or
    // nearly, reward heavily (harmonic pairing of item sizes).
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect two-item packing
        } else if slack <= 5 {
            score -= 12.0;
        } else {
            score -= 4.0 * (10.0 - (slack as f64).min(10.0)) / 10.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // Next item cannot use this leftover: penalize proportionally to waste.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should rarely win unless the
    // current item is huge relative to every residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred.
        score += 30.0;
        // But if the item barely fits anywhere (item is large and residuals are
        // tight), opening fresh is fine — relax the penalty.
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight {
            score -= 22.0;
        }
        // Late in the stream, consolidating matters more; make new bins costlier.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Huge items (harmonic top class, > 3/4 capacity) deserve a fresh bin
        // when residuals are fragmented.
        if item_size * 4 > bin_capacity * 3 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild preference for fuller bins overall (low mean residual environment
    // favors tight packing choices).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight tie-break toward fewer open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space penalty
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 30 {
            score += 6.0;
        } else {
            score -= 4.0; // large residual remains reusable
        }
    } else {
        score -= 30.0; // perfect fill strongly rewarded
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 25.0 + (open_bins_count as f64) * 3.0;
        // If this is the last fitting bin option, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in stream, prefer reusing existing capacity.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += progress * 10.0;
    } else {
        // Reward bins that are the last chance to fit the item.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward bins whose residual is below the mean (tighter packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // dead space that next item cannot use
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // 2-step lookahead: reward when next item exactly fills post_residual (perfect chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving residuals that are hard to fill (small odd residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny dead space
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.2 * (mean_residual - post_residual as f64);

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is huge and no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 60 && (fitting_bins_count == 0 || next_item_size > post_residual) {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (post_residual below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: slight penalty if we leave lots of space anyway.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
    score -= pressure * (0.5 + progress);

    // New-bin candidate handling: only attractive when current fit is poor or no real fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and open bins.
        score += 30.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // If the item is huge relative to capacity, opening fresh is less bad.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If nothing else fits, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild time-horizon shaping: early in the stream, be slightly greedy toward tight fits.
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    // Prefer bins whose residual is close to the item (best-fit flavor) with nonlinear sharpening.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late in the stream, dead space hurts more.
    let coupling = progress * progress * (1.0 - progress);
    score += 40.0 * coupling * norm_post * norm_post;

    // Penalize leaving residual that is too small for any plausible item (dead space),
    // smoothly: residual below ~10 is nearly unusable.
    let dead = ((12.0 - post).max(0.0)) / 12.0;
    score += 15.0 * dead * dead;

    // Reward tight fits (post_residual near zero) non-linearly.
    score -= 20.0 * (1.0 - norm_post).powi(6) * (1.0 - progress);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty scaled by leftover size.
        score += 4.0 * norm_post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // are fragmented (high mean residual spread) or this is a poor fit.
    if bin_residual == bin_capacity {
        // Default mild penalty so open bins with decent fit win.
        score = cap * 0.6 + 10.0 * progress;
        // If open bins are very fragmented (mean residual low relative to item),
        // opening a new bin becomes attractive.
        let fragmentation = (item_size as f64) / (mean_residual.max(1.0));
        if fragmentation > 0.85 {
            score -= 30.0 * (fragmentation - 0.85) / 0.15;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "dead class" (too small for typical small items) are penalized.
    let dead_threshold = 10u32.min(post_residual);
    let _ = dead_threshold;

    // Penalize residuals that cannot fit the smallest plausible item (size 1..)
    // but reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        // Large leftover: mild penalty growing with leftover size
        score += (post_residual as f64 - 30.0) * 0.25;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the remainder
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after / cap);
            // harmonic class: residual divisible by next item size is good
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this leftover: penalize leftover more
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // last item: minimize leftover at all costs
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, reduced late in stream or with many bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 70.0 - 20.0 * progress + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin fits everything; slightly better if item is large
            score -= (item_size as f64) * 0.1;
        }
        if fitting_bins_count == 1 {
            // there is a usable open bin; discourage new bin moderately
            score += 15.0;
        }
    }

    // Mean residual context: if this bin's residual deviates favorably
    // (smaller than mean), reward slightly.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.1;
    } else {
        score += (res - mean_residual) * 0.05;
    }

    // Harmonic modulo classes on capacity fraction of post_residual
    let class = post_residual % 20;
    score -= match class {
        0 => 6.0,
        1..=5 => 3.0,
        6..=10 => 0.0,
        _ => -1.5,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // possible item (1..100 range, but practically < ~10) are wasted forever.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64 / dead_threshold as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin
    // and slightly favor consolidating into existing ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 2.5 * open_pressure;
    } else {
        score -= 1.0 * open_pressure.min(15.0);
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // this placement chains perfectly; reward it. If the next item would fit
    // this bin's residual but NOT the post residual, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 { score -= 120.0; }
            else if slack < dead_threshold { score += 30.0; }
            else { score -= 10.0; }
        } else if bin_residual >= next_item_size {
            score += 15.0;
        }
    }

    // Mean-residual coupling: when average residual across bins is low,
    // keep tight packing (reward low post_residual extra); when high, be pickier.
    let mr = mean_residual.max(0.0);
    score -= 5.0 * (mr / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Stream progression: late in the stream, prefer closing bins out (fill existing)
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into the remaining space reasonably well.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack.min(20.0) * 0.15;
    }
    // Next item will NOT fit in this bin after placement: penalize leftover dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.1;
    }

    // Reward tight fits relative to the mean residual across open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Discourage opening a brand-new bin when good open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + open_bins_count as f64 * 0.5 - progress * 5.0;
        // If the new bin promises a perfect two-item packing, soften the penalty.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of the fit: 1.0 = perfect fit
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible future item
    let dead_zone = if post_residual > 0 && post_residual < 10 { 40.0 } else if post_residual < 20 { 15.0 } else { 0.0 };
    score += dead_zone;

    // Lookahead: reward bins whose post-residual can still hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 6.0 * pressure * (open_bins_count as f64).ln();
    }

    // Late in the stream, prefer filling existing bins over opening new ones
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: slightly worse than a decent fit, better than a terrible one
        score += 18.0 - 20.0 * progress;
    } else {
        // Reward using bins with smaller residuals (best-fit bias)
        score += 0.15 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Base: reward tight fits (small post_residual), non-linearly.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Smooth coupling: tight placements matter more as the stream progresses.
    score -= 18.0 * fill * fill * (0.35 + 0.65 * progress);

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let dead = (post / cap).powi(3);
    score += 55.0 * dead * (1.0 - 0.5 * progress);

    // Lookahead: reward leaving room for the next item, penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 14.0 * (gap / cap).exp() * (1.0 - gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Crowding bonus: prefer bins in a set with many fitting options only if tight.
    if fitting_bins_count > 1 {
        score += 3.0 * (1.0 - fill);
    }

    // New-bin candidate: penalize opening a new bin unless the fit here is bad
    // (large post_residual) or few bins fit the item elsewhere.
    let is_new_bin = bin_residual as f64 == cap && post == cap - item;
    if is_new_bin {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 30.0 + 25.0 * openness * (1.0 - progress)
            + 40.0 * (1.0 - fill) * (1.0 - progress);
        // Allow new bin late in stream when residuals are fragmented.
        if mean_residual < item * 0.6 && progress > 0.5 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers in "small" classes
    // (multiples of 10) are far more reusable than odd dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward leftovers that are exactly divisible into coarse harmonic classes.
    let class = if post_residual == 0 {
        0.0 // perfect fit, best possible
    } else if post_residual <= 10 {
        1.0
    } else if post_residual <= 20 {
        2.0
    } else if post_residual <= 30 {
        3.0
    } else {
        4.0
    };
    score += class * 6.0;

    // Modulo-10 harmony: leftover divisible by 10 is reusable by typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement is chain-friendly; penalize if it nearly fits but not quite.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward for exact modulo harmony between leftover and next item
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else if next_item_size <= post_residual + 10 {
            score += 6.0; // tantalizing near-fit, dead space risk
        }
    }

    // Penalize spreading across many bins when mean residual is already high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64) * (1.0 - progress) * 0.8;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no good-fitting bin exists, or late in stream
    // with tiny leftovers everywhere.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * cap;
        let poor_fits = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.35 && fitting_bins_count <= 2);
        if (big_item && poor_fits) || (fitting_bins_count == 1 && item_size >= 50) {
            score -= 18.0; // new bin justified
        } else {
            score += 30.0 + post; // strongly discourage wasting a fresh bin
        }
        // Slight preference for new bins early when item is huge
        if big_item && progress < 0.3 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 6.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // (new bin candidate has bin_residual == bin_capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 2.5 * open_bins_count as f64;
        // Opening a new bin is acceptable if the item is large relative to residual
        // patterns; large items pack well into fresh bins.
        if item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Reward tight fits relative to the mean residual across open bins.
        let tightness = (bin_capacity as f64 - mean_residual).max(0.0);
        score -= 0.05 * tightness;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If the next item cannot fit in the resulting gap, mildly penalize leaving a mid gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Early in the stream, allow more bins; later, be frugal.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with little waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Penalize small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        let _ = good_fit_exists;
        // Base penalty so open bins are preferred unless they score badly.
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If few bins fit the item, new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Mild bonus for filling bins tightly (low post residual relative to capacity).
    score -= 0.1 * (bin_capacity as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // no open bin fits well or residuals are already fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if mean_residual > 0.0 { (mean_residual - post_residual as f64).abs() } else { 0.0 };
        // Base penalty for wasting a fresh bin; reduced late in stream or when
        // mean residual is high (open bins are too full/fragmented anyway).
        score += 45.0 - 20.0 * progress - 0.3 * mean_residual.min(100.0);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0; // fresh bin is flexible for lookahead
        }
        let _ = fragmentation;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 3.0;
        // Prefer bins with residual close below mean (balanced packing).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: prefer small post-residual, with a non-linear penalty on tiny dead space.
    let mut score = post;

    // Smooth non-linear coupling: waste grows super-linearly as post-residual shrinks.
    score += 30.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Lookahead coupling: reward residual that can host the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_frac = nxt / cap;
            score -= 25.0 * fit_frac * (1.0 + progress) * (post / (post + nxt));
        } else {
            // Penalize residuals just below the next item size (near-miss dead space).
            let miss = (nxt - post) / cap;
            score += 18.0 * miss * (1.0 - miss) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by how many alternatives exist.
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * pr_norm;
    }

    // Mean-residual coupling: prefer bins whose residual is close to the mean (balance),
    // penalize outliers smoothly.
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score += 12.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: discourage opening a new bin early, allow it late or when
    // the item barely fits an open bin.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / cap;
        score += 60.0 * (1.0 - progress) - 30.0 * progress * tight;
    }

    // Tight-fit reward: near-exact fills are excellent.
    if post_residual == 0 {
        score -= 35.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/8 buckets)
    let item_class = item_size / (bin_capacity / 8).max(1);
    let next_class = next_item_size / (bin_capacity / 8).max(1);
    let post_class = post_residual / (bin_capacity / 8).max(1);

    // Reward tight fits: post_residual in a low harmonic class
    score -= (8 - post_class as f64) * 2.0;

    // Penalize dead space that is too small for typical items (1..100 unknown,
    // so treat very small post_residual as dead, but perfect fit is great)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; mild penalty proportional to wasted chain potential
        score += 5.0;
    }

    // Harmonic complementarity: item class + post class covering capacity nicely
    let complement = (item_size as u32).wrapping_add(post_residual);
    if complement == bin_capacity {
        score -= 12.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Modulo thresholds on post_residual: mid-range residuals (25..75) are versatile
    let mid = post_residual > bin_capacity / 4 && post_residual < (3 * bin_capacity) / 4;
    if mid {
        score -= 6.0;
    } else if post_residual > 0 {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.9;
        // Cheaper to open new bin early in stream (more future use)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * cap * 0.2;
        // If current bin would leave a bad fit for the next item, opening is better
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= cap * 0.35;
        }
        // If this bin is the only fitting bin and fit is decent, discourage new bin
        if fitting_bins_count >= 1 && post_residual >= 0 && item_size <= bin_residual {
            score += cap * 0.25;
        }
    }

    // Slight tie-break toward bins with residual close to mean (balance load)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Small penalty per open bin to encourage bin consolidation
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest
    // plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are risky too: they may become dead space.
    if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins; but
    // relax when this bin is the only fitting candidate (last chance).
    let pressure = (open_bins_count as f64).ln().max(0.5) * 6.0;
    if fitting_bins_count == 1 {
        score -= 30.0; // strongly prefer using the last chance bin
    } else {
        score += pressure;
    }

    // Prefer bins below mean residual (denser bins) to consolidate fill.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.25 * mean_gap;

    // New-bin candidate logic: an empty bin is attractive only when the
    // item is large relative to capacity or existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Slight default penalty so open bins win on good fits.
        score += 10.0;
        // Large items open fresh bins to avoid fragmenting partial bins.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // If mean residual is small, opening a bin is wasteful.
        if mean_residual < item_size as f64 * 1.5 {
            score += 20.0;
        }
        // Late in the stream, avoid opening bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
