pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * dead * dead;

    // Lookahead: if next item fits the post-residual exactly-ish, reward heavily.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 8.0 * next_fit;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
        // next item won't fit here anyway; slight penalty for wasting residual
        score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0;
        // If item is huge relative to capacity, opening fresh may be fine.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins fit the item, discourage new bin.
        score += 3.0 * fitting_bins_count as f64;
        // If mean residual across open bins is large, discourage new bin.
        score += 0.15 * mean_residual;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for bins with residual close to mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer filling bins with smaller residual first (compactness).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Core: reward tight fits (small post_residual) with non-linear emphasis.
    let mut score = pr / cap;

    // Quadratic coupling: dead space becomes increasingly costly as stream progresses.
    let prn = pr / cap;
    score += 0.8 * prn * prn * (0.5 + progress);

    // Cubic interaction: strongly punish large residuals late in the stream.
    score += 0.35 * prn * prn * prn * progress;

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating space into fewer bins).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.25 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        // Among many options, mildly prefer tighter fits via smooth weighting.
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0) * prn;
    }

    // New-bin candidate handling: opening a new bin wastes consolidation space;
    // penalize it smoothly, but relax when the item barely fits anywhere
    // (post_residual small means item nearly fills a fresh bin).
    if is_new_bin {
        let waste = 1.0 - prn; // larger when item is small -> more waste
        score += 0.6 * waste * waste + 0.4 * progress;
        // But if no open bin could fit, opening is necessary; soften penalty.
        if fitting_bins_count == 0 {
            score -= 1.5;
        }
    }

    // Lookahead coupling: reward placements leaving residual close to next item size.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score += 0.3 * gap * gap;
    }

    // Small smooth open-bins pressure: encourage filling existing bins when many are open.
    score += 0.02 * (open_bins_count as f64) * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
