    score += rem * 0.35;                 // prefer residuals that are exact decade multiples
    score += (decade as f64) * 1.5;      // mild preference for smaller decades overall

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 60.0;
    }
    // Dead space below the minimum item size is unusable
    else if post_residual < 10 {
        score -= 20.0;
    }

    // --- Harmonic coupling with lookahead item (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can chain into this bin's remainder
            score -= 10.0;
            // extra reward if next item exactly consumes the remainder
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // remainder too small for next item: penalize proportionally
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.25;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Opening a new bin while alternatives exist is costly;
            // cost scales with how much room is idle in open bins (mean_residual),
            // but is discounted when the item nearly fills the fresh bin
            // (small post_residual => item is large, opening is natural).
            let mut penalty = 55.0 + mean_residual * 0.4;
            let fill_ratio = item_size as f64 / bin_capacity as f64;
            penalty *= 1.0 - 0.5 * fill_ratio;
            // if many bins fit the item, alternatives are plentiful: penalize more
            penalty += (fitting_bins_count as f64).min(6.0) * 4.0;
            score += penalty;
        } else {
            // no open bin can take the item: new bin is mandatory
            score -= 100.0;
        }
    }

    // --- Stream progression: late in the stream, tighten packing further ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squash small post_residuals.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else {
        // Diminishing penalty for larger dead space (quadratic-ish).
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // 2-step lookahead: strongly favor bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0) * 0.4;
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly discourage wasting the only fitting bin on a bad fit,
    // but strongly favor it on a good fit.
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 15.0;
        } else {
            score += 12.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity && item_size > 0 {
        let good_fit_exists = fitting_bins_count > 0 && post_residual <= 15;
        if good_fit_exists {
            score += 50.0; // keep using existing bins on tight fits
        } else if fitting_bins_count == 0 {
            score -= 10.0; // must open a bin anyway
        } else {
            // Poor fits everywhere: opening a fresh bin is competitive,
            // scaled by stream progress (late stream: consolidate more).
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Mild consolidation pressure: fewer open bins -> prefer filling them.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer smallest post residual (tightest fit).
    let mut score = post;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post <= 10.0 {
        score -= 25.0;
    } else if post <= 20.0 {
        score -= 10.0;
    }

    // Penalize dead space relative to capacity (non-linear).
    score += (post / cap).powi(2) * 30.0;

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize waste.
    if next > 0.0 {
        if next <= post {
            score -= 8.0;
        } else {
            score += (next - post).min(cap) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely the best move.
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).max(1.0).ln();
        // Early in stream: allow new bins more freely; later: discourage.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 45.0 + 35.0 * progress + 5.0 * congestion;
        score += new_bin_penalty;
        // If item is large relative to capacity and mean residuals are small, new bin is less bad.
        score -= (item / cap) * 10.0;
    }

    // Mild bonus for using bins with larger residuals (balance across bins),
    // scaled by how much above the mean residual this bin is.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight preference late in stream for filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer low post-residual, mildly scaled by progress.
    let mut score = pr * (0.9 + 0.4 * progress);

    // Smooth polynomial coupling of fill level with progress.
    let f2 = fill * fill;
    let f3 = f2 * fill;
    score -= 12.0 * f3 * (0.5 + progress);

    // Dead-space penalty: very small post-residuals are great unless they
    // strand space that nothing can use; reward near-exact fits smoothly.
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 8.0 * tightness * fill;

    // Lookahead: penalize residual that can't fit the next item, reward
    // residuals that remain compatible with it (smooth in gap size).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 6.0 * (1.0 - gap * gap);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, with smooth decay as alternatives appear.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 15.0 * scarcity * (0.6 + 0.4 * progress);
    }

    // New-bin candidate: penalize opening a bin, more so early and when
    // existing bins have slack that could still absorb items.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * progress + 0.15 * mean_residual;
        if fitting_bins_count == 1 {
            score -= 20.0; // but still allow escape from a forced bad fit
        }
    }

    // Mild dispersion pressure: keep residuals balanced across open bins.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of the fill ratio.
    let fill = (item_size as f64) / cap;
    let tight_bonus = match (item_size * 10) / bin_capacity {
        0 => 0.0,
        1 => 4.0,
        2 => 2.0,
        3 => 1.0,
        4 => 0.5,
        5 => 0.0,
        6 => -1.0,
        7 => -2.0,
        8 => -3.5,
        9 => -5.0,
        _ => -7.0,
    };
    score -= tight_bonus;

    // Dead-space penalty for small unusable residuals (cannot hold even a mid item).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Harmonic classes on post_residual: penalize residuals in awkward bands.
    let pr_class = post_residual % 25;
    if pr_class > 0 && pr_class < 8 {
        score += 2.5;
    } else if pr_class == 0 {
        score -= 2.0; // perfectly divisible residual is reusable
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: default slightly worse than a decent fit, but
    // attractive when existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        score = 14.0;
        // Opening a fresh bin is good if the item is huge or the fit elsewhere is terrible.
        if item_size >= 60 {
            score -= 6.0;
        }
        if post_residual < 10 && post_residual > 0 {
            score -= 12.0; // would be a perfect pack anyway; rare for empty bin
        }
        // Late in the stream, consolidate rather than proliferate bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item would fit exactly in the post residual,
    // reward strongly; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            score -= 2.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here regardless; mild bonus to consume this bin
            score -= 1.5;
        } else {
            score += 1.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (reduces bin count pressure), scaled by mean residual gap.
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild preference for bins that are already substantially loaded.
    score -= 0.03 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < item_size.min(20) as f64 {
        score += 25.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer only when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score -= 60.0; // fresh bin won't create dead space here
        }
    }

    // Lookahead: if next item can use this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect lookahead match: next item exactly fills remaining space.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            // Bonus for exact or near-exact two-item fill.
            if slack_after_next == 0 {
                score -= 60.0;
            } else if slack_after_next <= 5 {
                score -= 25.0;
            }
        } else if next_item_size == post_residual {
            score -= 80.0;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how large the dead space is relative to smallest items.
            let dead = post_residual as f64;
            score += 0.5 * dead * dead / bin_capacity as f64;
        }
    }

    // Prefer tight fits overall: reward small post_residual.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large and current residuals are mostly unusable.
    if bin_residual == bin_capacity {
        let avg_usable = mean_residual;
        let poor_fit_env = avg_usable < item_size as f64 * 1.2;
        if poor_fit_env || item_size > bin_capacity as u32 / 2 {
            score -= 20.0;
        } else {
            score += 35.0;
        }
    }

    // Slight preference for bins whose residual is below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream, consolidate: favor filling bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (low post_residual already favored).

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.35 * next_item_size as f64;
        } else {
            // Dead space penalty scaled by how much next item overshoots.
            let waste = (next_item_size as f64 - post_residual as f64).min(60.0);
            score += 0.25 * waste;
        }
        // Perfect pairing: post_residual exactly equals next item.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize post residual (already base term).
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Many open bins: discourage spreading; prefer tightest fit even more.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, allow slight preference for balanced bins;
    // late in stream, prioritize closing bins (minimize post_residual harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when item fits poorly everywhere (large dead-space creation elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Late in the stream, opening new bins is less attractive.
        score += 10.0 * progress;
        // If other bins fit, make new bin clearly worse unless it's the only option.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Small bonus for bins that become exactly half-full or leave classic
    // combinable residuals (e.g., 10, 20) that future items can absorb.
    match post_residual {
        0 => score -= 25.0,
        10 | 20 | 25 | 50 => score -= 4.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - (pr / cap); // 1.0 = perfect fit, 0.0 = empty bin
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 12.0 * tightness * tightness * progress_coupling;

    // Penalize mid-range dead space quadratically (wasted capacity that few items can fill)
    let dead = (pr / cap - 0.5).abs();
    score += 8.0 * dead * dead * cap * 0.1;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early and when other bins fit
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 + 30.0 * (1.0 - progress) * (1.0 - scarcity);
        // allow new bin late if lookahead won't fit the resulting residual anyway
        if next_item_size > 0 && (next_item_size as f64) > pr {
            score -= 15.0 * progress;
        }
    }

    // Lookahead synergy: reward bins whose post-residual still fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild preference for bins tighter than average (consolidation)
    score += 0.05 * (pr - mean_residual);

    // Deter bin sprawl when many bins are open
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues divisible by small sizes are reusable
    let pr = post_residual;
    // Reward post-residuals that sit exactly on "harmonic" class boundaries
    // (multiples of 10, 20, 25, 33, 50 are more likely to absorb future items)
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill is best
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 || pr % 20 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 33 == 0 || pr % 34 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead-space classes (1..10 residue is nearly unusable)
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to tightness
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 4.0 * ((next_item_size - pr) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Tight fit reward: relative waste
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Prefer denser bins early; spread load when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    // Deviation from mean residual: bins with much more room than average are better targets
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists (large residual waste elsewhere)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 + 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (unusable for typical items) are heavily penalized.
    if post_residual > 0 {
        let unusable_threshold = 12.0;
        if (post_residual as f64) < unusable_threshold {
            score += (unusable_threshold - post_residual as f64) * 8.0;
        }
        // Perfect fit is gold.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Reward filling most of the bin (high fill ratio).
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill * 25.0;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // Many alternatives: mild penalty to prefer tighter fits among them.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Lookahead coupling: if the next item can use the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // gap is dead for the next item too
            score += 6.0;
        }
    }

    // New-bin candidate: keep it attractive only when no good fit exists (residual is tight everywhere)
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual;
        if mean_tightness < item_size as f64 * 0.5 {
            score -= 15.0; // open bins are mostly full -> new bin is fine
        } else {
            score += 25.0; // prefer existing bins when there is room
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly accommodates the next item (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // exact chain match gets full bonus
        if slack == 0.0 {
            score -= 40.0; // double-perfect chain: post_residual == next_item_size
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead: penalize unusable slivers.
        let waste = (next_item_size - post_residual) as f64;
        if post_residual < 10 {
            score += 50.0; // tiny sliver is nearly unusable
        } else {
            score += waste * 0.3;
        }
    }

    // Penalize post_residual far below mean residual (creating outliers of dead space).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= 15.0 || (next_item_size > 0 && post_residual == next_item_size);
        score += if good_fit { 500.0 } else { 300.0 };
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins when many are open (consolidation).
    if open_bins_count > 4 {
        score += (bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect closure: item exactly fills the bin -> extremely strong reward.
    if post_residual == 0 {
        score -= cap * 4.0;
    }

    // Lookahead pairing: if the next item fits exactly in the leftover space,
    // this placement is ideal (chains two items into one bin).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= cap * 3.0;
    }
    // Next item still fits comfortably in the leftover: mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= post * 0.5;
    }
    // Next item would NOT fit in leftover: penalize leaving medium dead space
    // that is too small for the upcoming item.
    else if next_item_size > 0 && next_item_size > post_residual {
        let dead = post / next_item_size as f64;
        score += dead * cap * 0.3;
    }

    // Tightness reward: smaller post_residual relative to item size is better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * cap * 0.8;

    // Penalize creating tiny unusable slivers (1..=5) that rarely get filled.
    if post_residual > 0 && post_residual < 6 {
        score += cap * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 2.5;
    }

    // Global state coupling: when mean residual across open bins is high,
    // we can afford looser fits; when low, be pickier (penalize waste more).
    let pressure = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += pressure * post * 0.4;

    // Many open bins: discourage opening yet another bin; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins.
        score += cap * 1.2 + open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is more costly (leftover waste).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * cap * 0.8;
        // But if next item is huge and no open bin can hold both, new bin is fine.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= cap * 0.6;
        }
    }

    // Time horizon: early in the stream keep bins flexible (prefer larger post_residual);
    // late in the stream, pack tightly regardless.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * tightness * cap * 0.6;

    // Mild preference for bins with residual close to item size (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = norm_pr * (1.0 + progress * norm_pr * 2.0 + progress * progress * 3.0);
    score += 4.0 * poly;

    // Penalize tight fits that leave awkward residuals relative to mean residual
    let mean_gap = norm_pr - mean_residual / cap;
    score += 3.0 * mean_gap * mean_gap * cap;

    // Reward near-perfect fits smoothly
    score -= 30.0 * (-(norm_pr * norm_pr) * 60.0).exp();

    // Lookahead: penalize leaving residual too small for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let deficit = (ns - pr).max(0.0) / cap;
        score += 12.0 * deficit * deficit * cap;
        // Bonus if next item fits exactly in the post residual
        score -= 8.0 * (-( (pr - ns) * (pr - ns) ) / 40.0).exp();
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage opening new bins early, more later
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress;
    }

    // Slight pressure toward consolidating into fewer bins
    score += (open_bins_count as f64).ln() * 0.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough for typical future items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class the post_residual into integer-division buckets of 10.
    let post_class = post_residual / 10; // 0..=10
    // Dead-space classes: very small leftovers are nearly useless.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 30.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic modulo logic: residuals that are multiples of common item
    // classes (10, 20, 25, 50) are more likely to be filled later.
    let harmonic_bonus = if post_residual % 10 == 0 {
        8.0
    } else if post_residual % 25 == 0 {
        6.0
    } else if post_residual % 20 == 0 {
        5.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if the next item exactly fits the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to how well it nests.
            score -= (post - next_item_size as f64).min(20.0) * 0.5;
        } else {
            // Next item cannot use this residual: penalize proportional to
            // how close-but-failing it is (wasted opportunity).
            score += ((next_item_size as f64 - post).min(30.0)) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: the empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin is costly.
        score += 55.0;
        // But if the current item is huge and would leave a tiny residual in
        // any existing bin, a fresh bin may be better. Estimate best existing
        // fit via mean residual.
        let would_leave_mean = mean_residual - item_size as f64;
        if would_leave_mean >= 0.0 && would_leave_mean < 10.0 {
            // Existing bins would end up with dead space; new bin is fine.
            score -= 45.0;
        }
        // If many open bins exist, opening yet another one dilutes packing.
        score += open_bins_count as f64 * 1.5;
        // Early in the stream, be more willing to open bins (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    } else {
        // Reward using existing bins, more so when they are relatively full.
        let fullness = 1.0 - (bin_residual as f64 / cap);
        score -= fullness * 15.0;
        // Prefer bins below mean residual? No: prefer filling emptier bins
        // slightly to balance, but tightest-fit dominates via post_residual.
        score += ((bin_residual as f64 - mean_residual) / cap) * 5.0;
    }

    // Post-residual class penalty: classes 1..9 (residual 10..90) are fine,
    // but class 0 with nonzero residual impossible; penalize mid-tiny classes.
    if post_class == 1 && post_residual != 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily
    // penalized since future items likely cannot use them.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Zero residual is a perfect fit — strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward filling the bin densely with the current item.
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize so it wins only when all fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0 + 6.0 * progress;
    } else {
        score -= 3.0;
    }

    // Open-bin pressure: mild penalty grows with number of open bins,
    // discouraging proliferation of half-empty bins.
    score += open_bins_count as f64 * 0.4;

    // Lookahead (k=2): reward leaving space the next item can use,
    // penalize stranding residual the next item cannot fit.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 9.0;
        } else {
            score += 5.0;
        }
    }

    // Slightly prefer bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits comfortably in the leftover space (good chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    }
    // Dead space: next item cannot use the leftover.
    else if next_item_size > 0 && post_residual > 0 {
        score += 0.75 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize bins that are already tight relative to the fleet mean (avoid
    // fragmenting many half-empty bins), mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Brand-new empty bin candidate: keep it expensive unless the item is large
    // and no open bin fits well (its raw post_residual is high, which already
    // discourages it; add a fixed opening cost).
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Slight preference to consolidate into fewer bins late in the stream.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item can still fit after placement, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            // Extra reward if next item exactly consumes what's left (perfect pair).
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else if next_item_size > bin_residual {
            // Next item won't fit here anyway; residual waste is less costly.
            score -= 6.0;
        } else {
            // Next item would have fit before, but not after this placement: penalize.
            score += 20.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 12.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Discard near-empty bins as candidates when mean residual is high elsewhere.
    if (bin_residual as f64 - mean_residual).abs() < 1e-9 && bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced late in the stream or when fits are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 40.0 - 15.0 * progress - 20.0 * scarcity;
    } else {
        // Slight preference for bins whose residual is close to the mean (balanced use).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: convex non-linear cost of leftover space (dead space penalized super-linearly).
    let norm_post = post / cap;
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, prefer filling bins aggressively; later, be more tolerant of slack.
    let tightness = 1.0 - norm_post;
    let progress_coupling = (progress - 0.5) * (progress - 0.5); // 0.25 at ends, 0 mid-stream
    score -= tightness * tightness * (cap * 0.6) * (0.5 + progress_coupling * 2.0);

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many fitting bins when alternatives exist
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: reward if the next item can still fit in the post-residual (keeps bin useful),
    // penalize if next item would be blocked (creating dead space relative to lookahead).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            // smooth reward proportional to how well next item nests
            let nest = 1.0 - (post - next) / cap;
            score -= nest * cap * 0.35 * (1.0 - progress * 0.5);
        } else {
            // blocked lookahead: penalize proportionally to overflow gap
            let gap = (next - post) / cap;
            score += gap * gap * cap * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        let rel = (post - mean_post) / cap;
        score += rel * cap * 0.25;
    }

    // Mild penalty for opening many bins late in the stream when consolidation is possible.
    score += (open_bins_count as f64).sqrt() * (0.5 + progress) * 3.0;

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin;
    // give it a moderate fixed handicap so existing bins are preferred unless fit is poor.
    if bin_residual == bin_capacity {
        score += cap * 0.45;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
