        } else {
            // Next item won't fit here: penalize large dead space relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare bin residual against mean residual: prefer bins with below-average residual
    // (i.e., tighter bins) to consolidate fill.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.25 * (res_f - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge relative
    // to residual and few bins fit it.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items with poor fit elsewhere justify a new bin.
        let relief = if item_frac > 0.6 && fitting_bins_count <= 2 { 55.0 } else { 0.0 };
        score += base_penalty - relief;
    }

    // Early in stream: mild preference for spreading items to create future options.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize small dead space that nothing can use (min item size assumed ~1..100; treat <15 as likely dead)
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // Reward tight fits: normalized fill ratio
    let fill = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: only fitting bin available -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            1.0
        } else {
            let mean_fill_gap = mean_residual / bin_capacity as f64;
            (mean_fill_gap * 2.0).min(1.0)
        };
        // Baseline cost of a fresh bin; cheaper early in stream (more future use)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 90.0 + 60.0 * progress - 70.0 * desperation;
        if post_residual == 0 { score -= 200.0; }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 50.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Global pressure: many open bins -> consolidate into fuller bins
    let pressure = (open_bins_count as f64 / 20.0).min(1.0);
    score -= 30.0 * pressure * (1.0 - fill);

    // Prefer bins with residual above mean (keep balanced spread) mildly
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64 / cap; // normalized post residual
    let fit = item_size as f64 / cap;   // normalized item size
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_r = mean_residual / cap;

    let mut score = r;

    // Reward tight fits: quadratic bonus as post residual approaches 0
    score -= (1.0 - r) * (1.0 - r) * 12.0;

    // Penalize mid-range dead space (residuals too small for typical items but wasted)
    let dead = if r > 0.0 && r < 0.2 { (0.2 - r) * 25.0 } else { 0.0 };
    score += dead;

    // Smooth stream-progress coupling: early stream favors tight packing more strongly
    let progress_weight = 0.5 + 1.5 * t * (1.0 - t) * 4.0 * 0.25 + t * 2.0;
    score -= progress_weight * (1.0 - r).powi(3);

    // Lookahead: reward bins whose post residual fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (r - nxt).abs();
        if r >= nxt {
            score -= 3.0 * (1.0 - gap).abs() * (1.0 - nxt);
        } else {
            score += 4.0 * gap * gap;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins below mean residual (more filled) via smooth coupling
    score += 2.0 * (r - mean_r) * (r - mean_r).signum();

    // Penalize opening new bins as stream matures, mildly
    let new_bin_penalty = 6.0 * (0.3 + 0.7 * t) * (1.0 - (1.0 - r).powi(2));
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // But allow new bins for large items that leave bad residuals elsewhere
        score -= 4.0 * fit * fit;
    }

    // Mild congestion term: many open bins -> favor filling existing ones
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= ((bin_capacity - post_residual.min(bin_capacity)) as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Penalize dead space: residual too small to ever fit a typical item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic class: bucket residual into capacity fractions (mod-style classes).
    let class = post_residual / 10; // 0..=10 integer division threshold
    match class {
        0 => score += 25.0,      // 0-9: nearly dead space
        1 => score += 15.0,      // 10-19: only tiny items fit
        2 => score += 5.0,       // 20-29
        3 => score -= 3.0,       // 30-39: usable
        4 => score -= 5.0,       // 40-49: sweet spot
        5 => score -= 6.0,       // 50-59: sweet spot
        6 => score -= 4.0,       // 60-69
        7 => score -= 2.0,       // 70-79
        _ => score += 0.0,       // 80+: loose bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // Next item won't fit here; penalize more if this was a tight fit wasted.
            score += 6.0;
        }
    }

    // Last-chance bin: only one bin fits the item — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: opening a new bin is only good when open bins are crowded
    // or the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open when many bins are open and mean residual is low (fragmented).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        score += mean_residual * 0.35; // high mean residual => existing bins are roomy, keep using them
        score -= progress * 8.0; // late in stream, consolidation matters more
        // If item is large relative to capacity, avoid wasting existing tight space.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin: slight preference when bins are numerous (consolidate).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1, realistically >=10) can use are heavily penalized.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += 120.0 * (dead_threshold - post_residual as f64 + 1.0);
    }
    // Mid-range awkward gaps (too small for typical items) get a softer penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 9.0);
    }

    // Perfect/near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: penalize by open-bin count so new bins are only opened
        // when no existing bin offers a decent fit.
        score += open_pressure * 2.0;
        // Allow new bin when remaining space after placement would be large and useful
        // (e.g. big item arriving), or when nothing fits well.
        if post_residual >= 40 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if the next item could use this bin's post-residual, reward keeping it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    }
    // If next item would NOT fit in the leftover, penalize leaving an awkward gap.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 15.0;
    }

    // Mild preference for fuller bins relative to the mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Late-stream tightness: as the stream progresses, avoid opening bins even harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic penalty for large dead space.
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_val = (post - nxt).abs();
        // Perfect chain (post_residual == next_item_size) is highly desirable.
        score -= 6.0 * (1.0 - match_val / bin_capacity as f64).powi(3);
        // Penalize leaving residual that can't fit the next item at all.
        if post_residual < next_item_size {
            score += 4.0 * (1.0 - post as f64 / nxt.max(1.0));
        }
        // If next item fits exactly leaving near-zero, extra reward.
        if next_item_size <= post_residual && (post - nxt) < 5.0 {
            score -= 3.0;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins that are
    // already below-average full (consumes slack where it's least useful).
    let dev = mean_residual - post;
    score += 0.15 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; offset by lookahead potential.
        score += 18.0;
        if next_item_size > 0 {
            // A fresh bin chains well if item + next item pack nicely.
            let chain = item_size as f64 + next_item_size as f64;
            if chain <= bin_capacity as f64 {
                score -= 10.0 * (1.0 - (bin_capacity as f64 - chain) / bin_capacity as f64);
            }
        }
        // Late in the stream, avoid opening unnecessary bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Slight preference for fuller bins among equals (best-fit tiebreak).
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let ni = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate.
        // Baseline reference: slightly penalized so existing bins win on equal fit,
        // but with a bonus when the item is large (post_residual small) since
        // starting a fresh bin for a big item preserves flexibility elsewhere.
        score = post - 4.0;
        // Reward opening a new bin when the lookahead item would also fit here
        // (a fresh bin becomes a versatile "pair" container).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
        // Late in the stream, opening new bins is less attractive (fewer chances
        // to fill them); scale the opening bonus down with progress.
        score += 6.0 * progress;
    } else {
        // Existing bin: tight fits are naturally favored by low post_residual.
        // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
        if fitting_bins_count == 1 {
            score -= 6.0;
        }
        // Lookahead-aware dead-space penalty: if the next item can no longer
        // fit after this placement, the leftover is likely dead space.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 0.4 * (ni - post);
            } else {
                // Residual still usable by the next item: small reward.
                score -= 0.5;
            }
        }
        // Penalize placements that leave residual far below the mean when the
        // mean is small (fragmenting a healthy bin landscape).
        if mean_residual > 0.0 && post < mean_residual * 0.5 {
            score += 0.15 * (mean_residual - post);
        }
        // Mild preference for filling already-well-used bins earlier in the
        // stream, keeping fresh capacity available.
        score -= 2.0 * (1.0 - progress) * (1.0 - bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = post / cap;

    // Base: prefer low post residual, with non-linear shaping
    let mut score = post * (1.0 + 0.5 * x * x);

    // Polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize tiny residuals); later, pack tight.
    let progress_weight = 0.4 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += progress_weight * post * (1.0 - x);

    // Penalize very small dead space asymmetrically (wasted slivers)
    score += 8.0 * (x * (1.0 - x)).powf(0.5) * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (nxt / cap)) * (0.5 + progress);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when other bins fit
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).sqrt();
        // Allow new bin only if current bin would leave a bad fit
        score -= (post_residual as f64).min(item_size as f64) * 0.05;
    }

    // Slight preference to balance against mean residual
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    score -= (cap - post_residual as f64).max(0.0) * 0.15;

    // Harmonic classes: exact-fit residual classes get bonuses.
    // Class 0: post_residual == 0 (perfect fill)
    // Class 1: post_residual divides cleanly into small chunks (<= 10)
    // Class 2: post_residual in a "usable" band (10..=30)
    // Class 3: dead space (> 30) -> penalize
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    } else {
        score += (pr as f64 - 30.0) * 0.35;
    }

    // Modulo arithmetic on residual: residuals divisible by common item
    // granularities (10, 20, 25) are more likely reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item won't fit here; penalize leaving awkward space.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we want spread.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins generally; relax early in the stream.
        score += 55.0 - 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 80.0; // forced new bin anyway
        } else if fitting_bins_count == 1 {
            score += 15.0; // a last-chance bin exists; keep it closed
        }
        // If mean residual is large, open bins are wasteful already.
        if mean_residual > cap * 0.5 {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is too small to hold even the smallest
    // plausible item (use 1 as floor for unknown distributions), but gaps in
    // the awkward band (1..=15) are the classic waste zone.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 4.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Open bins pressure: more open bins -> prefer filling existing ones
    // (penalize less when many bins are open relative to a soft target).
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we only
    // open a new bin when existing fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 20.0;
        // If next item is large and current post_residual would be too small
        // for it, opening a fresh bin becomes more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward bins whose leftover can host the next item (lookahead synergy)
        score -= 12.0;
    }

    // Late in the stream, consolidate harder (fewer wasted residuals).
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a super-linear penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: perfect match leaves zero dead space for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chaining: item + next item fills bin perfectly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.8; // leftover after next item would still be dead space
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5; // next item won't chain here
        }
    } else {
        // Last item: only exact fit matters.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Compare against mean residual: bins already below mean are more valuable to fill.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the item
    // fits poorly in every open bin (large waste) or would strand the next item.
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item when they complement.
            if item_size + next_item_size <= bin_capacity {
                score -= 55.0;
            }
        }
        // If this bin is the only fitting bin and fit is terrible, new bin looks better.
        if fitting_bins_count == 1 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Mild stream-progression bias: early on, prefer consolidation into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: larger items consume more of the bin's value.
    score -= (item_size as f64 / cap) * 8.0;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Very small dead space is still good.
    if post_residual <= 5 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin,
    // but only if the fit isn't terrible (post_residual already in base score).
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead coupling (k=2): reward if the next item can also fit here afterward.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0 * (1.0 - progress * 0.5);
        } else if post_residual < 10 {
            // Small residual unlikely to serve future items; mildly acceptable to "close" bin.
            score -= 2.0;
        } else {
            // Medium residual that blocks the next item: penalize.
            score += 3.0;
        }
    }

    // Non-linear penalty on wasted capacity (quadratic dead space), softened early.
    score += (post_residual as f64).powi(2) / cap * 0.5 * (0.6 + 0.4 * progress);

    // New-bin candidate handling: it starts with residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with how much residual is already
        // available across open bins (no need for more space if bins are roomy).
        score += 10.0 + mean_residual * 0.15 * (open_bins_count as f64).sqrt();
        // If the item barely fits any open bin (mean residual is tight relative
        // to the item), opening a fresh bin becomes attractive.
        if item_size as f64 > mean_residual * 0.9 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 5.0;
    }

    // Mild penalty when many bins fit the item: spreading items thin is wasteful,
    // prefer the bin where the item is proportionally largest (already rewarded),
    // but add slight ordering pressure by residual.
    score += (bin_residual as f64 / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling: residual cost grows super-linearly as
    // post_residual shrinks toward dead space, modulated by stream progress.
    let x = post / cap; // normalized post residual in [0,1]
    let poly = x * x * (2.0 - x); // smooth bump: penalizes small AND large residuals mildly
    score += poly * cap * (0.35 + 0.4 * progress);

    // Penalize dead space more sharply late in the stream (quadratic in progress).
    score += (1.0 - x) * (1.0 - x) * 12.0 * progress;

    // Tight fits (small post_residual) are rewarded, especially when this is
    // the last fitting bin.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0 * (1.0 + progress);
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * tightness;
    }

    // Lookahead: reward leaving room for the next item; penalize blocking it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 4.0 * (1.0 - slack_fit);
        } else {
            score += 3.0 + (nxt - post) / cap * 10.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or residuals are scattered (poor average fit).
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
        let scatter = ((mean_residual - post).abs()) / cap;
        score += 25.0 - 18.0 * congestion - 15.0 * scatter;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Mild penalty for opening many bins relative to stream length.
    score += (open_bins_count as f64) * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small denominators) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fractional capacity classes: leftover below 10 is dead space -> penalize hard.
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic divisibility rewards: leftover divisible by 2, 4, 5, 10 is more reusable.
        if post_residual % 10 == 0 { score -= 25.0; }
        else if post_residual % 5 == 0 { score -= 12.0; }
        else if post_residual % 2 == 0 { score -= 5.0; }

        // Integer division threshold: leftover in [10, 30] is a "small pocket";
        // only good if the lookahead item can use it exactly.
        if post_residual <= 30 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 30.0;
                if post_residual % next_item_size.max(1) == 0 {
                    score -= 20.0;
                }
            } else if next_item_size > post_residual {
                // pocket too small for next item: penalize proportionally
                score += (post_residual as f64) * 0.5;
            }
        } else {
            // Large leftover: mild reward for keeping space flexible.
            score -= 8.0;
        }
    }

    // Last chance: only one bin fits -> strongly favor using it (avoid new bin).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: opening a new bin is only attractive when current bins fit badly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin ~ wasted capacity potential.
        score = cap * 0.9;
        // If item fits poorly everywhere (few fitting bins) or item is small,
        // a new bin may still lose; make new bin expensive unless current fit is terrible.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else {
            // penalize new bin more when a decent fit exists elsewhere
            let spread = (bin_residual as f64 - mean_residual).abs();
            score += spread * 0.1;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score -= (open_bins_count as f64) * 0.5;

    // Tightness reward: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to fit any plausible item (min size 1..100 unknown,
    // but treat gaps below a "danger threshold" as likely wasted).
    let danger = 15.0;
    if (post_residual as f64) < danger && post_residual > 0 {
        // Unusable sliver: strong penalty proportional to how dead the gap is.
        score += (danger - post_residual as f64) * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening new bins is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.8;

    // New-bin candidate logic: an empty bin has large post_residual; make it attractive only
    // when the current bin would leave a bad gap or mean residual is already low.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin: penalize opening when many bins are open.
        score += 25.0 + open_bins_count as f64 * 1.5;
        // If current item would leave a dangerous gap in an existing bin, opening is fine.
        if (post_residual as f64) < danger && post_residual > 0 {
            score -= 30.0;
        }
        // Lookahead: if next item fits the fresh-bin residual, opening is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: penalize if placing here blocks the lookahead item.
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would have fit before this placement but not after.
            score += 12.0;
        }
        // Slight reward if post_residual still accommodates the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (more filled bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive by default, but discourage it
    // if a lookahead-perfect fit exists in an open bin.
    if bin_residual == bin_capacity {
        score = 1000.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        return score;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin becomes exactly sized for the next item.
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits here afterward: mild reward, scaled by slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack.min(50.0);
        } else {
            // Next item would NOT fit after this placement: penalize by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize tiny unusable dead space (< 10 = minimum item size).
    if post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.1;
    }

    // Late in the stream, consolidate aggressively to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty normalized by capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward keeping this bin viable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would NOT fit after placing here, mild penalty unless post_residual tiny.
    if next_item_size > post_residual && post_residual >= 10 {
        score += 8.0;
    }

    // Penalize bins whose residual is far above mean (fragmented spread) — prefer balanced residuals.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.25 * diff.abs();

    // Early in stream: encourage opening/using fresh bins for large items to keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable for large items or when many bins can fit (poor fits elsewhere).
        let large_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if large_item {
            score -= 25.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // Late in stream, avoid opening new bins with small remaining work.
        if progress > 0.85 {
            score += 30.0 * progress;
        }
    }

    // Mild penalty when many open bins already: discourage proliferation.
    score += 0.4 * open_bins_count as f64;

    // Reward filling bins that are already quite full (residual close to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = norm_post * (1.0 + 2.5 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, dead space matters more.
    score += 1.8 * norm_post * norm_post * progress * (1.0 - progress + 0.25);

    // Penalize bins whose residual deviates from the mean residual (keep pool homogeneous).
    score += 0.6 * (norm_post - mean_residual / cap).abs();

    // Lookahead: reward bins that can also host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 1.2 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 0.8 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    }

    // More open bins => mild pressure to fill existing ones rather than spread.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (residual == capacity): strongly penalize unless item is huge
    // relative to typical residual, so we only open fresh bins for poor fits.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 3.0 - 2.0 * fill * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division thresholds.
    // Residual classes: 0 (perfect), 1..=10 (tight), 11..=40 (mid), >40 (loose).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, maximal reward
    } else if post <= 10 {
        score -= 25.0; // tight residual, near-perfect packing
    } else if post <= 40 {
        score -= 5.0; // usable residual band
    } else {
        score += 8.0; // loose residual, dead-space risk
    }

    // Lookahead coupling: next item exactly fills the residual is gold.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            // next item fits: reward proportional to how well it uses leftover
            let fill = next_item_size as f64 / post as f64;
            score -= 18.0 * fill;
            // harmonic bonus if next item leaves another tight residual
            let post2 = post - next_item_size;
            if post2 <= 10 {
                score -= 12.0;
            }
        } else {
            score += 10.0; // next item cannot use this residual
        }
    }

    // Last-chance dynamics: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // strongly favor using the last fitting bin
    } else if fitting_bins_count > 1 {
        // competition among bins: prefer tighter fits (smaller post_residual),
        // add a mild penalty so ties resolve toward best-fit naturally
        score += 1.0;
    }

    // New-bin candidate handling: penalize opening a new bin when any open bin fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 || open_bins_count == 0 {
            // if other bins fit, new bin is wasteful; if no bins open, it's mandatory
            if open_bins_count > 0 {
                score += 45.0 + 0.5 * (fitting_bins_count as f64);
            }
        }
        // modulo threshold on item_size: very large items (> 50) leaving big
        // residuals in a fresh bin get extra penalty to discourage fragmentation
        if item_size > 50 {
            score += 6.0;
        }
    }

    // Stream progression: early in the stream, keep bins tighter (more bins
    // available later to absorb residuals); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (mean_residual / cap);

    // Harmonic fraction shaping: score = post * post/(post+1) dampens large
    // residuals' dominance while preserving ordering.
    let harmonic = (post as f64) * (post as f64) / (post as f64 + 1.0);
    score = score * 0.5 + harmonic * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: keep it slightly expensive unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match with the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 {
        // Penalize post_residual that can't fit the next item if it's small dead space.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.5;
    }

    // Reward tight fits (small post_residual) relative to item size.
    score -= (item_size as f64) * 0.3;

    // Penalize bins whose residual is far above mean residual (wasteful large gaps),
    // but only when the bin is genuinely open (not the new-bin candidate).
    if bin_residual < bin_capacity {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when it yields a perfect
    // split for the next item or when current bin fits are hopeless.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen on strong lookahead value.
        score += 150.0;
        if next_item_size > 0 {
            let rem = bin_capacity as i64 - item_size as i64 - next_item_size as i64;
            if rem == 0 {
                score -= 1200.0; // perfect two-item packing in a fresh bin
            } else if rem > 0 && rem < 10 {
                score -= 300.0; // near-perfect packing
            }
        }
        // Late in the stream, discourage opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
        // If many bins are open, mildly discourage adding more.
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward near-zero post residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        let dead = post_residual as f64 / cap;
        score += 10.0 * dead * dead;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap);
        if gap == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't host next item: mild penalty scaled by wasted potential.
        score += 4.0 * (post_residual as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (leaves a useful residual for future items) or no good fit exists.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // New bin is penalized by default; discount for big items.
        score += 30.0 - 40.0 * item_frac * item_frac;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // If open bins have plenty of mean residual, use them instead.
        if mean_residual > item_size as f64 + 10.0 {
            score += 10.0;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // favor placements that reduce fragmentation (small post_residual).
    if open_bins_count > 1 {
        let frag = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Tight fits are rewarded more strongly as the stream progresses
    let tightness = 1.0 - fit; // 1.0 = perfect fit
    score -= tightness * tightness * (20.0 + 40.0 * progress) * (item_size as f64 / cap);

    // Penalize large dead space with a cubic term modulated by progress
    score += fit * fit * fit * (30.0 + 60.0 * progress);

    // Smooth interaction: small residuals become more valuable late in the stream
    score -= (fit * (1.0 - fit)) * (10.0 + 30.0 * progress * (1.0 - progress));

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly
        score += 4.0 * (1.0 - progress);
    }

    // Prefer bins with residuals close to the mean residual (smooth balancing)
    score += 0.15 * (pr - mean_residual).abs();

    // Mild pressure against scattering across many bins early on
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * (1.0 - fit);
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: harmonic class 0 (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic quarter-class of the post residual
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;

    // Dead-space penalty: residual too small to hold any plausible future item
    // (min item size is small; residuals below ~1/4 capacity are low-utility)
    if post_residual < quarter {
        score += 60.0 + (quarter - post_residual) as f64 * 0.5;
    }

    // Lookahead coupling: if the next item cannot fit in the post residual,
    // this bin's remaining space likely becomes waste
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // reward leaving room exactly sized for the next item
            let slack = post_residual - next_item_size;
            if slack < quarter {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: residual == capacity. Give it a neutral-to-slightly-high
    // score so it only wins when open bins fit poorly. Bias it against when
    // many open bins exist (prefer consolidating).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 5.0;
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        return score;
    }

    // Prefer tighter bins slightly: penalize bins with large residual relative
    // to the mean (they retain more future flexibility, so use small-residual bins first)
    if (bin_residual as f64) > mean_residual {
        score += 8.0;
    }

    // Modular nudge: post_residuals congruent to 0 mod 10 are "clean" classes,
    // mildly favored as they align with typical item-size granularity
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=10)
    // are pure waste; penalize heavily, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Gaps in [10, 25) can only host small items; mild penalty that grows
    // as the gap shrinks toward the minimum usable size.
    else if post_residual >= 10 && post_residual < 25 {
        score += 6.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward
    // this placement (chaining); if next item is large and post-residual is
    // a useless sliver, add pressure.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; with few open bins, opening is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has zero dead-space risk but
    // incurs an opening cost that grows with stream progress and open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 + 12.0 * progress + 1.5 * open_bins_count as f64;
        // Still allow opening when the item would leave a bad gap elsewhere:
        // the dead-space penalties above already raise other candidates.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: when open bins are already loose on average,
    // tighten selection (favor small post_residual more aggressively).
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish matches: post_residual equal to next_item_size means
    // the lookahead item fills this bin perfectly next step.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect two-item fill: post_residual == 0 and next item fits a fresh bin anyway.
        if post_residual == 0 {
            score -= 8.0;
        }
        // Penalize leaving a residual that neither fits the next item nor is useful.
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer minimal waste, i.e. minimal post_residual.
        score -= 5.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent existing fits exist, unless it enables
    // a perfect 2-step match (post_residual == next_item_size).
    if bin_residual == bin_capacity {
        let perfect_lookahead = next_item_size > 0 && post_residual as i64 == next_item_size as i64;
        if !perfect_lookahead {
            score += 10.0;
        }
        // Early stream: opening bins is cheaper (more future items to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest possible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally to waste
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is penalized, but less when items are large or open bins are tight.
        let open_penalty = 45.0 - 30.0 * pressure - 20.0 * mean_tightness;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = open_penalty + 25.0 * progress;
        // If nothing else fits (no open bins), a new bin must score well.
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild global balance: prefer bins whose residual is below mean (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: penalize large residuals more strongly as stream progresses
    let pr_norm = pr / cap;
    score += pr_norm * pr_norm * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= (1.0 - pr_norm).powi(3) * 20.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin mildly,
    // more so early in the stream when consolidation is cheap
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 5.0 + 25.0 * (1.0 - progress) + open * 0.5;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            // penalty proportional to wasted potential, smooth quadratic
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap * cap;
        }
    }

    // Coupling with mean residual: bins far below mean are better targets (smooth)
    let dev = (pr - mean_residual) / cap;
    score -= 5.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction via integer division thresholds.
    let item_class = item_size / 25;              // 0..3 (tiny, small, medium, large)
    let next_class = (next_item_size / 25).min(4);

    // Perfect fit reward: post residual exactly 0 or a tiny harmonic residue.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    }

    // Dead-space penalty: post_residual that no plausible item class can fill.
    // Items >= 10, so residual < 10 is dead space (unless zero).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo coupling: reward when post_residual is a multiple of a common
    // item granularity (10/20/25), making future fills likely.
    let r = post_residual;
    if r % 10 == 0 {
        score -= 25.0;
    }
    if r % 20 == 0 {
        score -= 15.0;
    }
    if r % 25 == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size < 10 {
            score -= 120.0; // next item closes the bin nearly perfectly
        } else {
            score -= 30.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to waste.
        score += (post_residual as f64).min(60.0) * 0.5;
    }

    // Class matching: pairing items of complementary harmonic classes.
    // post_residual ideally equals a class boundary value (25/50/75).
    match post_residual {
        25 => score -= 40.0,
        50 => score -= 45.0,
        75 => score -= 40.0,
        _ => {}
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we
    // prefer reusing open bins unless the fit is poor. Scale the penalty with
    // stream progress and current open-bin count.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.05 * (open_bins_count as f64);
        // But if the item is large (class 3), a fresh bin is fine.
        if item_class == 3 {
            score -= 30.0;
        }
    }

    // Tight-fit preference: reward using a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 30.0;

    // Penalize bins whose residual deviates far from the mean residual
    // (keeps bin population balanced, avoids stragglers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Stream progression: early on, be slightly more willing to open bins
    // (spread items); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    } else {
        score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Last-chance bin pressure: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when no open bin would leave a decent residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Lookahead: opening a fresh bin is better if next item is large.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: penalize placements that fragment many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is near the mean (avoid extreme outliers).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;

    // Lookahead coupling: reward a post_residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        // Exact match for next item is excellent.
        if slack == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: dead space risk, but small is okay.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when reasonable alternatives exist,
    // unless the current item would leave a very awkward fit everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 35.0 + waste * 0.3 * (1.0 - progress);
        // If next item fits nicely in the fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
    }

    // Mild preference for more-filled bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
        // Extra reward if the next item fills the bin almost exactly (chained fit).
        let chained = post_residual - next_item_size;
        if chained <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual too small for the next item (dead space risk),
        // but less so late in the stream.
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Penalize very small unusable post-residual fragments (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins fit poorly (large item, few fitting bins) or stream is early
    // and we can afford slack for future flexibility.
    if is_new_bin {
        let poor_fit_pressure = (fitting_bins_count == 0) as i32 as f64 * 40.0
            + (fitting_bins_count == 1) as i32 as f64 * 15.0;
        // Slack value: larger post-residual in a fresh bin is more useful early.
        let slack_value = 0.15 * post_residual as f64 * (1.0 - 0.7 * progress);
        // Congestion: many open bins with high mean residual -> prefer consolidating.
        let congestion = 0.05 * open_bins_count as f64 + 0.1 * mean_residual;
        score = score - poor_fit_pressure - slack_value + congestion;
        // Hard-ish baseline penalty so new bins are chosen only when clearly better.
        score += 25.0;
    } else {
        // Mild preference for tighter existing bins relative to global mean residual.
        score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space hurts super-linearly.
    let progress_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.5;
    score += progress_penalty;

    // Reward filling bins deeply, smoothed via polynomial in fit fraction
    score -= 40.0 * fit * fit * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Penalize opening a new bin when plenty of open bins exist (smooth in open count)
    let open_pressure = (open_bins_count as f64).ln_1p();
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * open_pressure - 20.0 * progress;
    }

    // Lookahead: if next item would fit the post-residual, reward leaving that space
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: smooth penalty proportional to wasted residual
        score += 5.0 * norm_pr * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is below average (tighter bins)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: post_residual in {0} -> perfect fit, huge reward.
    // Class 1: post_residual <= 10 -> near-perfect, dead space unlikely useful.
    // Class 2: post_residual small but next item may fit -> lookahead bonus.
    let post = post_residual;
    if post == 0 {
        score -= 60.0;
    } else if post <= 10 {
        score -= 35.0;
    } else if post <= 25 {
        score -= 15.0;
    } else if post <= 50 {
        score -= 5.0;
    } else {
        // large leftover: mild penalty proportional to waste fraction
        score += (post as f64 / cap) * 10.0;
    }

    // Integer-division thresholds: leftover usable for next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // next item fits here: reward, more if snug
            let slack = (post - next_item_size) as f64;
            score -= 20.0 - (slack / cap) * 15.0;
        } else {
            // next item cannot fit: penalize if leftover is in a "dead zone"
            // (too small for typical items, i.e. post < min plausible size)
            if post < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // cheaper to open new bin when many bins are already open and fragmented
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        // if the item would leave a big hole in an existing bin, new bin is fine
        let worst_existing = mean_residual.max(0.0);
        if worst_existing > 0.0 && (post_residual as f64) < worst_existing * 0.5 {
            score -= 10.0;
        }
        // early in stream, opening bins is fine; late, consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 12.0;
    }

    // Modulo/arithmetic coupling: leftover divisible into common item sizes
    // (10,20,25,50) is more reusable -> reward.
    if post > 0 {
        if post % 10 == 0 || post % 20 == 0 || post % 25 == 0 || post % 50 == 0 {
            score -= 6.0;
        }
    }

    // Mild tie-breaker: prefer fuller bins overall (lower residual vs mean).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is worthless
    } else if post_residual < 20 {
        score += 8.0; // marginal gap
    } else if post_residual == 0 {
        score -= 15.0; // perfect fill is ideal
    }

    // Reward leaving a gap that can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap too small for the next item: dead space risk
    }

    // Last-chance pressure: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin when
    // reasonable fits exist, but allow it when this avoids tight cramming.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual >= next_item_size {
            score -= 8.0; // fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative: opening is fine
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting capacity further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + 0.5 * progress);

    // Slight preference for bins with below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward bins whose leftover matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 55.0; // next item fills this bin perfectly
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            // partial credit, scaled by how much slack remains after next item
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // leftover can't host the next item: penalize dead space proportionally
        score += 0.35 * post_residual as f64;
    }

    // Penalize bins far from the mean residual (outliers waste capacity)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream: consolidate into existing bins, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: acceptable early, costly later
        score += 20.0 + 30.0 * progress;
        if post_residual < 10 {
            score -= 15.0; // a fresh bin that will be nearly filled right away
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Penalize wasted space more strongly when post_residual is small but
    // nonzero and unlikely to be used by the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead reward: this bin can also serve the next item.
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead-space penalty proportional to how close the next item
            // comes to fitting but failing.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 4.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty when the item is large relative to capacity or when no good
    // fit exists (post_residual in open bins would be very small).
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 60 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size <= 30 && item_size >= 70 {
            // Large item followed by small one: new bin keeps room.
            score -= 6.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global-state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into bins with above-mean residual.
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Mild preference for bins that keep a "useful" leftover band.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;
    let mut score = post;

    // Smooth non-linear coupling: penalize mid-range waste, reward tight fits
    let tightness = (1.0 - fit_ratio).powi(3);
    score -= 8.0 * tightness * cap * (0.5 + progress);

    // Quadratic dead-space penalty for residuals too small for typical items
    let dead = if post > 0.0 { (1.0 - post / 20.0).max(0.0) } else { 0.0 };
    score += 6.0 * dead * dead;

    // Lookahead coupling: smooth interaction with next item fit
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let next_fit = (post - nx) / cap;
        if next_fit >= 0.0 {
            score -= 4.0 * (1.0 - next_fit).powi(2) * (1.0 - progress);
        } else {
            score += 3.0 * (-next_fit * cap / 40.0);
        }
    }

    // Last-chance bonus with smooth saturation
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 - progress.powi(2));
    }

    // Mild dispersion penalty: prefer bins near mean residual
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);

    // Late-stream consolidation: favor filling existing bins more aggressively
    score -= 3.0 * progress * (1.0 - fit_ratio) * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic: classify post_residual into residue classes ---
    // Residue class mod 10: residuals that are multiples of 10 are "harmonic"
    // (likely reusable by common item sizes), odd/dead residues are penalized.
    let residue_class = post_residual % 10;
    let harmonic_bonus = match residue_class {
        0 => 6.0,                       // perfectly harmonic residual space
        5 => 3.0,                       // half-harmonic
        r if r % 2 == 0 => 1.0,         // even residues mildly favored
        _ => -2.0,                      // odd residues create dead-space risk
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: how many "typical items" (size ~20) still fit
    let slots = post_residual / 20;
    score -= slots as f64 * 2.5;

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: strong reward.
            score -= 8.0 + (next_item_size as f64) * 0.05;
            // Extra reward for exact/near-exact two-item packing
            let two_gap = post_residual.saturating_sub(next_item_size);
            if two_gap <= 5 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: penalize small unusable leftovers.
            if post_residual < 10 {
                score += 4.0; // tiny dead space
            }
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += post_residual as f64 * 0.5;
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; strongly prefer it over opening new.
        score -= 10.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (fitting_bins_count as f64).min(5.0)
        };
        // Penalize new bin if any open bin can fit, scaled by how "roomy" open bins are.
        score += 15.0 + pressure * 4.0 + mean_residual * 0.1;
        // But if the item is huge relative to mean residual, new bin may be better:
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count > 0 {
            score -= 20.0;
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // --- Global residual dispersion: prefer bins below mean residual (tighter bins) ---
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3; // tighter-than-average bins favored
    } else {
        score += (-diff) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0; // mildly awkward gap
    } else if post_residual == 0 {
