    }

    // Lookahead: favor bins whose post_residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // dead space relative to lookahead
    }

    // New-bin candidate handling: default penalty so we prefer existing bins,
    // but allow opening when fits are scarce or the gap would be large/wasteful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 55.0;
        if fitting_bins_count <= 1 {
            score -= 70.0; // opening is fine when no real alternative
        }
        if item_size >= 70 {
            score -= 20.0; // large items deserve fresh space
        }
    }

    // Slight progression term: later in stream, tighten up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

