    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly here: big reward (subtract).
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 0.5 * waste;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Perfect fit bonus: closing a bin exactly is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residual (<10, below min item size) is dead space: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish base; discourage when an open bin gives a tight fit elsewhere.
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Two items can share a fresh bin: encourage opening it when open bins are fragmented.
            let fragmentation = (mean_residual - post_residual as f64).abs();
            score -= 20.0 + fragmentation.min(50.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins: opening another is cheap; few open bins: discourage.
        score -= (open_bins_count as f64).min(10.0);
    }

    // Mild tie-breaker: prefer bins with residual below mean (consolidating fuller bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
