    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Discourage spreading when many bins are open: prefer fullest bin.
    let fill_ratio = (bin_residual as f64) / cap;
    score += 4.0 * fill_ratio * (open_bins_count as f64).sqrt();

    // Global pressure: when mean residual is low, conserve space (penalize waste more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (1.0 - mean_residual / cap).clamp(0.0, 1.0);
    score += 5.0 * fill_ratio * pressure * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a base penalty so it's chosen
    // only when open bins would waste a lot (large dead space otherwise).
    if bin_residual == bin_capacity && item_size > 0 {
        score += 35.0;
        // Early stream: opening bins is cheaper; late stream: avoid new bins.
        score -= 25.0 * (1.0 - progress);
