    score -= 14.0 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Prefer bins whose residual is close to item (smooth gaussian fit term).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * fit_gap * fit_gap;

