        score += 20.0 * (1.0 - poor_fit) + 8.0 * (1.0 - progress);
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones.
    score += 0.35 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Align with mean residual state: bins below mean residual are more precious.
    score += 3.0 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "friendly"
    // (multiples of common item sizes 10/20/25/50) are worth keeping.
    let friendly = |r: u32| -> f64 {
        if r == 0 { 0.0 }
        else if r % 50 == 0 { 2.0 }
        else if r % 25 == 0 { 1.5 }
        else if r % 20 == 0 { 1.2 }
        else if r % 10 == 0 { 0.8 }
        else { 0.0 }
    };

    // Reward bins whose post-residual lands on a friendly class.
    score -= 3.0 * friendly(post_residual);

    // Penalize dead space: post-residual too small for the smallest item (1)
    // is fine, but small nonzero waste is bad. Penalize 1..9 strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post-residual
    // (harmonic chaining), penalize if next item cannot fit.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            score -= 2.0 * friendly(next_post);
            score += 0.3 * next_post as f64;
        } else {
            // next item won't fit here; leaving large residual is fine,
            // but tiny residual is wasted.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when all open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is not chosen unless existing bins score badly.
        score += 30.0;
        // Late in the stream, or with many open bins, discourage new bins more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        score += 0.5 * open_bins_count as f64;
        // If mean residual is large, existing bins likely suffice.
        score += 0.2 * mean_residual;
        // But if the next item is huge and current item leaves bad residue,
        // a fresh bin can still win via the base score comparisons.
        if next_item_size >= 50 && item_size >= 50 {
            score -= 25.0;
        }
    } else {
        // Mild preference for tighter existing bins (best-fit flavor),
        // modulated by harmonic class of the pre-residual.
        score -= 0.5 * friendly(bin_residual % bin_capacity);
        // Slight preference for bins that are already well-loaded.
        let load = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * load;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // moderate penalty for smallish gaps
        score += 8.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Last chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * 15.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual < next_item_size {
        // penalize leaving a gap the next item cannot use
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate: keep it neutral-ish baseline but add slight penalty
    // so it is only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // In early stream with few bins, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to next item
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: keep bins balanced
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: moderate penalty so it's chosen only when
    // open bins give poor fits
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Penalize large unusable gaps (small post_residual that can't fit typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal; penalize mid-range waste.
    let pr = post_residual as f64;
    score -= 30.0 * (-pr / 12.0).exp(); // strong bonus for very small post_residual

    // Penalize dead space that is too small for the smallest plausible item (<= 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // only large items can use it
    }

    // Lookahead: reward if next item fits the post_residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 12.0 * (-gap / 10.0).exp(); // next item chains well
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // lookahead item cannot chain here
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; few open bins: mild encouragement to use existing space.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.6 * pressure * (pr / bin_capacity as f64);

    // Time horizon: early in the stream, be pickier about large residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (pr * 0.15);
    score -= progress * 5.0; // late in stream, just fill bins

    // New-bin candidate handling: opening a new bin is only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Default cost of a fresh bin: capacity-scale baseline.
        score = bin_capacity as f64 * 0.9;
        // If the only fitting bin is this new one (no open bin fits), opening is necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If current item + lookahead would perfectly fill a fresh bin, favor opening.
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
        // Early stream with few bins: opening is cheaper.
        score -= (1.0 - progress) * 10.0;
        // Many open bins with high mean residual: avoid opening yet another bin.
        score += 0.5 * open_bins_count as f64 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early on, tight packing matters less; later, dead space is costly.
    let mut score = norm_post * (1.0 + 1.5 * progress * norm_post);

    // Smooth non-linear coupling: residual efficiency term
    let fill = 1.0 - norm_post;
    score -= 0.6 * fill * fill * (0.5 + progress);

    // Lookahead: reward bins whose post residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 0.8 * (1.0 - slack * slack) * (1.0 - progress * 0.5);
        } else {
            let gap = (nxt - post) / cap;
            score += 1.2 * gap * gap;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - norm_post * norm_post);
    }

    // Penalize proliferation of open bins mildly, smoothed
    let bin_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 0.3 * bin_pressure * norm_post;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    let dev = (post - mean_residual) / cap;
    score += 0.4 * dev * dev.abs();

    // New-bin candidate handling: empty bin gets a mild opening cost that
    // shrinks as the stream progresses (late stream tolerates new bins less)
    if bin_residual == bin_capacity {
        score += 1.5 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base preference: tight fit (small post_residual) rewarded.
    score -= 12.0 * (1.0 - post / cap);

    // Harmonic class of post_residual: dead-space classes.
    // Residuals in (0,10] are nearly unusable (min item size ~1..10): reward heavily.
    if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        // small dead zone, mildly bad
        score += 6.0;
    } else if post_residual <= 50 {
        score += 2.0;
    } else {
        // large residual: bin stays very reusable
        score -= 5.0;
    }

    // Modulo-25 harmonic banding on post_residual: quantized leftover quality.
    let band = post_residual % 25;
    if band == 0 {
        score -= 4.0; // perfectly quantized leftover
    } else if band < 10 {
        score += 3.0; // awkward sliver leftover
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size as f64 <= post {
            // bin remains useful for the known next item
            let slack = post - next_item_size as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if next_item_size as f64 == post {
                score -= 8.0; // perfect chain fill
            }
        } else {
            // next item cannot use this bin: leftover likely becomes dead space
            score += 8.0;
            // extra penalty if leftover is in the unusable sliver class
            if post < next_item_size as f64 && post < 20.0 {
                score += 6.0;
            }
        }
    } else {
        // last item: any residual is pure waste
        score += post * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well
        // and the item is large enough that fragmentation elsewhere hurts.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // penalize opening a bin when many open bins exist with room
        score += 10.0 + 0.4 * crowdedness;
        // allow new bins more readily early in the stream
        score -= 8.0 * (1.0 - progress);
        // if this is the only fitting option, the last-chance bonus above
        // already favors an open bin; neutralize a bit for very tight fits elsewhere
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // never open a new bin for a tiny item
        if item_size < 30 {
            score += 25.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Tie-break: prefer bins whose residual is close to the mean (balance).
    score += 0.02 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward exact closure of a bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Strict dead-space avoidance: gaps of 1..9 units are essentially unusable
    // (min item size is 1, but statistically small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Medium gaps (10..19) are only usable by the smallest items: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin so existing bins are
    // preferred unless all fits are poor (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 25.0;
        // If lookahead item would also fit well in a fresh bin, slightly favor it.
        if next_item_size > 0 && next_item_size <= bin_residual.saturating_sub(item_size) {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize new-bin creation, reward filling crowded state).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5;
    } else {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean-residual coupling: when average residual is high, tight fits are
    // more valuable (reward bins below the mean residual, i.e. tighter bins).
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Late in the stream, closing bins cleanly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual == 0 {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // 2-step lookahead: strongly reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 600.0; // perfect 2-step chain
        } else if gap <= 3 {
            score -= 250.0;
        } else if gap <= 10 {
            score -= 80.0;
        } else {
            // penalize leaving space that the next item cannot use well
            score += gap as f64 * 0.5;
        }
        // if next item fits exactly into current residual too, prefer keeping that option
        if next_item_size == bin_residual {
            score += 60.0;
        }
    }

    // Relative-to-mean coupling: favor bins tighter than average residual.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res_f - mean_residual) / mean_residual;
        score += rel * 30.0; // tighter bins (small residual) get lower score
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or no good fits.
    if bin_residual == bin_capacity {
        let big_item = item_size >= 60;
        let poor_options = fitting_bins_count <= 1;
        if big_item || poor_options {
            score -= 50.0; // acceptable to open new bin for big items / last resort
        } else {
            score += 150.0 + (item_size as f64); // discourage wasting a fresh bin
        }
        // early in stream, fresh bins are cheap; later, prefer consolidating
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 100.0;
    }

    // Slight preference for filling fuller bins overall.
    score += (bin_capacity as f64 - res_f) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual after placement drives waste, so weight it.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large post-residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    }

    // Lookahead: if the next item fits the post-residual exactly, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 8.0;  // next item can still use this bin
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing residuals are all poor fits for the item (high fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // If mean residual is small (bins nearly full), opening is fine.
        // If mean residual is large but item fits badly everywhere, allow it.
        let poor_fit_elsewhere = (bin_residual - item_size.min(bin_residual)) as f64;
        let horizon = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 40.0 * (1.0 - fragmentation) - 10.0 * horizon;
        // Slight penalty so a genuinely good existing fit still wins.
        score += 5.0;
        let _ = poor_fit_elsewhere;
    }

    // Mild penalty for scattering across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer placing into bins with residual close to item size (best-fit bias).
    let gap = (bin_residual - item_size) as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth coupling: as stream progresses, tighten preference for tight fits.
    score += 12.0 * progress * norm_post * norm_post * cap;

    // Dead-space penalty for residuals that are hard to fill later (small post residual is fine,
    // mid residuals that fit nothing are bad). Smooth quadratic trough around mid residuals.
    let mid_gap = (norm_post - 0.35).abs();
    score += 8.0 * mid_gap * mid_gap * cap;

    // Lookahead: reward if the next item fits the post residual (smooth affinity).
    if next_item_size > 0 {
        let fits_next = (post - next_item_size as f64).max(0.0);
        let affinity = 1.0 - (fits_next / cap);
        score -= 6.0 * affinity * affinity * (norm_next.max(0.05));
        // Penalize leaving exactly a sliver the next item cannot use.
        if post < next_item_size as f64 {
            score += 5.0 * (next_item_size as f64 - post) / cap * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when other bins fit; smooth decay so early stream may open bins.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.5);
        score += 30.0 + 20.0 * progress - 10.0 / openness;
        // If the item is large relative to capacity, opening fresh is less bad.
        score -= 15.0 * norm_item * norm_item;
    }

    // Mild preference for bins already below mean residual (balancing load smoothly).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead space classification via harmonic residue classes.
    // post_residual in 1..=9 is "dead" (nothing in [1,100] can use it reliably).
    let pr = post_residual;
    if pr <= 9 {
        score += 60.0 * (10 - pr) as f64; // smaller leftover = worse dead space
    } else if pr <= 20 {
        // usable only by tiny items; mild penalty
        score += 8.0;
    } else if pr >= 50 {
        // large residual: bin stays flexible, mild reward
        score -= 6.0;
    }

    // Harmonic class: does post_residual match a plausible next-item class?
    // Reward when post_residual is at least next_item_size (chain fit possible).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.2;
        } else {
            // can't host next item; penalty scaled by how close we came
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Modulo-class coupling: post_residual divisible structure
    let cls = post_residual % 10;
    if cls == 0 {
        score -= 5.0; // round residuals are friendlier for future packing
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
        // If item is large and no good fit exists, opening is fine.
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size > bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Late in stream: tighten packing, prefer tightest fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.3;

    // Tie-break: prefer bins whose residual is closest to item (best-fit bias).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable
    // for future items (sizes >= 1 but realistically >= 10 in classic streams),
    // so penalize them quadratically, stricter as the stream progresses.
    if post_residual > 0 && post_residual < 10 {
        let gap = (10 - post_residual) as f64;
        score += gap * gap * (1.5 + 2.5 * progress);
    }

    // If the lookahead item can exactly or nearly fill the post residual,
    // reward this bin strongly (chain fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * 0.6 + (10.0 - slack.min(10.0)) * 0.5;
    } else if next_item_size > 0 {
        // Next item cannot use the gap: penalize proportional dead space.
        score += post_residual as f64 * 0.15;
    }

    // Last-chance pressure: if this is the only open bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is penalized, but the
    // penalty relaxes if the current fit across open bins is poor (large
    // post_residual elsewhere) or many bins are already open and consolidation
    // pressure is high.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count > 0 { post_residual as f64 } else { 0.0 };
        score += 20.0 + open_bins_count as f64 * 0.4 - poor_fit_elsewhere * 0.1;
    }

    // Open-bins pressure: when many bins are open, be greedier about tight fits
    // (mildly amplify residual penalty) to avoid fragmenting capacity.
    score += post_residual as f64 * (open_bins_count as f64 * 0.01);

    // Mild global coupling: high mean residual across bins indicates wasted
    // space; tighten selection by slightly boosting residual penalties then.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += gap * 0.35;
            // If next item can't fit but a future smaller one might, mild penalty.
            if post_residual < next_item_size {
                score += gap * 0.25;
            }
        }
    } else {
        // Last item: prefer tightest fill.
        score += post_residual as f64 * 0.5;
    }

    // Penalize dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - pr) * 0.05;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits more aggressively.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Late in the stream, prioritize closing out bins (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    // Slight preference to keep many open bins from proliferating: using an
    // existing bin is mildly favored over opening a new empty one.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Reward near-perfect packing: post_residual below smallest item size is dead space.
    if pr < 10 {
        score -= 8.0; // bin effectively closed, good outcome
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leaving post_residual that matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.35 * gap;
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-item chain
        }
        // If next item cannot fit post_residual anywhere else, this bin is valuable.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: prefer fullest packing, any residual is waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer bins with below-mean residual (close them out).
    if open_bins_count > 3 {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.2 * diff; // lower residual than mean -> lower score
    }

    // Early in stream: be more tolerant of slack; late in stream: pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize unless current alternatives are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
        // But if item is huge relative to capacity, opening fresh may be fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear fit quality: tight fits (small post_residual) rewarded.
    let fit_frac = post_residual as f64 / cap; // 0 = perfect fit
    let tightness = (1.0 - fit_frac).powi(2); // grows as fit tightens
    score -= 40.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that is too small to be useful for future items,
    // with a smooth bump centered around unusable residuals.
    let dead = (fit_frac * (1.0 - fit_frac) * 4.0).powi(2); // peaks at fit_frac=0.5
    score += 8.0 * dead;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open bins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward leaving space that still fits the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            score -= 10.0 * (1.0 - (post_residual as f64 - n) / cap);
        } else {
            score += 6.0 * (n - post_residual as f64) / cap;
        }
    }

    // Mean-residual coupling: deviating from mean residual toward fullness is good.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 5.0 * dev * dev.abs();

    // Mild preference for filling fuller bins as stream progresses (polynomial in progress).
    score -= 15.0 * progress * progress * (1.0 - fit_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1..9] is nearly unusable
    // (items are >= 10 in classic streams, but sizes 1..100 possible here).
    let pr = post_residual;
    let harmonic = pr % 10;

    // Penalize residuals that fall into "dead zones" relative to item granularity.
    if pr > 0 && pr < 10 {
        score += 25.0; // almost-dead space
    } else if harmonic == 0 {
        score -= 6.0; // perfectly aligned residual, reusable by decade-sized items
    } else if harmonic >= 5 {
        score += (harmonic as f64) * 0.8; // awkward half-class
    } else {
        score -= 2.0; // small but still usable remainder
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    let tightness = 1.0 - (pr as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chain
        } else if slack < 10 {
            score -= 10.0;
        } else {
            score += (slack as f64) * 0.15;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this bin's remainder; penalize leftover proportionally
        score += (pr as f64) * 0.25;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, softened late in the stream
        let progress = (step_index as f64) / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * 0.9 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can also host the next item
        }
    }

    // Slight preference for bins below mean residual (balances load).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Modulo threshold on item_size class: large items prefer large residual bins.
    let item_class = item_size / 10;
    let bin_class = bin_residual / 10;
    if bin_class < item_class {
        score += 15.0; // shouldn't happen (residual >= item), safety
    } else if bin_class == item_class {
        score -= 4.0; // exact class match: ideal
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // tiny gaps are pure loss
        } else if post_residual <= 20 {
            score += (20 - post_residual) as f64 * 1.5; // moderately risky gaps
        } else {
            // Larger residual space remains usable; mild reward relative to mean.
            score -= (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is a tiny dead gap).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item exactly fits the post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover; penalize creating stranded space.
            score += (next_item_size.min(60) as f64) * 0.1;
        }
    }

    // New-bin candidate: keep it moderately attractive only when the item is large
    // relative to a fresh bin and no good existing fit exists.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - fill_frac * 40.0 + open_bins_count as f64 * 0.3;
        // A new bin is good if the item is big (would leave little residual anyway).
        if fill_frac > 0.7 {
            score -= 15.0;
        }
        // Early in the stream, opening bins is cheap.
        if progress < 0.3 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual > next_item_size {
            // next item fits too: reward tight two-item packing
            let two_left = post_residual - next_item_size;
            score -= 250.0 - (two_left as f64) * 2.0;
        } else {
            // next item won't fit here: penalize dead space proportionally
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 30.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 40.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted post space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Scarcity pressure: fewer fitting bins -> favor existing bins.
    if fitting_bins_count >= 2 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut newbin_score = 35.0 - 30.0 * fill_ratio;
        // If lookahead item can pair with the leftover of this item, opening
        // a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            newbin_score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        newbin_score += 20.0 * progress;
        // Many open bins with fat residuals: don't open another.
        newbin_score += (open_bins_count as f64) * 1.5 + mean_residual * 0.15;
        return newbin_score;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            // Dead space for the known next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Prefer filling bins that deviate below the mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate loose fits; later demand tighter packing.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr_norm * pr * 0.5;

    // Reward near-perfect fits more strongly as stream advances.
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize proportionally to how much it would waste
    // relative to existing slack, but allow it when open bins are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = pr;
        score += waste * (0.8 + 1.2 * progress);
        score -= 4.0 * (1.0 - (fitting_bins_count as f64).min(4.0) / 4.0);
    }

    // Lookahead: bonus if next item fits exactly into resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            score += 1.5 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for scattering across many open bins with slack.
    score += 0.15 * (open_bins_count as f64).sqrt() * pr_norm;

    // Mean-residual coupling: if this bin is far from the mean residual,
    // slight penalty (prefer balanced packing), smooth quadratic form.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline score = full capacity.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 - 0.5;
    }

    let pr = post_residual as f64;

    // Harmonic class of post_residual modulo 10: dead space in small residue classes
    // (1..=5) is nearly unusable for items >= 10, penalize heavily.
    let r = post_residual % 10;
    if post_residual > 0 {
        if r >= 1 && r <= 5 {
            score += 8.0 + (5 - r) as f64;
        } else if r == 0 {
            score -= 3.0; // perfectly divisible residual, very reusable
        } else {
            score -= 1.0; // 6..9 still usable by small items
        }
    } else {
        score -= 10.0; // perfect fill: best outcome
    }

    // Fractional capacity coupling: how full the bin becomes
    let fill = 1.0 - pr / bin_capacity as f64;
    score -= 6.0 * fill * fill;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 7.0;
        } else if nxt <= pr {
            // harmonic class match: next item leaves a divisible residual too
            let nr = (pr as u32 - next_item_size) % 10;
            if nr == 0 { score -= 4.0; } else if nr <= 5 { score += 2.0; }
        } else {
            // next item cannot use this bin's residual: residual likely dead
            score += 3.0;
        }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing).
    score += 0.3 * (mean_residual - pr);

    // Late in stream: tighten, avoid opening marginal bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * pr / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size)
    // are essentially unusable -> heavy penalty.
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill is highly desirable
    } else if post_residual <= 20 {
        // Gaps between 10 and 20 can only host small items: moderate penalty
        score += 25.0;
    }

    // Progressive dead-space penalty: quadratic in post_residual
    let pr = post_residual as f64;
    score += 0.15 * pr * pr / bin_capacity as f64;

    // Reward tight fits relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; new empty bin gets penalized via count.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, scaled by pressure.
        score += 45.0 + 8.0 * open_bins_count as f64;
        // If no existing bin fits well (this call is the new-bin candidate and
        // item barely fits anywhere), opening may still win via other terms.
        if post_residual < 10 {
            score -= 60.0; // still allow fresh bin when item fills it exactly
        }
    } else {
        // Existing bin: slight reward to counteract new-bin base cost.
        score -= 5.0;
        // Prefer bins with below-mean residual (consolidate fuller bins).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if next item can use the post residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // residual too small for next item: dead space risk
    }

    // Early in stream: be slightly conservative about opening bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 300.0 - slack * 5.0;
            } else {
                // Next item fits but leaves large second residual: mild penalty.
                score += slack * 0.5;
            }
        } else {
            // Next item cannot fit here: penalize relative to gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.8;
    } else {
        score += (res - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin unless current bin is a poor fit and next item
    // would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no tight fit exists elsewhere.
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 80.0;
    }

    // Slight preference for consolidating when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post-residual dead space (but not zero, which is perfect).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead);
        }
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead: reward if the next item also fits in the post-residual (chaining),
    // penalize if post-residual is just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * chain;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 12.0; // stranded residual relative to next item
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists,
    // i.e., when mean residual across open bins is small relative to the item.
    if bin_residual == bin_capacity {
        let mean_tightness = item_size as f64 / (mean_residual + 1.0);
        // Base cost of opening a new bin, reduced if open bins are all too tight.
        let mut new_bin_cost = 90.0;
        if mean_residual < item_size as f64 {
            new_bin_cost -= 45.0 * (1.0 - mean_residual / item_size as f64);
        }
        // Late in the stream, opening fresh bins is less costly (fewer future regrets).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 20.0 * progress;
        // Many open bins: prefer consolidation into an existing bin.
        new_bin_cost += 2.0 * open_bins_count as f64;
        score += new_bin_cost;
        // A fresh bin has perfect post-residual for future large items; slight
        // discount if the next item is large and would fit a fresh bin well.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild preference for bins with below-average residual (consolidate slack).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_frac = pr / cap;

    // Base: prefer small post-residual (tight fit), with a smooth convex penalty
    // that grows super-linearly as wasted space increases.
    let mut score = pr + 12.0 * fit_frac * fit_frac * cap;

    // Smooth interaction: as the stream progresses, residual space becomes more
    // valuable to consolidate — penalize leftover space more strongly later.
    score += 20.0 * progress * fit_frac * (1.0 - fit_frac).sqrt();

    // Reward filling a bin almost completely (near-zero post-residual), smoothly.
    score -= 15.0 * (1.0 - fit_frac).powi(6) * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // otherwise penalize creating space that the next item cannot use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap) * progress;
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate handling: an empty bin has fit_frac == 1.0 for the item's
    // complement; make it attractive only when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly, reduced when few bins fit the item.
        score += 18.0 - 12.0 * (1.0 / (fitting_bins_count as f64 + 1.0));
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 10.0 * progress * (1.0 - fit_frac);
    }

    // Mild coupling with mean residual: prefer bins whose residual is below the
    // mean (i.e., close out fuller bins first), smooth quadratic term.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Slight preference to reduce open-bin count pressure early on.
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class4 = (pr % (bin_capacity / 4).max(1)) as f64;
    let class5 = (pr % (bin_capacity / 5).max(1)) as f64;

    // Reward post-residuals that land on "clean" harmonic boundaries (0 mod class),
    // which pair well with future items divisible by those classes.
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else {
        score -= 4.0 * (1.0 - class4 / (bin_capacity as f64 / 4.0));
        score -= 2.0 * (1.0 - class5 / (bin_capacity as f64 / 5.0));
    }

    // Small dead space is bad if it can't fit the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; penalize leaving awkward residue
            let q = pr / next_item_size.max(1);
            score += 6.0 * (1.0 - q as f64 / 4.0);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins, more so early in the stream
    // and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if existing bins would leave tiny unusable residue, opening is OK.
        if pr > 0 && pr < 10 && item_size > 0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean (diversity of classes).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Mild preference for tighter bins overall.
    score += 0.02 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 - 2.5 * post_residual as f64; // smaller gap => worse dead space
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit anticipation: if the next item exactly matches post_residual, strongly reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 8 {
        score -= 20.0; // sets up a near-perfect next placement
    }

    // Penalize leaving a gap that nothing typical (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        // base new-bin cost grows with number of open bins
        score = 55.0 + 3.0 * open_bins_count as f64;
        // if this bin is a last chance elsewhere, discourage opening a new bin
        if fitting_bins_count == 1 {
            score += 50.0;
        }
        // if next item could combine with current item in a fresh bin (item + next <= capacity), slight discount
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // early stream: allow more bins cheaply to build structure
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // if open bins have large mean residual, discourage new bin
        score += (mean_residual - 30.0).max(0.0) * 0.5;
    }

    // Open-bins pressure: penalize placements that fragment many open bins
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins below mean residual (balancing toward tighter bins)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fill bin exactly
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally to wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    } else {
        // Last item: just minimize post_residual strongly.
        score = post_residual as f64 * 2.0;
    }

    // Penalize creating tiny unusable dead space (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins below mean residual are already tight;
    // prefer filling tight bins, discourage spreading into loose bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate (empty bin): only attractive when current bin fit is bad
    // (large post_residual relative to capacity) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64 / bin_capacity as f64; // = 1 - item/capacity
        score = 45.0 + tightness * 55.0;
        if open_bins_count == 0 {
            score = -100.0; // must open a bin
        }
        if next_item_size > 0 && (next_item_size as f64) >= bin_residual as f64 * 0.9 {
            score -= 30.0; // next item nearly fills a fresh bin: good to open
        }
        // Later in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize post_residual with a superlinear penalty.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward zone
    } else if post_residual >= 60 {
        score += 4.0; // large leftover is flexible but wasteful now
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item can still use this bin
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste; // next item won't fit here; slight penalty
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with how many bins are already open
        // and how much residual capacity is idle overall.
        let mut new_bin_cost = 18.0 + 0.6 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            new_bin_cost += 10.0; // discourage opening when alternatives exist
        }
        // Late in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost += 10.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_cost += 0.15 * mean_residual;
        // If item is large relative to capacity, a fresh bin is more attractive.
        new_bin_cost -= 0.1 * item_size as f64;
        score += new_bin_cost;
    } else {
        // Slight preference for fuller bins among open ones.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // Mild global-load balancing: avoid dumping into bins far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress * 2.0);
    score += 12.0 * poly;

    // Tight fits rewarded, scaled by progress
    let tight = 1.0 - norm_pr;
    score -= 18.0 * tight * tight * (0.5 + progress);

    // Penalize leaving residual close to next item's mismatch
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 8.0 * gap * gap;
        // Reward exact next-item fit
        let fit_next = (pr - next_item_size as f64).abs() < 0.5;
        if fit_next {
            score -= 25.0 * (1.0 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // New bin candidate: penalize opening unless residual waste would be large elsewhere
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score += 15.0 + 10.0 * spread / cap - 30.0 * (1.0 - norm_pr);
        score += 10.0 * (1.0 - progress);
    }

    // Mild dispersion penalty relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space is worse in certain
    // residue classes. Items 1..100, so post_residual in 0..cap.
    let pr = post_residual as f64;
    let res_frac = pr / cap;

    // Class penalty: residuals that are "harmonically useful" (multiples of
    // common item sizes) are less penalized than awkward residuals.
    let awkward = if post_residual == 0 {
        0.0
    } else if post_residual > 80 {
        3.0
    } else if post_residual > 50 {
        1.5
    } else if post_residual > 20 {
        2.5
    } else {
        1.0
    };
    score += awkward * res_frac * 10.0;

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial fit quality
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 12.0 * fill;
        } else {
            // next item cannot use this residual at all -> dead space risk
            score += 8.0 * (pr / cap) * (pr / cap) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residual is very small
    // (i.e., this bin is nearly full anyway) or no real alternative.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; relax when stream is early
        // and open bins are congested.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / cap;
        score = 20.0 + 30.0 * (1.0 - progress) - 10.0 * congestion;
        // If the item is large, a fresh bin is actually good (better packing).
        if item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild penalty for leaving residual in a class that no typical item
    // (1..100) can exactly fill unless it's tiny.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny scraps are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum conceivable future item (1..=12) are pure waste.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual <= 25 {
        score += 15.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 55.0;
        if post_residual > 0 && post_residual <= 12 {
            score += 40.0; // but still punish creating tiny dead space
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is below the mean (tighter bins first),
    // which keeps large residuals available for large future items.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item could use the post residual exactly,
    // reward leaving that much space; if it cannot, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual <= 12 {
            score += 20.0;
        }
    }

    // New-bin candidate: an empty bin should only win when no open bin
    // offers a decent fit. Base it high; subtract if the item is large
    // relative to capacity (large items waste less in a fresh bin).
    if bin_residual == bin_capacity {
        score = 120.0 - 30.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 10.0; // next item pairs well with this one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // 2-step lookahead: reward bins where the next item also fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match of next item into post residual is the jackpot.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving dead space that is hard to reuse.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // tiny dead space is fine (near-perfect packing)
            } else {
                score += dead * 0.3;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fitting bins exist, but allow it
    // when the item would leave a large unusable gap in every open bin.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10 && next_item_size > post_residual;
        if fitting_bins_count > 0 && !poor_fit {
            score += 60.0;
        } else {
            score -= 15.0;
        }
    }

    // Mild preference for bins tighter than the current mean residual.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Early in the stream, allow more bin creation flexibility; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows quadratically for small leftovers that
        // can't host typical items.
        let dead = if post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
        score += 3.0 * dead * dead / 10.0;

        // Reward residuals that can still fit the lookahead item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                score += 5.0;
            }
        } else {
            // Last item: prefer exact fill, any residual is waste.
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bin: strong incentive to use it instead of opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a bin; reduced late in the stream.
        score += 25.0 - 10.0 * progress;
        // If many bins fit well, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 6.0 * fitting_bins_count as f64;
        }
        // If the current bin's residual would be tiny anyway, new bin is fine.
        if bin_residual - item_size <= 5 {
            score -= 20.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        // Mild preference for tighter existing bins relative to mean state.
        let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= 4.0 * tightness;
        // Discourage dumping into bins with already-large residuals when the
        // global mean residual is high (spread load instead).
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 3.0;
        }
        // Prefer using more-full bins when many bins are open (consolidation).
        if open_bins_count > 4 {
            score -= 2.0 * tightness;
        }
    }

    // Early stream: keep bins balanced slightly to preserve flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 {
        score += (post_residual as f64 - mean_residual).abs() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let norm_pr = pr / cap;
    let progress_coupling = norm_pr * (1.0 + progress * progress * 2.0);
    score += progress_coupling * cap * 0.15;

    // Penalize dead space relative to next item: if post_residual cannot hold lookahead
    // item, the leftover is likely wasted; smooth quadratic penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * cap * 0.5;
        // Reward bins whose post_residual exactly accommodates the next item.
        let fit_next = (pr - nxt).abs() / cap;
        score -= (1.0 - fit_next.min(1.0)) * 2.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (encourages balance),
    // weighted smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * (1.0 + (open_bins_count as f64).ln().max(0.0)) * 0.8;

    // Prefer filling bins tightly overall: quadratic reward for small normalized residual.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class penalty: dead space bucketed by capacity fractions.
        let cap_f = bin_capacity as f64;
        let pr = post_residual as f64;
        let class = (pr / cap_f * 8.0).floor(); // 8 harmonic classes of residual
        let class_center = (class + 0.5) * cap_f / 8.0;
        score += (class_center - pr).abs() * 0.5; // penalize residual far from class centers

        // Small dead space (<10) is nearly unusable for future items: heavy penalty.
        if post_residual < 10 {
            score += 40.0;
        }
        // Medium dead space (10..=30) partially usable: mild penalty.
        else if post_residual <= 30 {
            score += 8.0;
        } else {
            score -= 5.0; // large residual stays flexible
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: next item can slot in; reward proportionally.
            score -= 3.0 + (next_item_size as f64) * 0.2;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            // Next item cannot use this dead space; penalize.
            score += 15.0;
        }
    }

    // New-bin candidate logic: penalize opening a new bin, more when stream is late
    // or many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
        // If no open bin fits (fitting_bins_count counts only open bins that fit;
        // for the empty-bin call residual==capacity so it always "fits"), check scarcity.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0; // unavoidable opening
        }
        // If mean residual across open bins is large, opening new bins is wasteful.
        new_bin_score += mean_residual * 0.3;
        // Lookahead: if next item is large, fresh bin is more valuable.
        if next_item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score += new_bin_score;
    }

    // Prefer fuller bins slightly (best-fit bias beyond raw post_residual).
    score -= (bin_capacity.saturating_sub(bin_residual)) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fill — extremely desirable.
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Unusable dead space for the 10..80 regime: heavy penalty.
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual <= 20 {
        // Marginal gap: moderate penalty, but usable if next item is small.
        let next_usable = next_item_size > 0 && next_item_size <= post_residual;
        if !next_usable {
            score += 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 40.0;
    } else if fill_ratio > 0.75 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins have poor fit potential.
        let mean_r = mean_residual.max(0.0);
        // If next item could use mean residual well, avoid new bin.
        let next_fits_mean = next_item_size > 0 && (next_item_size as f64) <= mean_r;
        let mut new_bin_score = 120.0 + open_bins_count as f64 * 8.0;
        if next_fits_mean {
            new_bin_score += 40.0;
        }
        // Late in stream, opening fresh bins is fine (cleanup phase).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= progress * 30.0;
        score = new_bin_score + post_residual as f64;
    } else {
        // Mild preference for bins whose residual is close to item size.
        score -= (bin_residual as f64 - item_size as f64).abs() * -0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Post residual can still hold the next item: moderate reward scaled by slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack.min(60.0);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space that is too small to be useful.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 8.0;
        }
    }

    // Compare against mean residual: bins tighter than average are preferred.
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.25;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless current bin fit is really bad
    // (large post_residual with no useful lookahead match).
    if bin_residual == bin_capacity {
        score += 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if item_size <= 20 {
            score += 4.0;
        }
    }

    // Early in the stream, keep bins tighter to build structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post-residual penalizes wasted space super-linearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward using bins that are already fairly full (small residual before placement).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty if we leave a tiny dead zone.
            if post_residual < 10 {
                score += 6.0;
            }
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins, softened when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut nb = 30.0 - 15.0 * progress;
        // If no open bin fits well (large item, few fitting bins), allow opening a new bin.
        if fitting_bins_count == 0 {
            nb -= 40.0;
        } else if fitting_bins_count <= 2 {
            nb -= 10.0;
        }
        // If mean residual across open bins is small, open bins are crowded -> new bin is fine.
        if mean_residual < item_size as f64 {
            nb -= 20.0;
        }
        score += nb.max(-10.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer placing large items into bins where they leave a usable remainder (>10).
    if post_residual >= 10 && post_residual <= 40 {
        score -= 3.0;
    }

    score
}
